wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(62130582653678498653)
,p_plugin_id=>wwv_flow_imp.id(62129061745824344953)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Execute PL/SQL Code'
,p_attribute_type=>'PLSQL'
,p_is_required=>true
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(62130459454908364224)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'plsql'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'begin',
'    apex_debug.info(''drag and drop on sequence update at %s by %s'',to_char(sysdate,''hh24:mi:ss''), :APP_USER);',
'    apex_debug.info(''input json=%s'', apex_application.g_clob_01);    ',
'    apex_debug.info(''substitution drag_id=%s'',:DRAG_ID);',
'    apex_debug.info(''substitution drop_id=%s'', :DROP_ID);',
'    apex_debug.info(''substitution before_sequence=%s'',:BEFORE_SEQUENCE);',
'    apex_debug.info(''substitution after_sequence=%s'',:AFTER_SEQUENCE);',
'    --',
'    -- now do your updates',
'end;',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>A PL/SQL Code block that will be executed each time the order of items has changed (this is after dropping an element).</p>',
'<p>In PL/SQL you''ll have access to the same JSON information as in the event by using apex_application.g_clob_01.</p>',
'<p>To make it more comfortable, you can also access these bind variables: :DRAG_ID, :DROP_ID, :BEFORE_SEQUENCE, and :AFTER_SEQUENCE. Those variables will provide the element-id''s taken out of the data-id HTML attribute.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(62131147865248835152)
,p_plugin_id=>wwv_flow_imp.id(62129061745824344953)
