'--             l_tabela := null;',
'--     end;',
'',
'--     -- tenta buscar coluna',
'--     if l_tabela is not null then',
'--         begin',
'--             select column_name',
'--               into l_coluna',
'--               from all_tab_columns',
'--              where table_name = upper(l_tabela)',
'--                and (column_name like ''%NOME%'' or column_name like ''%DESCRICAO%'')',
