'--         end;',
'',
'--         l_sql := ''select ''||l_coluna||'' as display_value, id as return_value from '' || l_tabela;',
'--     else',
unistr('--         -- se n\00E3o achou nada, devolve query vazia'),
'--         l_sql := ''select null as display_value, null as return_value from dual where 1=2'';',
'--     end if;',
'',
'--     return l_sql;',
'-- end;',
''))
