,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select trim(column_value)',
'  from table(',
'         apex_string.split(',
'             nvl(',
'                 (select id_registro',
'                    from mpd_configuracao_ng',
'                   where id = :P427_PARAMETRO),',
