'        l_sql := q''~',
'            select ',
'                null              id,',
'                null              campo1,             ',
'                null              campo2,             ',
'                null              campo3,             ',
'                null              campo4,             ',
'                null              campo5,             ',
'                null              campo6,             ',
'                null              campo7,             ',
'                null              campo8,                                      ',
'                null              campo9,      ',
'                null              campo10,                                ',
'                null              filtro1,',
'                null              filtro2,',
'                null              filtro3,',
'                null              filtro4,',
'                null              filtro5,',
'                null              filtro_mult1,',
'                null              filtro_mult2,',
'                null              filtro_mult3,',
'                null              filtro_mult4,',
'                null              filtro_mult5,',
'                null              filtro_rangen,',
'                null              filtro_ranged,',
'                pkg_componentes.icone_opcao opcao',
'            from dual    ',
'        ~'';',
'    end if;',
'',
'    return l_sql;       ',
'end;'))
