'begin',
'    begin',
'        execute immediate',
'            ''begin :l_sql := UI_MPD_'' || l_pagina || ''.sql_report(:order); end;''',
'            using out l_sql, in :P9006_ORDER;',
'',
'    exception',
'        when others then',
'            begin',
'                execute immediate',
'                    ''begin :l_sql := UI_MPD_'' || l_pagina || ''.sql_report; end;''',
'                    using out l_sql;',
'',
'            exception',
'                when others then',
'                    return ''select 1 from dual'';',
