wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(37859591955962805)
,p_name=>'P9006_SORT_JSON'
,p_item_sequence=>50
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_campos        clob;',
'    l_labels        clob;',
'    l_pagina        varchar2(256) := nvl(:P9006_CODIGO_ARTEFATO, ''TD150'');',
'    l_card_ou_lista varchar2(10)  := :P9006_CARD_OU_LISTA;',
'begin',
'    l_pagina := upper(trim(l_pagina));',
'',
'    if not regexp_like(l_pagina, ''^[A-Z0-9_]+$'') then',
'        raise_application_error(-20001, ''Codigo de artefato invalido.'');',
'    end if;',
'',
'    execute immediate',
'        ''begin ui_mpd_'' || l_pagina || ''.campos_ordenacao(:card_ou_grid, :campos, :labels); end;''',
'        using in l_card_ou_lista, out l_campos, out l_labels;',
'',
'    return monta_json_campos_ordenacao(',
'        p_campos => l_campos,',
'        p_labels => l_labels',
'    );',
'    ',
'    exception',
'        when others then',
'            return null;',
'',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'N')).to_clob
);
