prompt --application/deployment/install/install_valor_client_identifier
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(48252845360613265)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'valor_client_identifier'
,p_sequence=>2
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace function valor_client_identifier(',
'    p_chave in varchar2',
') return varchar2',
'is',
'    l_client_identifier varchar2(4000);',
'    l_chave             varchar2(100);',
'    l_valor             varchar2(4000);',
'begin',
'    l_client_identifier := sys_context(''USERENV'', ''CLIENT_IDENTIFIER'');',
'',
'    if l_client_identifier is null or p_chave is null then',
'        return null;',
'    end if;',
'',
'    l_chave := upper(trim(p_chave));',
'',
'    l_valor := regexp_substr(',
'        l_client_identifier,',
'        ''(^|;)'' || l_chave || '':([^;]+)'',',
'        1,',
'        1,',
'        ''i'',',
'        2',
'    );',
'',
'    return l_valor;',
'',
'exception',
'    when others then',
'        return null;',
'end valor_client_identifier;',
'/'))
);
end;
/
prompt --application/deployment/install/install_fn_is_system
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(48253066453617828)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'FN_IS_SYSTEM'
,p_sequence=>3
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace FUNCTION FN_IS_SYSTEM',
'RETURN boolean',
'IS',
'    v_count NUMBER;',
'BEGIN',
'    SELECT COUNT(1)',
'      INTO v_count',
'      FROM MPD_USUARIO_PAPEL a',
'      JOIN MPD_PAPEL b',
'        ON b.ID = a.ID_PAPEL_USUARIO',
'     WHERE a.ID_USUARIO = pkg_util.retorna_id_usuario_logado',
'       AND b.SYSTEM = ''S'';',
'',
'    RETURN v_count > 0;',
'END;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1042
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16261395274982132)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'UI_MPD_TD1042'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1042" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'end "UI_MPD_TD1042";',
'/',
'create or replace package body "UI_MPD_TD1042" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                j.job_name                                                       as id,',
'                j.job_name ||'' - ''||c.codigo_artefato                            as titulo,',
'',
unistr('                ''Execu\00E7\00F5es: ''||nvl(j.run_count,0)||'),
unistr('                '' \2022 Falhas: ''||nvl(j.failure_count,0)                            as subtitulo,'),
'',
'                -- distintivo (pode ser JOB_NAME ou algo mais curto)',
'                case when j.enabled = ''TRUE'' then ''Ativo'' else ''Inativo'' end as distintivo,',
'                null                                                             as class_distintivo,',
'',
'                -- filtros (se quiser plugar em facet search)',
'                null filtro1,',
'                null filtro2,',
'                null filtro3,',
'                null filtro4,',
'                null filtro5,',
'                null filtro6,',
'                null filtro7,',
'',
unistr('                -- labels (segue o padr\00E3o do seu framework)'),
'                ''Job''                                                            as label_titulo,',
'                ''Resumo''                                                         as label_subtitulo,',
unistr('                ''Situa\00E7\00E3o''                                                       as label_distintivo,'),
'',
unistr('                -- \00CDcone por estado (SCHEDULED / DISABLED / outros)'),
'                case',
'                    when j.state = ''SCHEDULED'' and j.enabled = ''TRUE'' then',
'                        ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start">''||',
'                        ''<span class="a-CardView-icon u-color fa fa-check" aria-hidden="true" title="Ativo"></span>''||',
'                        ''</div>''',
'                    when j.state = ''DISABLED'' or j.enabled = ''FALSE'' then',
'                        ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start">''||',
'                        ''<span class="a-CardView-icon u-color fa fa-pause-circle-o" aria-hidden="true" title="Desabilitado"></span>''||',
'                        ''</div>''',
'                    when j.state = ''FAILED'' then',
'                        ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start">''||',
'                        ''<span class="a-CardView-icon u-color fa fa-times-circle" aria-hidden="true" title="Falhou"></span>''||',
'                        ''</div>''',
'                    else',
'                        ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start">''||',
'                        ''<span class="a-CardView-icon u-color fa fa-question-circle-o" aria-hidden="true" title="Outro estado"></span>''||',
'                        ''</div>''',
'                end                                                               as icon,',
'',
'                -- -- Atributos (cards)',
'                pkg_componentes.html_card_colunas(',
unistr('                    ''Pr\00F3xima Execu\00E7\00E3o'','),
'                    pkg_data.fmt(j.next_run_date,''DATA_SEGUNDO''),',
'                    3,''S''',
'                ) as atributo1,',
'',
'                pkg_componentes.html_card_colunas(',
unistr('                    ''\00DAltima Execu\00E7\00E3o'','),
'                    pkg_data.fmt(j.last_start_date,''DATA_SEGUNDO''),',
'                    3,''S''',
'                ) as atributo2,',
'',
'                pkg_componentes.html_card_colunas(',
unistr('                    ''Dura\00E7\00E3o \00DAltima Execu\00E7\00E3o'','),
'                    pkg_maestro_monitoramento.formatar_duration_job(j.last_run_duration),',
'                    3,''S''',
'                ) as atributo3,',
'',
'                pkg_componentes.html_card_colunas(',
unistr('                    ''Recorr\00EAncia'','),
'                    case',
unistr('                        when j.repeat_interval is null then ''Execu\00E7\00E3o \00FAnica'''),
'                        else pkg_maestro_monitoramento.fmt_repeat_interval(j.repeat_interval)',
'                    end,',
'                    3,''S''',
'                ) as atributo4,',
'',
'                null lista_distintivo,',
'',
unistr('                -- URL mais detalhes (voc\00EA mapeia para a p\00E1gina de detalhes/edi\00E7\00E3o do job)'),
'                pkg_ui.url_mais_detalhes(''TD1042'', nvl(a.id,0) )          as url_mais_detalhes,',
'',
unistr('                -- bot\00E3o op\00E7\00F5es'),
'                pkg_componentes.html_botao_opcao(nvl(a.id,0) ,''TD1042'')   as opcao',
'',
'            from user_scheduler_jobs j',
'            join mae_agenda_cfg a on a.job_name = j.job_name',
'            join srv_artefato c on c.id = a.id_artefato',
'            order by j.next_run_date nulls last, j.job_name;',
'            ~'';',
'',
'            return l_sql;',
'          ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'               a.id,',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''ind_execucao_assincrona'',ind_execucao_assincrona) campo1,',
'               plsql_entrypoint campo2,',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''modo_bloqueio_falha'',modo_bloqueio_falha) campo3,',
'               prioridade_padrao campo4,               ',
'               delay_execucao_seg campo5,      ',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''estrategia_retry'',estrategia_retry) campo6,      ',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''ind_coalescencia'',ind_coalescencia) campo7,      ',
'               null campo8,',
'               null campo9,',
'               null campo10,',
'               null filtro1,',
'               null filtro2,',
'               null filtro3,',
'               null filtro4,',
'               null filtro5,',
'               null filtro6,',
'               null filtro7,',
'               null filtro_mult1,                                ',
'               null filtro_mult2,                                ',
'               null filtro_mult3, ',
'               null filtro_mult4,                                ',
'               null filtro_mult5,                                  ',
'               null opcao                ',
'            from srv_artefato_cfg a',
'            join srv_artefato b on b.id = a.id_artefato',
'            where a.id_artefato = #PARAM1#',
'        ~'';   ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin   ',
'        return q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD1009'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''srv_artefato'')) a',
'            ~'';',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin  ',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.ind_execucao_assincrona'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.plsql_entrypoint'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.modo_bloqueio_falha'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.prioridade_padrao'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.delay_execucao_seg'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.estrategia_retry'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.ind_coalescencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''nome_artefato,descricao_artefato,codigo_artefato'';',
'        else',
'            campos := ''campo4,campo1,campo2'';',
'        end if;',
'        select pkg_ui.retorna_label_coluna(''srv_artefato.nome_artefato'') || '','' ||',
'           pkg_ui.retorna_label_coluna(''srv_artefato.descricao_artefato'') || '','' ||',
'           pkg_ui.retorna_label_coluna(''srv_artefato.codigo_artefato'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'end "UI_MPD_TD1042";',
'/'))
);
end;
/
