,p_name=>'UI_MPD_TD1013'
,p_sequence=>20
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1013" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'end "UI_MPD_TD1013";',
'/',
'create or replace package body "UI_MPD_TD1013" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'               a.id,',
'               b.nome_artefato ||'' - ''|| b.codigo_artefato titulo,',
unistr('               ''Total de Execu\00E7\00F5es: ''||RUN_COUNT ||'' \2022 Quantidade de Falhas: ''|| FAILURE_COUNT ||'' \2022 Intervalo de execu\00E7\00E3o: ''||intervalo_segundos||'' s''  subtitulo,'),
'               pkg_util.dominio_retorna_tag(''mae_sched_cfg'',''ind_sincronizar'',nvl(ind_sincronizar,''N'')) distintivo,',
'               null class_distintivo,',
'               null                 filtro1,',
'               null                 filtro2,',
'               null                 filtro3,',
'               null                 filtro4,',
'               null                 filtro5,',
'               null                 filtro6,',
'               null                 filtro7,',
'               pkg_ui.retorna_label_coluna(''srv_artefato.nome_artefato'') label_titulo,',
'               pkg_ui.retorna_label_coluna(''srv_artefato_cfg.plsql_entrypoint'') label_subtitulo,',
'               pkg_ui.retorna_label_coluna(''mae_sched_cfg.ind_sincronizar'') label_distintivo,  ',
'                case ',
'                    when exists (',
'                        select 1',
'                          from user_scheduler_jobs j',
'                         where j.job_name = ''JOB_MAE_WORKER_'' || a.id',
'                           and j.state = ''SCHEDULED''',
'                    ) then  ',
unistr('                        ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-color fa fa-check" aria-hidden="true" title="Execu\00E7\00E3o: Ativa"></span></div>'''),
'                    ',
'                    when exists (',
'                        select 1',
'                          from user_scheduler_jobs j',
'                         where j.job_name = ''JOB_MAE_WORKER_'' || a.id',
'                           and j.state = ''DISABLED''',
'                    ) then  ',
unistr('                        ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-color fa fa-pause-circle-o" aria-hidden="true" title="Execu\00E7\00E3o: Desabilitada"></span></div>'''),
'                    ',
'                    else',
unistr('                        ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-color fa fa-question-circle-o" aria-hidden="true" title="Execu\00E7\00E3o: N\00E3o encontrado ou outro estado"></span></div>'''),
'                end icon,  ',
'               ',
'',
unistr('               pkg_componentes.html_card_colunas(''Solicita\00E7\00F5es pendentes na fila'', (select count(1) from mae_solicitacao_execucao a1 where a1.id_artefato = a.id_artefato and a1.status = ''PENDENTE'') ,3,''S'') as atributo1,    '),
unistr('               pkg_componentes.html_card_colunas(''\00DAltima Execu\00E7\00E3o'',pkg_data.fmt(last_start_date,''DATA_SEGUNDO''),3,''S'') as atributo2,    '),
unistr('               pkg_componentes.html_card_colunas(''Pr\00F3xima Execu\00E7\00E3o'', pkg_data.fmt(last_start_date,''DATA_SEGUNDO'') ,3,''S'') as atributo3,    '),
unistr('               pkg_componentes.html_card_colunas(''Dura\00E7\00E3o da \00DAltima Execu\00E7\00E3o'',fn_formatar_duration_job(last_run_duration),3,''S'') as atributo4,    '),
'',
'               null lista_distintivo,',
'               pkg_ui.url_mais_detalhes(''TD1013'',a.id) url_mais_detalhes,',
'               pkg_componentes.html_botao_opcao(a.id,''TD1013'') as opcao                ',
'            from mae_sched_cfg a',
'            left join srv_artefato b on b.id = a.id_artefato',
'            left join srv_artefato_cfg c on c.id_artefato = b.id',
'            left join user_scheduler_jobs j',
'                on j.job_name = ''JOB_MAE_WORKER_'' || a.id',
'            ~'';',
'',
'            return l_sql;',
'          ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'               a.id,',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''ind_execucao_assincrona'',ind_execucao_assincrona) campo1,',
'               plsql_entrypoint campo2,',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''modo_bloqueio_falha'',modo_bloqueio_falha) campo3,',
'               prioridade_padrao campo4,               ',
'               delay_execucao_seg campo5,      ',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''estrategia_retry'',estrategia_retry) campo6,      ',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''ind_coalescencia'',ind_coalescencia) campo7,      ',
'               null campo8,',
'               null campo9,',
'               null campo10,',
'               null filtro1,',
'               null filtro2,',
'               null filtro3,',
'               null filtro4,',
'               null filtro5,',
'               null filtro6,',
'               null filtro7,',
'               null filtro_mult1,                                ',
'               null filtro_mult2,                                ',
'               null filtro_mult3, ',
'               null filtro_mult4,                                ',
'               null filtro_mult5,                                  ',
'               null opcao                ',
'            from srv_artefato_cfg a',
'            join srv_artefato b on b.id = a.id_artefato',
'            where a.id_artefato = #PARAM1#',
'        ~'';   ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin   ',
'        return q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD1009'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''srv_artefato'')) a',
'            ~'';',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin  ',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.ind_execucao_assincrona'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.plsql_entrypoint'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.modo_bloqueio_falha'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.prioridade_padrao'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.delay_execucao_seg'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.estrategia_retry'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.ind_coalescencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''nome_artefato,descricao_artefato,codigo_artefato'';',
'        else',
'            campos := ''campo4,campo1,campo2'';',
'        end if;',
'        select pkg_ui.retorna_label_coluna(''srv_artefato.nome_artefato'') || '','' ||',
'           pkg_ui.retorna_label_coluna(''srv_artefato.descricao_artefato'') || '','' ||',
'           pkg_ui.retorna_label_coluna(''srv_artefato.codigo_artefato'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'end "UI_MPD_TD1013";',
'/'))
);
end;
/
