'',
'        l_label_atributo1  := pkg_ui.retorna_label_coluna(''mae_registro_tecnico.dt_evento'');',
'        l_label_atributo2  := pkg_ui.retorna_label_coluna(''mae_registro_tecnico.detalhes'');',
'',
'        l_sql := q''~',
'            select',
'                a.id,',
'                pkg_data.fmt(a.dt_evento,''DATA_MILESIMO'') titulo,',
'                a.tipo_evento subtitulo,',
'',
'                ''#LABEL_TITULO#'' label_titulo,',
'                ''#LABEL_SUBTITULO#'' label_subtitulo,',
'                ''#LABEL_DISTINTIVO#'' label_distintivo,',
'',
'                case',
'                    when a.resultado in (''SUCESSO'',''OK'') then pkg_componentes.html_icone_lista(''fa-check-circle-o'')',
'                    when a.resultado in (''ERRO'',''FALHA'',''FALHA_TECNICA'',''FALHA_NEGOCIO'') then pkg_componentes.html_icone_lista(''fa-exclamation-triangle'')',
'                    when a.resultado in (''ALERTA'',''WARN'') then pkg_componentes.html_icone_lista(''fa-warning'')',
'                    else pkg_componentes.html_icone_lista(''fa-info-circle-o'')',
'                end icon,',
'',
'                nvl(a.resultado, ''-'') distintivo,',
'                case',
'                    when a.resultado in (''SUCESSO'',''OK'') then ''u-success''',
'                    when a.resultado in (''ERRO'',''FALHA'',''FALHA_TECNICA'',''FALHA_NEGOCIO'') then ''u-danger''',
'                    when a.resultado in (''ALERTA'',''WARN'') then ''u-warning''',
'                    else null',
'                end class_distintivo,',
'                null lista_distintivo,',
'',
'                -- pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO1#'', pkg_data.fmt(a.dt_evento,''DATA_SEGUNDO''), 3, ''S'') atributo1,',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO2#'', a.detalhes, '''', ''S'') atributo1,',
'',
'                -- FILTROS',
'                a.id_tenant filtro1,',
'                a.tipo_evento filtro2,',
'                a.resultado filtro3,',
'                a.id_solicitacao filtro4,',
'                a.id_worker filtro5,',
'                null filtro6,',
'                null filtro_mult1,',
'                null filtro_mult2,',
'',
unistr('                -- ORDENA\00C7\00C3O'),
'                a.dt_evento order1,',
'                a.id order2,',
'                null order3,',
'',
unistr('                -- T\00C9CNICO'),
'                pkg_ui.url_mais_detalhes(''TD002'', a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id, ''TD002'') opcao',
'            from mae_registro_tecnico a',
'            where #condicao# and #condicao1#',
'            order by dt_evento desc',
'        ~'';',
'',
'        l_sql := replace(l_sql,''#condicao#'','' id_solicitacao = ''||p_param1);',
'        if p_param4 is not null then',
'            l_sql := replace(l_sql,''#condicao1#'',''a.tipo_evento in (''||fn_trata_lista_in(p_param4)||'')'');',
'        else',
'            l_sql := replace(l_sql,''#condicao1#'',''1 = 1'');',
'        end if;',
'',
'        l_sql := replace(l_sql, ''#LABEL_TITULO#'', l_label_titulo);',
'        l_sql := replace(l_sql, ''#LABEL_SUBTITULO#'', l_label_subtitulo);',
'        l_sql := replace(l_sql, ''#LABEL_DISTINTIVO#'', l_label_distintivo);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO1#'', l_label_atributo1);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO2#'', l_label_atributo2);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO3#'', l_label_atributo3);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO4#'', l_label_atributo4);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO5#'', l_label_atributo5);',
'',
'        return l_sql;',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql       clob;',
'        l_id_idioma number;',
'    begin',
'        l_id_idioma := nvl(apex_util.get_session_state(''IDIOMA_LOGADO''),1);',
'',
'        l_sql := q''~',
'            select',
'                a.id id,',
'                a.id campo1,',
'                a.tipo_evento campo2,',
'                a.resultado campo3,',
'                a.id_solicitacao campo4,',
'                a.id_worker campo5,',
'                pkg_data.fmt(a.dt_evento, ''DATA_SEGUNDO'') campo6,',
'                a.id_correlation campo7,',
'                a.id_tenant campo8,',
'                dbms_lob.substr(a.detalhes, 4000, 1) campo9,',
'                null campo10,',
'',
'                -- FILTROS',
'                a.id_tenant filtro1,',
'                a.tipo_evento filtro2,',
'                a.resultado filtro3,',
'                a.id_solicitacao filtro4,',
'                a.id_worker filtro5,',
'                null filtro6,',
'                null filtro_mult1,',
'                null filtro_mult2,',
'                null filtro_mult3,',
'                null filtro_mult4,',
'                null filtro_mult5,',
'                null opcao',
'            from mae_registro_tecnico a',
'            where #condicao# and #condicao1#',
'            order by dt_evento desc',
'        ~'';',
'',
'        l_sql := replace(l_sql,''#condicao#'','' id_solicitacao = ''||p_param1);',
'        if p_param4 is not null then',
'            l_sql := replace(l_sql,''#condicao1#'',''a.tipo_evento in (''||fn_trata_lista_in(p_param4)||'')'');',
'        else',
'            l_sql := replace(l_sql,''#condicao1#'',''1 = 1'');',
'        end if;',
'',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql       clob;',
'        l_region_id number;',
'    begin',
'        select region_id',
'          into l_region_id',
'          from apex_application_page_regions',
'         where application_id = v(''APP_ID'')',
'           and page_id        = v(''APP_PAGE_ID'')',
'           and static_id      = ''LISTA_CR'';',
'',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD002'') as opcao',
'            from table(pkg_ui.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''mae_registro_tecnico'', #l_region_id#)) a',
'            order by',
'                to_timestamp(campo6, ''dd/mm/yyyy hh24:mi:ss'') desc,',
'                to_number(campo1) desc',
'        ~'';',
'',
'        l_sql := replace(l_sql, ''#l_region_id#'', l_region_id);',
'        return l_sql;',
'    end sql_report;',
'',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~',
'                select distinct tipo_evento d, tipo_evento r',
'                  from mae_registro_tecnico',
'                 where tipo_evento is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''3'' then',
'            return q''~',
'                select distinct resultado d, resultado r',
'                  from mae_registro_tecnico',
'                 where resultado is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''4'' then',
'            return q''~',
'                select distinct to_char(id_solicitacao) d, id_solicitacao r',
'                  from mae_registro_tecnico',
'                 where id_solicitacao is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''5'' then',
'            return q''~',
'                select distinct to_char(id_worker) d, id_worker r',
'                  from mae_registro_tecnico',
'                 where id_worker is not null',
'                 order by 1',
'            ~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;',
'    end sql_verifica_filtro;',
'',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id'')',
'              into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.tipo_evento'')',
'              into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.resultado'')',
'              into l_campo from dual;',
'        elsif campo in (''4'',''F4'') then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_solicitacao'')',
'              into l_campo from dual;',
'        elsif campo in (''5'',''F5'') then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_worker'')',
'              into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.dt_evento'')',
'              into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_correlation'')',
'              into l_campo from dual;',
'        elsif campo = ''8'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_tenant'')',
'              into l_campo from dual;',
'        elsif campo = ''9'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.detalhes'')',
'              into l_campo from dual;',
'        elsif campo = ''F1'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_tenant'')',
'              into l_campo from dual;',
'        elsif campo = ''F2'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.tipo_evento'')',
'              into l_campo from dual;',
'        elsif campo = ''F3'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.resultado'')',
'              into l_campo from dual;',
'        end if;',
'',
'        return l_campo;',
'    end label_coluna;',
'',
'',
'    function ordenacao',
'    return varchar2 is',
'    begin',
'        return q''~',
'            select ''Data do evento (mais recente primeiro)'' d, ''ORDER1D'' r from dual union all',
'            select ''ID (maior para menor)'' d, ''ORDER2D'' r from dual',
'        ~'';',
'    end;',
'',
'',
'    function default_ordenacao',
'    return varchar2 is',
'    begin',
'        return ''ORDER1D&ORDER2D'';',
'    end;',
'',
'end "UI_MPD_TD1038";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1039
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262140599958853)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'UI_MPD_TD1039'
,p_sequence=>80
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1039" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    ',
'end "UI_MPD_TD1039";',
'/',
'create or replace package body "UI_MPD_TD1039" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is ',
'        l_ind_tipo_movimento imp_processoimportacao_numerario.ind_tipo_movimento%type; ',
'        l_id_tenant number;',
'        l_id_moeda_nacional number;',
'    begin ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null dependencia, null '
||'atribuir_valor, null executa_js from dual union all',
'               SELECT p_codigo_artefato, ''id_artefato'',                         3, '''',null, '''', '''', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_negocio'',                          5, '''',null, '''', '''', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''parametros'',                          6, '''',null, '''', '''', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''prioridade'',                          7, '''',null, '''', '''', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''tipo_acao'',                           8, '''',null, '''', '''', null valor, null dependencia, null atribuir_valor, null executa_js from dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js);',
'    end formulario;',
'    ',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'        l_id number;',
'    begin',
'        l_id := pkg_maestro_api.postar_requisicao(',
'            p_id_artefato       => apex_application.g_f03(1),',
'            p_id_tenant         => apex_application.g_f01(1),',
'            p_id_usuario        => apex_util.get_session_state(''ID_USUARIO_LOGADO''),',
'            p_id_negocio        => apex_application.g_f05(1),',
'            p_payload           => apex_application.g_f06(1),',
'            p_prioridade        => apex_application.g_f07(1),',
'            p_tipo_acao         => apex_application.g_f08(1)',
'        );',
'    end;',
'',
'end "UI_MPD_TD1039";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1043
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262288065953071)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'UI_MPD_TD1043'
,p_sequence=>90
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1043" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD1043";',
'/',
'create or replace package body UI_MPD_TD1043 as',
'',
'  procedure formulario(',
'      p_codigo_artefato in varchar2,',
'      p_param1 in varchar2 default null,',
'      p_param2 in varchar2 default null',
'  ) is',
'  begin',
'    /*',
unistr('      Observa\00E7\00E3o: esta UI usa temp_formulario exatamente como o seu padr\00E3o.'),
'      Ajuste os "nome_consulta" para suas LOVs reais.',
'    */',
'',
'    merge into temp_formulario tf',
'    using (',
unistr('      -- Identifica\00E7\00E3o do Job'),
'      select p_codigo_artefato as codigo_artefato, ''id_tenant'' as nome_coluna, 1 as indice,',
'             ''SEL'' as tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' as nome_consulta, ''N'' as somente_leitura, ''N'' as coluna_tabela, ''S'' obrigatorio, ''TD1043.ID_TENANT'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''job_name'', 2,',
'             ''TXT'', '''', ''N'', ''N'', ''S'', ''TD1043.JOB_NAME'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''codigo_artefato'', 3,',
'             ''SEL'', ''R_SRV_ARTEFATO.NOME_ARTEFATO_MAESTRO'', ''N'', ''N'', ''S'', ''TD1043.CODIGO_ARTEFATO'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''tipo_agendamento'', 4,',
'             ''SEL'', ''D_MAESTRO.TIPO_AGENDAMENTO'', ''N'', ''N'', ''S'', ''TD1043.TIPO_AGENDAMENTO'' tag_campo ',
'        from dual union all',
'',
'      select p_codigo_artefato, ''start_date'', 5,',
'             ''DAH'', null, ''N'', ''N'', ''S'', ''TD1043.START_DATE'' tag_campo',
'        from dual union all',
'',
unistr('      -- Recorr\00EAncia (op\00E7\00F5es MVP)'),
unistr('      -- Se tipo_agendamento = RECORRENTE, usu\00E1rio informa:'),
'      select p_codigo_artefato, ''repeat_freq'', 6,',
'             ''SEL'', ''D_MAESTRO.FREQUENCIA_REPETICAO'', ''N'', ''N'', ''N'', ''TD1043.REPEAT_FREQ'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''repeat_interval'', 7,',
'             ''TXT'', null, ''N'', ''N'', ''N'', ''TD1043.REPEAT_INTERVAL'' tag_campo',
'        from dual union all',
'',
'      -- Dados MAESTRO',
'',
'      select p_codigo_artefato, ''id_negocio'', 8,',
'             ''TXT'', null, ''N'', ''N'', ''N'', ''TD1043.ID_NEGOCIO'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''payload'', 9,',
'             ''TEX'', null, ''N'', ''N'', ''N'', ''TD1043.PAYLOAD'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''prioridade'', 10,',
'             ''TXT'', null, ''N'', ''N'', ''N'', ''TD1043.PRIORIDADE'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''tipo_acao'', 11,',
'             ''TXT'', null, ''N'', ''N'', ''N'', ''TD1043.TIPO_ACAO'' tag_campo',
'        from dual union all',
'',
'      select p_codigo_artefato, ''enabled'', 12,',
'             ''SEL'', ''D_GERAL.SIM_NAO'', ''N'', ''N'', ''S'' , ''TD1043.ENABLED'' tag_campo',
'        from dual ',
'',
'',
'    ) new_data',
'    on (tf.codigo_artefato = new_data.codigo_artefato and tf.nome_coluna = new_data.nome_coluna)',
'    when not matched then',
'      insert (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, obrigatorio, tag_campo)',
'      values (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.obrigatorio, new_data.tag_campo);',
'',
'  end formulario;',
'',
'procedure post(',
'    p_id in number default null,',
'    p_sucesso out clob,',
'    p_messages out pkg_mensagem.message_record_table',
') is',
'  l_job_name        varchar2(128);',
'  l_enabled         varchar2(10);',
'  l_tipo_ag         varchar2(20);',
'  l_start_date      date;',
'',
'  l_repeat_freq     varchar2(3000);',
'  l_repeat_interval varchar2(4000);',
'',
'  l_id_tenant       number;',
'  l_cod_artefato    varchar2(50);',
'  l_id_negocio      varchar2(200);',
'  l_payload         clob;',
'  l_prioridade      number;',
'  l_tipo_acao       varchar2(50);',
'',
'  l_id_usuario      number;',
'begin',
'  /*',
unistr('    Ordem do FORMUL\00C1RIO (UI_MPD_TD1043):'),
'      1  id_tenant',
'      2  job_name',
'      3  codigo_artefato',
'      4  tipo_agendamento',
'      5  start_date',
'      6  repeat_freq',
unistr('      7  repeat_interval   (amig\00E1vel ou t\00E9cnico; backend decide)'),
'      8  id_negocio',
'      9  payload',
'      10 prioridade',
'      11 tipo_acao',
'      12 enabled',
'  */',
'',
'  l_id_tenant       := to_number(apex_application.g_f01(1));',
'  l_job_name        := apex_application.g_f02(1);',
'  l_cod_artefato    := apex_application.g_f03(1);',
'  l_tipo_ag         := apex_application.g_f04(1);',
'',
unistr('  -- Ajuste a m\00E1scara conforme o item DAT do seu APEX'),
'  l_start_date      := to_date(apex_application.g_f05(1), ''DD/MM/YYYY HH24:MI:SS'');',
'',
'  l_repeat_freq     := apex_application.g_f06(1);',
'  l_repeat_interval := apex_application.g_f07(1);',
'',
'  l_id_negocio      := apex_application.g_f08(1);',
'  l_payload         := apex_application.g_f09(1);',
'',
'  l_prioridade      := case',
'                         when trim(apex_application.g_f10(1)) is not null',
'                         then to_number(apex_application.g_f10(1))',
'                       end;',
'',
'  l_tipo_acao       := apex_application.g_f11(1);',
'  l_enabled         := apex_application.g_f12(1); -- ''S''/''N''',
'',
unistr('  -- Resolve usu\00E1rio do contexto APEX'),
'  select id',
'    into l_id_usuario',
'    from mpd_usuario',
'    where upper(login) = pkg_maestro_monitoramento.fn_obter_usuario_atual;',
'',
'',
'',
'  -- Cria/atualiza JOB no DBMS_SCHEDULER + grava MAE_AGENDA_CFG',
unistr('  -- A procedure SALVAR_AGENDAMENTO j\00E1 faz toda a interpreta\00E7\00E3o do repeat_interval.'),
'  pkg_maestro_monitoramento.salvar_agendamento(',
'      p_job_name        => l_job_name,',
'      p_enabled         => l_enabled,',
'      p_start_date      => l_start_date,',
'',
unistr('      -- Se n\00E3o for recorrente, passa null e vira execu\00E7\00E3o \00FAnica'),
'      p_repeat_interval => case',
'                             when l_tipo_ag = ''RECORRENTE''',
'                             then nullif(trim(l_repeat_interval), '''')',
'                             else null',
'                           end,',
'',
'      p_id_tenant       => l_id_tenant,',
'      p_codigo_artefato => l_cod_artefato,',
'      p_id_usuario      => l_id_usuario,',
'      p_id_negocio      => l_id_negocio,',
'      p_payload         => l_payload,',
'      p_prioridade      => l_prioridade,',
'      p_tipo_acao       => l_tipo_acao,',
'',
'      p_sucesso         => p_sucesso,',
'      p_messages        => p_messages,',
'',
unistr('      -- Frequ\00EAncia s\00F3 faz sentido se for recorrente'),
'      p_repeat_freq     => case',
'                             when l_tipo_ag = ''RECORRENTE''',
'                             then nullif(trim(l_repeat_freq), '''')',
'                             else null',
'                           end',
'',
unistr('      -- demais par\00E2metros opcionais ficam default/null'),
'  );',
'',
'exception',
'  when no_data_found then',
'    raise_application_error(-20001, ''MAE-AGENDA|NO_DATA_FOUND no POST. APP_USER=''||v(''APP_USER''));',
'  when others then',
'    raise_application_error(-20001, ''MAE-AGENDA|Falha no POST: ''||substr(sqlerrm,1,300));',
'    ',
'end post;',
'',
'end UI_MPD_TD1043;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_admin
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262414759946289)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_ADMIN'
,p_sequence=>100
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_admin is',
'',
'    c_oper_reprocessar_mensagem constant varchar2(50) := ''ADMIN_REPROCESSAR_MENSAGEM'';',
'    c_oper_alterar_status       constant varchar2(50) := ''ADMIN_ALTERAR_STATUS'';',
'    c_oper_expurgo_manual       constant varchar2(50) := ''ADMIN_EXPURGO_MANUAL'';',
'    c_oper_alterar_configuracao constant varchar2(50) := ''ADMIN_ALTERAR_CONFIGURACAO'';',
'    c_oper_desbloquear_mensagem constant varchar2(50) := ''ADMIN_DESBLOQUEAR_MENSAGEM'';',
'    v_parametro pkg_mensagem.paramentros;',
'',
'    function get_operador_atual return varchar2;',
'',
'    function is_operador_autorizado(',
'        p_operacao in varchar2,',
'        p_operador in varchar2 default null',
'    ) return boolean;',
'',
'    procedure assert_permissao(',
'        p_operacao  in varchar2,',
'        p_id_tenant in number default null',
'    );',
'',
'end pkg_maestro_admin;',
'/',
'create or replace package body pkg_maestro_admin is',
'',
'    function normalizar_usuario(',
'        p_usuario in varchar2',
'    ) return varchar2',
'    is',
'    begin',
'        return upper(trim(p_usuario));',
'    end normalizar_usuario;',
'',
'',
'    function get_operador_atual return varchar2',
'    is',
'        l_app_user          varchar2(200);',
'        l_client_identifier varchar2(200);',
'        l_user              varchar2(200);',
'    begin',
'        -------------------------------------------------------------------',
unistr('        -- 1) Sess\00E3o APEX'),
'        -------------------------------------------------------------------',
'        begin',
'            l_app_user := v(''APP_USER'');',
'        exception',
'            when others then',
'                l_app_user := null;',
'        end;',
'',
'        if trim(l_app_user) is not null then',
'            return normalizar_usuario(l_app_user);',
'        end if;',
'',
'        -------------------------------------------------------------------',
'        -- 2) CLIENT_IDENTIFIER',
'        -------------------------------------------------------------------',
'        begin',
'            l_client_identifier := sys_context(''USERENV'', ''CLIENT_IDENTIFIER'');',
'        exception',
'            when others then',
'                l_client_identifier := null;',
'        end;',
'',
'        if trim(l_client_identifier) is not null then',
'            return normalizar_usuario(l_client_identifier);',
'        end if;',
'',
'        -------------------------------------------------------------------',
'        -- 3) DB USER',
'        -------------------------------------------------------------------',
'        l_user := user;',
'        return normalizar_usuario(l_user);',
'    end get_operador_atual;',
'',
'',
'    function is_operador_autorizado(',
'        p_operacao in varchar2,',
'        p_operador in varchar2 default null',
'    ) return boolean',
'    is',
'        l_operador varchar2(200);',
'        l_dummy    number;',
'        l_id_usuario number;',
'    begin',
'        l_operador := normalizar_usuario(nvl(p_operador, get_operador_atual));',
'',
'        if l_operador is null then',
'            return false;',
'        end if;',
'',
'        select id into l_id_usuario from mpd_usuario where upper(login) = upper(l_operador);',
'',
'        -------------------------------------------------------------------',
'        -- MVP:',
unistr('        -- qualquer usu\00E1rio ativo em MAE_ADMIN_OPERADOR pode executar'),
unistr('        -- qualquer opera\00E7\00E3o administrativa'),
'        -------------------------------------------------------------------',
'        select 1',
'          into l_dummy',
'          from mae_admin_operador',
'         where id_usuario = l_id_usuario',
'           and ativo = ''S''',
'           and rownum = 1;',
'',
'        return true;',
'',
'    exception',
'        when no_data_found then',
'            return false;',
'    end is_operador_autorizado;',
'',
'',
'    procedure assert_permissao(',
'        p_operacao  in varchar2,',
'        p_id_tenant in number default null',
'    )',
'    is',
'        l_operador varchar2(200);',
'        l_operacao varchar2(100);',
'    begin',
'        l_operador := get_operador_atual;',
'        l_operacao := upper(trim(p_operacao));',
'',
'        if l_operacao is null then',
'            raise_application_error(',
'                -20001,',
unistr('                ''Opera\00E7\00E3o administrativa inv\00E1lida: opera\00E7\00E3o n\00E3o informada.'''),
'            );',
'        end if;',
'',
'        if not is_operador_autorizado(',
'            p_operacao => l_operacao,',
'            p_operador => l_operador',
'        ) then',
'            raise_application_error(',
'                -20001,',
unistr('                ''Opera\00E7\00E3o administrativa n\00E3o autorizada (OPERACAO='' ||'),
'                l_operacao || '', OPERADOR='' || nvl(l_operador, ''<null>'') || '').''',
'            );',
'        end if;',
'    end assert_permissao;',
'',
'end pkg_maestro_admin;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_api
