,p_name=>'PKG_MAESTRO_API'
,p_sequence=>110
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_api as',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-35 \2013 Permiss\00F5es de reprocessamento manual'),
'    -------------------------------------------------------------------',
'    c_err_reproc_sem_permissao       constant number := -20023;',
