'    function usuario_pode_reprocessar(',
'        p_id_usuario     in number',
'    ) return boolean;',
'',
'    procedure validar_permissao_reprocessamento(',
'        p_id_usuario in number',
'    );    ',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-34 \2013 Reprocessamento manual'),
'    -------------------------------------------------------------------',
'',
'    function status_elegivel_reprocessamento(',
'        p_status in varchar2',
'    ) return boolean;',
'',
'    procedure registrar_reprocessamento_manual(',
'        p_id_solicitacao  in number,',
'        p_id_tenant       in number,',
'        p_id_artefato     in number,',
'        p_id_negocio      in varchar2,',
