'    );',
'',
'    procedure reprocessar(',
'        p_id in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table    ',
'    );',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-18 \2013 Normaliza\00E7\00E3o de coalesc\00EAncia'),
'    -------------------------------------------------------------------',
'    function normalizar_ind_coalescencia(',
'        p_ind_coalescencia in varchar2',
'    ) return varchar2;',
'',
'    function coalescencia_habilitada(',
'        p_ind_coalescencia in varchar2',
'    ) return boolean;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-21 \2013 Pol\00EDtica de payload da coalesc\00EAncia'),
'    -------------------------------------------------------------------',
'    function get_politica_payload_coalescencia',
'        return varchar2;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-08 \2013 Resolu\00E7\00E3o de prioridade'),
'    -------------------------------------------------------------------',
'    function resolver_prioridade(',
'        p_prioridade     in number,',
'        p_prioridade_def in number',
'    ) return number;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-24 \2013 Normaliza\00E7\00E3o / fallback do modo de bloqueio'),
'    -------------------------------------------------------------------',
'    function normalizar_modo_bloqueio_falha(',
'        p_modo_bloqueio_falha in varchar2',
'    ) return varchar2;',
'',
'    -------------------------------------------------------------------',
unistr('    -- Valida\00E7\00F5es de contexto'),
'    -------------------------------------------------------------------',
'    function validar_usuario(',
'        p_id_usuario in number',
'    ) return number;',
'',
'    function validar_tenant_usuario(',
'        p_id_tenant  in number,',
'        p_id_usuario in number',
'    ) return number;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-24 \2013 Carregar configura\00E7\00E3o do artefato'),
'    -- Retorna:',
'    --   - id_artefato',
unistr('    --   - prioridade padr\00E3o'),
unistr('    --   - delay de execu\00E7\00E3o padr\00E3o'),
unistr('    --   - indicador de coalesc\00EAncia'),
'    --   - modo de bloqueio por falha',
'    -------------------------------------------------------------------',
'    procedure validar_artefato(',
'        p_codigo_artefato        in varchar2,',
'        p_id_artefato            out number,',
'        p_prioridade_def         out number,',
'        p_delay_execucao_seg     out number,',
'        p_ind_coalescencia       out varchar2,',
'        p_modo_bloqueio_falha    out varchar2',
'    );',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-19 / ST-CI-20 \2013 Coalesc\00EAncia'),
'    -------------------------------------------------------------------',
'    function buscar_pendente_equivalente(',
'        p_id_tenant   in number,',
'        p_id_artefato in number,',
'        p_id_negocio  in varchar2',
'    ) return number;',
'',
'    function tentar_coalescer_pendente(',
'        p_id_solicitacao         in number,',
'        p_id_artefato            in number,',
'        p_delay_execucao_seg     in number,',
'        p_id_tenant              in number,',
'        p_id_negocio             in varchar2,',
'        p_codigo_artefato        in varchar2,',
'        p_id_correlation         in varchar2',
'    ) return number;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-22 \2013 Observabilidade t\00E9cnica da coalesc\00EAncia / postagem'),
'    -------------------------------------------------------------------',
'    procedure registrar_coalesce_create(',
'        p_id_solicitacao           in number,',
'        p_id_tenant                in number,',
'        p_id_artefato              in number,',
'        p_codigo_artefato          in varchar2,',
'        p_id_negocio               in varchar2,',
'        p_delay_execucao_seg       in number,',
'        p_dt_disponivel_execucao   in timestamp with time zone,',
'        p_id_equivalente           in number,',
'        p_id_correlation           in varchar2,',
'        p_motivo_create            in varchar2 default null',
'    );',
'',
'    procedure registrar_coalesce_update(',
'        p_id_solicitacao                 in number,',
'        p_id_tenant                      in number,',
'        p_id_artefato                    in number,',
'        p_codigo_artefato                in varchar2,',
'        p_id_negocio                     in varchar2,',
'        p_delay_execucao_seg             in number,',
'        p_dt_disponivel_execucao_ant     in timestamp with time zone,',
'        p_dt_disponivel_execucao_nova    in timestamp with time zone,',
'        p_id_correlation                 in varchar2',
'    );',
'',
'    procedure registrar_postagem_padrao(',
'        p_id_solicitacao           in number,',
'        p_id_tenant                in number,',
'        p_id_artefato              in number,',
'        p_codigo_artefato          in varchar2,',
'        p_id_negocio               in varchar2,',
'        p_prioridade               in number,',
'        p_delay_execucao_seg       in number,',
'        p_ind_coalescencia         in varchar2,',
'        p_dt_disponivel_execucao   in timestamp with time zone,',
'        p_id_correlation           in varchar2',
'    );',
'',
'    -------------------------------------------------------------------',
'    -- API principal',
'    -------------------------------------------------------------------',
'    function postar_requisicao(',
'        p_codigo_artefato   in varchar2,',
'        p_id_tenant         in number,',
'        p_id_usuario        in number,',
'        p_id_negocio        in varchar2 default 0,',
'        p_payload           in clob     default null,',
'        p_prioridade        in number   default null,',
'        p_tipo_acao         in varchar2 default null,',
'        p_id_correlation    in varchar2 default null',
'    ) return number;',
'',
'    function postar_requisicao(',
'        p_id_artefato       in number,',
'        p_id_tenant         in number,',
'        p_id_usuario        in number,',
'        p_id_negocio        in varchar2 default 0,',
'        p_payload           in clob     default null,',
'        p_prioridade        in number   default null,',
'        p_tipo_acao         in varchar2 default null,',
'        p_id_correlation    in varchar2 default null',
'    ) return number;',
'',
'    -------------------------------------------------------------------',
'    -- Wrapper APEX',
'    -------------------------------------------------------------------',
'    function postar_requisicao_apex(',
'        p_codigo_artefato   in varchar2,',
'        p_id_tenant         in number   default null,',
'        p_id_negocio        in varchar2 default null,',
'        p_payload           in clob     default null,',
'        p_prioridade        in number   default null,',
'        p_tipo_acao         in varchar2 default null,',
'        p_id_correlation    in varchar2 default null',
'    ) return number;',
'',
'end pkg_maestro_api;',
'/',
'create or replace package body pkg_maestro_api as',
'',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-66 \2013 Validar tamanho de payload/conte\00FAdo'),
'    -------------------------------------------------------------------',
'    function obter_tamanho_clob(',
'        p_clob in clob',
'    ) return number',
'    is',
'    begin',
'        if p_clob is null then',
'            return 0;',
'        end if;',
'',
'        return dbms_lob.getlength(p_clob);',
'    end obter_tamanho_clob;',
'',
'    procedure registrar_evento_queue_abuse_rejected(',
'        p_tipo           in varchar2,',
'        p_id_artefato    in number,',
'        p_id_usuario     in number,',
'        p_id_tenant      in number,',
'        p_id_negocio     in varchar2,',
'        p_id_correlation in varchar2,',
'        p_tamanho        in number,',
'        p_maximo         in number',
'    ) is',
'        pragma autonomous_transaction;',
'        l_detalhes clob;',
'    begin',
'        l_detalhes :=',
'              ''TIPO='' || nvl(trim(p_tipo), ''<null>'')',
'           || ''; ID_USUARIO='' || nvl(to_char(p_id_usuario), ''<null>'')',
'           || ''; ID_TENANT='' || nvl(to_char(p_id_tenant), ''<null>'')',
'           || ''; ID_ARTEFATO='' || nvl(to_char(p_id_artefato), ''<null>'')',
'           || ''; ID_NEGOCIO='' || nvl(to_char(p_id_negocio), ''<null>'')',
'           || ''; TAMANHO='' || nvl(to_char(p_tamanho), ''<null>'')',
'           || ''; MAX='' || nvl(to_char(p_maximo), ''<null>'');',
'',
'        pkg_maestro_evento.registrar_evento(',
'            p_id_solicitacao => null,',
'            p_id_worker      => null,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_correlation => p_id_correlation,',
'            p_tipo_evento    => ''QUEUE_ABUSE_REJECTED'',',
'            p_resultado      => ''REJEITADO'',',
'            p_detalhes       => l_detalhes',
'        );',
'        commit;',
'    end registrar_evento_queue_abuse_rejected;    ',
'',
'    procedure validar_tamanho_payload_conteudo(',
'        p_id_artefato    in number,',
'        p_id_usuario     in number,',
'        p_id_tenant      in number,',
'        p_id_negocio     in varchar2,',
'        p_id_correlation in varchar2,',
'        p_parametros     in clob',
'    ) is',
'        l_max_payload   number;',
'        l_tam_payload   number;',
'    begin',
'        l_max_payload  := pkg_maestro_cfg.obter_max_payload_bytes(',
'            p_id_artefato => p_id_artefato',
'        );',
'',
'        l_tam_payload  := obter_tamanho_clob(p_parametros);',
'',
'        -------------------------------------------------------------------',
unistr('        -- Prioridade de rejei\00E7\00E3o no MVP:'),
unistr('        -- payload primeiro, depois conte\00FAdo'),
'        -------------------------------------------------------------------',
'        if l_max_payload is not null and l_tam_payload > l_max_payload then',
'            registrar_evento_queue_abuse_rejected(',
'                p_tipo           => ''PAYLOAD_SIZE'',',
'                p_id_artefato    => p_id_artefato,',
'                p_id_usuario     => p_id_usuario,',
'                p_id_tenant      => p_id_tenant,',
'                p_id_negocio     => p_id_negocio,',
'                p_id_correlation => p_id_correlation,',
'                p_tamanho        => l_tam_payload,',
'                p_maximo         => l_max_payload',
'            );',
'            commit;',
'            raise_application_error(',
'                -20001,',
'                ''MAE-API-PAYLOAD_EXCEDIDO|Postagem rejeitada: payload excede limite (TAM='' ||',
'                l_tam_payload || '', MAX='' || l_max_payload || '')''',
'            );',
'        end if;',
'',
'    end validar_tamanho_payload_conteudo;    ',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-35 \2013 Regra MVP de autoriza\00E7\00E3o para reprocessamento'),
unistr('    -- Estrat\00E9gia atual:'),
unistr('    --   - usu\00E1rio precisa existir em MPD_USUARIO'),
unistr('    --   - usu\00E1rio precisa estar explicitamente autorizado nesta regra'),
'    --',
unistr('    -- Observa\00E7\00E3o:'),
unistr('    --   esta implementa\00E7\00E3o \00E9 simples e centralizada, preparada para'),
unistr('    --   futura evolu\00E7\00E3o para perfis, grupos, tenant e artefato.'),
'    -------------------------------------------------------------------',
'    function usuario_pode_reprocessar(',
'        p_id_usuario in number',
'    ) return boolean',
'    is',
'        l_flag mpd_usuario.ind_pode_reprocessar_maestro%type;',
'    begin',
'',
'        if p_id_usuario is null then',
'            return false;',
'        end if;',
'',
'        select ind_pode_reprocessar_maestro',
'          into l_flag',
'          from mpd_usuario',
'         where id = p_id_usuario;',
'',
'        return l_flag = ''S'';',
'',
'    exception',
'        when no_data_found then',
'            return false;',
'    end usuario_pode_reprocessar;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-35 \2013 Valida\00E7\00E3o fail-fast da permiss\00E3o de reprocessamento'),
'    -------------------------------------------------------------------',
'    procedure validar_permissao_reprocessamento(',
'        p_id_usuario in number',
'    ) is',
'    begin',
'        if p_id_usuario is null then',
'            raise_application_error(',
'                c_err_reproc_usuario_invalido,',
unistr('                ''MAE-API-REPROCESSAR_USUARIO_INVALIDO|Usu\00E1rio n\00E3o informado'''),
'            );',
'        end if;',
'',
'        pkg_maestro_admin.assert_permissao(',
'            p_operacao  => pkg_maestro_admin.c_oper_reprocessar_mensagem,',
'            p_id_tenant => null',
'        );',
'',
'        -- if not usuario_pode_reprocessar(p_id_usuario) then',
'        --     raise_application_error(',
'        --         c_err_reproc_sem_permissao,',
'        --         ''MAE-API-REPROCESSAR_SEM_PERMISSAO|Acesso negado''',
'        --     );',
'        -- end if;',
'    end validar_permissao_reprocessamento;',
'    ',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-34 \2013 Status eleg\00EDveis para reprocessamento manual'),
'    -------------------------------------------------------------------',
'    function status_elegivel_reprocessamento(',
'        p_status in varchar2',
'    ) return boolean',
'    is',
'        l_status varchar2(30);',
'    begin',
'        l_status := upper(trim(p_status));',
'',
'        return l_status in (',
'            ''FALHA_NEGOCIO'',',
'            ''FALHA_TECNICA'',',
'            ''ERRO_FINAL''',
'        );',
'    end status_elegivel_reprocessamento;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-34 \2013 Rastreabilidade m\00EDnima do reprocessamento manual'),
'    -------------------------------------------------------------------',
'    procedure registrar_reprocessamento_manual(',
'        p_id_solicitacao  in number,',
'        p_id_tenant       in number,',
'        p_id_artefato     in number,',
'        p_id_negocio      in varchar2,',
'        p_status_anterior in varchar2,',
'        p_id_correlation  in varchar2',
'    ) is',
'        l_detalhes varchar2(4000);',
'    begin',
'        l_detalhes :=',
'            ''id_artefato='' || nvl(to_char(p_id_artefato), c_msg_null) ||',
'            ''; id_negocio='' || nvl(trim(p_id_negocio), c_msg_null) ||',
'            ''; status_anterior='' || nvl(trim(p_status_anterior), c_msg_null) ||',
'            ''; status_novo='' || c_status_pendente ||',
'            ''; tentativas_nova=0'' ||',
'            ''; dt_disponivel_execucao_nova='' ||',
'                to_char(agora_utc, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM'');',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            null,',
'            agora_utc,',
'            c_evt_reprocessamento_manual,',
'            ''INFO'',',
'            substr(l_detalhes, 1, 4000),',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'    end registrar_reprocessamento_manual;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-34 \2013 Reprocessamento manual'),
'    -- Regras:',
unistr('    --   - s\00F3 permite FALHA_NEGOCIO / FALHA_TECNICA / ERRO_FINAL'),
'    --   - volta para PENDENTE',
'    --   - zera tentativas',
unistr('    --   - limpa contexto de execu\00E7\00E3o'),
'    --   - preserva motivo_falha',
unistr('    --   - atualiza\00E7\00E3o at\00F4mica por PK + status no WHERE'),
'    -------------------------------------------------------------------',
'    procedure reprocessar(',
'        p_id_solicitacao in number,',
'        p_id_usuario     in number',
'    ) is',
'        l_status_atual            mae_solicitacao_execucao.status%type;',
'        l_id_tenant               mae_solicitacao_execucao.id_tenant%type;',
'        l_id_artefato             mae_solicitacao_execucao.id_artefato%type;',
'        l_id_negocio              mae_solicitacao_execucao.id_negocio%type;',
'        l_id_correlation          mae_solicitacao_execucao.id_correlation%type;',
'        l_delay_execucao_seg      number;',
'        l_dt_disponivel_execucao  timestamp with time zone;',
'        l_agora_utc              timestamp with time zone;',
'    begin',
'        ----------------------------------------------------------------',
unistr('        -- ST-CI-35 \2013 Permiss\00E3o antes de qualquer altera\00E7\00E3o de dados'),
'        ----------------------------------------------------------------',
'        validar_permissao_reprocessamento(',
'            p_id_usuario => p_id_usuario',
'        );',
'',
'        if p_id_solicitacao is null then',
'            raise_application_error(',
'                c_err_reproc_nao_encontrado,',
unistr('                ''MAE-API-REPROCESSAR_ID_OBRIGATORIO|Informe o id da solicita\00E7\00E3o'''),
'            );',
'        end if;',
'',
'        select a.status,',
'               a.id_tenant,',
'               a.id_artefato,',
'               a.id_negocio,',
'               a.id_correlation,',
'               delay_execucao_seg',
'          into l_status_atual,',
'               l_id_tenant,',
'               l_id_artefato,',
'               l_id_negocio,',
'               l_id_correlation,',
'               l_delay_execucao_seg',
'          from mae_solicitacao_execucao a',
'          join srv_artefato_cfg b on b.id_artefato = a.id_artefato',
'         where a.id = p_id_solicitacao',
'           for update;',
'',
'        if not status_elegivel_reprocessamento(l_status_atual) then',
'            raise_application_error(',
'                c_err_reproc_status_invalido,',
unistr('                ''MAE-API-REPROCESSAR_STATUS_INVALIDO|Solicita\00E7\00E3o n\00E3o eleg\00EDvel para reprocessamento. Status atual='' ||'),
'                l_status_atual',
'            );',
'        end if;',
'',
'        l_agora_utc := agora_utc;',
'        l_dt_disponivel_execucao :=',
'            l_agora_utc + numtodsinterval(l_delay_execucao_seg, ''SECOND'');',
'',
'',
'        update mae_solicitacao_execucao',
'           set status                 = c_status_pendente,',
'               tentativas             = 0,',
'               dt_disponivel_execucao = l_dt_disponivel_execucao,',
'               dt_inicio              = null,',
'               dt_fim                 = null,',
'               id_worker              = null,',
'               dt_saude               = null',
'         where id = p_id_solicitacao',
'           and status in (',
'               ''FALHA_NEGOCIO'',',
'               ''FALHA_TECNICA'',',
'               ''ERRO_FINAL''',
'           );',
'',
'        if sql%rowcount = 0 then',
'            raise_application_error(',
'                c_err_reproc_status_invalido,',
unistr('                ''MAE-API-REPROCESSAR_CONCORRENCIA|Solicita\00E7\00E3o n\00E3o p\00F4de ser reenfileirada porque o status mudou durante a opera\00E7\00E3o'''),
'            );',
'        end if;',
'',
'        registrar_reprocessamento_manual(',
'            p_id_solicitacao  => p_id_solicitacao,',
'            p_id_tenant       => l_id_tenant,',
'            p_id_artefato     => l_id_artefato,',
'            p_id_negocio      => l_id_negocio,',
'            p_status_anterior => l_status_atual,',
'            p_id_correlation  => l_id_correlation',
'        );',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                c_err_reproc_nao_encontrado,',
unistr('                ''MAE-API-REPROCESSAR_NAO_ENCONTRADO|Solicita\00E7\00E3o inexistente: '' || p_id_solicitacao'),
'            );',
'    end reprocessar;       ',
'',
'    procedure reprocessar(',
'        p_id in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table    ',
'    )is',
'    begin',
'        reprocessar(',
'            p_id_solicitacao => p_id,',
'            p_id_usuario     => 124',
'            -- p_id_usuario     => pkg_maestro_admin.get_operador_atual',
'        );',
'    end;    ',
'',
'    -------------------------------------------------------------------',
unistr('    -- Utilit\00E1rios internos'),
'    -------------------------------------------------------------------',
'    function obter_modo_bloqueio_falha(',
'        p_id_artefato in number',
'    ) return varchar2',
'    is',
'        l_modo varchar2(30);',
'    begin',
'        select normalizar_modo_bloqueio_falha(cfg.modo_bloqueio_falha)',
'          into l_modo',
'          from srv_artefato_cfg cfg',
'         where cfg.id_artefato = p_id_artefato;',
'',
'        return l_modo;',
'',
'    exception',
'        when no_data_found then',
'            return c_modo_bloqueio_nenhum;',
'    end obter_modo_bloqueio_falha;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-24 \2013 Normaliza\00E7\00E3o do modo de bloqueio por falha'),
'    -- Regra:',
unistr('    --   - null, vazio ou inv\00E1lido => NENHUM'),
unistr('    --   - valores v\00E1lidos:'),
'    --       NENHUM',
'    --       ID_NEGOCIO',
'    --       FILA',
'    -------------------------------------------------------------------',
'    function normalizar_modo_bloqueio_falha(',
'        p_modo_bloqueio_falha in varchar2',
'    ) return varchar2',
'    is',
'        l_valor varchar2(30);',
'    begin',
'        l_valor := upper(trim(p_modo_bloqueio_falha));',
'',
'        if l_valor = c_modo_bloqueio_nenhum then',
'            return c_modo_bloqueio_nenhum;',
'        elsif l_valor = c_modo_bloqueio_id_negocio then',
'            return c_modo_bloqueio_id_negocio;',
'        elsif l_valor = c_modo_bloqueio_fila then',
'            return c_modo_bloqueio_fila;',
'        end if;',
'',
'        return c_modo_bloqueio_nenhum;',
'    end normalizar_modo_bloqueio_falha;',
'',
'    -------------------------------------------------------------------',
unistr('    -- Utilit\00E1rios b\00E1sicos'),
'    -------------------------------------------------------------------',
'    function gerar_correlation_id return varchar2',
'    is',
'    begin',
'        return lower(rawtohex(sys_guid()));',
'    end gerar_correlation_id;',
'',
'    function agora_utc return timestamp with time zone',
'    is',
'    begin',
'        return systimestamp at time zone ''UTC'';',
'    end agora_utc;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-08 \2013 Normaliza\00E7\00E3o e resolu\00E7\00E3o de prioridade'),
'    -------------------------------------------------------------------',
'    function normalizar_prioridade(',
'        p_prioridade in number',
'    ) return number',
'    is',
'    begin',
'        if p_prioridade is null then',
'            return 0;',
'        elsif p_prioridade < 0 then',
'            return 0;',
'        else',
'            return p_prioridade;',
'        end if;',
'    end normalizar_prioridade;',
'',
'    function resolver_prioridade(',
'        p_prioridade     in number,',
'        p_prioridade_def in number',
'    ) return number',
'    is',
'    begin',
'        if p_prioridade is not null then',
'            return normalizar_prioridade(p_prioridade);',
'        end if;',
'',
'        if p_prioridade_def is not null then',
'            return normalizar_prioridade(p_prioridade_def);',
'        end if;',
'',
'        return 0;',
'    end resolver_prioridade;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-13 / ST-CI-15 \2013 Normaliza\00E7\00E3o do delay'),
'    -------------------------------------------------------------------',
'    function normalizar_delay_execucao(',
'        p_delay_segundos in number',
'    ) return number',
'    is',
'    begin',
'        if p_delay_segundos is null then',
'            return 0;',
'        elsif p_delay_segundos < 0 then',
'            return 0;',
'        else',
'            return p_delay_segundos;',
'        end if;',
'    end normalizar_delay_execucao;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-18 \2013 Normaliza\00E7\00E3o da coalesc\00EAncia'),
'    -------------------------------------------------------------------',
'    function normalizar_ind_coalescencia(',
'        p_ind_coalescencia in varchar2',
'    ) return varchar2',
'    is',
'    begin',
'        if upper(trim(p_ind_coalescencia)) = c_ind_sim then',
'            return c_ind_sim;',
'        else',
'            return c_ind_nao;',
'        end if;',
'    end normalizar_ind_coalescencia;',
'',
'    function coalescencia_habilitada(',
'        p_ind_coalescencia in varchar2',
'    ) return boolean',
'    is',
'    begin',
'        return normalizar_ind_coalescencia(p_ind_coalescencia) = c_ind_sim;',
'    end coalescencia_habilitada;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-21 \2013 Pol\00EDtica de payload da coalesc\00EAncia'),
'    -------------------------------------------------------------------',
'    function get_politica_payload_coalescencia',
'        return varchar2',
'    is',
'    begin',
'        return c_politica_payload_coalescencia;',
'    end get_politica_payload_coalescencia;',
'',
'    -------------------------------------------------------------------',
unistr('    -- Valida\00E7\00F5es de contexto'),
'    -------------------------------------------------------------------',
'    function validar_usuario(',
'        p_id_usuario in number',
'    ) return number',
'    is',
'        l_id number;',
'    begin',
'        if p_id_usuario is null then',
'            raise_application_error(',
'                c_err_usuario_obrigatorio,',
'                ''MAE-API-USUARIO_OBRIGATORIO|Informe o id_usuario''',
'            );',
'        end if;',
'',
'        select id',
'          into l_id',
'          from mpd_usuario',
'         where id = p_id_usuario;',
'',
'        return l_id;',
'',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                c_err_usuario_invalido,',
unistr('                ''MAE-API-USUARIO_INVALIDO|Usu\00E1rio n\00E3o existe em MPD_USUARIO'''),
'            );',
'    end validar_usuario;',
'',
'    function validar_tenant_usuario(',
'        p_id_tenant  in number,',
'        p_id_usuario in number',
'    ) return number',
'    is',
'        l_cnt number;',
'    begin',
'        if p_id_tenant is null then',
'            raise_application_error(',
'                c_err_tenant_indisp,',
'                ''MAE-API-TENANT_INDISPONIVEL|Informe o id_tenant''',
'            );',
''))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(16262468931944393)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'        end if;',
'',
'        select count(1)',
'          into l_cnt',
'          from mpd_usuario_tenant ut',
'         where ut.id_usuario = p_id_usuario',
'           and ut.id_tenant  = p_id_tenant;',
'',
'        if l_cnt = 0 then',
'            raise_application_error(',
'                c_err_tenant_nao_perm,',
unistr('                ''MAE-API-TENANT_NAO_PERMITIDO|Usu\00E1rio n\00E3o possui acesso ao tenant informado'''),
'            );',
'        end if;',
'',
'        return p_id_tenant;',
'    end validar_tenant_usuario;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-24 \2013 Carregar configura\00E7\00E3o do artefato'),
'    -- Fonte real:',
'    --   prioridade   -> SRV_ARTEFATO_CFG.PRIORIDADE_PADRAO',
'    --   delay        -> SRV_ARTEFATO_CFG.DELAY_EXECUCAO_SEG',
unistr('    --   coalesc\00EAncia -> SRV_ARTEFATO_CFG.IND_COALESCENCIA'),
'    --   bloqueio     -> SRV_ARTEFATO_CFG.MODO_BLOQUEIO_FALHA',
'    -------------------------------------------------------------------',
'    procedure validar_artefato(',
'        p_codigo_artefato        in varchar2,',
'        p_id_artefato            out number,',
'        p_prioridade_def         out number,',
'        p_delay_execucao_seg     out number,',
'        p_ind_coalescencia       out varchar2,',
'        p_modo_bloqueio_falha    out varchar2',
'    ) is',
'        l_ind_execucao_assincrona varchar2(1);',
'        l_modo_bloqueio_raw       varchar2(30);',
'    begin',
'        if trim(p_codigo_artefato) is null then',
'            raise_application_error(',
'                c_err_artefato_invalido,',
unistr('                ''MAE-API-ARTEFATO_INVALIDO|codigo_artefato \00E9 obrigat\00F3rio'''),
'            );',
'        end if;',
'',
'        select a.id,',
'               cfg.prioridade_padrao,',
'               cfg.delay_execucao_seg,',
'               nvl(cfg.ind_execucao_assincrona, c_ind_nao),',
'               case',
'                   when upper(trim(cfg.ind_coalescencia)) = c_ind_sim then c_ind_sim',
'                   else c_ind_nao',
'               end,',
'               cfg.modo_bloqueio_falha',
'          into p_id_artefato,',
'               p_prioridade_def,',
'               p_delay_execucao_seg,',
'               l_ind_execucao_assincrona,',
'               p_ind_coalescencia,',
'               l_modo_bloqueio_raw',
'          from srv_artefato a',
'          left join srv_artefato_cfg cfg',
'            on cfg.id_artefato = a.id',
'         where upper(a.codigo_artefato) = upper(trim(p_codigo_artefato));',
'',
'        p_prioridade_def      := normalizar_prioridade(p_prioridade_def);',
'        p_delay_execucao_seg  := normalizar_delay_execucao(p_delay_execucao_seg);',
'        p_ind_coalescencia    := normalizar_ind_coalescencia(p_ind_coalescencia);',
'        p_modo_bloqueio_falha := normalizar_modo_bloqueio_falha(l_modo_bloqueio_raw);',
'',
'        if l_ind_execucao_assincrona = c_ind_nao then',
'            raise_application_error(',
'                c_err_artefato_invalido,',
'                ''MAE-API-ARTEFATO_DESABILITADO|Artefato desabilitado para assincronia''',
'            );',
'        end if;',
'',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                c_err_artefato_invalido,',
'                ''MAE-API-ARTEFATO_INVALIDO|Artefato inexistente''',
'            );',
'    end validar_artefato;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-19 \2013 Buscar mensagem pendente equivalente'),
'    -- Regra MVP:',
'    --   id_tenant',
'    --   id_artefato',
'    --   id_negocio',
'    --   status = PENDENTE',
'    -------------------------------------------------------------------',
'    function buscar_pendente_equivalente(',
'        p_id_tenant   in number,',
'        p_id_artefato in number,',
'        p_id_negocio  in varchar2',
'    ) return number',
'    is',
'        l_id_solicitacao number;',
'        l_id_negocio     mae_solicitacao_execucao.id_negocio%type;',
'    begin',
'        if p_id_tenant is null',
'           or p_id_artefato is null',
'        then',
'            return null;',
'        end if;',
'',
'        l_id_negocio := trim(p_id_negocio);',
'',
'        select id',
'          into l_id_solicitacao',
'          from (',
'                select /*+ index(m IX_MAE_SOL_COALESCENCIA) */',
'                       m.id',
'                  from mae_solicitacao_execucao m',
'                 where m.id_tenant   = p_id_tenant',
'                   and m.id_artefato = p_id_artefato',
'                   and m.status      = c_status_pendente',
'                   and (',
'                        (l_id_negocio is null and m.id_negocio is null)',
'                        or',
'                        (l_id_negocio is not null and m.id_negocio = l_id_negocio)',
'                   )',
'                 order by m.dt_criacao asc,',
'                          m.id asc',
'               )',
'         where rownum = 1;',
'',
'        return l_id_solicitacao;',
'',
'    exception',
'        when no_data_found then',
'            return null;',
'    end buscar_pendente_equivalente;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-22 \2013 Registro t\00E9cnico de cria\00E7\00E3o em contexto de coalesc\00EAncia'),
'    -------------------------------------------------------------------',
'    procedure registrar_coalesce_create(',
'        p_id_solicitacao           in number,',
'        p_id_tenant                in number,',
'        p_id_artefato              in number,',
'        p_codigo_artefato          in varchar2,',
'        p_id_negocio               in varchar2,',
'        p_delay_execucao_seg       in number,',
'        p_dt_disponivel_execucao   in timestamp with time zone,',
'        p_id_equivalente           in number,',
'        p_id_correlation           in varchar2,',
'        p_motivo_create            in varchar2 default null',
'    ) is',
'        l_delay_normalizado number;',
'        l_detalhes          varchar2(4000);',
'        l_dt_evento         timestamp with time zone;',
'    begin',
'        l_delay_normalizado := normalizar_delay_execucao(p_delay_execucao_seg);',
'        l_dt_evento := agora_utc;',
'',
'        l_detalhes :=',
'            ''codigo_artefato='' || trim(p_codigo_artefato) ||',
'            ''; id_artefato='' || to_char(p_id_artefato) ||',
'            ''; id_negocio='' || nvl(trim(p_id_negocio), c_msg_null) ||',
'            ''; delay_segundos='' || to_char(l_delay_normalizado) ||',
'            ''; dt_disponivel_execucao_nova='' ||',
'                to_char(p_dt_disponivel_execucao, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM'') ||',
'            ''; politica_payload='' || get_politica_payload_coalescencia ||',
'            ''; payload_atualizado='' || c_ind_nao ||',
'            ''; id_equivalente='' || nvl(to_char(p_id_equivalente), c_msg_null);',
'',
'        if trim(p_motivo_create) is not null then',
'            l_detalhes := l_detalhes || ''; motivo_create='' || trim(p_motivo_create);',
'        end if;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            null,',
'            l_dt_evento,',
'            c_evt_coalesce_create,',
'            ''INFO'',',
'            l_detalhes,',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'    end registrar_coalesce_create;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-22 \2013 Registro t\00E9cnico de atualiza\00E7\00E3o por coalesc\00EAncia'),
'    -------------------------------------------------------------------',
'    procedure registrar_coalesce_update(',
'        p_id_solicitacao                 in number,',
'        p_id_tenant                      in number,',
'        p_id_artefato                    in number,',
'        p_codigo_artefato                in varchar2,',
'        p_id_negocio                     in varchar2,',
'        p_delay_execucao_seg             in number,',
'        p_dt_disponivel_execucao_ant     in timestamp with time zone,',
'        p_dt_disponivel_execucao_nova    in timestamp with time zone,',
'        p_id_correlation                 in varchar2',
'    ) is',
'        l_delay_normalizado number;',
'        l_detalhes          varchar2(4000);',
'        l_dt_evento         timestamp with time zone;',
'    begin',
'        l_delay_normalizado := normalizar_delay_execucao(p_delay_execucao_seg);',
'        l_dt_evento := agora_utc;',
'',
'        l_detalhes :=',
'            ''codigo_artefato='' || trim(p_codigo_artefato) ||',
'            ''; id_artefato='' || to_char(p_id_artefato) ||',
'            ''; id_negocio='' || nvl(trim(p_id_negocio), c_msg_null) ||',
'            ''; delay_segundos='' || to_char(l_delay_normalizado) ||',
'            ''; dt_disponivel_execucao_anterior='' ||',
'                to_char(p_dt_disponivel_execucao_ant, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM'') ||',
'            ''; dt_disponivel_execucao_nova='' ||',
'                to_char(p_dt_disponivel_execucao_nova, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM'') ||',
'            ''; politica_payload='' || get_politica_payload_coalescencia ||',
'            ''; payload_atualizado='' || c_ind_nao;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            null,',
'            l_dt_evento,',
'            c_evt_coalesce_update,',
'            ''INFO'',',
'            l_detalhes,',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'    end registrar_coalesce_update;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-18 / ST-CI-22 \2013 Log t\00E9cnico padr\00E3o da postagem'),
'    -------------------------------------------------------------------',
'    procedure registrar_postagem_padrao(',
'        p_id_solicitacao           in number,',
'        p_id_tenant                in number,',
'        p_id_artefato              in number,',
'        p_codigo_artefato          in varchar2,',
'        p_id_negocio               in varchar2,',
'        p_prioridade               in number,',
'        p_delay_execucao_seg       in number,',
'        p_ind_coalescencia         in varchar2,',
'        p_dt_disponivel_execucao   in timestamp with time zone,',
'        p_id_correlation           in varchar2',
'    ) is',
'        l_delay_normalizado number;',
'        l_detalhes          varchar2(4000);',
'        l_dt_evento         timestamp with time zone;',
'    begin',
'        l_delay_normalizado := normalizar_delay_execucao(p_delay_execucao_seg);',
'        l_dt_evento := agora_utc;',
'',
'        l_detalhes :=',
'            ''codigo_artefato='' || trim(p_codigo_artefato) ||',
'            ''; id_artefato='' || to_char(p_id_artefato) ||',
'            ''; id_negocio='' || nvl(trim(p_id_negocio), c_msg_null) ||',
'            ''; prioridade='' || to_char(p_prioridade) ||',
'            ''; delay_execucao_seg='' || to_char(l_delay_normalizado) ||',
'            ''; coalescencia_habilitada='' || p_ind_coalescencia ||',
'            ''; dt_disponivel_execucao='' ||',
'                to_char(p_dt_disponivel_execucao, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM'');',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            null,',
'            l_dt_evento,',
'            c_evt_requisicao_postada,',
'            ''INFO'',',
'            l_detalhes,',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'    end registrar_postagem_padrao;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-20 / ST-CI-21 / ST-CI-22 \2013 Tentar coalescer em pendente'),
'    -- Atualiza apenas DT_DISPONIVEL_EXECUCAO',
'    -------------------------------------------------------------------',
'    function tentar_coalescer_pendente(',
'        p_id_solicitacao         in number,',
'        p_id_artefato            in number,',
'        p_delay_execucao_seg     in number,',
'        p_id_tenant              in number,',
'        p_id_negocio             in varchar2,',
'        p_codigo_artefato        in varchar2,',
'        p_id_correlation         in varchar2',
'    ) return number',
'    is',
'        l_agora_utc              timestamp with time zone;',
'        l_novo_dt_disponivel     timestamp with time zone;',
'        l_dt_disponivel_anterior timestamp with time zone;',
'        l_delay_normalizado      number;',
'    begin',
'        if p_id_solicitacao is null then',
'            return null;',
'        end if;',
'',
'        l_delay_normalizado := normalizar_delay_execucao(p_delay_execucao_seg);',
'',
'        select dt_disponivel_execucao',
'          into l_dt_disponivel_anterior',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao;',
'',
'        l_agora_utc := agora_utc;',
'        l_novo_dt_disponivel :=',
'            l_agora_utc + numtodsinterval(l_delay_normalizado, ''SECOND'');',
'',
'        update mae_solicitacao_execucao',
'           set dt_disponivel_execucao = l_novo_dt_disponivel',
'         where id = p_id_solicitacao',
'           and status = c_status_pendente;',
'',
'        if sql%rowcount = 1 then',
'            registrar_coalesce_update(',
'                p_id_solicitacao              => p_id_solicitacao,',
'                p_id_tenant                   => p_id_tenant,',
'                p_id_artefato                 => p_id_artefato,',
'                p_codigo_artefato             => p_codigo_artefato,',
'                p_id_negocio                  => p_id_negocio,',
'                p_delay_execucao_seg          => l_delay_normalizado,',
'                p_dt_disponivel_execucao_ant  => l_dt_disponivel_anterior,',
'                p_dt_disponivel_execucao_nova => l_novo_dt_disponivel,',
'                p_id_correlation              => p_id_correlation',
'            );',
'',
'            return p_id_solicitacao;',
'        end if;',
'',
'        return null;',
'    end tentar_coalescer_pendente;',
'',
'    -------------------------------------------------------------------',
unistr('    -- CORE \2013 Postar requisi\00E7\00E3o'),
'    -------------------------------------------------------------------',
'    function postar_requisicao(',
'        p_id_artefato       in number,',
'        p_id_tenant         in number,',
'        p_id_usuario        in number,',
'        p_id_negocio        in varchar2 default 0,',
'        p_payload           in clob     default null,',
'        p_prioridade        in number   default null,',
'        p_tipo_acao         in varchar2 default null,',
'        p_id_correlation    in varchar2 default null',
'    ) return number is',
'        l_codigo_artefato srv_artefato.codigo_artefato%type;',
'    begin',
'        select codigo_artefato into l_codigo_artefato from srv_artefato where id = p_id_artefato;',
'        return postar_requisicao(',
'            p_codigo_artefato   => l_codigo_artefato,',
'            p_id_tenant         => p_id_tenant,',
'            p_id_usuario        => p_id_usuario,',
'            p_id_negocio        => p_id_negocio,',
'            p_payload           => p_payload,',
'            p_prioridade        => p_prioridade,',
'            p_tipo_acao         => p_tipo_acao,',
'            p_id_correlation    => p_id_correlation',
'        );',
'        exception',
'            when no_data_found then',
'                raise_application_error(',
'                    c_err_artefato_invalido,',
unistr('                    ''MAE-API-ARTEFATO_INVALIDO|Id do artefato informa\00E7\00E3o n\00E3o existe.'''),
'                );        ',
'    end;',
'',
'    function postar_requisicao(',
'        p_codigo_artefato   in varchar2,',
'        p_id_tenant         in number,',
'        p_id_usuario        in number,',
'        p_id_negocio        in varchar2 default 0,',
'        p_payload           in clob     default null,',
'        p_prioridade        in number   default null,',
'        p_tipo_acao         in varchar2 default null,',
'        p_id_correlation    in varchar2 default null',
'    ) return number',
'    is',
'        l_id_solicitacao          number;',
'        l_id_artefato             number;',
'        l_prio_def                number;',
'        l_delay_execucao_seg      number;',
'        l_prioridade              number;',
'        l_corr                    varchar2(64);',
'        l_usuario_id              number;',
'        l_tenant_id               number;',
'        l_agora_utc               timestamp with time zone;',
'        l_dt_disponivel_execucao  timestamp with time zone;',
'        l_ind_coalescencia        varchar2(1);',
'        l_coalescencia_habilitada boolean;',
'        l_id_equivalente          number;',
'        l_id_coalescido           number;',
'        l_motivo_create           varchar2(50);',
'        l_modo_bloqueio_falha     varchar2(30);',
'    begin',
'        ----------------------------------------------------------------',
unistr('        -- 1) Validar usu\00E1rio e tenant'),
'        ----------------------------------------------------------------',
'        l_usuario_id := validar_usuario(p_id_usuario);',
'',
'        l_tenant_id := validar_tenant_usuario(',
'            p_id_tenant  => p_id_tenant,',
'            p_id_usuario => l_usuario_id',
'        );',
'',
'        ----------------------------------------------------------------',
unistr('        -- 2) Validar artefato e carregar configura\00E7\00F5es'),
'        ----------------------------------------------------------------',
'        validar_artefato(',
'            p_codigo_artefato     => p_codigo_artefato,',
'            p_id_artefato         => l_id_artefato,',
'            p_prioridade_def      => l_prio_def,',
'            p_delay_execucao_seg  => l_delay_execucao_seg,',
'            p_ind_coalescencia    => l_ind_coalescencia,',
'            p_modo_bloqueio_falha => l_modo_bloqueio_falha',
'        );',
'',
'        ----------------------------------------------------------------',
unistr('        -- 3) Normaliza\00E7\00F5es de entrada'),
'        ----------------------------------------------------------------',
'        l_prioridade := resolver_prioridade(',
'            p_prioridade     => p_prioridade,',
'            p_prioridade_def => l_prio_def',
'        );',
'',
'        l_corr := case',
'                    when trim(p_id_correlation) is not null',
'                    then trim(p_id_correlation)',
'                    else gerar_correlation_id',
'                  end;',
'',
'        ----------------------------------------------------------------',
'        -- 4) Validar tamanho do payload',
'        ----------------------------------------------------------------',
'        validar_tamanho_payload_conteudo(',
'            p_id_artefato    => l_id_artefato,',
'            p_id_usuario     => p_id_usuario,',
'            p_id_negocio     => p_id_negocio,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_correlation => l_corr,',
'            p_parametros     => p_payload',
'        );                  ',
'',
'        l_coalescencia_habilitada := coalescencia_habilitada(l_ind_coalescencia);',
'',
'        l_id_equivalente := null;',
'        l_id_coalescido  := null;',
'        l_motivo_create  := null;',
'',
'        ----------------------------------------------------------------',
'        -- 4) Tentar coalescer quando habilitado e com id_negocio informado',
'        ----------------------------------------------------------------',
'        if l_coalescencia_habilitada then',
'            l_id_equivalente := buscar_pendente_equivalente(',
'                p_id_tenant   => l_tenant_id,',
'                p_id_artefato => l_id_artefato,',
'                p_id_negocio  => trim(p_id_negocio)',
'            );',
'',
'            if l_id_equivalente is not null then',
'                l_id_coalescido := tentar_coalescer_pendente(',
'                    p_id_solicitacao     => l_id_equivalente,',
'                    p_id_artefato        => l_id_artefato,',
'                    p_delay_execucao_seg => l_delay_execucao_seg,',
'                    p_id_tenant          => l_tenant_id,',
'                    p_id_negocio         => trim(p_id_negocio),',
'                    p_codigo_artefato    => trim(p_codigo_artefato),',
'                    p_id_correlation     => l_corr',
'                );',
'',
'                if l_id_coalescido is not null then',
'                    return l_id_coalescido;',
'                end if;',
'',
'                l_motivo_create := c_msg_motivo_update_0_linhas;',
'            else',
'                l_motivo_create := c_msg_motivo_sem_equivalente;',
'            end if;',
'        end if;',
'',
'        ----------------------------------------------------------------',
unistr('        -- 5) Base temporal \00FAnica em UTC para nova linha'),
'        ----------------------------------------------------------------',
'        l_agora_utc := agora_utc;',
'        l_dt_disponivel_execucao :=',
'            l_agora_utc + numtodsinterval(l_delay_execucao_seg, ''SECOND'');',
'',
'        ----------------------------------------------------------------',
unistr('        -- 6) Persist\00EAncia m\00EDnima'),
'        ----------------------------------------------------------------',
'        insert into mae_solicitacao_execucao (',
'            id_tenant,',
'            id_usuario,',
'            id_artefato,',
'            tipo_acao,',
'            status,',
'            prioridade,',
'            parametros,',
'            dt_criacao,',
'            dt_disponivel_execucao,',
'            tentativas,',
'            id_worker,',
'            id_negocio,',
'            id_correlation',
'        ) values (',
'            l_tenant_id,',
'            l_usuario_id,',
'            l_id_artefato,',
'            p_tipo_acao,',
'            c_status_pendente,',
'            l_prioridade,',
'            p_payload,',
'            l_agora_utc,',
'            l_dt_disponivel_execucao,',
'            0,',
'            null,',
'            trim(p_id_negocio),',
'            l_corr',
'        )',
'        returning id into l_id_solicitacao;',
'',
'        ----------------------------------------------------------------',
unistr('        -- 7) Observabilidade t\00E9cnica'),
'        ----------------------------------------------------------------',
'        if l_coalescencia_habilitada then',
'            registrar_postagem_padrao(',
'                p_id_solicitacao         => l_id_solicitacao,',
'                p_id_tenant              => l_tenant_id,',
'                p_id_artefato            => l_id_artefato,',
'                p_codigo_artefato        => trim(p_codigo_artefato),',
'                p_id_negocio             => trim(p_id_negocio),',
'                p_prioridade             => l_prioridade,',
'                p_delay_execucao_seg     => l_delay_execucao_seg,',
'                p_ind_coalescencia       => l_ind_coalescencia,',
'                p_dt_disponivel_execucao => l_dt_disponivel_execucao,',
'                p_id_correlation         => l_corr',
'            );        ',
'            registrar_coalesce_create(',
'                p_id_solicitacao         => l_id_solicitacao,',
'                p_id_tenant              => l_tenant_id,',
'                p_id_artefato            => l_id_artefato,',
'                p_codigo_artefato        => trim(p_codigo_artefato),',
'                p_id_negocio             => trim(p_id_negocio),',
'                p_delay_execucao_seg     => l_delay_execucao_seg,',
'                p_dt_disponivel_execucao => l_dt_disponivel_execucao,',
'                p_id_equivalente         => l_id_equivalente,',
'                p_id_correlation         => l_corr,',
'                p_motivo_create          => l_motivo_create',
'            );',
'        else',
'            registrar_postagem_padrao(',
'                p_id_solicitacao         => l_id_solicitacao,',
'                p_id_tenant              => l_tenant_id,',
'                p_id_artefato            => l_id_artefato,',
'                p_codigo_artefato        => trim(p_codigo_artefato),',
'                p_id_negocio             => trim(p_id_negocio),',
'                p_prioridade             => l_prioridade,',
'                p_delay_execucao_seg     => l_delay_execucao_seg,',
'                p_ind_coalescencia       => l_ind_coalescencia,',
'                p_dt_disponivel_execucao => l_dt_disponivel_execucao,',
'                p_id_correlation         => l_corr',
'            );',
'        end if;',
'',
'        return l_id_solicitacao;',
'    end postar_requisicao;',
'',
'    -------------------------------------------------------------------',
'    -- Wrapper APEX',
'    -------------------------------------------------------------------',
'    function postar_requisicao_apex(',
'        p_codigo_artefato   in varchar2,',
'        p_id_tenant         in number   default null,',
'        p_id_negocio        in varchar2 default null,',
'        p_payload           in clob     default null,',
'        p_prioridade        in number   default null,',
'        p_tipo_acao         in varchar2 default null,',
'        p_id_correlation    in varchar2 default null',
'    ) return number',
'    is',
'        l_id_usuario number;',
'        l_id_tenant  number;',
'    begin',
'        select id',
'          into l_id_usuario',
'          from mpd_usuario',
'         where upper(login) = upper(v(''APP_USER''));',
'',
'        if p_id_tenant is null then',
'            l_id_tenant := to_number(apex_util.get_session_state(''P0_TENANT_INFORMADO''));',
'',
'            if l_id_tenant is null then',
'                l_id_tenant := to_number(apex_util.get_session_state(''P0_TENANT_SUGERIDO''));',
'            end if;',
'        else',
'            l_id_tenant := p_id_tenant;',
'        end if;',
'',
'        return postar_requisicao(',
'            p_codigo_artefato => p_codigo_artefato,',
'            p_id_tenant       => l_id_tenant,',
'            p_id_usuario      => l_id_usuario,',
'            p_id_negocio      => p_id_negocio,',
'            p_payload         => p_payload,',
'            p_prioridade      => p_prioridade,',
'            p_tipo_acao       => p_tipo_acao,',
'            p_id_correlation  => p_id_correlation',
'        );',
'',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                c_err_usuario_invalido,',
unistr('                ''MAE-API-USUARIO_INVALIDO|APP_USER n\00E3o cadastrado em MPD_USUARIO'''),
'            );',
'    end postar_requisicao_apex;',
'',
'',
'end pkg_maestro_api;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_cfg
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262571505942469)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_CFG'
,p_sequence=>120
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_cfg as',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-65 \2013 Circuit breaker por falha t\00E9cnica do artefato'),
'    -------------------------------------------------------------------',
'    subtype t_cb_estado is varchar2(20);',
'',
'    c_cb_fechado     constant t_cb_estado := ''FECHADO'';',
'    c_cb_aberto      constant t_cb_estado := ''ABERTO'';',
'    c_cb_meio_aberto constant t_cb_estado := ''MEIO_ABERTO'';',
'',
'    c_cb_result_permitido      constant varchar2(30) := ''PERMITIDO'';',
'    c_cb_result_bloqueado      constant varchar2(30) := ''BLOQUEADO'';',
'    c_cb_result_teste_halfopen constant varchar2(30) := ''TESTE_HALF_OPEN'';',
'',
'    type r_circuit_breaker_cfg is record (',
'        id_artefato               srv_artefato_cfg.id_artefato%type,',
'        ind_circuit_breaker       srv_artefato_cfg.ind_circuit_breaker%type,',
'        cb_qtd_falhas_abertura    srv_artefato_cfg.cb_qtd_falhas_abertura%type,',
'        cb_cooldown_seg           srv_artefato_cfg.cb_cooldown_seg%type,',
'        cb_estado                 srv_artefato_cfg.cb_estado%type,',
'        cb_falhas_consecutivas    srv_artefato_cfg.cb_falhas_consecutivas%type,',
'        cb_dt_ultima_falha        srv_artefato_cfg.cb_dt_ultima_falha%type,',
'        cb_dt_abertura            srv_artefato_cfg.cb_dt_abertura%type,',
'        cb_ind_teste_em_andamento srv_artefato_cfg.cb_ind_teste_em_andamento%type',
'    );',
'',
'    function get_cb_estado(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return varchar2;',
'',
'    function obter_circuit_breaker_cfg(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return r_circuit_breaker_cfg;',
'',
'    function tentar_permitir_execucao_cb(',
'        p_id_artefato      in srv_artefato_cfg.id_artefato%type,',
'        p_id_solicitacao   in mae_solicitacao_execucao.id%type,',
'        p_id_worker        in number,',
'        p_id_tenant        in number,',
'        p_id_correlation   in varchar2',
'    ) return varchar2;',
'',
'    procedure registrar_falha_tecnica_cb(',
'        p_id_artefato      in srv_artefato_cfg.id_artefato%type,',
'        p_id_solicitacao   in mae_solicitacao_execucao.id%type,',
'        p_id_worker        in number,',
'        p_id_tenant        in number,',
'        p_id_correlation   in varchar2,',
'        p_detalhe          in clob default null',
'    );',
'',
'    procedure registrar_sucesso_cb(',
'        p_id_artefato      in srv_artefato_cfg.id_artefato%type,',
'        p_id_solicitacao   in mae_solicitacao_execucao.id%type,',
'        p_id_worker        in number,',
'        p_id_tenant        in number,',
'        p_id_correlation   in varchar2',
'    );',
'',
'    procedure resetar_circuit_breaker(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    );',
'',
