'    -------------------------------------------------------------------',
unistr('    -- ST-CI-65 \2013 Circuit breaker por falha t\00E9cnica do artefato'),
'    -------------------------------------------------------------------',
'    function get_cb_estado(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return varchar2',
'    is',
'        l_estado srv_artefato_cfg.cb_estado%type;',
'    begin',
'        if p_id_artefato is null then',
'            return c_cb_fechado;',
'        end if;',
'',
'        begin',
'            select nvl(cb_estado, c_cb_fechado)',
'              into l_estado',
'              from srv_artefato_cfg',
'             where id_artefato = p_id_artefato;',
'        exception',
'            when no_data_found then',
'                return c_cb_fechado;',
'        end;',
'',
'        return l_estado;',
'    end get_cb_estado;',
'',
'    function obter_circuit_breaker_cfg(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return r_circuit_breaker_cfg',
'    is',
'        l_cfg r_circuit_breaker_cfg;',
'    begin',
'        select',
'            id_artefato,',
'            nvl(ind_circuit_breaker, ''N''),',
'            nvl(cb_qtd_falhas_abertura, 0),',
'            nvl(cb_cooldown_seg, 0),',
'            nvl(cb_estado, c_cb_fechado),',
'            nvl(cb_falhas_consecutivas, 0),',
'            cb_dt_ultima_falha,',
'            cb_dt_abertura,',
'            nvl(cb_ind_teste_em_andamento, ''N'')',
'        into',
'            l_cfg.id_artefato,',
'            l_cfg.ind_circuit_breaker,',
'            l_cfg.cb_qtd_falhas_abertura,',
'            l_cfg.cb_cooldown_seg,',
'            l_cfg.cb_estado,',
'            l_cfg.cb_falhas_consecutivas,',
'            l_cfg.cb_dt_ultima_falha,',
'            l_cfg.cb_dt_abertura,',
'            l_cfg.cb_ind_teste_em_andamento',
'        from srv_artefato_cfg',
'        where id_artefato = p_id_artefato;',
'',
'        return l_cfg;',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                -20001,',
'                ''Configuracao de circuit breaker nao encontrada para o artefato '' || p_id_artefato',
'            );',
'    end obter_circuit_breaker_cfg;',
'',
'',
'    procedure registrar_evento_cb(',
'        p_id_solicitacao in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_tipo_evento    in varchar2,',
'        p_resultado      in varchar2,',
'        p_detalhes       in clob',
'    ) is',
'    begin',
'        pkg_maestro_evento.registrar_evento(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => p_id_worker,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_correlation => p_id_correlation,',
'            p_tipo_evento    => p_tipo_evento,',
'            p_resultado      => p_resultado,',
'            p_detalhes       => p_detalhes',
'        );',
'    end registrar_evento_cb;',
'',
'',
'    function tentar_permitir_execucao_cb(',
'        p_id_artefato      in srv_artefato_cfg.id_artefato%type,',
'        p_id_solicitacao   in mae_solicitacao_execucao.id%type,',
'        p_id_worker        in number,',
'        p_id_tenant        in number,',
'        p_id_correlation   in varchar2',
'    ) return varchar2',
'    is',
'        l_ind_cb          srv_artefato_cfg.ind_circuit_breaker%type;',
'        l_estado          srv_artefato_cfg.cb_estado%type;',
'        l_dt_abertura     srv_artefato_cfg.cb_dt_abertura%type;',
'        l_cooldown_seg    srv_artefato_cfg.cb_cooldown_seg%type;',
'        l_teste_andamento srv_artefato_cfg.cb_ind_teste_em_andamento%type;',
'    begin',
'        select',
'            nvl(ind_circuit_breaker, ''N''),',
'            nvl(cb_estado, c_cb_fechado),',
'            cb_dt_abertura,',
'            nvl(cb_cooldown_seg, 0),',
'            nvl(cb_ind_teste_em_andamento, ''N'')',
'        into',
'            l_ind_cb,',
'            l_estado,',
'            l_dt_abertura,',
'            l_cooldown_seg,',
'            l_teste_andamento',
'        from srv_artefato_cfg',
'        where id_artefato = p_id_artefato',
'        for update;',
'',
'        if l_ind_cb <> ''S'' then',
'            return c_cb_result_permitido;',
'        end if;',
'',
'        if l_estado = c_cb_fechado then',
'            return c_cb_result_permitido;',
'        end if;',
'',
'        if l_estado = c_cb_aberto then',
'            if l_dt_abertura is not null',
'               and systimestamp >= l_dt_abertura + numtodsinterval(l_cooldown_seg, ''SECOND'')',
'            then',
'                if l_teste_andamento = ''N'' then',
'                    update srv_artefato_cfg',
'                       set cb_estado                 = c_cb_meio_aberto,',
'                           cb_ind_teste_em_andamento = ''S''',
'                     where id_artefato = p_id_artefato;',
'',
'                    registrar_evento_cb(',
'                        p_id_solicitacao => p_id_solicitacao,',
'                        p_id_worker      => p_id_worker,',
'                        p_id_tenant      => p_id_tenant,',
'                        p_id_correlation => p_id_correlation,',
'                        p_tipo_evento    => ''CIRCUIT_BREAKER_HALF_OPEN'',',
'                        p_resultado      => ''SUCESSO'',',
'                        p_detalhes       => ''Cooldown expirado. Execucao de teste liberada para o artefato '' || p_id_artefato',
'                    );',
'',
'                    return c_cb_result_teste_halfopen;',
'                else',
'                    registrar_evento_cb(',
'                        p_id_solicitacao => p_id_solicitacao,',
'                        p_id_worker      => p_id_worker,',
'                        p_id_tenant      => p_id_tenant,',
'                        p_id_correlation => p_id_correlation,',
'                        p_tipo_evento    => ''CIRCUIT_BREAKER_BLOCKED'',',
'                        p_resultado      => ''BLOQUEADO'',',
'                        p_detalhes       => ''Circuito aberto e execucao de teste ja em andamento para o artefato '' || p_id_artefato',
'                    );',
'',
'                    return c_cb_result_bloqueado;',
'                end if;',
'            else',
'                registrar_evento_cb(',
'                    p_id_solicitacao => p_id_solicitacao,',
'                    p_id_worker      => p_id_worker,',
'                    p_id_tenant      => p_id_tenant,',
'                    p_id_correlation => p_id_correlation,',
'                    p_tipo_evento    => ''CIRCUIT_BREAKER_BLOCKED'',',
'                    p_resultado      => ''BLOQUEADO'',',
'                    p_detalhes       => ''Circuito aberto. Cooldown ainda nao expirou para o artefato '' || p_id_artefato',
'                );',
'',
'                return c_cb_result_bloqueado;',
'            end if;',
'        end if;',
'',
'        if l_estado = c_cb_meio_aberto then',
'            registrar_evento_cb(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_worker      => p_id_worker,',
'                p_id_tenant      => p_id_tenant,',
'                p_id_correlation => p_id_correlation,',
'                p_tipo_evento    => ''CIRCUIT_BREAKER_BLOCKED'',',
'                p_resultado      => ''BLOQUEADO'',',
'                p_detalhes       => ''Circuito em meio-aberto aguardando conclusao da execucao de teste para o artefato '' || p_id_artefato',
'            );',
'',
'            return c_cb_result_bloqueado;',
'        end if;',
'',
'        return c_cb_result_permitido;',
'    end tentar_permitir_execucao_cb;',
'',
'',
'    procedure registrar_falha_tecnica_cb(',
'        p_id_artefato      in srv_artefato_cfg.id_artefato%type,',
'        p_id_solicitacao   in mae_solicitacao_execucao.id%type,',
'        p_id_worker        in number,',
'        p_id_tenant        in number,',
'        p_id_correlation   in varchar2,',
'        p_detalhe          in clob default null',
'    )',
'    is',
'        l_ind_cb       srv_artefato_cfg.ind_circuit_breaker%type;',
'        l_estado       srv_artefato_cfg.cb_estado%type;',
'        l_qtd_abertura srv_artefato_cfg.cb_qtd_falhas_abertura%type;',
'        l_falhas       srv_artefato_cfg.cb_falhas_consecutivas%type;',
'    begin',
'        select',
'            nvl(ind_circuit_breaker, ''N''),',
'            nvl(cb_estado, c_cb_fechado),',
'            nvl(cb_qtd_falhas_abertura, 0),',
'            nvl(cb_falhas_consecutivas, 0)',
'        into',
'            l_ind_cb,',
'            l_estado,',
'            l_qtd_abertura,',
'            l_falhas',
'        from srv_artefato_cfg',
'        where id_artefato = p_id_artefato',
'        for update;',
'',
'        if l_ind_cb <> ''S'' then',
'            return;',
'        end if;',
'',
'        if l_estado = c_cb_meio_aberto then',
'            update srv_artefato_cfg',
'               set cb_estado                 = c_cb_aberto,',
'                   cb_dt_abertura            = systimestamp,',
'                   cb_dt_ultima_falha        = systimestamp,',
'                   cb_ind_teste_em_andamento = ''N'',',
'                   cb_falhas_consecutivas    = nvl(cb_falhas_consecutivas, 0) + 1',
'             where id_artefato = p_id_artefato;',
'',
'            registrar_evento_cb(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_worker      => p_id_worker,',
'                p_id_tenant      => p_id_tenant,',
'                p_id_correlation => p_id_correlation,',
'                p_tipo_evento    => ''CIRCUIT_BREAKER_REOPENED'',',
'                p_resultado      => ''FALHA_TECNICA'',',
'                p_detalhes       => coalesce(',
'                                        p_detalhe,',
'                                        ''Falha tecnica na execucao de teste. Circuito reaberto para o artefato '' || p_id_artefato',
'                                    )',
'            );',
'            return;',
'        end if;',
'',
'        l_falhas := l_falhas + 1;',
'',
'        if l_qtd_abertura > 0 and l_falhas >= l_qtd_abertura then',
'            update srv_artefato_cfg',
'               set cb_estado                 = c_cb_aberto,',
'                   cb_falhas_consecutivas    = l_falhas,',
'                   cb_dt_ultima_falha        = systimestamp,',
'                   cb_dt_abertura            = systimestamp,',
'                   cb_ind_teste_em_andamento = ''N''',
'             where id_artefato = p_id_artefato;',
'',
'            registrar_evento_cb(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_worker      => p_id_worker,',
'                p_id_tenant      => p_id_tenant,',
'                p_id_correlation => p_id_correlation,',
'                p_tipo_evento    => ''CIRCUIT_BREAKER_OPENED'',',
'                p_resultado      => ''FALHA_TECNICA'',',
'                p_detalhes       => ''Circuito aberto por falhas tecnicas consecutivas. Total='' || l_falhas ||',
'                                    ''. Artefato='' || p_id_artefato ||',
'                                    case when p_detalhe is not null then '' Detalhe='' || dbms_lob.substr(p_detalhe, 3000, 1) end',
'            );',
'        else',
'            update srv_artefato_cfg',
'               set cb_falhas_consecutivas = l_falhas,',
'                   cb_dt_ultima_falha     = systimestamp',
'             where id_artefato = p_id_artefato;',
'        end if;',
'    end registrar_falha_tecnica_cb;',
'',
'',
'    procedure registrar_sucesso_cb(',
'        p_id_artefato      in srv_artefato_cfg.id_artefato%type,',
'        p_id_solicitacao   in mae_solicitacao_execucao.id%type,',
'        p_id_worker        in number,',
'        p_id_tenant        in number,',
'        p_id_correlation   in varchar2',
'    )',
'    is',
'        l_ind_cb srv_artefato_cfg.ind_circuit_breaker%type;',
'        l_estado srv_artefato_cfg.cb_estado%type;',
'    begin',
'        select',
'            nvl(ind_circuit_breaker, ''N''),',
'            nvl(cb_estado, c_cb_fechado)',
'        into',
'            l_ind_cb,',
'            l_estado',
'        from srv_artefato_cfg',
'        where id_artefato = p_id_artefato',
'        for update;',
'',
'        if l_ind_cb <> ''S'' then',
'            return;',
'        end if;',
'',
'        if l_estado = c_cb_meio_aberto then',
'            update srv_artefato_cfg',
'               set cb_estado                 = c_cb_fechado,',
'                   cb_falhas_consecutivas    = 0,',
'                   cb_dt_ultima_falha        = null,',
'                   cb_dt_abertura            = null,',
'                   cb_ind_teste_em_andamento = ''N''',
'             where id_artefato = p_id_artefato;',
'',
'            registrar_evento_cb(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_worker      => p_id_worker,',
'                p_id_tenant      => p_id_tenant,',
'                p_id_correlation => p_id_correlation,',
'                p_tipo_evento    => ''CIRCUIT_BREAKER_CLOSED'',',
'                p_resultado      => ''SUCESSO'',',
'                p_detalhes       => ''Execucao de teste bem-sucedida. Circuito fechado para o artefato '' || p_id_artefato',
'            );',
'',
'        elsif l_estado = c_cb_fechado then',
'            update srv_artefato_cfg',
'               set cb_falhas_consecutivas = 0',
'             where id_artefato = p_id_artefato;',
'        end if;',
'    end registrar_sucesso_cb;',
'',
'',
'    procedure resetar_circuit_breaker(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) is',
'    begin',
'        update srv_artefato_cfg',
'           set cb_estado                 = c_cb_fechado,',
'               cb_falhas_consecutivas    = 0,',
'               cb_dt_ultima_falha        = null,',
'               cb_dt_abertura            = null,',
'               cb_ind_teste_em_andamento = ''N''',
'         where id_artefato = p_id_artefato;',
'    end resetar_circuit_breaker;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-62 \2013 Validar limite m\00E1ximo de retry'),
'    -------------------------------------------------------------------',
'    function get_max_retry_tecnico return number',
'    is',
'    begin',
'        return 10;',
'    end get_max_retry_tecnico;',
'',
'    procedure validar_max_tentativas_config(',
'        p_max_tentativas in number',
'    ) is',
'        l_max_retry_tecnico number;',
'    begin',
'        l_max_retry_tecnico := get_max_retry_tecnico;',
'',
'        if p_max_tentativas is null then',
'            raise_application_error(',
'                -20092,',
unistr('                ''MAX_TENTATIVAS \00E9 obrigat\00F3rio.'''),
'            );',
'        end if;',
'',
'        if p_max_tentativas < 0 then',
'            raise_application_error(',
'                -20093,',
unistr('                ''MAX_TENTATIVAS inv\00E1lido. O valor deve ser maior ou igual a zero.'''),
'            );',
'        end if;',
'',
'        if p_max_tentativas > l_max_retry_tecnico then',
'            raise_application_error(',
'                -20094,',
unistr('                ''Retry excede limite t\00E9cnico (MAX_RETRY_TECNICO='' || l_max_retry_tecnico || '').'''),
'            );',
'        end if;',
'    end validar_max_tentativas_config;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-61 \2013 Limitar concorr\00EAncia por artefato'),
'    -------------------------------------------------------------------',
'    function obter_limite_execucao_simultanea(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return number',
'    is',
'        l_limite srv_artefato_cfg.limite_execucao_simultanea%type;',
'    begin',
'        if p_id_artefato is null then',
'            return null;',
'        end if;',
'',
'        begin',
'            select cfg.limite_execucao_simultanea',
'              into l_limite',
'              from srv_artefato_cfg cfg',
'             where cfg.id_artefato = p_id_artefato;',
'        exception',
'            when no_data_found then',
'                return null;',
'        end;',
'',
'        if l_limite is null then',
'            return null;',
'        end if;',
'',
'        if l_limite <= 0 then',
'            raise_application_error(',
'                -20091,',
unistr('                ''LIMITE_EXECUCAO_SIMULTANEA inv\00E1lido para o artefato '' || p_id_artefato ||'),
'                ''. Deve ser maior que zero ou NULL.''',
'            );',
'        end if;',
'',
'        return l_limite;',
'    end obter_limite_execucao_simultanea;    ',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-50 \2013 Obter TTL pendente por artefato'),
'    -- Regras:',
'    --   - NULL = TTL desabilitado',
unistr('    --   - > 0  = TTL v\00E1lido'),
unistr('    --   - <= 0 = inv\00E1lido'),
'    -------------------------------------------------------------------',
'    function obter_ttl_pendente_artefato(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return number',
'    is',
'        l_ttl srv_artefato_cfg.ttl_pendente_seg%type;',
'    begin',
'        select cfg.ttl_pendente_seg',
'          into l_ttl',
'          from srv_artefato_cfg cfg',
'         where cfg.id_artefato = p_id_artefato;',
'',
'        if l_ttl is null then',
'            return null;',
'        end if;',
'',
'        if l_ttl <= 0 then',
'            raise_application_error(',
'                -20061,',
unistr('                ''TTL_PENDENTE_SEG inv\00E1lido para o artefato '' || p_id_artefato ||'),
'                ''. O valor deve ser maior que zero ou NULL.''',
'            );',
'        end if;',
'',
'        return l_ttl;',
'',
'    exception',
'        when no_data_found then',
'            return null;',
'    end obter_ttl_pendente_artefato;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-50 \2013 Calcular data/hora de expira\00E7\00E3o por TTL'),
'    -------------------------------------------------------------------',
'    function calcular_dt_expiracao(',
'        p_dt_criacao   in timestamp,',
'        p_ttl_segundos in number',
'    ) return timestamp',
'    is',
'    begin',
'        if p_dt_criacao is null then',
'            raise_application_error(',
'                -20063,',
unistr('                ''p_dt_criacao \00E9 obrigat\00F3rio para c\00E1lculo de expira\00E7\00E3o.'''),
'            );',
'        end if;',
'',
'        if p_ttl_segundos is null then',
'            return null;',
'        end if;',
'',
'        if p_ttl_segundos <= 0 then',
'            raise_application_error(',
'                -20064,',
'                ''p_ttl_segundos deve ser maior que zero quando informado.''',
'            );',
'        end if;',
'',
'        return p_dt_criacao + numtodsinterval(p_ttl_segundos, ''SECOND'');',
'    end calcular_dt_expiracao;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-50 \2013 Verifica se a mensagem j\00E1 expirou por TTL'),
'    -- Regras:',
unistr('    --   - NULL = n\00E3o expira'),
'    --   - retorno:',
'    --       S = expirou',
unistr('    --       N = n\00E3o expirou'),
'    -------------------------------------------------------------------',
'    function mensagem_expirada_por_ttl(',
'        p_dt_criacao   in timestamp,',
'        p_ttl_segundos in number',
'    ) return varchar2',
'    is',
'        l_dt_expiracao timestamp;',
'    begin',
'        if p_ttl_segundos is null then',
'            return ''N'';',
'        end if;',
'',
'        l_dt_expiracao := calcular_dt_expiracao(',
'            p_dt_criacao   => p_dt_criacao,',
'            p_ttl_segundos => p_ttl_segundos',
'        );',
'',
'        if l_dt_expiracao < systimestamp then',
'            return ''S'';',
'        else',
'            return ''N'';',
'        end if;',
'    end mensagem_expirada_por_ttl;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-54 \2013 Obter SLA de perman\00EAncia em fila por artefato'),
'    -- Regras:',
'    --   - NULL = SLA desabilitado',
unistr('    --   - > 0  = SLA v\00E1lido'),
unistr('    --   - <= 0 = inv\00E1lido'),
'    -------------------------------------------------------------------',
'    function obter_sla_fila_seg(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return number',
'    is',
'        l_sla srv_artefato_cfg.sla_fila_seg%type;',
'    begin',
'        if p_id_artefato is null then',
'            return null;',
'        end if;',
'',
'        begin',
'            select cfg.sla_fila_seg',
'              into l_sla',
'              from srv_artefato_cfg cfg',
'             where cfg.id_artefato = p_id_artefato;',
'        exception',
'            when no_data_found then',
'                return null;',
'        end;',
'',
'        if l_sla is null then',
'            return null;',
'        end if;',
'',
'        if l_sla <= 0 then',
'            raise_application_error(',
'                -20071,',
unistr('                ''SLA_FILA_SEG inv\00E1lido para o artefato '' || p_id_artefato ||'),
'                ''. O valor deve ser maior que zero ou NULL.''',
'            );',
'        end if;',
'',
'        return l_sla;',
'    end obter_sla_fila_seg;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-54 \2013 Calcular data/hora limite do SLA de fila'),
'    -------------------------------------------------------------------',
'    function calcular_dt_limite_sla_fila(',
'        p_dt_criacao   in timestamp,',
'        p_sla_fila_seg in number',
'    ) return timestamp',
'    is',
'    begin',
'        if p_dt_criacao is null then',
'            raise_application_error(',
'                -20072,',
unistr('                ''p_dt_criacao \00E9 obrigat\00F3rio para c\00E1lculo do SLA de fila.'''),
'            );',
'        end if;',
'',
'        if p_sla_fila_seg is null then',
'            return null;',
'        end if;',
'',
'        if p_sla_fila_seg <= 0 then',
'            raise_application_error(',
'                -20073,',
'                ''p_sla_fila_seg deve ser maior que zero quando informado.''',
'            );',
'        end if;',
'',
'        return p_dt_criacao + numtodsinterval(p_sla_fila_seg, ''SECOND'');',
'    end calcular_dt_limite_sla_fila;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-54 \2013 Verifica se a mensagem violou o SLA de fila'),
'    -- Regras:',
'    --   - NULL = SLA desabilitado',
'    --   - retorno:',
'    --       S = violou',
unistr('    --       N = n\00E3o violou / desabilitado'),
'    -------------------------------------------------------------------',
'    function mensagem_violou_sla_fila(',
'        p_dt_criacao   in timestamp,',
'        p_sla_fila_seg in number',
'    ) return varchar2',
'    is',
'        l_dt_limite timestamp;',
'    begin',
'        if p_sla_fila_seg is null then',
'            return ''N'';',
'        end if;',
'',
'        l_dt_limite := calcular_dt_limite_sla_fila(',
'            p_dt_criacao   => p_dt_criacao,',
'            p_sla_fila_seg => p_sla_fila_seg',
'        );',
'',
'        if l_dt_limite < systimestamp then',
'            return ''S'';',
'        else',
'            return ''N'';',
'        end if;',
'    end mensagem_violou_sla_fila;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-66 \2013 Validar tamanho de payload/conte\00FAdo'),
'    -------------------------------------------------------------------',
'    function obter_max_payload_bytes(',
'        p_id_artefato in srv_artefato_cfg.id_artefato%type',
'    ) return number',
'    is',
'        l_limite srv_artefato_cfg.max_payload_bytes%type;',
'    begin',
'        if p_id_artefato is null then',
'            return null;',
'        end if;',
'',
'        begin',
'            select cfg.max_payload_bytes',
'              into l_limite',
'              from srv_artefato_cfg cfg',
'             where cfg.id_artefato = p_id_artefato;',
'        exception',
'            when no_data_found then',
'                return null;',
'        end;',
'',
'        if l_limite is null then',
'            return null;',
'        end if;',
'',
'        if l_limite <= 0 then',
'            raise_application_error(',
'                -20111,',
unistr('                ''MAX_PAYLOAD_BYTES inv\00E1lido para o artefato '' || p_id_artefato ||'),
'                ''. Deve ser maior que zero ou NULL.''',
'            );',
'        end if;',
'',
'        return l_limite;',
'    end obter_max_payload_bytes;',
'',
'end pkg_maestro_cfg;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_evento
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262703656940728)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_EVENTO'
,p_sequence=>130
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_evento as',
'',
'    -------------------------------------------------------------------',
unistr('    -- API interna \00FAnica para emiss\00E3o de eventos t\00E9cnicos'),
unistr('    -- ST-CI-53 \2013 Garantir desacoplamento da integra\00E7\00E3o'),
'    --',
'    -- Regras:',
unistr('    --   - persist\00EAncia somente em mae_registro_tecnico'),
unistr('    --   - nunca chamar integra\00E7\00F5es externas'),
unistr('    --   - tratamento defensivo: erro de log n\00E3o propaga'),
'    -------------------------------------------------------------------',
'',
'    procedure registrar_evento(',
'        p_id_solicitacao in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_tipo_evento    in varchar2,',
'        p_resultado      in varchar2,',
'        p_detalhes       in clob',
'    );',
'',
'    procedure registrar_critical_failure_event(',
'        p_id_solicitacao in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_sqlcode        in number,',
'        p_sqlerrm        in varchar2,',
'        p_etapa          in varchar2 default null,',
'        p_tentativas     in number   default null,',
'        p_detalhes_extra in varchar2 default null',
'    );',
'',
'end pkg_maestro_evento;',
'/',
'create or replace package body pkg_maestro_evento as',
'',
'    c_evt_critical_failure constant varchar2(100) := ''CRITICAL_FAILURE_EVENT'';',
'    c_result_falha_critica constant varchar2(30)  := ''FALHA_CRITICA'';',
'',
'    -------------------------------------------------------------------',
unistr('    -- Utilit\00E1rios internos'),
'    -------------------------------------------------------------------',
'    function normalizar_texto(',
'        p_valor in varchar2',
'    ) return varchar2',
'    is',
'    begin',
'        if trim(p_valor) is null then',
'            return null;',
'        end if;',
'',
'        return trim(p_valor);',
'    end normalizar_texto;',
'',
'    function clob_para_varchar2_4k(',
'        p_texto in clob',
'    ) return varchar2',
'    is',
'        l_result varchar2(4000);',
'    begin',
'        if p_texto is null then',
'            return null;',
'        end if;',
'',
'        l_result := dbms_lob.substr(p_texto, 4000, 1);',
'        return substr(l_result, 1, 4000);',
'',
'    exception',
'        when others then',
'            return substr(to_char(p_texto), 1, 4000);',
'    end clob_para_varchar2_4k;',
'',
'    function montar_detalhes_critical_failure(',
'        p_sqlcode        in number,',
'        p_sqlerrm        in varchar2,',
'        p_etapa          in varchar2,',
'        p_tentativas     in number,',
'        p_detalhes_extra in varchar2',
'    ) return clob',
'    is',
'        l_detalhes clob;',
'    begin',
'        l_detalhes :=',
'            ''SQLCODE='' || nvl(to_char(p_sqlcode), ''<null>'') ||',
'            ''; SQLERRM='' || nvl(substr(p_sqlerrm, 1, 1000), ''<null>'') ||',
'            ''; ETAPA='' || nvl(normalizar_texto(p_etapa), ''<null>'') ||',
'            ''; TENTATIVAS='' || nvl(to_char(p_tentativas), ''<null>'');',
'',
'        if trim(p_detalhes_extra) is not null then',
'            l_detalhes := l_detalhes || ''; DETALHES='' || substr(trim(p_detalhes_extra), 1, 2000);',
'        end if;',
'',
'        return l_detalhes;',
'    end montar_detalhes_critical_failure;',
'',
'    -------------------------------------------------------------------',
unistr('    -- API p\00FAblica \2013 evento gen\00E9rico'),
'    -------------------------------------------------------------------',
'    procedure registrar_evento(',
'        p_id_solicitacao in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_tipo_evento    in varchar2,',
'        p_resultado      in varchar2,',
'        p_detalhes       in clob',
'    ) is',
'        l_tipo_evento varchar2(100);',
'        l_resultado   varchar2(30);',
'        l_detalhes    varchar2(4000);',
'    begin',
'        -- if p_id_solicitacao is null then',
'        --     return;',
'        -- end if;',
'',
'        l_tipo_evento := normalizar_texto(p_tipo_evento);',
'        l_resultado   := normalizar_texto(p_resultado);',
'        l_detalhes    := clob_para_varchar2_4k(p_detalhes);',
'',
'        if l_tipo_evento is null or l_resultado is null then',
'            return;',
'        end if;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            p_id_worker,',
'            systimestamp,',
'            l_tipo_evento,',
'            l_resultado,',
'            l_detalhes,',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'',
'    exception',
'        when others then',
unistr('            -- ST-CI-53: logging n\00E3o pode derrubar o worker'),
'            null;',
'    end registrar_evento;',
'',
'    -------------------------------------------------------------------',
unistr('    -- API p\00FAblica \2013 evento especializado de falha cr\00EDtica'),
'    -------------------------------------------------------------------',
'    procedure registrar_critical_failure_event(',
'        p_id_solicitacao in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_sqlcode        in number,',
'        p_sqlerrm        in varchar2,',
'        p_etapa          in varchar2 default null,',
'        p_tentativas     in number   default null,',
'        p_detalhes_extra in varchar2 default null',
'    ) is',
'        l_detalhes clob;',
'    begin',
'        l_detalhes := montar_detalhes_critical_failure(',
'            p_sqlcode        => p_sqlcode,',
'            p_sqlerrm        => p_sqlerrm,',
'            p_etapa          => p_etapa,',
'            p_tentativas     => p_tentativas,',
'            p_detalhes_extra => p_detalhes_extra',
'        );',
'',
'        registrar_evento(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => p_id_worker,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_correlation => p_id_correlation,',
'            p_tipo_evento    => c_evt_critical_failure,',
'            p_resultado      => c_result_falha_critica,',
'            p_detalhes       => l_detalhes',
'        );',
'    end registrar_critical_failure_event;',
'',
'end pkg_maestro_evento;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_expurgo
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262748532939098)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_EXPURGO'
,p_sequence=>140
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_expurgo is',
'',
'    procedure expurgar_logs_tecnicos(',
'        p_retencao_dias   in number,',
'        p_lote            in number default 5000,',
'        p_total_expurgado out number',
'    );',
'',
'    procedure job_expurgar_logs;',
'',
'    procedure criar_job_expurgo_logs(',
'        p_habilitar in boolean default true',
'    );',
'',
'    function obter_parametro_numerico(',
'        p_chave   in varchar2,',
'        p_default in number',
'    ) return number;',
'',
'end pkg_maestro_expurgo;',
'/',
'create or replace package body pkg_maestro_expurgo is',
'',
'    c_job_name                    constant varchar2(128) := ''JOB_MAE_EXPURGO_LOG_TECNICO'';',
'    c_param_log_retencao_dias     constant varchar2(100) := ''LOG_RETENCAO_DIAS'';',
'    c_param_log_expurgo_lote      constant varchar2(100) := ''LOG_EXPURGO_LOTE'';',
'',
'    c_default_retencao_dias       constant number := 90;',
'    c_default_lote_expurgo        constant number := 5000;',
'',
'    c_repeat_interval_mvp         constant varchar2(200) := ''FREQ=DAILY;BYHOUR=3;BYMINUTE=0;BYSECOND=0'';',
'',
'',
'    function obter_parametro_numerico(',
'        p_chave   in varchar2,',
'        p_default in number',
'    ) return number',
'    is',
'        l_valor_texto mae_parametro_config.valor%type;',
'        l_valor_num   number;',
'    begin',
'        select valor',
'          into l_valor_texto',
'          from mae_parametro_config',
'         where chave = p_chave;',
'',
'        l_valor_num := to_number(trim(l_valor_texto));',
'',
'        return l_valor_num;',
'',
'    exception',
'        when no_data_found then',
'            return p_default;',
'',
'        when value_error then',
'            return p_default;',
'',
'        when others then',
'            return p_default;',
'    end obter_parametro_numerico;',
'',
'',
'    procedure expurgar_logs_tecnicos(',
'        p_retencao_dias   in number,',
'        p_lote            in number default 5000,',
'        p_total_expurgado out number',
'    ) is',
'        l_limite timestamp;',
'        l_rows   number := 0;',
'        l_total  number := 0;',
'        l_lote   number := nvl(p_lote, c_default_lote_expurgo);',
'    begin',
'        p_total_expurgado := 0;',
'',
'        if p_retencao_dias is null then',
'            raise_application_error(',
'                -20044,',
unistr('                ''Par\00E2metro p_retencao_dias \00E9 obrigat\00F3rio.'''),
'            );',
'        end if;',
'',
'        if p_retencao_dias < 0 then',
'            raise_application_error(',
'                -20045,',
unistr('                ''Par\00E2metro p_retencao_dias deve ser maior ou igual a zero.'''),
'            );',
'        end if;',
'',
'        if l_lote <= 0 then',
'            raise_application_error(',
'                -20046,',
unistr('                ''Par\00E2metro p_lote deve ser maior que zero.'''),
'            );',
'        end if;',
'',
'        l_limite := systimestamp - numtodsinterval(p_retencao_dias, ''DAY'');',
'',
'        loop',
'            delete from mae_registro_tecnico',
'             where rowid in (',
'                   select rid',
'                     from (',
'                           select rowid rid',
'                             from mae_registro_tecnico',
'                            where dt_evento < l_limite',
'                              and rownum <= l_lote',
'                     )',
'             );',
'',
'            l_rows := sql%rowcount;',
'',
'            exit when l_rows = 0;',
'',
'            l_total := l_total + l_rows;',
'',
'            commit;',
'        end loop;',
'',
'        p_total_expurgado := l_total;',
'',
'    exception',
'        when others then',
'            rollback;',
'            raise_application_error(',
'                -20047,',
unistr('                ''Erro ao expurgar logs t\00E9cnicos: '' || sqlerrm'),
'            );',
'    end expurgar_logs_tecnicos;',
'',
'',
'    procedure job_expurgar_logs is',
'        l_total_expurgado number := 0;',
'        l_retencao_dias   number;',
'        l_lote_expurgo    number;',
'    begin',
'        l_retencao_dias := obter_parametro_numerico(',
'            p_chave   => c_param_log_retencao_dias,',
'            p_default => c_default_retencao_dias',
'        );',
'',
'        l_lote_expurgo := obter_parametro_numerico(',
'            p_chave   => c_param_log_expurgo_lote,',
'            p_default => c_default_lote_expurgo',
'        );',
'',
'        if l_retencao_dias < 0 then',
'            l_retencao_dias := c_default_retencao_dias;',
'        end if;',
'',
'        if l_lote_expurgo <= 0 then',
'            l_lote_expurgo := c_default_lote_expurgo;',
'        end if;',
'',
'        expurgar_logs_tecnicos(',
'            p_retencao_dias   => l_retencao_dias,',
'            p_lote            => l_lote_expurgo,',
'            p_total_expurgado => l_total_expurgado',
'        );',
'',
'        dbms_output.put_line(',
'            ''JOB_EXPURGAR_LOGS executado com sucesso. RETENCAO='' || l_retencao_dias ||',
'            '' LOTE='' || l_lote_expurgo ||',
'            '' TOTAL_EXPURGADO='' || l_total_expurgado',
'        );',
'',
'    exception',
'        when others then',
'            raise;',
'    end job_expurgar_logs;',
'',
'',
'    procedure criar_job_expurgo_logs(',
'        p_habilitar in boolean default true',
'    ) is',
'        l_count number;',
'    begin',
'        select count(*)',
'          into l_count',
'          from user_scheduler_jobs',
'         where job_name = c_job_name;',
'',
'        if l_count > 0 then',
'            dbms_scheduler.drop_job(',
'                job_name => c_job_name,',
'                force    => true',
'            );',
'        end if;',
'',
'        dbms_scheduler.create_job(',
'            job_name        => c_job_name,',
'            job_type        => ''STORED_PROCEDURE'',',
'            job_action      => ''PKG_MAESTRO_EXPURGO.JOB_EXPURGAR_LOGS'',',
'            start_date      => systimestamp,',
'            repeat_interval => c_repeat_interval_mvp,',
'            enabled         => false,',
'            auto_drop       => false,',
unistr('            comments        => ''Expurgo t\00E9cnico di\00E1rio da MAE_REGISTRO_TECNICO.'''),
'        );',
'',
'        if p_habilitar then',
'            dbms_scheduler.enable(name => c_job_name);',
'        end if;',
'    end criar_job_expurgo_logs;',
'',
'end pkg_maestro_expurgo;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_interface
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262897459937475)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_INTERFACE'
,p_sequence=>150
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_interface as',
'',
'    ----------------------------------------------------------------------------',
unistr('    -- Contexto padr\00E3o recebido do MAESTRO'),
'    ----------------------------------------------------------------------------',
'    type r_contexto_maestro is record (',
'        id_solicitacao number,',
'        id_tenant      number,',
'        id_usuario     number,',
'        id_negocio     varchar2(4000),',
'        payload        clob,',
'        corr           varchar2(4000)',
'    );',
'',
'    ----------------------------------------------------------------------------',
unistr('    -- Interface padr\00E3o MAESTRO'),
'    ----------------------------------------------------------------------------',
'    procedure if_recalcula_rateio_invoice_item_despesa(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    );',
'',
'    procedure if_altera_valor_desconto_invoice_item(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    );    ',
'',
'    procedure if_limpar_log_tempo_com_item(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    );        ',
'',
'    procedure if_job_expurgar_logs(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    );        ',
'',
'    procedure if_job_expirar_ttl(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    );    ',
'',
'    procedure if_importar_cotacao_dia(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    );    ',
'',
'end pkg_maestro_interface;',
'/',
'create or replace package body pkg_maestro_interface as',
'',
'    ----------------------------------------------------------------------------',
unistr('    -- Monta record de contexto padr\00E3o'),
'    ----------------------------------------------------------------------------',
'    function build_context(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2',
'    ) return r_contexto_maestro',
'    is',
'        l_ctx r_contexto_maestro;',
'    begin',
'        l_ctx.id_solicitacao := p_id_solicitacao;',
'        l_ctx.id_tenant      := p_id_tenant;',
'        l_ctx.id_usuario     := p_id_usuario;',
'        l_ctx.id_negocio     := p_id_negocio;',
'        l_ctx.payload        := p_payload;',
'        l_ctx.corr           := p_corr;',
'',
'        return l_ctx;',
'    end build_context;',
'',
'',
'    ----------------------------------------------------------------------------',
unistr('    -- Valida\00E7\00E3o b\00E1sica comum'),
'    ----------------------------------------------------------------------------',
'    procedure validar_contexto(',
'        p_ctx in r_contexto_maestro',
'    )',
'    is',
'    begin',
'        if p_ctx.id_solicitacao is null then',
unistr('            raise_application_error(-20001, ''p_id_solicitacao n\00E3o informado.'');'),
'        end if;',
'',
'        if p_ctx.id_tenant is null then',
unistr('            raise_application_error(-20002, ''p_id_tenant n\00E3o informado.'');'),
'        end if;',
'',
'        if p_ctx.id_usuario is null then',
unistr('            raise_application_error(-20003, ''p_id_usuario n\00E3o informado.'');'),
'        end if;',
'',
'        if p_ctx.payload is null then',
unistr('            raise_application_error(-20004, ''p_payload n\00E3o informado.'');'),
'        end if;',
'    end validar_contexto;',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- Helpers JSON',
'    ----------------------------------------------------------------------------',
'    function get_number(',
'        p_json          in json_object_t,',
'        p_key           in varchar2,',
'        p_required      in boolean default false,',
'        p_default_value in number default null',
'    ) return number',
'    is',
'        l_value number;',
'    begin',
'        if p_json.has(p_key) then',
'            if p_json.get_number(p_key) is null then',
'                if p_required then',
'                    raise_application_error(',
'                        -20010,',
unistr('                        ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" est\00E1 nulo.'''),
'                    );',
'                end if;',
'                return p_default_value;',
'            end if;',
'            l_value := p_json.get_number(p_key);',
'            return l_value;',
'        end if;',
'',
'        if p_required then',
'            raise_application_error(',
'                -20011,',
unistr('                ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" n\00E3o informado.'''),
'            );',
'        end if;',
'',
'        return p_default_value;',
'    end get_number;',
'',
'',
'    function get_string(',
'        p_json          in json_object_t,',
'        p_key           in varchar2,',
'        p_required      in boolean default false,',
'        p_default_value in varchar2 default null',
'    ) return varchar2',
'    is',
'        l_value varchar2(32767);',
'    begin',
'        if p_json.has(p_key) then',
'            if p_json.get(p_key).is_null then',
'                if p_required then',
'                    raise_application_error(',
'                        -20012,',
unistr('                        ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" est\00E1 nulo.'''),
'                    );',
'                end if;',
'',
'                return p_default_value;',
'            end if;',
'',
'            l_value := p_json.get_string(p_key);',
'            return l_value;',
'        end if;',
'',
'        if p_required then',
'            raise_application_error(',
'                -20013,',
unistr('                ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" n\00E3o informado.'''),
'            );',
'        end if;',
'',
'        return p_default_value;',
'    end get_string;',
'',
'',
'    function to_boolean(',
'        p_value   in varchar2,',
'        p_default in boolean default false',
'    ) return boolean',
'    is',
'        l_value varchar2(100);',
'    begin',
'        if p_value is null then',
'            return p_default;',
'        end if;',
'',
'        l_value := upper(trim(p_value));',
'',
'        if l_value in (''TRUE'', ''T'', ''1'', ''S'', ''SIM'', ''Y'', ''YES'') then',
'            return true;',
unistr('        elsif l_value in (''FALSE'', ''F'', ''0'', ''N'', ''NAO'', ''N\00C3O'', ''NO'') then'),
'            return false;',
'        else',
'            raise_application_error(',
'                -20014,',
unistr('                ''Payload inv\00E1lido: valor booleano inv\00E1lido ['' || p_value || ''].'''),
'            );',
'        end if;',
'    end to_boolean;',
'',
'',
'    function get_boolean(',
'        p_json          in json_object_t,',
'        p_key           in varchar2,',
'        p_required      in boolean default false,',
'        p_default_value in boolean default false',
'    ) return boolean',
'    is',
'        l_raw_value varchar2(100);',
'    begin',
'        if p_json.has(p_key) then',
'            if p_json.get(p_key).is_null then',
'                if p_required then',
'                    raise_application_error(',
'                        -20015,',
unistr('                        ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" est\00E1 nulo.'''),
'                    );',
'                end if;',
'',
'                return p_default_value;',
'            end if;',
'',
'            l_raw_value := p_json.get_string(p_key);',
'            return to_boolean(l_raw_value, p_default_value);',
'        end if;',
'',
'        if p_required then',
'            raise_application_error(',
'                -20016,',
unistr('                ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" n\00E3o informado.'''),
'            );',
'        end if;',
'',
'        return p_default_value;',
'    end get_boolean;',
'',
'    function messages_to_json(',
'        p_messages in pkg_mensagem.message_record_table',
'    ) return clob',
'    is',
'        l_array   json_array_t := json_array_t();',
'        l_obj     json_object_t;',
'    begin',
'        if p_messages is null or p_messages.count = 0 then',
'            return ''[]'';',
'        end if;',
'',
'        for i in 1 .. p_messages.count loop',
'            l_obj := json_object_t();',
'',
'            l_obj.put(''mensagem'',       p_messages(i).mensagem);',
'            l_obj.put(''instrucao'',      p_messages(i).instrucao);',
'            l_obj.put(''help'',           p_messages(i).help);',
'            l_obj.put(''local_exibicao'', p_messages(i).local_exibicao);',
'            l_obj.put(''nome_item'',      p_messages(i).nome_item);',
'            l_obj.put(''tipo'',           p_messages(i).tipo);',
'',
'            l_array.append(l_obj);',
'        end loop;',
'',
'        return l_array.to_clob;',
'    end messages_to_json;',
'',
'    ----------------------------------------------------------------------------',
'    -- Interface concreta:',
'    -- bo_imp_invoice_item.recalcula_rateio_invoice_item_despesa',
'    ----------------------------------------------------------------------------',
'    procedure if_recalcula_rateio_invoice_item_despesa(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob',
'    )',
'    is',
'        l_ctx         r_contexto_maestro;',
'        l_json        json_object_t;',
'        l_id_invoice  imp_invoice_item.id_invoice%type;',
'        l_pagina      number := 0;',
'        l_encadeado   boolean := false;',
'        l_sucesso      clob;',
'        l_messages     pkg_mensagem.message_record_table;',
'    begin',
'        ----------------------------------------------------------------------------',
unistr('        -- Contexto padr\00E3o'),
'        ----------------------------------------------------------------------------',
'        l_ctx := build_context(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_usuario     => p_id_usuario,',
'            p_id_negocio     => p_id_negocio,',
'            p_payload        => p_payload,',
'            p_corr           => p_corr',
'        );',
'',
'        validar_contexto(l_ctx);',
'',
'        ----------------------------------------------------------------------------',
'        -- Parse do payload',
'        ----------------------------------------------------------------------------',
'        l_json := json_object_t.parse(l_ctx.payload);',
'',
'        ----------------------------------------------------------------------------',
unistr('        -- id_invoice obrigat\00F3rio'),
'        ----------------------------------------------------------------------------',
'        if l_json.has(''id_invoice'') then',
'            l_id_invoice := get_number(',
'                p_json     => l_json,',
'                p_key      => ''id_invoice'',',
'                p_required => true',
'            );',
'        end if;',
'',
'        ----------------------------------------------------------------------------',
'        -- pagina opcional',
'        ----------------------------------------------------------------------------',
'        if l_json.has(''pagina'') then',
'            l_pagina := get_number(',
'                p_json          => l_json,',
'                p_key           => ''pagina'',',
'                p_default_value => 0',
'            );',
'        elsif l_json.has(''p_pagina'') then',
'            l_pagina := get_number(',
'                p_json          => l_json,',
'                p_key           => ''p_pagina'',',
'                p_default_value => 0',
'            );',
'        else',
'            l_pagina := 0;',
'        end if;',
'',
'        ----------------------------------------------------------------------------',
'        -- encadeado opcional',
'        ----------------------------------------------------------------------------',
'        if l_json.has(''encadeado'') then',
'            l_encadeado := get_boolean(',
'                p_json          => l_json,',
'                p_key           => ''encadeado'',',
'                p_default_value => false',
'            );',
'        elsif l_json.has(''p_encadeado'') then',
'            l_encadeado := get_boolean(',
'                p_json          => l_json,',
'                p_key           => ''p_encadeado'',',
'                p_default_value => false',
'            );',
'        else',
'            l_encadeado := false;',
'        end if;',
'',
'        ----------------------------------------------------------------------------',
'        -- Chamada da rotina real do sistema',
'        -- Ajustar o nome do pacote real abaixo',
'        ----------------------------------------------------------------------------',
'        bo_imp_invoice_item.recalcula_rateio_invoice_item_despesa(',
'            p_id_invoice => l_id_invoice,',
'            p_pagina     => l_pagina,',
'            p_encadeado  => l_encadeado,',
'            p_sucesso    => l_sucesso,',
'            p_messages   => l_messages',
'        );',
'',
'        p_sucesso       := l_sucesso;',
'        p_messages_json := messages_to_json(l_messages);        ',
'',
'    exception',
'        when others then',
'            raise;',
'    end if_recalcula_rateio_invoice_item_despesa;',
'',
'    ----------------------------------------------------------------------------',
'    -- Interface concreta:',
'    -- bo_imp_invoice.altera_valor_desconto_invoice_item',
'    ----------------------------------------------------------------------------',
'    procedure if_altera_valor_desconto_invoice_item(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob',
'    )',
'    is',
'        l_ctx         r_contexto_maestro;',
'        l_json        json_object_t;',
'        l_id_invoice  imp_invoice_item.id_invoice%type;',
'        l_pagina      number := 0;',
'        l_encadeado   boolean := false;',
'        l_sucesso      clob;',
'        l_messages     pkg_mensagem.message_record_table;',
'    begin',
'        ----------------------------------------------------------------------------',
unistr('        -- Contexto padr\00E3o'),
'        ----------------------------------------------------------------------------',
'        l_ctx := build_context(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_usuario     => p_id_usuario,',
'            p_id_negocio     => p_id_negocio,',
'            p_payload        => p_payload,',
'            p_corr           => p_corr',
'        );',
'',
'        validar_contexto(l_ctx);',
'',
'        ----------------------------------------------------------------------------',
'        -- Parse do payload',
'        ----------------------------------------------------------------------------',
'        l_json := json_object_t.parse(l_ctx.payload);',
'',
'        ----------------------------------------------------------------------------',
unistr('        -- id_invoice obrigat\00F3rio'),
'        ----------------------------------------------------------------------------',
'        if l_json.has(''id_invoice'') then',
'            l_id_invoice := get_number(',
'                p_json     => l_json,',
'                p_key      => ''id_invoice'',',
'                p_required => true',
'            );',
'        end if;',
'',
'        ----------------------------------------------------------------------------',
'        -- pagina opcional',
'        ----------------------------------------------------------------------------',
'        if l_json.has(''pagina'') then',
'            l_pagina := get_number(',
'                p_json          => l_json,',
'                p_key           => ''pagina'',',
'                p_default_value => 0',
'            );',
'        elsif l_json.has(''p_pagina'') then',
'            l_pagina := get_number(',
'                p_json          => l_json,',
'                p_key           => ''p_pagina'',',
'                p_default_value => 0',
'            );',
'        else',
'            l_pagina := 0;',
'        end if;',
'',
'        ----------------------------------------------------------------------------',
'        -- encadeado opcional',
'        ----------------------------------------------------------------------------',
'        if l_json.has(''encadeado'') then',
'            l_encadeado := get_boolean(',
'                p_json          => l_json,',
'                p_key           => ''encadeado'',',
'                p_default_value => false',
'            );',
'        elsif l_json.has(''p_encadeado'') then',
'            l_encadeado := get_boolean(',
'                p_json          => l_json,',
'                p_key           => ''p_encadeado'',',
'                p_default_value => false',
'            );',
'        else',
'            l_encadeado := false;',
'        end if;',
'',
'        ----------------------------------------------------------------------------',
'        -- Chamada da rotina real do sistema',
'        -- Ajustar o nome do pacote real abaixo',
'        ----------------------------------------------------------------------------',
'        bo_imp_invoice.altera_valor_desconto_invoice_item(',
'            p_id         => l_id_invoice,',
'            p_pagina     => l_pagina,',
'            p_encadeado  => l_encadeado,',
'            p_sucesso    => l_sucesso,',
'            p_messages   => l_messages',
'        );',
'',
'        p_sucesso       := l_sucesso;',
'        p_messages_json := messages_to_json(l_messages);        ',
'',
'    exception',
'        when others then',
'            raise;',
'    end if_altera_valor_desconto_invoice_item;',
'',
'    procedure if_limpar_log_tempo_com_item(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    )is',
'    begin',
'        limpar_log_tempo_com_item;',
'    end;        ',
'',
'    procedure if_job_expurgar_logs(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    )is',
'    begin',
'        pkg_maestro_expurgo.job_expurgar_logs;',
'    end;        ',
'',
'    procedure if_job_expirar_ttl(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    )is',
'    begin',
'        pkg_maestro_ttl.job_expirar_ttl;',
'    end;    ',
'',
'    procedure if_importar_cotacao_dia(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob        ',
'    )is',
'         l_ctx         r_contexto_maestro;',
'        l_json        json_object_t;',
'        l_id_invoice  imp_invoice_item.id_invoice%type;',
'        l_pagina      number := 0;',
'        l_encadeado   boolean := false;',
'        l_sucesso      clob;',
'        l_messages     pkg_mensagem.message_record_table;',
'    begin',
'        ----------------------------------------------------------------------------',
unistr('        -- Contexto padr\00E3o'),
'        ----------------------------------------------------------------------------',
'        l_ctx := build_context(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_usuario     => p_id_usuario,',
'            p_id_negocio     => p_id_negocio,',
'            p_payload        => p_payload,',
'            p_corr           => p_corr',
'        );',
'        -- validar_contexto(l_ctx);      ',
'          ',
'        bo_ng_moeda_cotacao.importar_cotacao_dia(l_ctx.id_usuario);',
'    end;    ',
'',
'end pkg_maestro_interface;',
'/'))
);
end;
