prompt --application/deployment/install/install_pkg_maestro_monitoramento
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16262969604935681)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_MONITORAMENTO'
,p_sequence=>160
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_monitoramento as',
'  subtype t_cursor is sys_refcursor;',
'',
'function fn_mae_byday_ptbr_to_en(',
'    p_dias in varchar2',
') return varchar2;',
'',
'    function formatar_duration_job(',
'        p_last_run_duration in varchar2',
'    ) return varchar2;',
'',
'function fmt_repeat_interval(',
'        p_repeat_interval in varchar2',
'    ) return varchar2;',
'',
'  function fn_obter_usuario_atual return varchar2;',
'  function fn_operador_autorizado(',
'    p_operacao in varchar2,',
'    p_usuario  in varchar2 default null',
'  ) return varchar2;',
'  function fn_obter_cb_estado(p_id_artefato in number) return varchar2;',
'  function fn_obter_status_job(',
'    p_id_sched_cfg in number,',
'    p_job_name     in varchar2 default null',
'  ) return varchar2;',
'',
'  function fn_obter_id_usuario_atual return number;',
'',
'  procedure prc_consultar_resumo_filas(',
'    p_id_artefato            in number default null,',
'    p_ind_ativo              in varchar2 default null,',
'    p_ind_com_backlog        in varchar2 default null,',
'    p_ind_com_falha          in varchar2 default null,',
'    p_ind_em_processamento   in varchar2 default null,',
'    p_ind_breaker_aberto     in varchar2 default null,',
'    p_result                 out t_cursor',
'  );',
'',
'  procedure prc_consultar_mensagens(',
'    p_id_solicitacao         in number default null,',
'    p_id_artefato            in number default null,',
'    p_id_tenant              in number default null,',
'    p_id_usuario             in number default null,',
'    p_id_negocio             in varchar2 default null,',
'    p_id_correlation         in varchar2 default null,',
'    p_status                 in varchar2 default null,',
'    p_dt_criacao_ini         in timestamp default null,',
'    p_dt_criacao_fim         in timestamp default null,',
'    p_dt_inicio_ini          in timestamp default null,',
'    p_dt_inicio_fim          in timestamp default null,',
'    p_dt_fim_ini             in timestamp default null,',
'    p_dt_fim_fim             in timestamp default null,',
'    p_ind_sla_violado        in varchar2 default null,',
'    p_ind_expirada_ttl       in varchar2 default null,',
'    p_ind_bloqueada          in varchar2 default null,',
'    p_order_by               in varchar2 default ''DT_CRIACAO_DESC'',',
'    p_result                 out t_cursor',
'  );',
'',
'  procedure prc_obter_detalhe_solicitacao(',
'    p_id_solicitacao in number,',
'    p_result         out t_cursor',
'  );',
'',
'  procedure prc_consultar_eventos(',
'    p_id_solicitacao in number,',
'    p_ordem          in varchar2 default ''ASC'',',
'    p_result         out t_cursor',
'  );',
'',
'  procedure prc_consultar_jobs(',
'    p_id_artefato in number default null,',
