'  );',
'',
'  procedure prc_executar_solicitacao_manual(',
'    p_id_solicitacao in number,',
'    p_id_usuario     in number default null',
'  );',
'',
'    procedure executar_solicitacao_manual(',
'        p_id in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'  procedure prc_executar_fila(',
'    p_id_sched_cfg in number,',
'    p_id_usuario   in number default null',
'  );',
'',
'  procedure prc_parar_fila(',
'    p_id_sched_cfg in number,',
'    p_id_usuario   in number default null',
'  );',
'',
'  procedure prc_habilitar_fila(',
'    p_id_sched_cfg in number,',
'    p_recriar_job  in varchar2 default ''N'',',
'    p_id_usuario   in number default null',
'  );',
'',
'  procedure prc_resetar_circuit_breaker(',
'    p_id_artefato in number,',
'    p_id_usuario  in number default null',
'  );',
'',
'  procedure prc_desbloquear_mensagem(',
'    p_id_solicitacao in number,',
'    p_observacao     in varchar2 default null,',
'    p_id_usuario     in number default null',
'  );',
'',
'  procedure prc_alterar_status(',
'    p_id_solicitacao in number,',
'    p_novo_status    in varchar2,',
'    p_observacao     in varchar2 default null,',
'    p_id_usuario     in number default null',
'  );',
'',
'  procedure prc_atualizar_config_fila(',
'    p_id_sched_cfg         in number,',
'    p_ativo                in varchar2 default null,',
'    p_intervalo_segundos   in number default null,',
'    p_ind_paralelo         in varchar2 default null,',
'    p_observacao           in varchar2 default null,',
'    p_id_usuario           in number default null',
'  );',
'',
'  procedure salvar_agendamento(',
'      p_job_name        in varchar2,',
'      p_enabled         in varchar2,  -- ''S''/''N''',
'      p_start_date      in date,',
'      p_repeat_interval in varchar2,  -- pode ser null se usar repeat_freq',
'',
'      p_id_tenant       in number,',
'      p_codigo_artefato in varchar2,',
'      p_id_usuario      in number,',
'      p_id_negocio      in varchar2,',
'      p_payload         in clob,',
'      p_prioridade      in number,',
'      p_tipo_acao       in varchar2,',
'',
'      p_sucesso         out clob,',
'      p_messages        out pkg_mensagem.message_record_table,',
'',
unistr('      -- NOVOS (opcionais) - dom\00EDnio repeat_freq'),
'      p_repeat_freq     in varchar2 default null,  -- SEGUNDOS/MINUTOS/HORAS/DIARIO/SEMANAL/MENSAL',
'      p_repeat_x        in number   default null,  -- X p/ SEGUNDOS/MINUTOS/HORAS',
'      p_byday           in varchar2 default null,  -- MO,TU,... p/ SEMANAL',
'      p_monthday        in number   default null,  -- 1..31 p/ MENSAL',
unistr('      p_hour            in number   default null,  -- hor\00E1rio p/ DIARIO/SEMANAL/MENSAL'),
'      p_minute          in number   default null   -- minuto  p/ DIARIO/SEMANAL/MENSAL',
'  );',
'',
'  procedure run_agendamento(p_job_name in varchar2);',
'',
'function build_repeat_interval(',
'    p_repeat_freq   in varchar2,',
'    p_x             in number   default null,  -- usado por SEGUNDOS/MINUTOS/HORAS',
'    p_byday         in varchar2 default null,  -- usado por SEMANAL (MO,TU,WE...)',
'    p_monthday      in number   default null,  -- usado por MENSAL (1..31)',
'    p_hour          in number   default null,  -- usado por DIARIO/SEMANAL/MENSAL',
'    p_minute        in number   default null   -- usado por DIARIO/SEMANAL/MENSAL',
') return varchar2;',
'',
'    procedure excluir_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table        ',
'    );',
'',
'    procedure ativar_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table        ',
'    );',
'',
'    procedure desativar_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table        ',
'    );',
'',
'    procedure executar_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table        ',
'    );    ',
'',
'end pkg_maestro_monitoramento;',
'/',
'create or replace package body pkg_maestro_monitoramento as',
'',
'function fn_mae_byday_ptbr_to_en(',
'    p_dias in varchar2',
') return varchar2',
'is',
'    l_in   varchar2(4000) := lower(trim(nvl(p_dias,'''')));',
'    l_out  varchar2(4000) := null;',
'    l_tok  varchar2(50);',
'    l_i    number := 1;',
'',
'    function norm(p varchar2) return varchar2 is',
'        x varchar2(50) := lower(trim(p));',
'    begin',
unistr('        -- normaliza acentos b\00E1sicos'),
unistr('        x := replace(x,''\00E1'',''a'');'),
unistr('        x := replace(x,''\00E0'',''a'');'),
unistr('        x := replace(x,''\00E3'',''a'');'),
unistr('        x := replace(x,''\00E2'',''a'');'),
unistr('        x := replace(x,''\00E9'',''e'');'),
unistr('        x := replace(x,''\00EA'',''e'');'),
unistr('        x := replace(x,''\00ED'',''i'');'),
unistr('        x := replace(x,''\00F3'',''o'');'),
unistr('        x := replace(x,''\00F4'',''o'');'),
unistr('        x := replace(x,''\00F5'',''o'');'),
unistr('        x := replace(x,''\00FA'',''u'');'),
unistr('        x := replace(x,''\00E7'',''c'');'),
'',
'        -- remove "-feira"',
'        x := replace(x,''-feira'','''');',
'        x := replace(x,''feira'','''');',
'',
'        return x;',
'    end;',
'',
'    function map_day(p varchar2) return varchar2 is',
'        x varchar2(50) := norm(p);',
'    begin',
'        case x',
'            when ''dom'' then return ''SU'';',
'            when ''domingo'' then return ''SU'';',
'',
'            when ''seg'' then return ''MO'';',
'            when ''segunda'' then return ''MO'';',
'',
'            when ''ter'' then return ''TU'';',
'            when ''terca'' then return ''TU'';',
unistr('            when ''ter\00E7a'' then return ''TU'';'),
'',
'            when ''qua'' then return ''WE'';',
'            when ''quarta'' then return ''WE'';',
'',
'            when ''qui'' then return ''TH'';',
'            when ''quinta'' then return ''TH'';',
'',
'            when ''sex'' then return ''FR'';',
'            when ''sexta'' then return ''FR'';',
'',
'            when ''sab'' then return ''SA'';',
'            when ''sabado'' then return ''SA'';',
unistr('            when ''s\00E1bado'' then return ''SA'';'),
'',
'            else',
'                return null;',
'        end case;',
'    end;',
'',
'begin',
'    if l_in is null then',
'        return null;',
'    end if;',
'',
unistr('    -- aceita separador v\00EDrgula ou espa\00E7o'),
'    l_in := replace(l_in, '';'', '','');',
'    l_in := replace(l_in, '' '', '','');',
'',
'    loop',
'        l_tok := regexp_substr(l_in, ''[^,]+'', 1, l_i);',
'        exit when l_tok is null;',
'',
'        l_tok := map_day(l_tok);',
'',
'        if l_tok is null then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|Dia da semana inv\00E1lido: ''||'),
'                                    regexp_substr(l_in, ''[^,]+'', 1, l_i));',
'        end if;',
'',
'        -- evita duplicados',
'        if instr('',''||nvl(l_out,'''')||'','', '',''||l_tok||'','') = 0 then',
'            if l_out is null then',
'                l_out := l_tok;',
'            else',
'                l_out := l_out||'',''||l_tok;',
'            end if;',
'        end if;',
'',
'        l_i := l_i + 1;',
'    end loop;',
'',
'    return l_out;',
'end fn_mae_byday_ptbr_to_en;',
'',
'    /* ============================================================',
'       FN_FORMATAR_DURATION_JOB',
'       Objetivo:',
unistr('         Formatar o LAST_RUN_DURATION (USER_SCHEDULER_JOBS) para exibi\00E7\00E3o'),
unistr('         amig\00E1vel na UI.'),
'',
unistr('       Entrada t\00EDpica:'),
'         +000000000 00:00:00.016935   (INTERVAL DAY TO SECOND em texto)',
'',
unistr('       Sa\00EDda (MVP):'),
'         - Se dias > 0:   "D dias HH:MI:SS.mmm"',
'         - Se dias = 0:   "HH:MI:SS.mmm"',
'       (Sempre com milissegundos)',
'',
unistr('       Observa\00E7\00E3o:'),
'         - Usa TO_DSINTERVAL para converter o texto.',
unistr('         - Se n\00E3o conseguir converter, retorna o texto original.'),
'       ============================================================ */',
'    function formatar_duration_job(',
'        p_last_run_duration in varchar2',
'    ) return varchar2',
'    is',
'        l_raw    varchar2(4000);',
'        l_int    interval day to second;',
'        l_days   number;',
'        l_hours  number;',
'        l_mins   number;',
'        l_secs   number;',
'        l_ms     number;',
'    begin',
'        if p_last_run_duration is null or trim(p_last_run_duration) is null then',
'            return ''-'';',
'        end if;',
'',
'        l_raw := trim(p_last_run_duration);',
'',
'        -- Converte string -> INTERVAL DAY TO SECOND',
'        l_int := to_dsinterval(l_raw);',
'',
'        l_days  := extract(day    from l_int);',
'        l_hours := extract(hour   from l_int);',
'        l_mins  := extract(minute from l_int);',
'        l_secs  := floor(extract(second from l_int)); -- parte inteira',
'        l_ms    := floor((extract(second from l_int) - l_secs) * 1000); -- milissegundos',
'',
'        if l_days > 0 then',
'            return l_days||'' dia''||',
'                   case when l_days > 1 then ''s '' else '' '' end||',
'                   lpad(l_hours,2,''0'')||'':''||',
'                   lpad(l_mins,2,''0'')||'':''||',
'                   lpad(l_secs,2,''0'')||''.''||',
'                   lpad(l_ms,3,''0'');',
'        else',
'            return lpad(l_hours,2,''0'')||'':''||',
'                   lpad(l_mins,2,''0'')||'':''||',
'                   lpad(l_secs,2,''0'')||''.''||',
'                   lpad(l_ms,3,''0'');',
'        end if;',
'',
'    exception',
'        when others then',
unistr('            -- Fallback seguro para n\00E3o quebrar a UI'),
'            return l_raw;',
'    end formatar_duration_job;',
'',
'',
'    /* ============================================================',
'       FMT_REPEAT_INTERVAL',
'       Objetivo:',
'         Converter o campo USER_SCHEDULER_JOBS.REPEAT_INTERVAL em um',
unistr('         texto amig\00E1vel (MVP) para exibi\00E7\00E3o na UI.'),
'',
'       Coberturas (MVP):',
'         - FREQ=SECONDLY;INTERVAL=N            => "A cada N segundos"',
'         - FREQ=MINUTELY;INTERVAL=N            => "A cada N minutos"',
'         - FREQ=HOURLY;INTERVAL=N              => "A cada N horas"',
unistr('         - FREQ=DAILY;BYHOUR=H;BYMINUTE=M      => "Di\00E1rio \00E0s HH:MM"'),
unistr('         - FREQ=WEEKLY;BYDAY=MO,WE;BYHOUR=H... => "Semanal (Seg, Qua) \00E0s HH:MM"'),
unistr('         - FREQ=MONTHLY;BYMONTHDAY=D;BYHOUR... => "Mensal (dia D) \00E0s HH:MM"'),
unistr('         - caso n\00E3o reconhe\00E7a                 => retorna o texto t\00E9cnico'),
'',
unistr('       Observa\00E7\00E3o:'),
unistr('         - repeat_interval pode variar bastante; essa fun\00E7\00E3o cobre os'),
unistr('           padr\00F5es usados pelo formul\00E1rio da aplica\00E7\00E3o.'),
'       ============================================================ */',
'    function fmt_repeat_interval(',
'        p_repeat_interval in varchar2',
'    ) return varchar2',
'    is',
'        l_txt        varchar2(4000);',
'        l_freq       varchar2(50);',
'        l_interval   number;',
'        l_byhour     number;',
'        l_byminute   number;',
'        l_byday      varchar2(200);',
'        l_bymonthday number;',
'        l_bymonth    varchar2(200);',
'',
'        -- helpers',
'        function get_token(p_key varchar2) return varchar2 is',
'            l_val varchar2(4000);',
'        begin',
unistr('            -- Captura "KEY=valor" at\00E9 '';'' ou fim'),
'            l_val := regexp_substr(l_txt, p_key||''=([^;]+)'', 1, 1, ''i'', 1);',
'            return l_val;',
'        exception',
'            when others then',
'                return null;',
'        end;',
'',
'        function pad2(p_num number) return varchar2 is',
'        begin',
'            if p_num is null then return null; end if;',
'            return lpad(to_char(p_num), 2, ''0'');',
'        end;',
'',
'        function dow_ptbr(p_token varchar2) return varchar2 is',
'            -- p_token: MO TU WE TH FR SA SU',
'        begin',
'            case upper(trim(p_token))',
'                when ''MO'' then return ''Seg'';',
'                when ''TU'' then return ''Ter'';',
'                when ''WE'' then return ''Qua'';',
'                when ''TH'' then return ''Qui'';',
'                when ''FR'' then return ''Sex'';',
unistr('                when ''SA'' then return ''S\00E1b'';'),
'                when ''SU'' then return ''Dom'';',
'                else return upper(trim(p_token));',
'            end case;',
'        end;',
'',
'        function dow_list_ptbr(p_csv varchar2) return varchar2 is',
'            l_res varchar2(4000) := null;',
'            l_pos number := 1;',
'            l_tok varchar2(20);',
'        begin',
'            if p_csv is null then',
'                return null;',
'            end if;',
'',
'            loop',
'                l_tok := regexp_substr(p_csv, ''[^,]+'', 1, l_pos);',
'                exit when l_tok is null;',
'',
'                if l_res is null then',
'                    l_res := dow_ptbr(l_tok);',
'                else',
'                    l_res := l_res||'', ''||dow_ptbr(l_tok);',
'                end if;',
'',
'                l_pos := l_pos + 1;',
'            end loop;',
'',
'            return l_res;',
'        end;',
'',
'        function month_ptbr(p_num number) return varchar2 is',
'        begin',
'          case p_num',
'            when 1 then return ''Jan'';',
'            when 2 then return ''Fev'';',
'            when 3 then return ''Mar'';',
'            when 4 then return ''Abr'';',
'            when 5 then return ''Mai'';',
'            when 6 then return ''Jun'';',
'            when 7 then return ''Jul'';',
'            when 8 then return ''Ago'';',
'            when 9 then return ''Set'';',
'            when 10 then return ''Out'';',
'            when 11 then return ''Nov'';',
'            when 12 then return ''Dez'';',
'            else return to_char(p_num);',
'          end case;',
'        end;',
'',
'        function month_list_ptbr(p_csv varchar2) return varchar2 is',
'          l_res varchar2(4000) := null;',
'          l_pos number := 1;',
'          l_tok varchar2(20);',
'          l_n   number;',
'        begin',
'          if p_csv is null then return null; end if;',
'',
'          loop',
'            l_tok := regexp_substr(p_csv, ''[^,]+'', 1, l_pos);',
'            exit when l_tok is null;',
'',
'            l_n := to_number(l_tok);',
'            if l_res is null then',
'              l_res := month_ptbr(l_n);',
'            else',
'              l_res := l_res||'', ''||month_ptbr(l_n);',
'            end if;',
'',
'            l_pos := l_pos + 1;',
'          end loop;',
'',
'          return l_res;',
'        exception',
'          when others then',
'            return p_csv;',
'        end;        ',
'',
'    begin',
'        if p_repeat_interval is null or trim(p_repeat_interval) is null then',
unistr('            return ''Execu\00E7\00E3o \00FAnica'';'),
'        end if;',
'',
'        l_txt := trim(p_repeat_interval);',
'',
'        -- Tokens principais',
'        l_freq     := upper(nvl(get_token(''FREQ''), null));',
'        l_interval := to_number(get_token(''INTERVAL''));',
'        l_byhour   := to_number(get_token(''BYHOUR''));',
'        l_byminute := to_number(get_token(''BYMINUTE''));',
'        l_byday    := get_token(''BYDAY'');',
'        l_bymonthday := to_number(get_token(''BYMONTHDAY''));',
'        l_bymonth  := get_token(''BYMONTH'');',
'',
'        -- SECONDLY / MINUTELY / HOURLY',
'        if l_freq = ''SECONDLY'' then',
'            return case when nvl(l_interval,1) = 1',
'                        then ''A cada 1 segundo''',
'                        else ''A cada ''||nvl(l_interval,1)||'' segundos''',
'                   end;',
'        elsif l_freq = ''MINUTELY'' then',
'            return case when nvl(l_interval,1) = 1',
'                        then ''A cada 1 minuto''',
'                        else ''A cada ''||nvl(l_interval,1)||'' minutos''',
'                   end;',
'        elsif l_freq = ''HOURLY'' then',
'            return case when nvl(l_interval,1) = 1',
'                        then ''A cada 1 hora''',
'                        else ''A cada ''||nvl(l_interval,1)||'' horas''',
'                   end;',
'',
'        -- DAILY',
'        elsif l_freq = ''DAILY'' then',
'            if l_byhour is not null then',
unistr('                return ''Di\00E1rio \00E0s ''||pad2(l_byhour)||'':''||pad2(nvl(l_byminute,0));'),
'            else',
unistr('                return ''Di\00E1rio'';'),
'            end if;',
'',
'        -- WEEKLY',
'        elsif l_freq = ''WEEKLY'' then',
'            if l_byday is not null and l_byhour is not null then',
unistr('                return ''Semanal (''||dow_list_ptbr(l_byday)||'') \00E0s ''||'),
'                       pad2(l_byhour)||'':''||pad2(nvl(l_byminute,0));',
'            elsif l_byday is not null then',
'                return ''Semanal (''||dow_list_ptbr(l_byday)||'')'';',
'            elsif l_byhour is not null then',
unistr('                return ''Semanal \00E0s ''||pad2(l_byhour)||'':''||pad2(nvl(l_byminute,0));'),
'            else',
'                return ''Semanal'';',
'            end if;',
'',
'        -- MONTHLY',
'        elsif l_freq = ''MONTHLY'' then',
'            if l_bymonthday is not null and l_byhour is not null then',
unistr('                return ''Mensal (dia ''||l_bymonthday||'') \00E0s ''||'),
'                       pad2(l_byhour)||'':''||pad2(nvl(l_byminute,0));',
'            elsif l_bymonthday is not null then',
'                return ''Mensal (dia ''||l_bymonthday||'')'';',
'            elsif l_byhour is not null then',
unistr('                return ''Mensal \00E0s ''||pad2(l_byhour)||'':''||pad2(nvl(l_byminute,0));'),
'            else',
'                return ''Mensal'';',
'            end if;',
'        elsif l_freq = ''YEARLY'' then',
'          if l_bymonth is not null and l_bymonthday is not null and l_byhour is not null then',
unistr('            return ''Anual (''||month_list_ptbr(l_bymonth)||'') dia ''||l_bymonthday||'' \00E0s ''||'),
'                   pad2(l_byhour)||'':''||pad2(nvl(l_byminute,0));',
'          elsif l_bymonth is not null then',
'            return ''Anual (''||month_list_ptbr(l_bymonth)||'')'';',
'          else',
'            return ''Anual'';',
'          end if;            ',
'        end if;',
'',
unistr('        -- Fallback: n\00E3o reconhecido'),
'        return l_txt;',
'',
'    exception',
'        when value_error then',
unistr('            -- convers\00E3o number falhou em algum token'),
'            return l_txt;',
'        when others then',
'            return l_txt;',
'    end fmt_repeat_interval;',
'',
'',
'  function fn_normalizar_flag(p_valor in varchar2) return varchar2 is',
'  begin',
'    return upper(trim(nvl(p_valor, ''N'')));',
'  end fn_normalizar_flag;',
'',
'  function fn_normalizar_sn(',
'    p_valor      in varchar2,',
'    p_campo_nome in varchar2',
'  ) return varchar2 is',
'    l_valor varchar2(1);',
'  begin',
'    if p_valor is null then',
'      return null;',
'    end if;',
'',
'    l_valor := upper(trim(p_valor));',
'',
'    if l_valor not in (''S'', ''N'') then',
'      raise_application_error(-20002, p_campo_nome || '' deve ser S ou N.'');',
'    end if;',
'',
'    return l_valor;',
'  end fn_normalizar_sn;',
'',
'  procedure prc_assert_permissao(',
'    p_operacao in varchar2,',
'    p_id_tenant in number default null',
'  ) is',
'  begin',
'    pkg_maestro_admin.assert_permissao(',
'      p_operacao  => p_operacao,',
'      p_id_tenant => p_id_tenant',
'    );',
'  end prc_assert_permissao;',
'',
'  function fn_obter_usuario_atual return varchar2 is',
'  begin',
'    return pkg_maestro_admin.get_operador_atual;',
'  exception',
'    when others then',
'      return upper(trim(sys_context(''USERENV'', ''SESSION_USER'')));',
'  end fn_obter_usuario_atual;',
'',
'  function fn_operador_autorizado(',
'    p_operacao in varchar2,',
'    p_usuario  in varchar2 default null',
'  ) return varchar2 is',
'    l_resultado varchar2(1) := ''N'';',
'  begin',
'    if pkg_maestro_admin.is_operador_autorizado(',
'         p_operacao => p_operacao,',
'         p_operador => nvl(p_usuario, fn_obter_usuario_atual)',
'       ) then',
'      l_resultado := ''S'';',
'    end if;',
'',
'    return l_resultado;',
'  exception',
'    when others then',
'      return ''N'';',
'  end fn_operador_autorizado;',
'',
'  function fn_obter_id_usuario_atual return number is',
'    l_id_usuario number;',
'  begin',
'    select u.id',
'      into l_id_usuario',
'      from mpd_usuario u',
'     where upper(u.login) = upper(fn_obter_usuario_atual);',
'',
'    return l_id_usuario;',
'  exception',
'    when no_data_found then',
'      return null;',
'  end fn_obter_id_usuario_atual;',
'',
'  function fn_obter_cb_estado(p_id_artefato in number) return varchar2 is',
'  begin',
'    return pkg_maestro_cfg.get_cb_estado(p_id_artefato);',
'  exception',
'    when others then',
'      return null;',
'  end fn_obter_cb_estado;',
'',
'  function fn_obter_status_job(',
'    p_id_sched_cfg in number,',
'    p_job_name     in varchar2 default null',
'  ) return varchar2 is',
'    l_status_job varchar2(100);',
'    l_job_name   varchar2(200) := p_job_name;',
'  begin',
'    if l_job_name is null then',
'      l_job_name := pkg_maestro_worker_run.gerar_nome_job_fila(p_id_sched_cfg);',
'    end if;',
'',
'    begin',
'      select case',
'               when enabled = ''TRUE'' then nvl(state, ''HABILITADO'')',
'               else ''DESABILITADO''',
'             end',
'        into l_status_job',
'        from user_scheduler_jobs',
'       where job_name = upper(l_job_name);',
'    exception',
'      when no_data_found then',
'        l_status_job := ''NAO_EXISTE'';',
'    end;',
'',
'    return l_status_job;',
'  end fn_obter_status_job;',
'',
'  procedure prc_registrar_evento_manual(',
'    p_id_solicitacao in number,',
'    p_tipo_evento    in varchar2,',
'    p_resultado      in varchar2,',
'    p_detalhes       in varchar2,',
'    p_id_usuario     in number',
'  ) is',
'    l_id_tenant      number;',
'    l_id_correlation varchar2(64);',
'    l_detalhes       varchar2(4000);',
'  begin',
'    if p_id_solicitacao is null then',
'      return;',
'    end if;',
'',
'    select s.id_tenant,',
'           s.id_correlation',
'      into l_id_tenant,',
'           l_id_correlation',
'      from mae_solicitacao_execucao s',
'     where s.id = p_id_solicitacao;',
'',
'    l_detalhes := substr(',
'      ''id_usuario='' || nvl(to_char(p_id_usuario), ''<null>'') ||',
'      case',
'        when trim(p_detalhes) is not null then ''; '' || trim(p_detalhes)',
'        else null',
'      end,',
'      1,',
'      4000',
'    );',
'',
'    pkg_maestro_evento.registrar_evento(',
'      p_id_solicitacao => p_id_solicitacao,',
'      p_id_worker      => null,',
'      p_id_tenant      => l_id_tenant,',
'      p_id_correlation => l_id_correlation,',
'      p_tipo_evento    => p_tipo_evento,',
'      p_resultado      => p_resultado,',
'      p_detalhes       => l_detalhes',
'    );',
'  exception',
'    when no_data_found then',
'      raise_application_error(-20003, ''Solicitacao nao encontrada para auditoria: '' || p_id_solicitacao);',
'  end prc_registrar_evento_manual;',
'',
'  procedure prc_validar_status(',
'    p_id_solicitacao in number,',
'    p_status_esperado in varchar2',
'  ) is',
'    l_total number;',
'  begin',
'    execute immediate',
'      ''select count(*) from mae_solicitacao_execucao where id = :1 and status = :2''',
'      into l_total',
'      using p_id_solicitacao, p_status_esperado;',
'',
'    if l_total = 0 then',
'      raise_application_error(-20010, ''Solicitacao nao esta no estado esperado: '' || p_status_esperado);',
'    end if;',
'  end prc_validar_status;',
'',
'  procedure prc_consultar_resumo_filas(',
'    p_id_artefato            in number default null,',
'    p_ind_ativo              in varchar2 default null,',
'    p_ind_com_backlog        in varchar2 default null,',
'    p_ind_com_falha          in varchar2 default null,',
'    p_ind_em_processamento   in varchar2 default null,',
'    p_ind_breaker_aberto     in varchar2 default null,',
'    p_result                 out t_cursor',
'  ) is',
'    l_sql      varchar2(32767);',
'  begin',
'    l_sql := ''select ''',
'          || ''       sc.id as id_sched_cfg, ''',
'          || ''       sc.id_artefato, ''',
'          || ''       sc.ativo, ''',
'          || ''       sc.intervalo_segundos, ''',
'          || ''       sc.ind_paralelo, ''',
'          || ''       pkg_maestro_worker_run.gerar_nome_job_fila(sc.id) as job_name, ''',
'          || ''       nvl(agg.qtd_pendente, 0) as qtd_pendente, ''',
'          || ''       nvl(agg.qtd_processando, 0) as qtd_processando, ''',
'          || ''       nvl(agg.qtd_sucesso, 0) as qtd_sucesso, ''',
'          || ''       nvl(agg.qtd_falha_tecnica, 0) as qtd_falha_tecnica, ''',
'          || ''       nvl(agg.qtd_falha_negocio, 0) as qtd_falha_negocio, ''',
'          || ''       nvl(agg.qtd_erro_final, 0) as qtd_erro_final, ''',
'          || ''       nvl(agg.qtd_bloqueada, 0) as qtd_bloqueada, ''',
'          || ''       nvl(agg.qtd_expirada, 0) as qtd_expirada, ''',
'          || ''       nvl(agg.qtd_sla_breach, 0) as qtd_sla_breach, ''',
'          || ''       pkg_maestro_monitoramento.fn_obter_cb_estado(sc.id_artefato) as cb_estado, ''',
'          || ''       pkg_maestro_monitoramento.fn_obter_status_job(sc.id, pkg_maestro_worker_run.gerar_nome_job_fila(sc.id)) as status_job ''',
'          || ''  from mae_sched_cfg sc ''',
'          || ''  left join ( ''',
'          || ''       select se.id_artefato, ''',
'          || ''              sum(case when se.status = ''''PENDENTE'''' then 1 else 0 end) as qtd_pendente, ''',
'          || ''              sum(case when se.status = ''''EM_PROCESSAMENTO'''' then 1 else 0 end) as qtd_processando, ''',
'          || ''              sum(case when se.status = ''''SUCESSO'''' then 1 else 0 end) as qtd_sucesso, ''',
'          || ''              sum(case when se.status = ''''FALHA_TECNICA'''' then 1 else 0 end) as qtd_falha_tecnica, ''',
'          || ''              sum(case when se.status = ''''FALHA_NEGOCIO'''' then 1 else 0 end) as qtd_falha_negocio, ''',
'          || ''              sum(case when se.status = ''''ERRO_FINAL'''' then 1 else 0 end) as qtd_erro_final, ''',
'          || ''              sum(case when se.status = ''''BLOQUEADA'''' then 1 else 0 end) as qtd_bloqueada, ''',
'          || ''              sum(case when se.status = ''''EXPIRADO'''' then 1 else 0 end) as qtd_expirada, ''',
'           || ''              sum(case when se.status in (''''PENDENTE'''', ''''BLOQUEADA'''') and exists ( ''',
'           || ''                            select 1 ''',
'           || ''                              from mae_registro_tecnico rt ''',
'           || ''                             where rt.id_solicitacao = se.id ''',
'           || ''                               and rt.tipo_evento = ''''QUEUE_SLA_BREACH'''' ''',
'           || ''                          ) then 1 else 0 end) as qtd_sla_breach ''',
'          || ''         from mae_solicitacao_execucao se ''',
'          || ''        group by se.id_artefato ''',
'          || ''  ) agg on agg.id_artefato = sc.id_artefato ''',
'          || '' where (:1 is null or sc.id_artefato = :2) ''',
'          || ''   and (:3 is null or upper(sc.ativo) = upper(:4)) ''',
'          || ''   and (:5 is null or :5 <> ''''S'''' or nvl(agg.qtd_pendente, 0) > 0) ''',
'          || ''   and (:6 is null or :6 <> ''''S'''' or (nvl(agg.qtd_falha_tecnica, 0) + nvl(agg.qtd_falha_negocio, 0) + nvl(agg.qtd_erro_final, 0)) > 0) ''',
'          || ''   and (:7 is null or :7 <> ''''S'''' or nvl(agg.qtd_processando, 0) > 0) ''',
'          || ''   and (:8 is null or :8 <> ''''S'''' or pkg_maestro_monitoramento.fn_obter_cb_estado(sc.id_artefato) in (''''OPEN'''', ''''HALF_OPEN'''', ''''ABERTO'''', ''''MEIO_ABERTO'''')) ''',
'          || '' order by sc.id_artefato'';',
'',
'    open p_result for l_sql',
'      using p_id_artefato,',
'            p_id_artefato,',
'            p_ind_ativo,',
'            p_ind_ativo,',
'            fn_normalizar_flag(p_ind_com_backlog),',
'            fn_normalizar_flag(p_ind_com_backlog),',
'            fn_normalizar_flag(p_ind_com_falha),',
'            fn_normalizar_flag(p_ind_com_falha),',
'            fn_normalizar_flag(p_ind_em_processamento),',
'            fn_normalizar_flag(p_ind_em_processamento),',
'            fn_normalizar_flag(p_ind_breaker_aberto),',
'            fn_normalizar_flag(p_ind_breaker_aberto);',
'  end prc_consultar_resumo_filas;',
'',
'  procedure prc_consultar_mensagens(',
'    p_id_solicitacao         in number default null,',
'    p_id_artefato            in number default null,',
'    p_id_tenant              in number default null,',
'    p_id_usuario             in number default null,',
'    p_id_negocio             in varchar2 default null,',
'    p_id_correlation         in varchar2 default null,',
'    p_status                 in varcha'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(16262969604935681)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'r2 default null,',
'    p_dt_criacao_ini         in timestamp default null,',
'    p_dt_criacao_fim         in timestamp default null,',
'    p_dt_inicio_ini          in timestamp default null,',
'    p_dt_inicio_fim          in timestamp default null,',
'    p_dt_fim_ini             in timestamp default null,',
'    p_dt_fim_fim             in timestamp default null,',
'    p_ind_sla_violado        in varchar2 default null,',
'    p_ind_expirada_ttl       in varchar2 default null,',
'    p_ind_bloqueada          in varchar2 default null,',
'    p_order_by               in varchar2 default ''DT_CRIACAO_DESC'',',
'    p_result                 out t_cursor',
'  ) is',
'    l_sql      varchar2(32767);',
'    l_order_by varchar2(200);',
'  begin',
'    l_order_by := case upper(nvl(p_order_by, ''DT_CRIACAO_DESC''))',
'                    when ''DT_DISPONIVEL_EXECUCAO_ASC'' then ''se.dt_disponivel_execucao asc''',
'                    when ''PRIORIDADE_DESC'' then ''se.prioridade desc, se.dt_criacao desc''',
'                    when ''DT_INICIO_DESC'' then ''se.dt_inicio desc nulls last''',
'                    else ''se.dt_criacao desc''',
'                  end;',
'',
'    l_sql := ''select se.id as id_solicitacao, ''',
'          || ''       se.id_artefato, ''',
'          || ''       se.id_tenant, ''',
'          || ''       se.id_usuario, ''',
'          || ''       se.tipo_acao, ''',
'          || ''       se.id_negocio, ''',
'          || ''       se.id_correlation, ''',
'          || ''       se.status, ''',
'          || ''       se.prioridade, ''',
'          || ''       se.tentativas, ''',
'          || ''       se.dt_criacao, ''',
'          || ''       se.dt_disponivel_execucao, ''',
'          || ''       se.dt_disponibilidade, ''',
'          || ''       se.dt_inicio, ''',
'          || ''       se.dt_fim, ''',
'          || ''       se.id_worker, ''',
'          || ''       se.motivo_falha, ''',
'          || ''       case when exists ( ''',
'          || ''              select 1 from mae_registro_tecnico rt ''',
'          || ''               where rt.id_solicitacao = se.id ''',
'          || ''                 and rt.tipo_evento = ''''QUEUE_SLA_BREACH'''' ''',
'          || ''            ) then ''''S'''' else ''''N'''' end as ind_sla_violado ''',
'          || ''  from mae_solicitacao_execucao se ''',
'          || '' where (:1 is null or se.id = :2) ''',
'          || ''   and (:3 is null or se.id_artefato = :4) ''',
'          || ''   and (:5 is null or se.id_tenant = :6) ''',
'          || ''   and (:7 is null or se.id_usuario = :8) ''',
'          || ''   and (:9 is null or se.id_negocio = :10) ''',
'          || ''   and (:11 is null or se.id_correlation = :12) ''',
'          || ''   and (:13 is null or se.status = :14) ''',
'          || ''   and (:15 is null or se.dt_criacao >= :16) ''',
'          || ''   and (:17 is null or se.dt_criacao < :18) ''',
'          || ''   and (:19 is null or se.dt_inicio >= :20) ''',
'          || ''   and (:21 is null or se.dt_inicio < :22) ''',
'          || ''   and (:23 is null or se.dt_fim >= :24) ''',
'          || ''   and (:25 is null or se.dt_fim < :26) ''',
'          || ''   and (:27 is null or :27 <> ''''S'''' or exists ( ''',
'          || ''              select 1 from mae_registro_tecnico rt ''',
'          || ''               where rt.id_solicitacao = se.id ''',
'          || ''                 and rt.tipo_evento = ''''QUEUE_SLA_BREACH'''' ''',
'          || ''            )) ''',
'          || ''   and (:28 is null or :28 <> ''''S'''' or se.status = ''''EXPIRADO'''') ''',
'          || ''   and (:29 is null or :29 <> ''''S'''' or se.status = ''''BLOQUEADA'''') ''',
'          || '' order by '' || l_order_by;',
'',
'    open p_result for l_sql',
'      using p_id_solicitacao,',
'            p_id_solicitacao,',
'            p_id_artefato,',
'            p_id_artefato,',
'            p_id_tenant,',
'            p_id_tenant,',
'            p_id_usuario,',
'            p_id_usuario,',
'            p_id_negocio,',
'            p_id_negocio,',
'            p_id_correlation,',
'            p_id_correlation,',
'            p_status,',
'            p_status,',
'            p_dt_criacao_ini,',
'            p_dt_criacao_ini,',
'            p_dt_criacao_fim,',
'            p_dt_criacao_fim,',
'            p_dt_inicio_ini,',
'            p_dt_inicio_ini,',
'            p_dt_inicio_fim,',
'            p_dt_inicio_fim,',
'            p_dt_fim_ini,',
'            p_dt_fim_ini,',
'            p_dt_fim_fim,',
'            p_dt_fim_fim,',
'            fn_normalizar_flag(p_ind_sla_violado),',
'            fn_normalizar_flag(p_ind_sla_violado),',
'            fn_normalizar_flag(p_ind_expirada_ttl),',
'            fn_normalizar_flag(p_ind_expirada_ttl),',
'            fn_normalizar_flag(p_ind_bloqueada),',
'            fn_normalizar_flag(p_ind_bloqueada);',
'  end prc_consultar_mensagens;',
'',
'  procedure prc_obter_detalhe_solicitacao(',
'    p_id_solicitacao in number,',
'    p_result         out t_cursor',
'  ) is',
'    l_sql varchar2(32767);',
'  begin',
'    l_sql := ''select se.id as id_solicitacao, ''',
'          || ''       se.id_artefato, ''',
'          || ''       se.id_tenant, ''',
'          || ''       se.id_usuario, ''',
'          || ''       se.tipo_acao, ''',
'          || ''       se.id_negocio, ''',
'          || ''       se.id_correlation, ''',
'          || ''       se.status, ''',
'          || ''       se.prioridade, ''',
'          || ''       se.parametros, ''',
'          || ''       se.conteudo, ''',
'          || ''       se.dt_criacao, ''',
'          || ''       se.dt_disponivel_execucao, ''',
'          || ''       se.dt_inicio, ''',
'          || ''       se.dt_fim, ''',
'          || ''       se.tentativas, ''',
'          || ''       se.motivo_falha, ''',
'          || ''       se.id_worker, ''',
'          || ''       se.dt_saude ''',
'          || ''  from mae_solicitacao_execucao se ''',
'          || '' where se.id = :1'';',
'',
'    open p_result for l_sql using p_id_solicitacao;',
'  end prc_obter_detalhe_solicitacao;',
'',
'  procedure prc_consultar_eventos(',
'    p_id_solicitacao in number,',
'    p_ordem          in varchar2 default ''ASC'',',
'    p_result         out t_cursor',
'  ) is',
'    l_sql    varchar2(32767);',
'    l_ordem  varchar2(4) := case upper(nvl(p_ordem, ''ASC'')) when ''DESC'' then ''DESC'' else ''ASC'' end;',
'  begin',
'    l_sql := ''select rt.dt_evento, ''',
'          || ''       rt.tipo_evento, ''',
'          || ''       rt.resultado, ''',
'          || ''       rt.id_worker, ''',
'          || ''       rt.detalhes ''',
'          || ''  from mae_registro_tecnico rt ''',
'          || '' where rt.id_solicitacao = :1 ''',
'          || '' order by rt.dt_evento '' || l_ordem;',
'',
'    open p_result for l_sql using p_id_solicitacao;',
'  end prc_consultar_eventos;',
'',
'  procedure prc_consultar_jobs(',
'    p_id_artefato in number default null,',
'    p_result      out t_cursor',
'  ) is',
'    l_sql      varchar2(32767);',
'  begin',
'    l_sql := ''select sc.id as id_sched_cfg, ''',
'          || ''       sc.id_artefato, ''',
'          || ''       pkg_maestro_worker_run.gerar_nome_job_fila(sc.id) as job_name, ''',
'          || ''       uj.enabled, ''',
'          || ''       uj.state, ''',
'          || ''       uj.last_start_date, ''',
'          || ''       uj.next_run_date ''',
'          || ''  from mae_sched_cfg sc ''',
'          || ''  left join user_scheduler_jobs uj ''',
'          || ''    on uj.job_name = upper(pkg_maestro_worker_run.gerar_nome_job_fila(sc.id)) ''',
'          || '' where (:1 is null or sc.id_artefato = :2) ''',
'          || '' order by sc.id_artefato'';',
'',
'    open p_result for l_sql using p_id_artefato, p_id_artefato;',
'  end prc_consultar_jobs;',
'',
'  procedure prc_reprocessar_mensagem(',
'    p_id_solicitacao in number,',
'    p_id_usuario     in number default null',
'  ) is',
'    l_status     varchar2(50);',
'    l_usuario_id number := nvl(p_id_usuario, fn_obter_id_usuario_atual);',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_reprocessar_mensagem);',
'',
'    execute immediate ''select status from mae_solicitacao_execucao where id = :1''',
'      into l_status',
'      using p_id_solicitacao;',
'',
'    if l_status not in (''FALHA_NEGOCIO'', ''FALHA_TECNICA'', ''ERRO_FINAL'') then',
'      raise_application_error(-20020, ''Status nao elegivel para reprocessamento manual.'');',
'    end if;',
'',
'    begin',
'      pkg_maestro_api.reprocessar(p_id_solicitacao, l_usuario_id);',
'    exception',
'      when others then',
'        raise;',
'    end;',
'  end prc_reprocessar_mensagem;',
'',
'    procedure executar_solicitacao_manual(',
'        p_id in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    )is',
'    begin',
'        prc_executar_solicitacao_manual(',
'            p_id_solicitacao => p_id    ',
'        );',
'    end;',
'',
'  procedure prc_executar_solicitacao_manual(',
'    p_id_solicitacao in number,',
'    p_id_usuario     in number default null',
'  ) is',
'    l_usuario_id              number := nvl(p_id_usuario, fn_obter_id_usuario_atual);',
'    l_status                  mae_solicitacao_execucao.status%type;',
'    l_id_artefato             mae_solicitacao_execucao.id_artefato%type;',
'    l_id_tenant               mae_solicitacao_execucao.id_tenant%type;',
'    l_id_correlation          mae_solicitacao_execucao.id_correlation%type;',
'    l_id_negocio              mae_solicitacao_execucao.id_negocio%type;',
'    l_dt_criacao              mae_solicitacao_execucao.dt_criacao%type;',
'    l_dt_disponivel_anterior  mae_solicitacao_execucao.dt_disponivel_execucao%type;',
'    l_limite_execucao         number;',
'    l_execucoes_atuais        number;',
'    l_cb_result               varchar2(30);',
'    l_qtd_precedencia         number := 0;',
'    l_id_worker               number := 0;',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_alterar_status);',
'',
'    select status,',
'           id_artefato,',
'           id_tenant,',
'           id_correlation,',
'           id_negocio,',
'           dt_criacao,',
'           dt_disponivel_execucao',
'      into l_status,',
'           l_id_artefato,',
'           l_id_tenant,',
'           l_id_correlation,',
'           l_id_negocio,',
'           l_dt_criacao,',
'           l_dt_disponivel_anterior',
'      from mae_solicitacao_execucao',
'     where id = p_id_solicitacao',
'       for update;',
'',
'    if l_status <> ''PENDENTE'' then',
'      raise_application_error(-20023, ''A solicitacao precisa estar PENDENTE para execucao manual antecipada.'');',
'    end if;',
'',
'    if l_id_negocio is not null then',
'      select count(*)',
'        into l_qtd_precedencia',
'        from mae_solicitacao_execucao p',
'       where p.id_negocio = l_id_negocio',
'         and p.status in (''PENDENTE'', ''EM_PROCESSAMENTO'')',
'         and p.id <> p_id_solicitacao',
'         and (',
'              p.dt_criacao < l_dt_criacao',
'              or (p.dt_criacao = l_dt_criacao and p.id < p_id_solicitacao)',
'         );',
'',
'      if l_qtd_precedencia > 0 then',
'        raise_application_error(-20024, ''Existe solicitacao anterior do mesmo negocio pendente/em processamento.'');',
'      end if;',
'    end if;',
'',
'    l_cb_result := pkg_maestro_cfg.tentar_permitir_execucao_cb(',
'      p_id_artefato    => l_id_artefato,',
'      p_id_solicitacao => p_id_solicitacao,',
'      p_id_worker      => null,',
'      p_id_tenant      => l_id_tenant,',
'      p_id_correlation => l_id_correlation',
'    );',
'',
'    if l_cb_result = pkg_maestro_cfg.c_cb_result_bloqueado then',
'      raise_application_error(-20025, ''Execucao manual bloqueada pelo circuit breaker do artefato.'');',
'    end if;',
'',
'    l_limite_execucao := pkg_maestro_cfg.obter_limite_execucao_simultanea(',
'      p_id_artefato => l_id_artefato',
'    );',
'',
'    if l_limite_execucao is not null then',
'      select count(*)',
'        into l_execucoes_atuais',
'        from mae_solicitacao_execucao',
'       where id_artefato = l_id_artefato',
'         and status = ''EM_PROCESSAMENTO'';',
'',
'      if l_execucoes_atuais >= l_limite_execucao then',
'        raise_application_error(-20026, ''Limite de execucao simultanea atingido para o artefato.'');',
'      end if;',
'    end if;',
'',
'    update mae_solicitacao_execucao',
'       set dt_disponivel_execucao = systimestamp,',
'           dt_saude               = sysdate',
'     where id = p_id_solicitacao',
'       and status = ''PENDENTE'';',
'',
'    if sql%rowcount <> 1 then',
'      raise_application_error(-20027, ''Nao foi possivel reservar a solicitacao para execucao manual.'');',
'    end if;',
'',
'    prc_registrar_evento_manual(',
'      p_id_solicitacao => p_id_solicitacao,',
'      p_tipo_evento    => ''EXECUCAO_MANUAL_ANTECIPADA'',',
'      p_resultado      => ''INFO'',',
'      p_detalhes       => ''status_anterior=PENDENTE; status_novo=EM_PROCESSAMENTO; dt_disponivel_anterior='' ||',
'                          to_char(l_dt_disponivel_anterior, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM'') ||',
'                          ''; dt_disponivel_nova='' ||',
'                          to_char(systimestamp, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM'') ||',
'                          ''; cb_result='' || nvl(l_cb_result, ''<null>''),',
'      p_id_usuario     => l_usuario_id',
'    );',
'',
'    select id into l_id_worker from mae_sched_cfg where id_artefato = l_id_artefato;',
'    pkg_maestro_worker_run.run_once(l_id_worker);',
'  exception',
'    when no_data_found then',
'      raise_application_error(-20028, ''Solicitacao nao encontrada para execucao manual antecipada: '' || p_id_solicitacao);',
'  end prc_executar_solicitacao_manual;',
'',
'  procedure prc_executar_fila(',
'    p_id_sched_cfg in number,',
'    p_id_usuario   in number default null',
'  ) is',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_alterar_configuracao);',
'',
'    pkg_maestro_worker_run.executar_job_fila(p_id_sched_cfg);',
'  end prc_executar_fila;',
'',
'  procedure prc_parar_fila(',
'    p_id_sched_cfg in number,',
'    p_id_usuario   in number default null',
'  ) is',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_alterar_configuracao);',
'',
'    update mae_sched_cfg',
'       set ativo = ''N''',
'     where id = p_id_sched_cfg;',
'',
'    if sql%rowcount = 0 then',
'      raise_application_error(-20021, ''Configuracao da fila nao localizada para parada: '' || p_id_sched_cfg);',
'    end if;',
'',
'    pkg_maestro_worker_run.parar_job_fila(',
'      p_id_sched_cfg => p_id_sched_cfg,',
'      p_force        => true',
'    );',
'  end prc_parar_fila;',
'',
'  procedure prc_habilitar_fila(',
'    p_id_sched_cfg in number,',
'    p_recriar_job  in varchar2 default ''N'',',
'    p_id_usuario   in number default null',
'  ) is',
'    l_recriar_job varchar2(1) := fn_normalizar_sn(p_recriar_job, ''P_RECRIAR_JOB'');',
'    l_job_name    varchar2(128);',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_alterar_configuracao);',
'',
'    update mae_sched_cfg',
'       set ativo = ''S''',
'     where id = p_id_sched_cfg;',
'',
'    if sql%rowcount = 0 then',
'      raise_application_error(-20022, ''Configuracao da fila nao localizada para habilitacao: '' || p_id_sched_cfg);',
'    end if;',
'',
'    l_job_name := pkg_maestro_worker_run.gerar_nome_job_fila(p_id_sched_cfg);',
'',
'    if l_recriar_job = ''S'' then',
'      pkg_maestro_worker_run.criar_job_fila(p_id_sched_cfg);',
'      return;',
'    end if;',
'',
'    begin',
'      dbms_scheduler.enable(l_job_name);',
'    exception',
'      when others then',
'        pkg_maestro_worker_run.criar_job_fila(p_id_sched_cfg);',
'    end;',
'',
'  end prc_habilitar_fila;',
'',
'  procedure prc_resetar_circuit_breaker(',
'    p_id_artefato in number,',
'    p_id_usuario  in number default null',
'  ) is',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_alterar_configuracao);',
'',
'    pkg_maestro_cfg.resetar_circuit_breaker(p_id_artefato);',
'  end prc_resetar_circuit_breaker;',
'',
'  procedure prc_desbloquear_mensagem(',
'    p_id_solicitacao in number,',
'    p_observacao     in varchar2 default null,',
'    p_id_usuario     in number default null',
'  ) is',
'    l_total   number;',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_desbloquear_mensagem);',
'    prc_validar_status(p_id_solicitacao, ''BLOQUEADA'');',
'',
'    execute immediate',
'      ''update mae_solicitacao_execucao ''',
'      || ''   set status = ''''PENDENTE'''', ''',
'      || ''       tentativas = 0, ''',
'      || ''       motivo_falha = null, ''',
'       || ''       id_worker = null, ''',
'       || ''       dt_inicio = null, ''',
'       || ''       dt_fim = null, ''',
'       || ''       dt_saude = null, ''',
'       || ''       dt_expiracao = null, ''',
'       || ''       dt_disponivel_execucao = systimestamp ''',
'       || '' where id = :1 ''',
'       || ''   and status = ''''BLOQUEADA'''''' using p_id_solicitacao;',
'',
'    l_total := sql%rowcount;',
'',
'    if l_total = 0 then',
'      raise_application_error(-20030, ''Mensagem nao estava mais bloqueada no momento da operacao.'');',
'    end if;',
'',
'    prc_registrar_evento_manual(',
'      p_id_solicitacao => p_id_solicitacao,',
'      p_tipo_evento    => ''MENSAGEM_DESBLOQUEADA_MANUAL'',',
'      p_resultado      => ''SUCESSO'',',
'      p_detalhes       => nvl(p_observacao, ''Mensagem desbloqueada manualmente.''),',
'      p_id_usuario     => p_id_usuario',
'    );',
'  end prc_desbloquear_mensagem;',
'',
'  procedure prc_alterar_status(',
'    p_id_solicitacao in number,',
'    p_novo_status    in varchar2,',
'    p_observacao     in varchar2 default null,',
'    p_id_usuario     in number default null',
'  ) is',
'    l_novo_status   varchar2(50) := upper(trim(p_novo_status));',
'    l_status_atual  mae_solicitacao_execucao.status%type;',
'    l_observacao    varchar2(4000) := substr(trim(p_observacao), 1, 4000);',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_alterar_status);',
'',
'    if l_novo_status not in (''PENDENTE'', ''BLOQUEADA'', ''FALHA_TECNICA'', ''FALHA_NEGOCIO'', ''ERRO_FINAL'', ''EXPIRADO'') then',
'      raise_application_error(-20040, ''Novo status nao permitido para alteracao manual controlada.'');',
'    end if;',
'',
'    select status',
'      into l_status_atual',
'      from mae_solicitacao_execucao',
'     where id = p_id_solicitacao',
'       for update;',
'',
'    if l_status_atual = l_novo_status then',
'      raise_application_error(-20041, ''Nenhuma alteracao de status foi aplicada. A solicitacao ja esta em '' || l_novo_status || ''.'');',
'    end if;',
'',
'    if l_status_atual = ''EM_PROCESSAMENTO'' then',
'      raise_application_error(-20042, ''Nao e permitido alterar manualmente uma solicitacao em processamento.'');',
'    end if;',
'',
'    if l_novo_status = ''PENDENTE'' then',
'      update mae_solicitacao_execucao',
'         set status                 = ''PENDENTE'',',
'             tentativas             = 0,',
'             motivo_falha           = null,',
'             id_worker              = null,',
'             dt_inicio              = null,',
'             dt_fim                 = null,',
'             dt_saude               = null,',
'             dt_expiracao           = null,',
'             dt_disponivel_execucao = systimestamp',
'       where id = p_id_solicitacao',
'         and status = l_status_atual;',
'    elsif l_novo_status = ''BLOQUEADA'' then',
'      update mae_solicitacao_execucao',
'         set status       = ''BLOQUEADA'',',
'             id_worker    = null,',
'             dt_inicio    = null,',
'             dt_fim       = null,',
'             dt_saude     = null,',
'             dt_expiracao = null,',
'             motivo_falha = nvl(l_observacao, motivo_falha)',
'       where id = p_id_solicitacao',
'         and status = l_status_atual;',
'    elsif l_novo_status = ''EXPIRADO'' then',
'      update mae_solicitacao_execucao',
'         set status       = ''EXPIRADO'',',
'             dt_fim       = nvl(dt_fim, sysdate),',
'             dt_expiracao = nvl(dt_expiracao, sysdate),',
'             id_worker    = null,',
'             dt_saude     = null,',
'             motivo_falha = nvl(l_observacao, nvl(motivo_falha, ''Alteracao manual para EXPIRADO''))',
'       where id = p_id_solicitacao',
'         and status = l_status_atual;',
'    else',
'      update mae_solicitacao_execucao',
'         set status       = l_novo_status,',
'             dt_fim       = nvl(dt_fim, sysdate),',
'             id_worker    = null,',
'             dt_saude     = null,',
'             dt_expiracao = null,',
'             motivo_falha = nvl(l_observacao, nvl(motivo_falha, ''Alteracao manual para '' || l_novo_status))',
'       where id = p_id_solicitacao',
'         and status = l_status_atual;',
'    end if;',
'',
'    if sql%rowcount = 0 then',
'      raise_application_error(-20043, ''Nenhuma alteracao de status foi aplicada. Verifique concorrencia ou status atual.'');',
'    end if;',
'',
'    prc_registrar_evento_manual(',
'      p_id_solicitacao => p_id_solicitacao,',
'      p_tipo_evento    => ''ALTERACAO_STATUS_MANUAL'',',
'      p_resultado      => ''SUCESSO'',',
'      p_detalhes       => ''status_anterior='' || l_status_atual || ''; status_novo='' || l_novo_status ||',
'                          case',
'                            when l_observacao is not null then ''; observacao='' || l_observacao',
'                            else null',
'                          end,',
'      p_id_usuario     => p_id_usuario',
'    );',
'  exception',
'    when no_data_found then',
'      raise_application_error(-20044, ''Solicitacao nao encontrada para alteracao manual de status: '' || p_id_solicitacao);',
'  end prc_alterar_status;',
'',
'  procedure prc_atualizar_config_fila(',
'    p_id_sched_cfg         in number,',
'    p_ativo                in varchar2 default null,',
'    p_intervalo_segundos   in number default null,',
'    p_ind_paralelo         in varchar2 default null,',
'    p_observacao           in varchar2 default null,',
'    p_id_usuario           in number default null',
'  ) is',
'    l_total         number;',
'    l_ativo         varchar2(1) := fn_normalizar_sn(p_ativo, ''P_ATIVO'');',
'    l_ind_paralelo  varchar2(1) := fn_normalizar_sn(p_ind_paralelo, ''P_IND_PARALELO'');',
'    l_ativo_atual   mae_sched_cfg.ativo%type;',
'  begin',
'    prc_assert_permissao(pkg_maestro_admin.c_oper_alterar_configuracao);',
'',
'    if p_intervalo_segundos is not null and p_intervalo_segundos <= 0 then',
'      raise_application_error(-20045, ''P_INTERVALO_SEGUNDOS deve ser maior que zero.'');',
'    end if;',
'',
'    execute immediate',
'      ''update mae_sched_cfg ''',
'      || ''   set ativo = nvl(:2, ativo), ''',
'      || ''       intervalo_segundos = nvl(:3, intervalo_segundos), ''',
'      || ''       ind_paralelo = nvl(:4, ind_paralelo) ''',
'      || '' where id = :1''',
'      using p_id_sched_cfg,',
'            l_ativo,',
'            p_intervalo_segundos,',
'            l_ind_paralelo;',
'',
'    l_total := sql%rowcount;',
'',
'    if l_total = 0 then',
'      raise_application_error(-20050, ''Configuracao da fila nao localizada para atualizacao.'');',
'    end if;',
'',
'    select ativo',
'      into l_ativo_atual',
'      from mae_sched_cfg',
'     where id = p_id_sched_cfg;',
'',
'    if l_ativo_atual = ''N'' then',
'      begin',
'        pkg_maestro_worker_run.parar_job_fila(',
'          p_id_sched_cfg => p_id_sched_cfg,',
'          p_force        => true',
'        );',
'      exception',
'        when others then',
'          null;',
'      end;',
'      return;',
'    end if;',
'',
'    if l_ativo_atual = ''S'' and (l_ativo = ''S'' or p_intervalo_segundos is not null) then',
'      pkg_maestro_worker_run.criar_job_fila(p_id_sched_cfg);',
'    end if;',
'  end prc_atualizar_config_fila;',
'',
'  function norm_enabled(p_enabled varchar2) return boolean is',
'  begin',
'    return upper(trim(nvl(p_enabled,''N''))) in (''S'',''SIM'',''Y'',''YES'',''TRUE'',''T'',''1'');',
'  end;',
'',
'  procedure salvar_agendamento(',
'      p_job_name        in varchar2,',
'      p_enabled         in varchar2,',
'      p_start_date      in date,',
'      p_repeat_interval in varchar2,',
'',
'      p_id_tenant       in number,',
'      p_codigo_artefato in varchar2,',
'      p_id_usuario      in number,',
'      p_id_negocio      in varchar2,',
'      p_payload         in clob,',
'      p_prioridade      in number,',
'      p_tipo_acao       in varchar2,',
'',
'      p_sucesso         out clob,',
'      p_messages        out pkg_mensagem.message_record_table,',
'',
'      p_repeat_freq     in varchar2 default null,',
'      p_repeat_x        in number   default null,',
'      p_byday           in varchar2 default null,',
'      p_monthday        in number   default null,',
'      p_hour            in number   default null,',
'      p_minute          in number   default null',
'  ) is',
'    l_job_name   varchar2(128) := upper(trim(p_job_name));',
'    l_enabled    boolean       := norm_enabled(p_enabled);',
'    l_start_ts   timestamp     := cast(p_start_date as timestamp);',
'',
'    l_has_job    number;',
'',
'    l_id_artefato number;',
'',
'    l_freq       varchar2(30) := upper(nullif(trim(p_repeat_freq), ''''));',
'    l_rule_ui    varchar2(4000) := nullif(trim(p_repeat_interval), '''');',
'    l_repeat     varchar2(4000);',
'',
'    l_h          number;',
'    l_m          number;',
'',
'    l_byday      varchar2(200);',
'    l_x          number;',
'    l_md         number;',
'  begin',
'    l_job_name := upper(trim(p_job_name));',
'    l_enabled  := norm_enabled(p_enabled);',
'',
'    if l_job_name is null then',
unistr('      raise_application_error(-20001, ''MAE-AGENDA|JOB_NAME \00E9 obrigat\00F3rio'');'),
'    end if;',
'    if p_id_tenant is null then',
unistr('      raise_application_error(-20001, ''MAE-AGENDA|ID_TENANT \00E9 obrigat\00F3rio'');'),
'    end if;',
'    if trim(p_codigo_artefato) is null then',
unistr('      raise_application_error(-20001, ''MAE-AGENDA|CODIGO_ARTEFATO \00E9 obrigat\00F3rio'');'),
'    end if;',
'    if p_id_usuario is null then',
unistr('      raise_application_error(-20001, ''MAE-AGENDA|ID_USUARIO \00E9 obrigat\00F3rio'');'),
'    end if;',
'    if p_start_date is null then',
unistr('      raise_application_error(-20001, ''MAE-AGENDA|START_DATE \00E9 obrigat\00F3rio'');'),
'    end if;',
'',
'    l_start_ts := cast(p_start_date as timestamp);',
'',
'    --------------------------------------------------------------------',
'    -- 1) Determinar repeat_interval efetivo (l_repeat)',
'    --    Prioridade:',
'    --      (a) Se veio p_repeat_interval -> usa',
unistr('    --      (b) Se n\00E3o veio, mas veio p_repeat_freq -> gera pelo dom\00EDnio'),
unistr('    --      (c) Se n\00E3o veio nenhum -> execu\00E7\00E3o \00FAnica (l_repeat null)'),
'    --------------------------------------------------------------------',
'    l_repeat := nullif(trim(p_repeat_interval), '''');',
'    l_freq   := upper(nullif(trim(p_repeat_freq), ''''));',
'',
unistr('    -- Hor\00E1rio default (se n\00E3o vier separado)'),
'    l_h := nvl(p_hour,   to_number(to_char(p_start_date,''HH24'')));',
'    l_m := nvl(p_minute, to_number(to_char(p_start_date,''MI'')));',
'',
'  --------------------------------------------------------------------',
'    -- 1) Montar REPEAT_INTERVAL efetivo (l_repeat)',
'    --    Aceita:',
unistr('    --      - T\00E9cnico completo: FREQ=...'),
unistr('    --      - Amig\00E1vel conforme o dom\00EDnio:'),
'    --        HORAS/MINUTOS/SEGUNDOS -> "10"',
'    --        SEMANAL               -> "MO" / "MO,WE,FR"',
unistr('    --        MENSAL                -> "10" (dia do m\00EAs)'),
'    --        DIARIO                -> vazio (usa start_date)',
'    --------------------------------------------------------------------',
'    l_repeat := null;',
'',
unistr('    -- Se n\00E3o for recorrente, caller deve passar freq nula e regra nula.'),
unistr('    -- Aqui: se n\00E3o veio freq e n\00E3o veio regra -> execu\00E7\00E3o \00FAnica.'),
'    if l_freq is null and l_rule_ui is null then',
unistr('      l_repeat := null; -- execu\00E7\00E3o \00FAnica'),
'    else',
unistr('      -- Se usu\00E1rio j\00E1 informou formato t\00E9cnico completo'),
'      if l_rule_ui is not null and upper(substr(l_rule_ui,1,5)) = ''FREQ='' then',
'        l_repeat := l_rule_ui;',
'      else',
unistr('        -- Se n\00E3o tem freq, n\00E3o tem como interpretar'),
'        if l_freq is null then',
unistr('          raise_application_error(-20001, ''MAE-AGENDA|Informe a Frequ\00EAncia para interpretar a Regra de Recorr\00EAncia'');'),
'        end if;',
'',
unistr('        -- Preferir par\00E2metros separados, se vierem (futuro)'),
'        l_x     := p_repeat_x;',
'        l_byday := p_byday;',
'        l_md    := p_monthday;',
'',
unistr('        -- Se ainda n\00E3o vieram separados, inferir do campo "Regra de Recorr\00EAncia"'),
unistr('        -- HORAS/MINUTOS/SEGUNDOS: regra = n\00FAmero'),
'        if l_x is null',
'           and l_rule_ui is not null',
'           and regexp_like(l_rule_ui, ''^\d+$'')',
'           and l_freq in (''HORAS'',''MINUTOS'',''SEGUNDOS'') then',
'          l_x := to_number(l_rule_ui);',
'        end if;',
'',
unistr('        -- MENSAL: regra = dia do m\00EAs (n\00FAmero)'),
'        if l_md is null',
'           and l_rule_ui is not null',
'           and regexp_like(l_rule_ui, ''^\d+$'')',
'           and l_freq = ''MENSAL'' then',
'          l_md := to_number(l_rule_ui);',
'        end if;',
'',
'        -- SEMANAL: regra = BYDAY (MO,TU,...)',
unistr('        -- l_rule_ui \00E9 o que veio no campo "Regra de Recorr\00EAncia"'),
'        if l_freq = ''SEMANAL'' then',
'          if regexp_like(upper(replace(l_rule_ui,'' '','''')),',
'                         ''^(MO|TU|WE|TH|FR|SA|SU)(,(MO|TU|WE|TH|FR|SA|SU))*$'') then',
'            l_byday := upper(replace(l_rule_ui,'' '',''''));',
'          else',
'            l_byday := fn_mae_byday_ptbr_to_en(l_rule_ui); -- seg,qua,sex -> MO,WE,FR',
'          end if;',
'        end if;',
'',
unistr('        -- DIARIO: se regra vazia, monta a partir do hor\00E1rio'),
'        if l_freq = ''DIARIO'' and l_rule_ui is null then',
'          l_repeat := build_repeat_interval(',
'                        p_repeat_freq => l_freq,',
'                        p_hour        => l_h,',
'                        p_minute      => l_m',
'                      );',
'        elsif l_freq in (''HORAS'',''MINUTOS'',''SEGUNDOS'') then',
'          if nvl(l_x,0) < 1 then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|Para ''||l_freq||'' informe um valor num\00E9rico (X) >= 1 na Regra de Recorr\00EAncia'');'),
'          end if;',
'',
'          l_repeat := build_repeat_interval(',
'                        p_repeat_freq => l_freq,',
'                        p_x           => l_x,',
'                        p_hour        => l_h,',
'                        p_minute      => l_m',
'                      );',
'        elsif l_freq = ''SEMANAL'' then',
'          if l_byday is null then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|Para SEMANAL informe os dias (MO,TU,WE...) na Regra de Recorr\00EAncia:''||l_byday);'),
'          end if;',
'',
'          l_repeat := build_repeat_interval(',
'                        p_repeat_freq => l_freq,',
'                        p_byday       => l_byday,',
'                        p_hour        => l_h,',
'                        p_minute      => l_m',
'                      );',
'        elsif l_freq = ''MENSAL'' then',
'          if l_md is null or l_md not between 1 and 31 then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|Para MENSAL informe o dia do m\00EAs (1..31) na Regra de Recorr\00EAncia'');'),
'          end if;',
'',
'          l_repeat := build_repeat_interval(',
'                        p_repeat_freq => l_freq,',
'                        p_monthday    => l_md,',
'                       '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(16262969604935681)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' p_hour        => l_h,',
'                        p_minute      => l_m',
'                      );',
'        -- ANUAL: regra = meses do ano (1..12) em CSV: "1,5,10,12"',
'        elsif l_freq = ''ANUAL'' then',
'          declare',
'            l_months_csv varchar2(4000);',
'            l_tok        varchar2(30);',
'            l_i          number := 1;',
'            l_mes        number;',
'            l_dom        number := to_number(to_char(p_start_date, ''DD'')); -- dia vem do start_date',
'          begin',
'            if l_rule_ui is null then',
unistr('              raise_application_error(-20001, ''MAE-AGENDA|Para ANUAL informe os meses (1..12) na Regra de Recorr\00EAncia. Ex.: 1,5,10,12'');'),
'            end if;',
'',
'            l_months_csv := replace(trim(l_rule_ui), '' '', '''');',
'',
'            -- valida formato: "1,5,10,12"',
'            if not regexp_like(l_months_csv, ''^\d+(,\d+)*$'') then',
unistr('              raise_application_error(-20001, ''MAE-AGENDA|Para ANUAL informe apenas n\00FAmeros separados por v\00EDrgula (ex.: 1,5,10,12)'');'),
'            end if;',
'',
unistr('            -- valida cada m\00EAs (1..12)'),
'            loop',
'              l_tok := regexp_substr(l_months_csv, ''[^,]+'', 1, l_i);',
'              exit when l_tok is null;',
'',
'              l_mes := to_number(l_tok);',
'              if l_mes not between 1 and 12 then',
unistr('                raise_application_error(-20001, ''MAE-AGENDA|M\00EAs inv\00E1lido em ANUAL (1..12): ''||l_mes);'),
'              end if;',
'',
'              l_i := l_i + 1;',
'            end loop;',
'',
unistr('            -- monta repeat_interval t\00E9cnico YEARLY'),
'            l_repeat :=',
'              ''FREQ=YEARLY''||',
'              '';BYMONTH=''||l_months_csv||',
'              '';BYMONTHDAY=''||l_dom||',
'              '';BYHOUR=''||l_h||',
'              '';BYMINUTE=''||l_m||',
'              '';BYSECOND=0'';',
'          end;                      ',
'        else',
unistr('          raise_application_error(-20001, ''MAE-AGENDA|Frequ\00EAncia inv\00E1lida: ''||l_freq);'),
'        end if;',
'      end if;',
'    end if;',
'',
unistr('    -- Se o agendamento for "\00FAnico", l_repeat fica null (ok)'),
'    -- Se for recorrente, l_repeat deve estar preenchido',
unistr('    -- (Se voc\00EA quiser validar pelo tipo_agendamento, fa\00E7a no caller)'),
'    --------------------------------------------------------------------',
'',
'    --------------------------------------------------------------------',
unistr('    -- 2) UPSERT na tabela de configura\00E7\00E3o (robusto p/ payload)'),
'    --------------------------------------------------------------------',
'    merge into mae_agenda_cfg t',
'    using (select l_job_name as job_name from dual) s',
'       on (t.job_name = s.job_name)',
'    when matched then update set',
'      t.ativo           = ''S'',',
'      t.id_tenant       = p_id_tenant,',
'      t.id_artefato     = trim(p_codigo_artefato),',
'      t.id_usuario      = p_id_usuario,',
'      t.id_negocio      = nullif(trim(p_id_negocio), ''''),',
'      t.payload         = p_payload,',
'      t.prioridade      = p_prioridade,',
'      t.tipo_acao       = nullif(trim(p_tipo_acao), ''''),',
'      t.dt_atualizacao  = systimestamp',
'    when not matched then insert (',
'      job_name, ativo, id_tenant, id_artefato, id_usuario,',
'      id_negocio, payload, prioridade, tipo_acao, dt_criacao, dt_atualizacao',
'    ) values (',
'      l_job_name, ''S'', p_id_tenant, trim(p_codigo_artefato), p_id_usuario,',
'      nullif(trim(p_id_negocio), ''''), p_payload, p_prioridade, nullif(trim(p_tipo_acao), ''''),',
'      systimestamp, systimestamp',
'    );',
'',
'    --------------------------------------------------------------------',
unistr('    -- 3) Drop/Recreate do job (idempot\00EAncia simples)'),
'    --------------------------------------------------------------------',
'    select count(*)',
'      into l_has_job',
'      from user_scheduler_jobs',
'     where job_name = l_job_name;',
'',
'    if l_has_job > 0 then',
'      dbms_scheduler.drop_job(job_name => l_job_name, force => true);',
'    end if;',
'',
'    --------------------------------------------------------------------',
unistr('    -- 4) Create Job: chama procedure fixa (n\00E3o embute payload)'),
'    --------------------------------------------------------------------',
'    dbms_scheduler.create_job(  ',
'      job_name            => l_job_name,',
'      job_type            => ''STORED_PROCEDURE'',',
'      job_action          => ''PKG_MAESTRO_MONITORAMENTO.RUN_AGENDAMENTO'',',
unistr('      number_of_arguments => 1,               -- \2705 IMPORTANTE'),
'      start_date          => l_start_ts,',
'      repeat_interval     => l_repeat,',
'      enabled             => false,',
'      auto_drop           => false,',
'      comments            => ''Agendamento MAESTRO (postar_requisicao) - UI''',
'    );',
'',
'    dbms_scheduler.set_job_argument_value(',
'      job_name          => l_job_name,',
'      argument_position => 1,',
'      argument_value    => l_job_name',
'    );',
'',
'    --------------------------------------------------------------------',
unistr('    -- 5) Marca\00E7\00E3o p/ listagem (JOB_SUBNAME = ''AGENDA_MAESTRO'')'),
unistr('    --    Se o atributo n\00E3o existir no seu Oracle, n\00E3o bloqueia.'),
'    --------------------------------------------------------------------',
'    begin',
'      dbms_scheduler.set_attribute(',
'        name      => l_job_name,',
'        attribute => ''job_subname'',',
'        value     => ''AGENDA_MAESTRO''',
'      );',
'    exception',
'      when others then',
'        null;',
'    end;',
'',
'    --------------------------------------------------------------------',
'    -- 6) Enable/Disable conforme tela',
'    --------------------------------------------------------------------',
'    if l_enabled then',
'      dbms_scheduler.enable(l_job_name);',
'    else',
'      dbms_scheduler.disable(l_job_name, force => true);',
'    end if;',
'',
'    p_sucesso := ''Agendamento salvo com sucesso: ''||l_job_name;',
'',
unistr('    -- p_messages depende do seu framework; deixar vazio \00E9 seguro'),
'    null;',
'',
'  exception',
'      when others then',
'        begin',
'          dbms_scheduler.drop_job(job_name => upper(trim(p_job_name)), force => true);',
'        exception',
'          when others then null;',
'        end;',
'',
'        raise_application_error(',
'          -20001,',
'          ''MAE-AGENDA|Falha ao salvar agendamento JOB=''||upper(trim(p_job_name))||',
'          '' - ''||substr(sqlerrm,1,300)',
'        );',
'  end salvar_agendamento;',
'',
'    function build_repeat_interval(',
'        p_repeat_freq   in varchar2,',
'        p_x             in number   default null,  -- usado por SEGUNDOS/MINUTOS/HORAS',
'        p_byday         in varchar2 default null,  -- usado por SEMANAL (MO,TU,WE...)',
'        p_monthday      in number   default null,  -- usado por MENSAL (1..31)',
'        p_hour          in number   default null,  -- usado por DIARIO/SEMANAL/MENSAL',
'        p_minute        in number   default null   -- usado por DIARIO/SEMANAL/MENSAL',
'    ) return varchar2',
'    is',
'        l_freq varchar2(30) := upper(trim(p_repeat_freq));',
'        l_x    number := p_x;',
'        l_h    number := p_hour;',
'        l_m    number := p_minute;',
'    begin',
'        if l_freq is null then',
'            return null;',
'        end if;',
'',
'        if l_freq = ''SEGUNDOS'' then',
'            if nvl(l_x,0) < 1 then',
'                raise_application_error(-20001, ''MAE-AGENDA|Informe X (segundos) >= 1'');',
'            end if;',
'            return ''FREQ=SECONDLY;INTERVAL=''||l_x;',
'',
'        elsif l_freq = ''MINUTOS'' then',
'            if nvl(l_x,0) < 1 then',
'                raise_application_error(-20001, ''MAE-AGENDA|Informe X (minutos) >= 1'');',
'            end if;',
'            return ''FREQ=MINUTELY;INTERVAL=''||l_x;',
'',
'        elsif l_freq = ''HORAS'' then',
'            if nvl(l_x,0) < 1 then',
'                raise_application_error(-20001, ''MAE-AGENDA|Informe X (horas) >= 1'');',
'            end if;',
'            return ''FREQ=HOURLY;INTERVAL=''||l_x;',
'',
'        elsif l_freq = ''DIARIO'' then',
'            if l_h is null or l_m is null or l_h not between 0 and 23 or l_m not between 0 and 59 then',
unistr('                raise_application_error(-20001, ''MAE-AGENDA|Informe hor\00E1rio v\00E1lido (HH 0..23 / MM 0..59)'');'),
'            end if;',
'            return ''FREQ=DAILY;BYHOUR=''||l_h||'';BYMINUTE=''||l_m||'';BYSECOND=0'';',
'',
'        elsif l_freq = ''SEMANAL'' then',
'            if p_byday is null then',
'                raise_application_error(-20001, ''MAE-AGENDA|Informe os dias da semana (MO,TU,WE,TH,FR,SA,SU)'');',
'            end if;',
'            if l_h is null or l_m is null or l_h not between 0 and 23 or l_m not between 0 and 59 then',
unistr('                raise_application_error(-20001, ''MAE-AGENDA|Informe hor\00E1rio v\00E1lido (HH 0..23 / MM 0..59):''||l_h||'' + ''|| l_m ||'' + ''||l_h);'),
'            end if;',
'            return ''FREQ=WEEKLY;BYDAY=''||upper(replace(p_byday,'' '',''''))||',
'                   '';BYHOUR=''||l_h||'';BYMINUTE=''||l_m||'';BYSECOND=0'';',
'',
'        elsif l_freq = ''MENSAL'' then',
'            if p_monthday is null or p_monthday not between 1 and 31 then',
unistr('                raise_application_error(-20001, ''MAE-AGENDA|Informe o dia do m\00EAs (1..31)'');'),
'            end if;',
'            if l_h is null or l_m is null or l_h not between 0 and 23 or l_m not between 0 and 59 then',
unistr('                raise_application_error(-20001, ''MAE-AGENDA|Informe hor\00E1rio v\00E1lido (HH 0..23 / MM 0..59)'');'),
'            end if;',
'            return ''FREQ=MONTHLY;BYMONTHDAY=''||p_monthday||',
'                   '';BYHOUR=''||l_h||'';BYMINUTE=''||l_m||'';BYSECOND=0'';',
'        end if;',
'',
unistr('        -- Fallback (se seu dom\00EDnio crescer no futuro)'),
unistr('        raise_application_error(-20001, ''MAE-AGENDA|repeat_freq inv\00E1lido: ''||l_freq);'),
'    end;',
'',
'    ',
'',
'  procedure run_agendamento(p_job_name in varchar2) is',
'    l_job_name    varchar2(128) := upper(trim(p_job_name));',
'    l_cfg         mae_agenda_cfg%rowtype;',
'',
'    l_id_artefato number;',
'    l_id          number;',
'  begin',
'    -- 1) Carrega config ativa do job',
'    select *',
'      into l_cfg',
'      from mae_agenda_cfg',
'     where job_name = l_job_name',
'       and ativo = ''S'';',
'',
'    -- 2) Resolve id_artefato (preferir coluna se existir)',
'    if l_cfg.id_artefato is not null then',
'      l_id_artefato := l_cfg.id_artefato;',
'    end if;',
'',
'    -- 3) Posta no MAESTRO (assinatura por ID_ARTEFATO)',
'    l_id := pkg_maestro_api.postar_requisicao(',
'      p_id_artefato    => l_id_artefato,',
'      p_id_tenant      => l_cfg.id_tenant,',
'      p_id_usuario     => l_cfg.id_usuario,',
'      p_id_negocio     => l_cfg.id_negocio,',
'      p_payload        => l_cfg.payload,',
'      p_prioridade     => l_cfg.prioridade,',
'      p_tipo_acao      => l_cfg.tipo_acao,',
'      p_id_correlation => null',
'    );',
'',
unistr('    -- opcional: log t\00E9cnico do scheduler (se quiser rastrear tamb\00E9m)'),
'    -- insert into mae_registro_tecnico(...) values (..., ''AGENDA_EXECUTADA'', ''INFO'', ...);',
'',
'  exception',
'    when no_data_found then',
unistr('      -- Se n\00E3o existir config ativa, n\00E3o derruba o scheduler (evita falha recorrente)'),
'      null;',
'    when others then',
unistr('      -- Em produ\00E7\00E3o, voc\00EA pode optar por registrar em mae_registro_tecnico'),
unistr('      -- e re-raise para marcar o job run como FAILED (\00FAtil pra operar)'),
'      raise;',
'  end run_agendamento;    ',
'',
'    procedure excluir_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table    ',
'    )',
'    is',
'        l_job_name varchar2(128);',
'        l_exists   number;',
'    begin',
'        select job_name into l_job_name from mae_agenda_cfg where id = p_id;',
'        if l_job_name is null then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|JOB_NAME \00E9 obrigat\00F3rio'');'),
'        end if;',
'',
'        select count(*)',
'          into l_exists',
'          from user_scheduler_jobs',
'         where job_name = l_job_name;',
'',
'        if l_exists > 0 then',
'            begin',
'                dbms_scheduler.disable(l_job_name, force => true);',
'            exception',
'                when others then null;',
'            end;',
'',
'            dbms_scheduler.drop_job(job_name => l_job_name, force => true);',
'',
'            delete from mae_agenda_cfg where id = p_id;',
'        end if;',
'',
'',
'',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20001,',
'                ''MAE-AGENDA|Falha ao excluir job do scheduler ''||upper(trim(p_id))||',
'                '' - ''||substr(sqlerrm,1,300)',
'            );',
'    end excluir_agendamento;',
'',
'    -- function alterar_status_agendamento(',
'    --     p_job_name in varchar2,',
'    --     p_status in varchar2',
'    -- ) return clob;  ',
'',
'    procedure ativar_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table        ',
'    )is',
'        l_job_name varchar2(128);',
'        l_exists   number;',
'    begin',
'        select job_name into l_job_name from mae_agenda_cfg where id = p_id;',
'        if l_job_name is null then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|JOB_NAME \00E9 obrigat\00F3rio'');'),
'        end if;',
'',
'        select count(*)',
'          into l_exists',
'          from user_scheduler_jobs',
'         where job_name = l_job_name;',
'',
'        if l_exists > 0 then',
'            begin',
'                dbms_scheduler.enable(l_job_name);',
'            exception',
'                when others then null;',
'            end;',
'',
'            update mae_agenda_cfg set ativo = ''S'' where id = p_id;',
'        end if;',
'',
'',
'',
'        exception',
'            when others then',
'                raise_application_error(',
'                    -20001,',
'                    ''MAE-AGENDA|Falha ao excluir job do scheduler ''||upper(trim(p_id))||',
'                    '' - ''||substr(sqlerrm,1,300)',
'                );',
'    end;',
'',
'    procedure desativar_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table        ',
'    )is',
'        l_job_name varchar2(128);',
'        l_exists   number;',
'    begin',
'        select job_name into l_job_name from mae_agenda_cfg where id = p_id;',
'        if l_job_name is null then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|JOB_NAME \00E9 obrigat\00F3rio'');'),
'        end if;',
'',
'        select count(*)',
'          into l_exists',
'          from user_scheduler_jobs',
'         where job_name = l_job_name;',
'',
'        if l_exists > 0 then',
'            begin',
'                dbms_scheduler.disable(l_job_name, force => true);',
'            exception',
'                when others then null;',
'            end;',
'',
'            update mae_agenda_cfg set ativo = ''N'' where id = p_id;',
'        end if;',
'',
'',
'',
'        exception',
'            when others then',
'                raise_application_error(',
'                    -20001,',
'                    ''MAE-AGENDA|Falha ao excluir job do scheduler ''||upper(trim(p_id))||',
'                    '' - ''||substr(sqlerrm,1,300)',
'                );',
'    end;',
'',
'    procedure executar_agendamento(',
'        p_id in varchar2,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table        ',
'    )is',
'        l_job_name varchar2(128);',
'        l_exists   number;',
'    begin',
'        select job_name into l_job_name from mae_agenda_cfg where id = p_id;',
'        if l_job_name is null then',
unistr('            raise_application_error(-20001, ''MAE-AGENDA|JOB_NAME \00E9 obrigat\00F3rio'');'),
'        end if;',
'',
'        select count(*)',
'          into l_exists',
'          from user_scheduler_jobs',
'         where job_name = l_job_name;',
'',
'        if l_exists > 0 then',
'            begin',
'                dbms_scheduler.run_job(l_job_name);',
'            exception',
'                when others then null;',
'            end;',
'        end if;',
'',
'',
'',
'        exception',
'            when others then',
'                raise_application_error(',
'                    -20001,',
'                    ''MAE-AGENDA|Falha ao executar job do scheduler ''||upper(trim(p_id))||',
'                    '' - ''||substr(sqlerrm,1,300)',
'                );',
'    end;',
'',
'end pkg_maestro_monitoramento;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_sla
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16263085486933765)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_SLA'
,p_sequence=>170
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_sla as',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-55 \2013 Detectar mensagens acima do SLA'),
'    -------------------------------------------------------------------',
'    procedure selecionar_sla_breach(',
'        p_lote   in number default 500,',
'        p_cursor out sys_refcursor',
'    );',
'',
'    procedure listar_ids_sla_breach(',
'        p_lote      in number default 500,',
'        p_ids_saida out varchar2',
'    );',
'',
'    procedure selecionar_sla_breach_nao_sinalizado(',
'        p_lote   in number default 500,',
'        p_cursor out sys_refcursor',
'    );',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-56 \2013 Registrar evento QUEUE_SLA_BREACH'),
'    -------------------------------------------------------------------',
'    procedure registrar_queue_sla_breach(',
'        p_id_solicitacao in number',
'    );',
'',
'    procedure processar_sla_breach(',
'        p_lote              in number default 500,',
'        p_qtd_processada    out number,',
'        p_qtd_log_sucesso   out number',
'    );',
'',
'    -------------------------------------------------------------------',
'    -- ST-CI-57 / Agendamento do monitor SLA',
'    -------------------------------------------------------------------',
'    procedure job_processar_sla_breach;',
'',
'    procedure criar_job_sla_breach(',
'        p_habilitar          in boolean  default true,',
'        p_lote               in number   default 500,',
'        p_intervalo_segundos in number   default 60',
'    );',
'',
'    procedure dropar_job_sla_breach(',
'        p_force in boolean default true',
'    );',
'',
'end pkg_maestro_sla;',
'/',
'create or replace package body pkg_maestro_sla as',
'',
'    c_status_pendente        constant varchar2(30)  := ''PENDENTE'';',
'    c_lote_default           constant number        := 500;',
'',
'    c_evt_queue_sla_breach   constant varchar2(100) := ''QUEUE_SLA_BREACH'';',
'    c_resultado_alerta       constant varchar2(30)  := ''ALERTA'';',
'',
'    c_job_name_sla_monitor   constant varchar2(128) := ''JOB_MAE_SLA_BREACH'';',
'    c_repeat_default         constant varchar2(200) := ''FREQ=MINUTELY;INTERVAL=1'';',
'',
'    -------------------------------------------------------------------',
unistr('    -- Utilit\00E1rio interno \2013 idade aproximada em segundos'),
'    -------------------------------------------------------------------',
'    function calcular_idade_seg(',
'        p_dt_criacao in timestamp',
'    ) return number',
'    is',
'        l_interval interval day to second;',
'    begin',
'        if p_dt_criacao is null then',
'            return null;',
'        end if;',
'',
'        l_interval := systimestamp - p_dt_criacao;',
'',
'        return',
'              extract(day    from l_interval) * 86400',
'            + extract(hour   from l_interval) * 3600',
'            + extract(minute from l_interval) * 60',
'            + trunc(extract(second from l_interval));',
'    end calcular_idade_seg;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-55 \2013 Selecionar mensagens pendentes com SLA violado'),
'    -------------------------------------------------------------------',
'    procedure selecionar_sla_breach(',
'        p_lote   in number default 500,',
'        p_cursor out sys_refcursor',
'    ) is',
'        l_lote number := nvl(p_lote, c_lote_default);',
'    begin',
'        if l_lote <= 0 then',
'            open p_cursor for',
'                select',
'                    cast(null as number)    as id,',
'                    cast(null as number)    as id_artefato,',
'                    cast(null as timestamp) as dt_criacao,',
'                    cast(null as number)    as sla_fila_seg',
'                from dual',
'                where 1 = 0;',
'            return;',
'        end if;',
'',
'        open p_cursor for',
'            select *',
'              from (',
'                    select',
'                        s.id,',
'                        s.id_artefato,',
'                        s.dt_criacao,',
'                        cfg.sla_fila_seg',
'                      from mae_solicitacao_execucao s',
'                      join srv_artefato_cfg cfg',
'                        on cfg.id_artefato = s.id_artefato',
'                     where s.status = c_status_pendente',
'                       and cfg.sla_fila_seg is not null',
'                       and s.dt_criacao + numtodsinterval(cfg.sla_fila_seg, ''SECOND'') < systimestamp',
'                     order by s.dt_criacao asc, s.id asc',
'                   )',
'             where rownum <= l_lote;',
'    end selecionar_sla_breach;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-55 \2013 Listar IDs candidatos a SLA breach em CSV'),
'    -------------------------------------------------------------------',
'    procedure listar_ids_sla_breach(',
'        p_lote      in number default 500,',
'        p_ids_saida out varchar2',
'    ) is',
'        c             sys_refcursor;',
'        l_id          mae_solicitacao_execucao.id%type;',
'        l_id_artefato mae_solicitacao_execucao.id_artefato%type;',
'        l_dt_criacao  mae_solicitacao_execucao.dt_criacao%type;',
'        l_sla_fila    srv_artefato_cfg.sla_fila_seg%type;',
'    begin',
'        p_ids_saida := null;',
'',
'        selecionar_sla_breach(',
'            p_lote   => p_lote,',
'            p_cursor => c',
'        );',
'',
'        loop',
'            fetch c into l_id, l_id_artefato, l_dt_criacao, l_sla_fila;',
'            exit when c%notfound;',
'',
'            if p_ids_saida is null then',
'                p_ids_saida := to_char(l_id);',
'            else',
'                p_ids_saida := p_ids_saida || '','' || to_char(l_id);',
'            end if;',
'        end loop;',
'',
'        close c;',
'',
'    exception',
'        when others then',
'            begin',
'                if c%isopen then',
'                    close c;',
'                end if;',
'            exception',
'                when others then',
'                    null;',
'            end;',
'            raise;',
'    end listar_ids_sla_breach;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-57 \2013 Selecionar apenas mensagens ainda n\00E3o sinalizadas'),
'    -------------------------------------------------------------------',
'    procedure selecionar_sla_breach_nao_sinalizado(',
'        p_lote   in number default 500,',
'        p_cursor out sys_refcursor',
'    ) is',
'        l_lote number := nvl(p_lote, c_lote_default);',
'    begin',
'        if l_lote <= 0 then',
'            open p_cursor for',
'                select',
'                    cast(null as number)    as id,',
'                    cast(null as number)    as id_artefato,',
'                    cast(null as timestamp) as dt_criacao,',
'                    cast(null as number)    as sla_fila_seg',
'                from dual',
'                where 1 = 0;',
'            return;',
'        end if;',
'',
'        open p_cursor for',
'            select *',
'              from (',
'                    select',
'                        s.id,',
'                        s.id_artefato,',
'                        s.dt_criacao,',
'                        cfg.sla_fila_seg',
'                      from mae_solicitacao_execucao s',
'                      join srv_artefato_cfg cfg',
'                        on cfg.id_artefato = s.id_artefato',
'                     where s.status = c_status_pendente',
'                       and cfg.sla_fila_seg is not null',
'                       and s.dt_criacao + numtodsinterval(cfg.sla_fila_seg, ''SECOND'') < systimestamp',
'                       and not exists (',
'                           select 1',
'                             from mae_registro_tecnico t',
'                            where t.id_solicitacao = s.id',
'                              and t.tipo_evento = c_evt_queue_sla_breach',
'                       )',
'                     order by s.dt_criacao asc, s.id asc',
'                   )',
'             where rownum <= l_lote;',
'    end selecionar_sla_breach_nao_sinalizado;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-56/57 \2013 Registrar evento QUEUE_SLA_BREACH para uma mensagem'),
'    -------------------------------------------------------------------',
'    procedure registrar_queue_sla_breach(',
'        p_id_solicitacao in number',
'    ) is',
'        l_id_artefato    mae_solicitacao_execucao.id_artefato%type;',
'        l_status         mae_solicitacao_execucao.status%type;',
'        l_dt_criacao     mae_solicitacao_execucao.dt_criacao%type;',
'        l_id_tenant      mae_solicitacao_execucao.id_tenant%type;',
'        l_id_correlation mae_solicitacao_execucao.id_correlation%type;',
'        l_sla_fila_seg   srv_artefato_cfg.sla_fila_seg%type;',
'        l_idade_seg      number;',
'        l_detalhes       clob;',
'        l_existe         number;',
'    begin',
'        if p_id_solicitacao is null then',
'            return;',
'        end if;',
'',
'        begin',
'            select',
'                s.id_artefato,',
'                s.status,',
'                s.dt_criacao,',
'                s.id_tenant,',
'                s.id_correlation,',
'                cfg.sla_fila_seg',
'            into',
'                l_id_artefato,',
'                l_status,',
'                l_dt_criacao,',
'                l_id_tenant,',
'                l_id_correlation,',
'                l_sla_fila_seg',
'            from mae_solicitacao_execucao s',
'            join srv_artefato_cfg cfg',
'              on cfg.id_artefato = s.id_artefato',
'            where s.id = p_id_solicitacao;',
'        exception',
'            when no_data_found then',
'                return;',
'        end;',
'',
'        if l_status <> c_status_pendente then',
'            return;',
'        end if;',
'',
'        if l_sla_fila_seg is null then',
'            return;',
'        end if;',
'',
'        if l_dt_criacao + numtodsinterval(l_sla_fila_seg, ''SECOND'') >= systimestamp then',
'            return;',
'        end if;',
'',
'        select count(*)',
'          into l_existe',
'          from mae_registro_tecnico t',
'         where t.id_solicitacao = p_id_solicitacao',
'           and t.tipo_evento = c_evt_queue_sla_breach;',
'',
'        if l_existe > 0 then',
'            return;',
'        end if;',
'',
'        l_idade_seg := calcular_idade_seg(',
'            p_dt_criacao => l_dt_criacao',
'        );',
'',
'        l_detalhes :=',
'              ''SLA_SEG='' || nvl(to_char(l_sla_fila_seg), ''<null>'')',
'           || ''; IDADE_SEG='' || nvl(to_char(l_idade_seg), ''<null>'')',
'           || ''; STATUS='' || nvl(l_status, ''<null>'')',
'           || ''; ID_ARTEFATO='' || nvl(to_char(l_id_artefato), ''<null>'');',
'',
'        pkg_maestro_evento.registrar_evento(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => null,',
'            p_id_tenant      => l_id_tenant,',
'            p_id_correlation => l_id_correlation,',
'            p_tipo_evento    => c_evt_queue_sla_breach,',
'            p_resultado      => c_resultado_alerta,',
'            p_detalhes       => l_detalhes',
'        );',
'    exception',
'        when others then',
'            null;',
'    end registrar_queue_sla_breach;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-56/57 \2013 Processar lote deduplicado'),
'    -------------------------------------------------------------------',
'    procedure processar_sla_breach(',
'        p_lote              in number default 500,',
'        p_qtd_processada    out number,',
'        p_qtd_log_sucesso   out number',
'    ) is',
'        c             sys_refcursor;',
'        l_id          mae_solicitacao_execucao.id%type;',
'        l_id_artefato mae_solicitacao_execucao.id_artefato%type;',
'        l_dt_criacao  mae_solicitacao_execucao.dt_criacao%type;',
'        l_sla_fila    srv_artefato_cfg.sla_fila_seg%type;',
'    begin',
'        p_qtd_processada  := 0;',
'        p_qtd_log_sucesso := 0;',
'',
'        selecionar_sla_breach_nao_sinalizado(',
'            p_lote   => p_lote,',
'            p_cursor => c',
'        );',
'',
'        loop',
'            fetch c into l_id, l_id_artefato, l_dt_criacao, l_sla_fila;',
'            exit when c%notfound;',
'',
'            p_qtd_processada := p_qtd_processada + 1;',
'',
'            begin',
'                registrar_queue_sla_breach(',
'                    p_id_solicitacao => l_id',
'                );',
'',
'                p_qtd_log_sucesso := p_qtd_log_sucesso + 1;',
'            exception',
'                when others then',
'                    null;',
'            end;',
'        end loop;',
'',
'        close c;',
'',
'    exception',
'        when others then',
'            begin',
'                if c%isopen then',
'                    close c;',
'                end if;',
'            exception',
'                when others then',
'                    null;',
'            end;',
'            raise;',
'    end processar_sla_breach;',
'',
'    -------------------------------------------------------------------',
unistr('    -- Job t\00E9cnico \2013 entrada para DBMS_SCHEDULER'),
'    -------------------------------------------------------------------',
'    procedure job_processar_sla_breach is',
'        l_qtd_processada  number := 0;',
'        l_qtd_log_sucesso number := 0;',
'    begin',
'        processar_sla_breach(',
'            p_lote            => c_lote_default,',
'            p_qtd_processada  => l_qtd_processada,',
'            p_qtd_log_sucesso => l_qtd_log_sucesso',
'        );',
'',
'        dbms_output.put_line(',
'            ''JOB_PROCESSAR_SLA_BREACH executado com sucesso. '' ||',
'            ''QTD_PROCESSADA='' || l_qtd_processada ||',
'            '' QTD_LOG_SUCESSO='' || l_qtd_log_sucesso',
'        );',
'    exception',
'        when others then',
'            raise;',
'    end job_processar_sla_breach;',
'',
'    -------------------------------------------------------------------',
'    -- Criar job recorrente do monitor SLA',
'    -------------------------------------------------------------------',
'    procedure criar_job_sla_breach(',
'        p_habilitar          in boolean  default true,',
'        p_lote               in number   default 500,',
'        p_intervalo_segundos in number   default 60',
'    ) is',
'        l_count            number;',
'        l_repeat_interval  varchar2(200);',
'    begin',
'        if nvl(p_lote, 0) <= 0 then',
'            raise_application_error(',
'                -20081,',
'                ''p_lote deve ser maior que zero.''',
'            );',
'        end if;',
'',
'        if nvl(p_intervalo_segundos, 0) <= 0 then',
'            raise_application_error(',
'                -20082,',
'                ''p_intervalo_segundos deve ser maior que zero.''',
'            );',
'        end if;',
'',
'        select count(*)',
'          into l_count',
'          from user_scheduler_jobs',
'         where job_name = c_job_name_sla_monitor;',
'',
'        if l_count > 0 then',
'            dbms_scheduler.drop_job(',
'                job_name => c_job_name_sla_monitor,',
'                force    => true',
'            );',
'        end if;',
'',
'        l_repeat_interval := ''FREQ=SECONDLY;INTERVAL='' || p_intervalo_segundos;',
'',
'        dbms_scheduler.create_job(',
'            job_name        => c_job_name_sla_monitor,',
'            job_type        => ''STORED_PROCEDURE'',',
'            job_action      => ''PKG_MAESTRO_SLA.JOB_PROCESSAR_SLA_BREACH'',',
'            start_date      => systimestamp,',
'            repeat_interval => l_repeat_interval,',
'            enabled         => false,',
'            auto_drop       => false,',
unistr('            comments        => ''Monitor t\00E9cnico de SLA de fila do MAESTRO'''),
'        );',
'',
'        if p_habilitar then',
'            dbms_scheduler.enable(c_job_name_sla_monitor);',
'        end if;',
'    end criar_job_sla_breach;',
'',
'    -------------------------------------------------------------------',
'    -- Dropar job do monitor SLA',
'    -------------------------------------------------------------------',
'    procedure dropar_job_sla_breach(',
'        p_force in boolean default true',
'    ) is',
'    begin',
'        dbms_scheduler.drop_job(',
'            job_name => c_job_name_sla_monitor,',
'            force    => p_force',
'        );',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20083,',
'                ''Erro ao dropar job de SLA breach: '' || substr(sqlerrm, 1, 3000)',
'            );',
'    end dropar_job_sla_breach;',
'',
'end pkg_maestro_sla;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_ttl
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16263196568930691)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_TTL'
,p_sequence=>180
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_ttl is',
'',
'    procedure selecionar_pendentes_expiradas(',
'        p_lote   in number default 1000,',
'        p_cursor out sys_refcursor',
'    );',
'',
'    procedure reservar_pendentes_expiradas(',
'        p_lote            in number default 1000,',
'        p_ids_reservados  out varchar2',
'    );',
'',
'    procedure expirar_mensagem(',
'        p_id               in mae_solicitacao_execucao.id%type,',
'        p_total_expiradas  out number',
'    );',
'',
'    procedure expirar_pendentes_vencidas(',
'        p_lote             in number default 1000,',
'        p_total_expiradas  out number',
'    );',
'',
'    procedure job_expirar_ttl;',
'',
'    procedure criar_job_expiracao_ttl(',
'        p_habilitar in boolean default true',
'    );',
'',
'end pkg_maestro_ttl;',
'/',
'create or replace package body pkg_maestro_ttl is',
'',
'    c_status_pendente      constant varchar2(30)  := ''PENDENTE'';',
'    c_status_expirado      constant varchar2(30)  := ''EXPIRADO'';',
'',
'    c_evento_ttl_expirado  constant varchar2(100) := ''MENSAGEM_EXPIRADA_TTL'';',
'    c_resultado_finalizado constant varchar2(30)  := ''FINALIZADO'';',
'',
'    c_motivo_expiracao     constant varchar2(200) := ''TTL expirado'';',
'',
'    c_job_name_ttl            constant varchar2(128) := ''JOB_MAE_TTL_EXPIRACAO'';',
'    c_lote_ttl_mvp            constant number := 1000;',
'    c_repeat_interval_ttl_mvp constant varchar2(200) := ''FREQ=MINUTELY;INTERVAL=5'';',
'',
'',
'    procedure registrar_evento_ttl_expirado(',
'        p_id_solicitacao          in mae_solicitacao_execucao.id%type,',
'        p_id_correlation          in mae_solicitacao_execucao.id_correlation%type,',
'        p_ttl_pendente_seg        in number,',
'        p_dt_criacao              in mae_solicitacao_execucao.dt_criacao%type,',
'        p_dt_expiracao_calculada  in date',
'    ) is',
'        l_detalhes varchar2(4000);',
'    begin',
'        l_detalhes :=',
'              ''TTL='' || nvl(to_char(p_ttl_pendente_seg), ''NULL'')',
'           || ''; DT_CRIACAO='' || case',
'                                    when p_dt_criacao is not null',
'                                        then to_char(p_dt_criacao, ''YYYY-MM-DD HH24:MI:SS'')',
'                                    else',
'                                        ''NULL''',
'                                 end',
'           || ''; DT_EXPIRACAO='' || case',
'                                      when p_dt_expiracao_calculada is not null',
'                                          then to_char(p_dt_expiracao_calculada, ''YYYY-MM-DD HH24:MI:SS'')',
'                                      else',
'                                          ''NULL''',
'                                   end;',
'',
'        /*',
unistr('          Se j\00E1 existir procedure corporativa de log, substituir este INSERT por algo como:'),
'          pkg_maestro_log.registrar_evento(...)',
'',
unistr('          Como ID_SOLICITACAO \00E9 obrigat\00F3rio em MAE_REGISTRO_TECNICO,'),
unistr('          aqui o v\00EDnculo \00E9 natural e correto.'),
'        */',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_tenant,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            id_worker,',
'            id_correlation,',
'            detalhes',
'        )',
'        select',
'            s.id,',
'            s.id_tenant,',
'            systimestamp,',
'            c_evento_ttl_expirado,',
'            c_resultado_finalizado,',
'            null,',
'            p_id_correlation,',
'            substr(l_detalhes, 1, 4000)',
'        from mae_solicitacao_execucao s',
'        where s.id = p_id_solicitacao;',
'',
'    exception',
'        when others then',
'            /*',
'              Regra da ST-CI-50:',
unistr('              erro de log n\00E3o pode desfazer a expira\00E7\00E3o da mensagem.'),
'            */',
'            null;',
'    end registrar_evento_ttl_expirado;',
'',
'',
'    procedure selecionar_pendentes_expiradas(',
'        p_lote   in number default 1000,',
'        p_cursor out sys_refcursor',
'    ) is',
'        l_lote number := nvl(p_lote, 1000);',
'    begin',
'        if l_lote <= 0 then',
'            open p_cursor for',
'                select s.id,',
'                       s.id_artefato,',
'                       s.dt_criacao,',
'                       cast(null as number) as ttl_pendente_seg,',
'                       cast(null as date) as dt_expiracao_calculada',
'                  from mae_solicitacao_execucao s',
'                 where 1 = 0;',
'            return;',
'        end if;',
'',
'        open p_cursor for',
'            select *',
'              from (',
'                    select s.id,',
'                           s.id_artefato,',
'                           s.id_correlation,',
'                           s.dt_criacao,',
'                           cfg.ttl_pendente_seg,',
'                           s.dt_criacao + (cfg.ttl_pendente_seg / 86400) as dt_expiracao_calculada',
'                      from mae_solicitacao_execucao s',
'                      join srv_artefato_cfg cfg',
'                        on cfg.id_artefato = s.id_artefato',
'                     where s.status = c_status_pendente',
'                       and cfg.ttl_pendente_seg is not null',
'                       and cfg.ttl_pendente_seg > 0',
'                       and s.dt_criacao + (cfg.ttl_pendente_seg / 86400) < sysdate',
'                     order by s.dt_criacao asc',
'                   )',
'             where rownum <= l_lote;',
'    end selecionar_pendentes_expiradas;',
'',
'',
'    procedure reservar_pendentes_expiradas(',
'        p_lote            in number default 1000,',
'        p_ids_reservados  out varchar2',
'    ) is',
'        l_lote number := nvl(p_lote, 1000);',
'        l_id   mae_solicitacao_execucao.id%type;',
'        l_qtd  number := 0;',
'',
'        cursor c_expiradas is',
'            select s.id',
'              from mae_solicitacao_execucao s',
'              join srv_artefato_cfg cfg',
'                on cfg.id_artefato = s.id_artefato',
'             where s.status = c_status_pendente',
'               and cfg.ttl_pendente_seg is not null',
'               and cfg.ttl_pendente_seg > 0',
'               and s.dt_criacao + (cfg.ttl_pendente_seg / 86400) < sysdate',
'             order by s.dt_criacao asc',
'             for update skip locked;',
'    begin',
'        p_ids_reservados := null;',
'',
'        if l_lote <= 0 then',
'            return;',
'        end if;',
'',
'        open c_expiradas;',
'        loop',
'            fetch c_expiradas into l_id;',
'            exit when c_expiradas%notfound or l_qtd >= l_lote;',
'',
'            l_qtd := l_qtd + 1;',
'',
'            if p_ids_reservados is null then',
'                p_ids_reservados := to_char(l_id);',
'            else',
'                p_ids_reservados := p_ids_reservados || '','' || to_char(l_id);',
'            end if;',
'        end loop;',
'        close c_expiradas;',
'    end reservar_pendentes_expiradas;',
'',
'',
'    procedure expirar_mensagem(',
'        p_id               in mae_solicitacao_execucao.id%type,',
'        p_total_expiradas  out number',
'    ) is',
'        l_rows                   number := 0;',
'        l_id_correlation         mae_solicitacao_execucao.id_correlation%type;',
'        l_ttl_pendente_seg       srv_artefato_cfg.ttl_pendente_seg%type;',
'        l_dt_criacao             mae_solicitacao_execucao.dt_criacao%type;',
'        l_dt_expiracao_calc      date;',
'    begin',
'        p_total_expiradas := 0;',
'',
'        /*',
unistr('          Captura contexto antes do update, ainda sob a condi\00E7\00E3o de elegibilidade.'),
'        */',
'        begin',
'            select s.id_correlation,',
'                   s.dt_criacao,',
'                   cfg.ttl_pendente_seg,',
'                   s.dt_criacao + (cfg.ttl_pendente_seg / 86400)',
'              into l_id_correlation,',
'                   l_dt_criacao,',
'                   l_ttl_pendente_seg,',
'                   l_dt_expiracao_calc',
'              from mae_solicitacao_execucao s',
'              join srv_artefato_cfg cfg',
'                on cfg.id_artefato = s.id_artefato',
'             where s.id = p_id',
'               and s.status = c_status_pendente',
'               and cfg.ttl_pendente_seg is not null',
'               and cfg.ttl_pendente_seg > 0',
'               and s.dt_criacao + (cfg.ttl_pendente_seg / 86400) < sysdate;',
'        exception',
'            when no_data_found then',
'                return;',
'        end;',
'',
'        update mae_solicitacao_execucao s',
'           set s.status       = c_status_expirado,',
'               s.motivo_falha = substr(c_motivo_expiracao, 1, 4000),',
'               s.dt_fim       = sysdate,',
'               s.dt_expiracao = l_dt_expiracao_calc',
'         where s.id = p_id',
'           and s.status = c_status_pendente;',
'',
'        l_rows := sql%rowcount;',
'        p_total_expiradas := l_rows;',
'',
'        if l_rows > 0 then',
'            registrar_evento_ttl_expirado(',
'                p_id_solicitacao         => p_id,',
'                p_id_correlation         => l_id_correlation,',
'                p_ttl_pendente_seg       => l_ttl_pendente_seg,',
'                p_dt_criacao             => l_dt_criacao,',
'                p_dt_expiracao_calculada => l_dt_expiracao_calc',
'            );',
'        end if;',
'    end expirar_mensagem;',
'',
'',
'    procedure expirar_pendentes_vencidas(',
'        p_lote             in number default 1000,',
'        p_total_expiradas  out number',
'    ) is',
'        l_lote                 number := nvl(p_lote, 1000);',
'        l_ids                  varchar2(32767);',
'        l_total                number := 0;',
'        l_idx                  pls_integer;',
'        l_id_txt               varchar2(100);',
'        l_id                   number;',
'        l_rows                 number;',
'        l_id_correlation       mae_solicitacao_execucao.id_correlation%type;',
'        l_ttl_pendente_seg     srv_artefato_cfg.ttl_pendente_seg%type;',
'        l_dt_criacao           mae_solicitacao_execucao.dt_criacao%type;',
'        l_dt_expiracao_calc    date;',
'    begin',
'        p_total_expiradas := 0;',
'',
'        if l_lote <= 0 then',
'            return;',
'        end if;',
'',
'        loop',
'            reservar_pendentes_expiradas(',
'                p_lote           => l_lote,',
'                p_ids_reservados => l_ids',
'            );',
'',
'            exit when l_ids is null;',
'',
'            l_idx := 1;',
'            loop',
'                l_id_txt := regexp_substr(l_ids, ''[^,]+'', 1, l_idx);',
'                exit when l_id_txt is null;',
'',
'                l_id := to_number(l_id_txt);',
'',
'                begin',
'                    select s.id_correlation,',
'                           s.dt_criacao,',
'                           cfg.ttl_pendente_seg,',
'                           s.dt_criacao + (cfg.ttl_pendente_seg / 86400)',
'                      into l_id_correlation,',
'                           l_dt_criacao,',
'                           l_ttl_pendente_seg,',
'                           l_dt_expiracao_calc',
'                      from mae_solicitacao_execucao s',
'                      join srv_artefato_cfg cfg',
'                        on cfg.id_artefato = s.id_artefato',
'                     where s.id = l_id',
'                       and s.status = c_status_pendente',
'                       and cfg.ttl_pendente_seg is not null',
'                       and cfg.ttl_pendente_seg > 0',
'                       and s.dt_criacao + (cfg.ttl_pendente_seg / 86400) < sysdate;',
'                exception',
'                    when no_data_found then',
'                        l_idx := l_idx + 1;',
'                        continue;',
'                end;',
'',
'                update mae_solicitacao_execucao s',
'                   set s.status       = c_status_expirado,',
'                       s.motivo_falha = substr(c_motivo_expiracao, 1, 4000),',
'                       s.dt_fim       = sysdate,',
'                       s.dt_expiracao = l_dt_expiracao_calc',
'                 where s.id = l_id',
'                   and s.status = c_status_pendente;',
'',
'                l_rows := sql%rowcount;',
'                l_total := l_total + l_rows;',
'',
'                if l_rows > 0 then',
'                    registrar_evento_ttl_expirado(',
'                        p_id_solicitacao         => l_id,',
'                        p_id_correlation         => l_id_correlation,',
'                        p_ttl_pendente_seg       => l_ttl_pendente_seg,',
'                        p_dt_criacao             => l_dt_criacao,',
'                        p_dt_expiracao_calculada => l_dt_expiracao_calc',
'                    );',
'                end if;',
'',
'                l_idx := l_idx + 1;',
'            end loop;',
'',
'            commit;',
'        end loop;',
'',
'        p_total_expiradas := l_total;',
'',
'    exception',
'        when others then',
'            rollback;',
'            raise_application_error(',
'                -20072,',
'                ''Erro ao expirar mensagens e registrar evento TTL: '' || sqlerrm',
'            );',
'    end expirar_pendentes_vencidas;',
'',
' procedure job_expirar_ttl is',
'        l_total_expiradas number := 0;',
'    begin',
'        expirar_pendentes_vencidas(',
'            p_lote            => c_lote_ttl_mvp,',
'            p_total_expiradas => l_total_expiradas',
'        );',
'',
'        dbms_output.put_line(',
'            ''JOB_EXPIRAR_TTL executado com sucesso. TOTAL_EXPIRADAS='' || l_total_expiradas',
'        );',
'',
'    exception',
'        when others then',
'            raise;',
'    end job_expirar_ttl;',
'',
'',
'    procedure criar_job_expiracao_ttl(',
'        p_habilitar in boolean default true',
'    ) is',
'        l_count number;',
'    begin',
'        select count(*)',
'          into l_count',
'          from user_scheduler_jobs',
'         where job_name = c_job_name_ttl;',
'',
'        if l_count > 0 then',
'            dbms_scheduler.drop_job(',
'                job_name => c_job_name_ttl,',
'                force    => true',
'            );',
'        end if;',
'',
'        dbms_scheduler.create_job(',
'            job_name        => c_job_name_ttl,',
'            job_type        => ''STORED_PROCEDURE'',',
'            job_action      => ''PKG_MAESTRO_TTL.JOB_EXPIRAR_TTL'',',
'            start_date      => systimestamp,',
'            repeat_interval => c_repeat_interval_ttl_mvp,',
'            enabled         => false,',
'            auto_drop       => false,',
unistr('            comments        => ''Expira\00E7\00E3o t\00E9cnica autom\00E1tica de mensagens pendentes por TTL.'''),
'        );',
'',
'        if p_habilitar then',
'            dbms_scheduler.enable(name => c_job_name_ttl);',
'        end if;',
'    end criar_job_expiracao_ttl;',
'',
'end pkg_maestro_ttl;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_worker
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16263274299928990)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_WORKER'
,p_sequence=>190
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_maestro_worker as',
'',
'',
'    c_erro_falha_tecnica constant number := -20500;',
'',
'    c_evt_cb_fila_protegida constant varchar2(50) := ''CIRCUIT_BREAKER_QUEUE_PROTECTED'';',
'',
'    c_status_pendente              constant varchar2(30)  := ''PENDENTE'';',
'    c_status_em_processamento      constant varchar2(30)  := ''EM_PROCESSAMENTO'';',
'    c_status_sucesso               constant varchar2(30)  := ''SUCESSO'';',
'    c_status_falha_negocio         constant varchar2(30)  := ''FALHA_NEGOCIO'';',
