'    c_modo_bloqueio_fila           constant varchar2(30)  := ''FILA'';',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-31 \2013 Dom\00EDnio da pol\00EDtica de retry'),
'    -------------------------------------------------------------------',
'    c_retry_estrategia_fixo        constant varchar2(20) := ''FIXO'';',
'    c_retry_estrategia_linear      constant varchar2(20) := ''LINEAR'';',
'    c_retry_estrategia_exponencial constant varchar2(20) := ''EXPONENCIAL'';',
'',
'    type r_politica_retry is record (',
