'    c_evt_erro_final_marcado       constant varchar2(30)  := ''ERRO_FINAL_MARCADO'';',
'',
'    c_msg_bloqueio_tecnico_prefixo constant varchar2(100) := ''BLOQUEIO_TECNICO|origem='';',
'    c_msg_escopo_id_negocio        constant varchar2(30)  := ''ID_NEGOCIO'';',
'    c_msg_escopo_fila              constant varchar2(30)  := ''FILA'';',
'    c_msg_modo_nenhum              constant varchar2(30)  := ''MODO_NENHUM'';',
'    c_msg_modo_invalido            constant varchar2(30)  := ''MODO_INVALIDO_NORMALIZADO'';',
'    c_msg_bloqueio_efetivado       constant varchar2(30)  := ''BLOQUEIO_EFETIVADO'';',
'    c_msg_sem_pendentes_bloquear   constant varchar2(40)  := ''SEM_PENDENTES_PARA_BLOQUEAR'';',
'    c_msg_erro_sem_detalhe         constant varchar2(30)  := ''Erro sem detalhe'';',
