'/',
'create or replace package body pkg_maestro_worker as',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-65 \2013 Circuit breaker por falha t\00E9cnica do artefato'),
'    -------------------------------------------------------------------',
'    c_status_cb_bloqueado           constant varchar2(30) := ''CIRCUIT_BREAKER_BLOCKED'';',
unistr('    c_msg_execucao_bloqueada_cb     constant varchar2(1000) := ''Execu\00E7\00E3o bloqueada por circuit breaker do artefato'';'),
'    c_delay_cb_bloqueado_default_seg constant number := 30;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-51 \2013 Detectar falha irrecuper\00E1vel'),
'    -- Regras:',
unistr('    --   - n\00E3o pode propagar erro de logging'),
'    --   - truncar detalhes',
unistr('    --   - registrar SQLCODE / SQLERRM quando aplic\00E1vel'),
'    -------------------------------------------------------------------',
'    function is_falha_critica(',
'        p_sqlcode in number',
'    ) return boolean',
'    is',
'    begin',
'        return p_sqlcode in (-600, -7445);',
'    end is_falha_critica;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-65 \2013 Delay de reagendamento quando bloqueado por breaker'),
'    -- Regra:',
unistr('    --   - usa CB_COOLDOWN_SEG do artefato quando dispon\00EDvel'),
'    --   - fallback defensivo = 30s',
'    -------------------------------------------------------------------',
'    function obter_delay_reagendamento_cb(',
'        p_id_artefato in number',
'    ) return number',
'    is',
'        l_cooldown srv_artefato_cfg.cb_cooldown_seg%type;',
'    begin',
'        if p_id_artefato is null then',
'            return c_delay_cb_bloqueado_default_seg;',
'        end if;',
'',
'        begin',
'            select cfg.cb_cooldown_seg',
'              into l_cooldown',
'              from srv_artefato_cfg cfg',
'             where cfg.id_artefato = p_id_artefato;',
'        exception',
'            when no_data_found then',
'                return c_delay_cb_bloqueado_default_seg;',
'        end;',
'',
'        if l_cooldown is null or l_cooldown <= 0 then',
'            return c_delay_cb_bloqueado_default_seg;',
'        end if;',
'',
'        return l_cooldown;',
'    end obter_delay_reagendamento_cb;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-61 \2013 Limitar concorr\00EAncia por artefato'),
'    -------------------------------------------------------------------',
'    function contar_execucoes_em_processamento(',
'        p_id_artefato    in number,',
'        p_id_solicitacao in number default null',
'    ) return number',
'    is',
'        l_qtd number;',
'    begin',
'        if p_id_artefato is null then',
'            return 0;',
'        end if;',
'',
'        select count(*)',
'          into l_qtd',
'          from mae_solicitacao_execucao',
'         where id_artefato = p_id_artefato',
'           and status = c_status_em_processamento',
'           and (p_id_solicitacao is null or id <> p_id_solicitacao);',
'',
'        return l_qtd;',
'    end contar_execucoes_em_processamento;',
'',
'    function limite_execucao_atingido(',
'        p_id_artefato    in number,',
'        p_id_solicitacao in number default null',
'    ) return boolean',
'    is',
'        l_limite number;',
'        l_execucoes number;',
'    begin',
'        l_limite := pkg_maestro_cfg.obter_limite_execucao_simultanea(',
'            p_id_artefato => p_id_artefato',
'        );',
'',
'        if l_limite is null then',
'            return false;',
'        end if;',
'',
'        l_execucoes := contar_execucoes_em_processamento(',
'            p_id_artefato    => p_id_artefato,',
'            p_id_solicitacao => p_id_solicitacao',
'        );',
'',
'        return l_execucoes >= l_limite;',
'    end limite_execucao_atingido;',
'',
'    procedure registrar_evento_limite_execucao(',
'        p_id_solicitacao    in number,',
'        p_id_worker         in number,',
'        p_id_tenant         in number,',
'        p_id_correlation    in varchar2,',
'        p_id_artefato       in number,',
'        p_execucoes_atuais  in number,',
'        p_limite            in number',
'    ) is',
'        l_detalhes clob;',
'    begin',
'        l_detalhes :=',
'              ''TIPO_LIMITE=CONCORRENCIA''',
'           || ''; ID_ARTEFATO='' || nvl(to_char(p_id_artefato), ''<null>'')',
'           || ''; EXECUCOES_ATUAIS='' || nvl(to_char(p_execucoes_atuais), ''<null>'')',
'           || ''; LIMITE='' || nvl(to_char(p_limite), ''<null>'');',
'',
'        pkg_maestro_evento.registrar_evento(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => p_id_worker,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_correlation => p_id_correlation,',
'            p_tipo_evento    => ''LIMIT_EXECUTION_BLOCKED'',',
'            p_resultado      => ''BLOQUEADO'',',
'            p_detalhes       => l_detalhes',
'        );',
'    end registrar_evento_limite_execucao;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-40 \2013 Registro estruturado de falhas'),
'    -- Regras:',
unistr('    --   - n\00E3o pode propagar erro de logging'),
'    --   - truncar detalhes',
unistr('    --   - registrar SQLCODE / SQLERRM quando aplic\00E1vel'),
'    -------------------------------------------------------------------',
'    procedure registrar_evento_falha(',
'        p_id_solicitacao in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_tipo_evento    in varchar2,',
'        p_sqlcode        in number   default null,',
'        p_sqlerrm        in varchar2 default null,',
'        p_etapa          in varchar2 default null,',
'        p_tentativas     in number   default null,',
'        p_detalhes_extra in varchar2 default null',
'    ) is',
'        l_detalhes varchar2(4000);',
'    begin',
'        l_detalhes :=',
'            ''sqlcode='' || nvl(to_char(p_sqlcode), ''<null>'') ||',
'            ''; sqlerrm='' || nvl(substr(p_sqlerrm, 1, 1000), ''<null>'') ||',
'            ''; etapa='' || nvl(trim(p_etapa), ''<null>'') ||',
'            ''; tentativas='' || nvl(to_char(p_tentativas), ''<null>'');',
'',
'        if trim(p_detalhes_extra) is not null then',
'            l_detalhes := l_detalhes || ''; detalhes='' || substr(trim(p_detalhes_extra), 1, 2000);',
'        end if;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            p_id_worker,',
'            systimestamp,',
'            p_tipo_evento,',
'            ''FALHA'',',
'            substr(l_detalhes, 1, 4000),',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'    exception',
'        when others then',
'            null;',
'    end registrar_evento_falha;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-37 \2013 Reclassificar mensagem travada'),
'    -- Regras:',
unistr('    --   - s\00F3 atua se ainda estiver EM_PROCESSAMENTO'),
'    --   - marca como FALHA_TECNICA',
'    --   - preenche dt_fim',
unistr('    --   - registra motivo t\00E9cnico de timeout'),
'    --   - limpa id_worker e dt_saude',
'    --   - preserva tentativas',
'    --   - preserva dt_disponivel_execucao',
'    -------------------------------------------------------------------',
'    procedure reclassificar_travada(',
'        p_id_solicitacao in number',
'    ) is',
'        l_tenant        mae_solicitacao_execucao.id_tenant%type;',
'        l_corr          mae_solicitacao_execucao.id_correlation%type;',
'        l_tentativas    mae_solicitacao_execucao.tentativas%type;',
'        l_id_worker     mae_solicitacao_execucao.id_worker%type;',
'    begin',
'        if p_id_solicitacao is null then',
'            return;',
'        end if;',
'',
'        begin',
'            select id_tenant,',
'                   id_correlation,',
'                   tentativas,',
'                   id_worker',
'              into l_tenant,',
'                   l_corr,',
'                   l_tentativas,',
'                   l_id_worker',
'              from mae_solicitacao_execucao',
'             where id = p_id_solicitacao;',
'        exception',
'            when no_data_found then',
'                return;',
'        end;',
'',
'        -------------------------------------------------------------------',
unistr('        -- Derrubar job ef\00EAmero da solicita\00E7\00E3o antes da reclassifica\00E7\00E3o'),
'        -------------------------------------------------------------------',
'        begin',
'            pkg_maestro_worker_run.parar_job_execucao(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_force          => true,',
'                p_dropar         => true',
'            );',
'        exception',
'            when others then',
'                null;',
'        end;',
'',
'        update mae_solicitacao_execucao',
'           set status       = c_status_falha_tecnica,',
'               dt_fim       = sysdate,',
'               motivo_falha = c_msg_processamento_timeout,',
'               id_worker    = null,',
'               dt_saude     = null',
'         where id = p_id_solicitacao',
'           and status = c_status_em_processamento;',
'',
'        if sql%rowcount = 0 then',
'            return;',
'        end if;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            l_id_worker,',
'            systimestamp,',
'            c_evt_travamento_recuperado,',
'            c_resultado_info,',
'            substr(',
'                ''motivo='' || c_msg_processamento_timeout ||',
'                ''; tentativas_preservadas='' || nvl(to_char(l_tentativas), ''0''),',
'                1,',
'                4000',
'            ),',
'            l_tenant,',
'            l_corr',
'        );',
'',
'        registrar_evento_falha(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => l_id_worker,',
'            p_id_tenant      => l_tenant,',
'            p_id_correlation => l_corr,',
'            p_tipo_evento    => c_evt_processamento_timeout,',
'            p_sqlcode        => null,',
'            p_sqlerrm        => c_msg_processamento_timeout,',
'            p_etapa          => ''RECUPERAR_TRAVADA'',',
'            p_tentativas     => l_tentativas,',
'            p_detalhes_extra => ''timeout_detectado=true''',
'        );',
'    end reclassificar_travada;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-37 \2013 Recuperar mensagens travadas de um artefato'),
'    -- Fluxo:',
'    --   - usa selecionar_travadas da ST-CI-36',
'    --   - reclassifica cada uma individualmente',
unistr('    --   - n\00E3o faz retry aqui'),
'    -------------------------------------------------------------------',
'    procedure recuperar_travadas(',
'        p_id_artefato in number,',
'        p_qtd_processada out number',
'    ) is',
'        c    sys_refcursor;',
'        l_id number;',
'    begin',
'        p_qtd_processada := 0;',
'',
'        selecionar_travadas(',
'            p_id_artefato => p_id_artefato,',
'            p_cursor      => c',
'        );',
'',
'        loop',
'            fetch c into l_id;',
'            exit when c%notfound;',
'',
'            reclassificar_travada(',
'                p_id_solicitacao => l_id',
'            );',
'',
'            tratar_falha_tecnica(',
'                p_id_solicitacao => l_id',
'            );',
'',
'            p_qtd_processada := p_qtd_processada + 1;',
'        end loop;',
'',
'        close c;',
'    exception',
'        when others then',
'            begin',
'                if c%isopen then',
'                    close c;',
'                end if;',
'            exception',
'                when others then',
'                    null;',
'            end;',
'            raise;',
'    end recuperar_travadas;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-36 \2013 Normaliza\00E7\00E3o do TTL de processamento'),
'    -- Regra:',
'    --   - null, zero ou negativo => default defensivo',
'    -------------------------------------------------------------------',
'    function normalizar_ttl_processando_seg(',
'        p_ttl_processando_seg in number',
'    ) return number',
'    is',
'    begin',
'        if p_ttl_processando_seg is null or p_ttl_processando_seg <= 0 then',
'            return c_ttl_processando_default_seg;',
'        end if;',
'',
'        return p_ttl_processando_seg;',
'    end normalizar_ttl_processando_seg;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-36 \2013 Obter TTL de processamento por artefato'),
'    -- Fonte:',
'    --   SRV_ARTEFATO_CFG.TTL_PROCESSANDO_SEG',
'    -- Fallback:',
'    --   default defensivo = 900',
'    -------------------------------------------------------------------',
'    function obter_ttl_processando_seg(',
'        p_id_artefato in number',
'    ) return number',
'    is',
'        l_ttl srv_artefato_cfg.ttl_processando_seg%type;',
'    begin',
'        if p_id_artefato is null then',
'            return c_ttl_processando_default_seg;',
'        end if;',
'',
'        begin',
'            select cfg.ttl_processando_seg',
'              into l_ttl',
'              from srv_artefato_cfg cfg',
'             where cfg.id_artefato = p_id_artefato;',
'        exception',
'            when no_data_found then',
'                return c_ttl_processando_default_seg;',
'        end;',
'',
'        return normalizar_ttl_processando_seg(l_ttl);',
'    end obter_ttl_processando_seg;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-36 \2013 Selecionar mensagens travadas'),
'    -- Regras:',
'    --   - status = EM_PROCESSAMENTO',
unistr('    --   - usa NVL(dt_saude, dt_inicio) como refer\00EAncia'),
'    --   - respeita TTL por artefato',
unistr('    --   - n\00E3o altera dados'),
unistr('    --   - compat\00EDvel com multiworker via SKIP LOCKED'),
'    -------------------------------------------------------------------',
'    procedure selecionar_travadas(',
'        p_id_artefato in number,',
'        p_cursor      out sys_refcursor',
'    ) is',
'        l_ttl_seg number;',
'    begin',
'        if p_id_artefato is null then',
'            open p_cursor for',
'                select cast(null as number) as id',
'                  from dual',
'                 where 1 = 0;',
'            return;',
'        end if;',
'',
'        l_ttl_seg := obter_ttl_processando_seg(',
'            p_id_artefato => p_id_artefato',
'        );',
'',
'        open p_cursor for',
'            select m.id',
'              from mae_solicitacao_execucao m',
'             where m.id_artefato = p_id_artefato',
'               and m.status = c_status_em_processamento',
'               and nvl(m.dt_saude, m.dt_inicio) <',
'                   systimestamp - numtodsinterval(l_ttl_seg, ''SECOND'')',
'             for update skip locked;',
'    end selecionar_travadas;',
'',
'    -------------------------------------------------------------------',
unistr('    -- Fun\00E7\00F5es auxiliares internas'),
'    -------------------------------------------------------------------',
'    function montar_detalhe_origem_bloqueio(',
'        p_resultado   in varchar2,',
'        p_id_artefato in number,',
'        p_id_negocio  in varchar2',
'    ) return varchar2',
'    is',
'    begin',
'        return',
'            ''resultado='' || nvl(trim(p_resultado), ''<null>'') ||',
'            ''; id_artefato='' || nvl(to_char(p_id_artefato), ''<null>'') ||',
'            ''; id_negocio='' || nvl(trim(p_id_negocio), ''<null>'');',
'    end montar_detalhe_origem_bloqueio;',
'',
'    function montar_motivo_bloqueio(',
'        p_id_solicitacao_falha in number,',
'        p_escopo               in varchar2,',
'        p_detalhe_origem       in varchar2',
'    ) return varchar2',
'    is',
'    begin',
'        return substr(',
'            c_msg_bloqueio_tecnico_prefixo || p_id_solicitacao_falha ||',
'            ''; escopo='' || nvl(trim(p_escopo), ''<null>'') ||',
'            ''; '' || nvl(trim(p_detalhe_origem), ''<null>''),',
'            1,',
'            1000',
'        );',
'    end montar_motivo_bloqueio;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-25 \2013 Registro t\00E9cnico do bloqueio aplicado/ignorado'),
'    -------------------------------------------------------------------',
'    procedure registrar_evento_bloqueio(',
'        p_id_solicitacao_origem   in number,',
'        p_id_worker               in number,',
'        p_id_tenant               in number,',
'        p_id_correlation          in varchar2,',
'        p_tipo_evento             in varchar2,',
'        p_modo_bloqueio           in varchar2,',
'        p_status_origem           in varchar2,',
'        p_id_artefato             in number,',
'        p_id_negocio              in varchar2,',
'        p_qtd_mensagens_bloqueada in number,',
'        p_motivo                  in varchar2',
'    ) is',
'        l_detalhes varchar2(4000);',
'    begin',
'        l_detalhes :=',
'            ''modo_bloqueio='' || nvl(p_modo_bloqueio, ''<null>'') ||',
'            ''; motivo='' || nvl(p_motivo, ''<null>'') ||',
'            ''; status_origem='' || nvl(p_status_origem, ''<null>'') ||',
'            ''; id_artefato='' || nvl(to_char(p_id_artefato), ''<null>'') ||',
'            ''; id_negocio='' || nvl(trim(p_id_negocio), ''<null>'') ||',
'            ''; qtd_mensagens_bloqueadas='' || nvl(to_char(p_qtd_mensagens_bloqueada), ''0'') ||',
'          '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(16263274299928990)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  ''; id_correlation='' || nvl(trim(p_id_correlation), ''<null>'');',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao_origem,',
'            p_id_worker,',
'            systimestamp,',
'            p_tipo_evento,',
'            c_resultado_info,',
'            substr(l_detalhes, 1, 4000),',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'    end registrar_evento_bloqueio;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-25 \2013 Define se o resultado final \00E9 falha bloqueante'),
'    -- MVP:',
'    --   FALHA_NEGOCIO => bloqueia',
'    --   FALHA_TECNICA => bloqueia',
'    --   ERRO_FINAL    => bloqueia',
unistr('    --   demais        => n\00E3o bloqueia'),
'    -------------------------------------------------------------------',
'    function falha_bloqueante(',
'        p_resultado in varchar2',
'    ) return boolean',
'    is',
'        l_resultado varchar2(30);',
'    begin',
'        l_resultado := upper(trim(p_resultado));',
'',
'        return l_resultado in (',
'            c_status_falha_negocio,',
'            c_status_falha_tecnica,',
'            c_status_erro_final',
'        );',
'    end falha_bloqueante;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-25 \2013 Bloqueia pendentes do mesmo tenant/artefato/id_negocio'),
'    -------------------------------------------------------------------',
'    procedure bloquear_pendentes_por_id_negocio(',
'        p_id_solicitacao_falha in number,',
'        p_id_tenant            in number,',
'        p_id_artefato          in number,',
'        p_id_negocio           in varchar2,',
'        p_detalhe_origem       in varchar2,',
'        p_qtd_afetada          out number',
'    ) is',
'        l_motivo_falha varchar2(2000);',
'    begin',
'        p_qtd_afetada := 0;',
'',
'        if p_id_tenant is null',
'           or p_id_artefato is null',
'           or trim(p_id_negocio) is null',
'        then',
'            return;',
'        end if;',
'',
'        l_motivo_falha := montar_motivo_bloqueio(',
'            p_id_solicitacao_falha => p_id_solicitacao_falha,',
'            p_escopo               => c_msg_escopo_id_negocio,',
'            p_detalhe_origem       => p_detalhe_origem',
'        );',
'',
'        update mae_solicitacao_execucao m',
'           set m.status       = c_status_bloqueada,',
'               m.motivo_falha = l_motivo_falha',
'         where m.id_tenant    = p_id_tenant',
'           and m.id_artefato  = p_id_artefato',
'           and m.id_negocio   = trim(p_id_negocio)',
'           and m.status       = c_status_pendente',
'           and m.id          <> p_id_solicitacao_falha;',
'',
'        p_qtd_afetada := sql%rowcount;',
'    end bloquear_pendentes_por_id_negocio;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-25 \2013 Bloqueia pendentes do mesmo tenant/artefato'),
'    -------------------------------------------------------------------',
'    procedure bloquear_pendentes_por_fila(',
'        p_id_solicitacao_falha in number,',
'        p_id_tenant            in number,',
'        p_id_artefato          in number,',
'        p_detalhe_origem       in varchar2,',
'        p_qtd_afetada          out number',
'    ) is',
'        l_motivo_falha varchar2(2000);',
'    begin',
'        p_qtd_afetada := 0;',
'',
'        if p_id_tenant is null',
'           or p_id_artefato is null',
'        then',
'            return;',
'        end if;',
'',
'        l_motivo_falha := montar_motivo_bloqueio(',
'            p_id_solicitacao_falha => p_id_solicitacao_falha,',
'            p_escopo               => c_msg_escopo_fila,',
'            p_detalhe_origem       => p_detalhe_origem',
'        );',
'',
'        update mae_solicitacao_execucao m',
'           set m.status       = c_status_bloqueada,',
'               m.motivo_falha = l_motivo_falha',
'         where m.id_tenant    = p_id_tenant',
'           and m.id_artefato  = p_id_artefato',
'           and m.status       = c_status_pendente',
'           and m.id          <> p_id_solicitacao_falha;',
'',
'        p_qtd_afetada := sql%rowcount;',
'    end bloquear_pendentes_por_fila;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-24 / ST-CI-25 \2013 Ler modo de bloqueio por falha do artefato'),
'    -------------------------------------------------------------------',
'    function get_modo_bloqueio_falha(',
'        p_id_artefato in number',
'    ) return varchar2',
'    is',
'        l_modo srv_artefato_cfg.modo_bloqueio_falha%type;',
'    begin',
'        select cfg.modo_bloqueio_falha',
'          into l_modo',
'          from srv_artefato_cfg cfg',
'         where cfg.id_artefato = p_id_artefato;',
'',
'        return pkg_maestro_api.normalizar_modo_bloqueio_falha(l_modo);',
'',
'    exception',
'        when no_data_found then',
'            return c_modo_bloqueio_nenhum;',
'    end get_modo_bloqueio_falha;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-25 \2013 Aplicar bloqueio t\00E9cnico ap\00F3s falha'),
'    -------------------------------------------------------------------',
'    procedure aplicar_bloqueio_falha(',
'        p_id_solicitacao_falha in number,',
'        p_resultado            in varchar2',
'    ) is',
'        l_id_tenant      mae_solicitacao_execucao.id_tenant%type;',
'        l_id_artefato    mae_solicitacao_execucao.id_artefato%type;',
'        l_id_negocio     mae_solicitacao_execucao.id_negocio%type;',
'        l_id_correlation mae_solicitacao_execucao.id_correlation%type;',
'        l_id_worker      mae_solicitacao_execucao.id_worker%type;',
'        l_modo_bloqueio  varchar2(30);',
'        l_detalhe_origem varchar2(1000);',
'        l_qtd_afetada    number := 0;',
'        l_resultado      varchar2(30);',
'    begin',
'        l_resultado := upper(trim(p_resultado));',
'',
'        if not falha_bloqueante(l_resultado) then',
'            return;',
'        end if;',
'',
'        select id_tenant,',
'               id_artefato,',
'               id_negocio,',
'               id_correlation,',
'               id_worker',
'          into l_id_tenant,',
'               l_id_artefato,',
'               l_id_negocio,',
'               l_id_correlation,',
'               l_id_worker',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao_falha;',
'',
'        l_modo_bloqueio := get_modo_bloqueio_falha(l_id_artefato);',
'',
'        l_detalhe_origem := montar_detalhe_origem_bloqueio(',
'            p_resultado   => l_resultado,',
'            p_id_artefato => l_id_artefato,',
'            p_id_negocio  => l_id_negocio',
'        );',
'',
'        if l_modo_bloqueio = c_modo_bloqueio_nenhum then',
'            registrar_evento_bloqueio(',
'                p_id_solicitacao_origem   => p_id_solicitacao_falha,',
'                p_id_worker               => l_id_worker,',
'                p_id_tenant               => l_id_tenant,',
'                p_id_correlation          => l_id_correlation,',
'                p_tipo_evento             => c_evt_bloqueio_ignorado,',
'                p_modo_bloqueio           => l_modo_bloqueio,',
'                p_status_origem           => l_resultado,',
'                p_id_artefato             => l_id_artefato,',
'                p_id_negocio              => l_id_negocio,',
'                p_qtd_mensagens_bloqueada => 0,',
'                p_motivo                  => c_msg_modo_nenhum',
'            );',
'            return;',
'        end if;',
'',
'        if l_modo_bloqueio = c_modo_bloqueio_id_negocio then',
'            bloquear_pendentes_por_id_negocio(',
'                p_id_solicitacao_falha => p_id_solicitacao_falha,',
'                p_id_tenant            => l_id_tenant,',
'                p_id_artefato          => l_id_artefato,',
'                p_id_negocio           => l_id_negocio,',
'                p_detalhe_origem       => l_detalhe_origem,',
'                p_qtd_afetada          => l_qtd_afetada',
'            );',
'',
'        elsif l_modo_bloqueio = c_modo_bloqueio_fila then',
'            bloquear_pendentes_por_fila(',
'                p_id_solicitacao_falha => p_id_solicitacao_falha,',
'                p_id_tenant            => l_id_tenant,',
'                p_id_artefato          => l_id_artefato,',
'                p_detalhe_origem       => l_detalhe_origem,',
'                p_qtd_afetada          => l_qtd_afetada',
'            );',
'',
'        else',
'            registrar_evento_bloqueio(',
'                p_id_solicitacao_origem   => p_id_solicitacao_falha,',
'                p_id_worker               => l_id_worker,',
'                p_id_tenant               => l_id_tenant,',
'                p_id_correlation          => l_id_correlation,',
'                p_tipo_evento             => c_evt_bloqueio_ignorado,',
'                p_modo_bloqueio           => l_modo_bloqueio,',
'                p_status_origem           => l_resultado,',
'                p_id_artefato             => l_id_artefato,',
'                p_id_negocio              => l_id_negocio,',
'                p_qtd_mensagens_bloqueada => 0,',
'                p_motivo                  => c_msg_modo_invalido',
'            );',
'            return;',
'        end if;',
'',
'        if nvl(l_qtd_afetada, 0) > 0 then',
'            registrar_evento_bloqueio(',
'                p_id_solicitacao_origem   => p_id_solicitacao_falha,',
'                p_id_worker               => l_id_worker,',
'                p_id_tenant               => l_id_tenant,',
'                p_id_correlation          => l_id_correlation,',
'                p_tipo_evento             => c_evt_bloqueio_aplicado,',
'                p_modo_bloqueio           => l_modo_bloqueio,',
'                p_status_origem           => l_resultado,',
'                p_id_artefato             => l_id_artefato,',
'                p_id_negocio              => l_id_negocio,',
'                p_qtd_mensagens_bloqueada => l_qtd_afetada,',
'                p_motivo                  => c_msg_bloqueio_efetivado',
'            );',
'        else',
'            registrar_evento_bloqueio(',
'                p_id_solicitacao_origem   => p_id_solicitacao_falha,',
'                p_id_worker               => l_id_worker,',
'                p_id_tenant               => l_id_tenant,',
'                p_id_correlation          => l_id_correlation,',
'                p_tipo_evento             => c_evt_bloqueio_ignorado,',
'                p_modo_bloqueio           => l_modo_bloqueio,',
'                p_status_origem           => l_resultado,',
'                p_id_artefato             => l_id_artefato,',
'                p_id_negocio              => l_id_negocio,',
'                p_qtd_mensagens_bloqueada => 0,',
'                p_motivo                  => c_msg_sem_pendentes_bloquear',
'            );',
'        end if;',
'    end aplicar_bloqueio_falha;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-11 \2013 Registrar bloqueios por preced\00EAncia'),
'    -------------------------------------------------------------------',
'    procedure registrar_bloqueios_precedencia(',
'        p_id_worker   in number,',
'        p_id_artefato in number',
'    ) is',
'    begin',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        )',
'        select',
'            m.id,',
'            p_id_worker,',
'            systimestamp,',
'            c_evt_bloqueada_precedencia,',
'            c_resultado_info,',
'            ''Mensagem bloqueada por predecessora ativa do mesmo id_negocio'',',
'            m.id_tenant,',
'            m.id_correlation',
'        from mae_solicitacao_execucao m',
'        where m.status = c_status_pendente',
'          and m.id_artefato = p_id_artefato',
'          and m.dt_disponivel_execucao <= systimestamp',
'          and m.id_negocio is not null',
'          and exists (',
'                select 1',
'                  from mae_solicitacao_execucao p',
'                 where p.id_negocio = m.id_negocio',
'                   and p.status in (c_status_pendente, c_status_em_processamento)',
'                   and (',
'                        p.dt_criacao < m.dt_criacao',
'                        or (p.dt_criacao = m.dt_criacao and p.id < m.id)',
'                   )',
'          );',
'    exception',
'        when others then',
'            null;',
'    end registrar_bloqueios_precedencia;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-10 \2013 Obter primeira mensagem do grupo por id_negocio'),
'    -------------------------------------------------------------------',
'    function obter_primeira_mensagem_negocio(',
'        p_id_negocio in varchar2',
'    ) return number',
'    is',
'        l_id number;',
'    begin',
'        if trim(p_id_negocio) is null then',
'            return null;',
'        end if;',
'',
'        select id',
'          into l_id',
'          from (',
'                select m.id',
'                  from mae_solicitacao_execucao m',
'                 where m.id_negocio = trim(p_id_negocio)',
'                 order by m.dt_criacao asc, m.id asc',
'          )',
'         where rownum = 1;',
'',
'        return l_id;',
'',
'    exception',
'        when no_data_found then',
'            return null;',
'    end obter_primeira_mensagem_negocio;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-10 \2013 Verifica se existe predecessora no mesmo id_negocio'),
'    -------------------------------------------------------------------',
'    function existe_predecessora_negocio(',
'        p_id_solicitacao in number',
'    ) return boolean',
'    is',
'        l_id_negocio mae_solicitacao_execucao.id_negocio%type;',
'        l_dt_criacao mae_solicitacao_execucao.dt_criacao%type;',
'        l_id         mae_solicitacao_execucao.id%type;',
'        l_dummy      number;',
'    begin',
'        select id_negocio, dt_criacao, id',
'          into l_id_negocio, l_dt_criacao, l_id',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao;',
'',
'        if l_id_negocio is null then',
'            return false;',
'        end if;',
'',
'        select 1',
'          into l_dummy',
'          from mae_solicitacao_execucao m',
'         where m.id_negocio = l_id_negocio',
'           and (',
'                m.dt_criacao < l_dt_criacao',
'                or (m.dt_criacao = l_dt_criacao and m.id < l_id)',
'           )',
'           and rownum = 1;',
'',
'        return true;',
'',
'    exception',
'        when no_data_found then',
'            return false;',
'    end existe_predecessora_negocio;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-10 \2013 Verifica se a mensagem \00E9 a primeira do grupo'),
'    -------------------------------------------------------------------',
'    function eh_primeira_mensagem_negocio(',
'        p_id_solicitacao in number',
'    ) return boolean',
'    is',
'        l_id_negocio mae_solicitacao_execucao.id_negocio%type;',
'        l_primeira   number;',
'    begin',
'        select id_negocio',
'          into l_id_negocio',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao;',
'',
'        if l_id_negocio is null then',
'            return true;',
'        end if;',
'',
'        l_primeira := obter_primeira_mensagem_negocio(l_id_negocio);',
'',
'        return l_primeira = p_id_solicitacao;',
'    end eh_primeira_mensagem_negocio;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-05 / ST-CI-26 \2013 Selecionar pendente eleg\00EDvel'),
'    -------------------------------------------------------------------',
'    procedure selecionar_pendente(',
'        p_id_artefato in number,',
'        p_cursor      out sys_refcursor',
'    ) is',
'    begin',
'        if p_id_artefato is null then',
'            open p_cursor for',
'                select cast(null as number) as id',
'                  from dual',
'                 where 1 = 0;',
'            return;',
'        end if;',
'',
'        open p_cursor for',
'            select m.id',
'              from mae_solicitacao_execucao m',
'             where m.rowid in (',
'                select rid',
'                  from (',
'                    select /*+ index(m2 IX_MAE_SOL_BUSCA_EXECUCAO) */',
'                           m2.rowid as rid',
'                      from mae_solicitacao_execucao m2',
'                     where m2.status = c_status_pendente',
'                       and m2.id_artefato = p_id_artefato',
'                       and m2.dt_disponivel_execucao <= systimestamp',
'                       and (',
'                            m2.id_negocio is null',
'                            or not exists (',
'                                select 1',
'                                  from mae_solicitacao_execucao p',
'                                 where p.id_negocio = m2.id_negocio',
'                                   and p.status in (c_status_pendente, c_status_em_processamento)',
'                                   and (',
'                                        p.dt_criacao < m2.dt_criacao',
'                                        or (p.dt_criacao = m2.dt_criacao and p.id < m2.id)',
'                                   )',
'                            )',
'                       )',
'                     order by m2.prioridade desc,',
'                              m2.dt_criacao asc,',
'                              m2.id asc',
'                  )',
'                 where rownum = 1',
'             )',
'             for update skip locked;',
'    end selecionar_pendente;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-05 / ST-CI-26 \2013 Reservar pendente'),
'    -------------------------------------------------------------------',
'    procedure reservar_pendente(',
'        p_id_worker   in number,',
'        p_id_artefato in number,',
'        p_id_mensagem out number',
'    ) is',
'        c                  sys_refcursor;',
'        v_id               number;',
'        l_tenant           number;',
'        l_corr             varchar2(64);',
'        l_limite           number;',
'        l_execucoes_atuais number;',
'        l_id_artefato_msg  mae_solicitacao_execucao.id_artefato%type;',
'        l_cb_result        varchar2(30);',
'        l_delay_cb_seg     number;',
'    begin',
'        p_id_mensagem := null;',
'',
'        selecionar_pendente(',
'            p_id_artefato => p_id_artefato,',
'            p_cursor      => c',
'        );',
'',
'        fetch c into v_id;',
'',
'        if c%notfound then',
'            close c;',
'',
'            registrar_bloqueios_precedencia(',
'                p_id_worker   => p_id_worker,',
'                p_id_artefato => p_id_artefato',
'            );',
'',
'            return;',
'        end if;',
'',
'        begin',
'            select id_tenant,',
'                   id_correlation,',
'                   id_artefato',
'              into l_tenant,',
'                   l_corr,',
'                   l_id_artefato_msg',
'              from mae_solicitacao_execucao',
'             where id = v_id;',
'        exception',
'            when others then',
'                l_tenant          := null;',
'                l_corr            := null;',
'                l_id_artefato_msg := p_id_artefato;',
'        end;',
'',
'        -------------------------------------------------------------------',
unistr('        -- ST-CI-65 \2013 Validar circuit breaker antes da reserva'),
'        -- Regra:',
unistr('        --   - se bloqueado, n\00E3o reservar'),
'        --   - mensagem permanece PENDENTE',
'        --   - reagenda dt_disponivel_execucao',
'        -------------------------------------------------------------------',
'        l_cb_result := pkg_maestro_cfg.tentar_permitir_execucao_cb(',
'            p_id_artefato    => l_id_artefato_msg,',
'            p_id_solicitacao => v_id,',
'            p_id_worker      => p_id_worker,',
'            p_id_tenant      => l_tenant,',
'            p_id_correlation => l_corr',
'        );',
'',
'        if l_cb_result = pkg_maestro_cfg.c_cb_result_bloqueado then',
'            proteger_fila_cb_aberto(',
'                p_id_solicitacao => v_id,',
'                p_id_artefato    => l_id_artefato_msg,',
'                p_id_worker      => p_id_worker,',
'                p_id_tenant      => l_tenant,',
'                p_id_correlation => l_corr',
'            );',
'',
'            close c;',
'            commit;',
'            return;',
'        end if;',
'',
'        -------------------------------------------------------------------',
unistr('        -- ST-CI-61 \2013 Validar limite de concorr\00EAncia por artefato'),
'        -------------------------------------------------------------------',
'        l_limite := pkg_maestro_cfg.obter_limite_execucao_simultanea(',
'            p_id_artefato => p_id_artefato',
'        );',
'',
'        if l_limite is not null then',
'            l_execucoes_atuais := contar_execucoes_em_processamento(',
'                p_id_artefato    => p_id_artefato,',
'                p_id_solicitacao => null',
'            );',
'',
'            if l_execucoes_atuais >= l_limite then',
'                registrar_evento_limite_execucao(',
'                    p_id_solicitacao   => v_id,',
'                    p_id_worker        => p_id_worker,',
'                    p_id_tenant        => l_tenant,',
'                    p_id_correlation   => l_corr,',
'                    p_id_artefato      => p_id_artefato,',
'                    p_execucoes_atuais => l_execucoes_atuais,',
'                    p_limite           => l_limite',
'                );',
'',
'                close c;',
'                commit;',
'                return;',
'            end if;',
'        end if;',
'',
'        update mae_solicitacao_execucao',
'           set status    = c_status_em_processamento,',
'               dt_inicio = sysdate,',
'               id_worker = p_id_worker,',
'               dt_saude  = sysdate',
'         where id = v_id',
'           and status = c_status_pendente;',
'',
'        if sql%rowcount = 0 then',
'            close c;',
'            commit;',
'            return;',
'        end if;',
'',
'        if sql%rowcount <> 1 then',
'            raise_application_error(',
'                -20991,',
unistr('                ''MAE-WRK-RESERVA_FALHOU|N\00E3o foi poss\00EDvel reservar id='' || v_id'),
'            );',
'        end if;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            v_id,',
'            p_id_worker,',
'            sysdate,',
'            c_evt_mensagem_reservada,',
'            c_resultado_info,',
'            ''id_worker='' || nvl(to_char(p_id_worker), ''<null>''),',
'            l_tenant,',
'            l_corr',
'        );',
'',
'        close c;',
'        commit;',
'',
'        p_id_mensagem := v_id;',
'',
'    exception',
'        when others then',
'            begin',
'                if c%isopen then',
'                    close c;',
'                end if;',
'            exception',
'                when others then',
'                    null;',
'            end;',
'',
'            rollback;',
'            raise;',
'    end reservar_pendente;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-06 \2013 Resolver entrypoint do artefato'),
'    -------------------------------------------------------------------',
'    function get_entrypoint(',
'        p_id_artefato number',
'    ) return varchar2',
'    is',
'        l_entry srv_artefato_cfg.plsql_entrypoint%type;',
'    begin',
'        select cfg.plsql_entrypoint',
'          into l_entry',
'          from srv_artefato_cfg cfg',
'         where cfg.id_artefato = p_id_artefato;',
'',
'        if trim(l_entry) is null then',
'            raise_application_error(',
'                -20970,',
'                ''MAE-WRK-ENTRYPOINT_NULO|Artefato sem PLSQL_ENTRYPOINT (id_artefato=''||p_id_artefato||'')''',
'            );',
'        end if;',
'',
'        return trim(l_entry);',
'',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                -20971,',
unistr('                ''MAE-WRK-ENTRYPOINT_INEXISTENTE|SRV_ARTEFATO_CFG n\00E3o encontrado (id_artefato=''||p_id_artefato||'')'''),
'            );',
'    end get_entrypoint;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-29 / ST-CI-30 \2013 Classifica\00E7\00E3o da exce\00E7\00E3o'),
'    -------------------------------------------------------------------',
unistr('    -- -20000 at\00E9 -20499 = Falha de Neg\00F3cio'),
unistr('    -- -20500 at\00E9 -20999 = Falha T\00E9cnica'),
'    function classify_error return varchar2',
'    is',
'    begin',
'        if sqlcode = c_erro_falha_tecnica then',
'            return c_status_falha_tecnica;',
'        end if;',
'',
'        if sqlcode between -20999 and -20000 then',
'            return c_status_falha_negocio;',
'        end if;',
'',
'        return c_status_falha_tecnica;',
'    end classify_error;',
'',
'    procedure registrar_evento_inicio(',
'        p_id_solicitacao in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_entrypoint     in varchar2',
'    ) is',
'        pragma autonomous_transaction;',
'    begin',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            p_id_worker,',
'            sysdate,',
'            ''EXECUCAO_INICIADA'',',
'            ''INFO'',',
'            ''entrypoint='' || p_entrypoint,',
'            p_id_tenant,',
'            p_id_correlation',
'        );',
'',
'        commit;',
'    end registrar_evento_inicio;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-06 / ST-CI-65 \2013 Executar artefato PL/SQL'),
'    -------------------------------------------------------------------',
'    procedure executar_artefato(',
'        p_id_solicitacao in number,',
'        p_resultado      out varchar2,',
'        p_detalhes       out varchar2',
'    ) is',
'        l_id_artefato            mae_solicitacao_execucao.id_artefato%type;',
'        l_status                 mae_solicitacao_execucao.status%type;',
'        l_id_tenant              mae_solicitacao_execucao.id_tenant%type;',
'        l_id_usuario             mae_solicitacao_execucao.id_usuario%type;',
'        l_id_negocio             mae_solicitacao_execucao.id_negocio%type;',
'        l_payload                mae_solicitacao_execucao.parametros%type;',
'        l_corr                   mae_solicitacao_execucao.id_correlation%type;',
'        l_entry                  varchar2(400);',
'        l_sql                    varchar2(2000);',
'        l_result                 varchar2(30);',
'        l_details                varchar2(1000);',
'        l_id_worker              mae_solicitacao_execucao.id_worker%type;',
'        l_sucesso                clob;',
'        l_messages_json          clob;',
'        l_old_client_identifier  varchar2(4000);',
'        l_sqlcode                number;',
'        l_sqlerrm                varchar2(4000);',
'        l_falha_critica          boolean := false;',
'        l_cb_result              varchar2(30);',
'    begin',
'        p_resultado := null;',
'        p_detalhes  := null;',
'',
'        select id_artefato,',
'               status,',
'               id_tenant,',
'               id_usuario,',
'               id_negocio,',
'               parametros,',
'               id_correlation,',
'               id_worker',
'          into l_id_artefato,',
'               l_status,',
'               l_id_tenant,',
'               l_id_usuario,',
'               l_id_negocio,',
'               l_payload,',
'               l_corr,',
'               l_id_worker',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao;',
'',
'        if l_status <> c_status_em_processamento then',
'            raise_application_error(',
'                -20972,',
unistr('                ''MAE-WRK-STATUS_INVALIDO|Solicita\00E7\00E3o n\00E3o est\00E1 EM_PROCESSAMENTO (id=''||'),
'                p_id_solicitacao||'', status=''||l_status||'')''',
'            );',
'        end if;',
'',
'        l_entry := get_entrypoint(l_id_artefato);',
'        l_sql   := ''begin '' || l_entry || ''(:1,:2,:3,:4,:5,:6,:7,:8); end;'';',
'',
'        registrar_evento_inicio(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => l_id_worker,',
'            p_id_tenant      => l_id_tenant,',
'            p_id_correlation => l_corr,',
'            p_entrypoint     => l_entry',
'        );',
'',
'        ----------------------------------------------------------------------------',
unistr('        -- guardar contexto atual da sess\00E3o'),
'        ----------------------------------------------------------------------------',
'        l_old_client_identifier := sys_context(''USERENV'', ''CLIENT_IDENTIFIER'');',
'',
'        ----------------------------------------------------------------------------',
unistr('        -- setar contexto do tenant para VPD / pol\00EDtica de privacidade'),
'        ----------------------------------------------------------------------------',
'        dbms_session.set_identifier(''TENANT:'' || to_char(l_id_tenant)|| '';USUARIO:'' || l_id_usuario);',
'',
'',
'        begin',
'            execute immediate l_sql',
'                using',
'                    p_id_solicitacao,',
'                    l_id_tenant,',
'                    l_id_usuario,',
'                    l_id_negocio,',
'                    l_payload,',
'                    l_corr,',
'                    out l_sucesso,',
'                    out l_messages_json;',
'',
'            l_result  := c_status_sucesso;',
'            l_details := c_msg_execucao_ok;',
'',
'        exception',
'            when others then',
'                l_sqlcode       := sqlcode;',
'                l_sqlerrm       := sqlerrm;',
'                l_falha_critica := is_falha_critica(l_sqlcode);',
'',
'                if l_falha_critica then',
'                    l_result := c_status_erro_final;',
'',
'                    -------------------------------------------------------------------',
unistr('                    -- ST-CI-52 / ST-CI-53 \2013 emitir somente o evento cr\00EDtico'),
'                    -------------------------------------------------------------------',
'                    pkg_maestro'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(16263274299928990)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'_evento.registrar_critical_failure_event(',
'                        p_id_solicitacao => p_id_solicitacao,',
'                        p_id_worker      => l_id_worker,',
'                        p_id_tenant      => l_id_tenant,',
'                        p_id_correlation => l_corr,',
'                        p_sqlcode        => l_sqlcode,',
'                        p_sqlerrm        => l_sqlerrm,',
'                        p_etapa          => ''EXECUTAR_ARTEFATO'',',
'                        p_tentativas     => null,',
'                        p_detalhes_extra => ''entrypoint='' || l_entry || ''; falha_critica=S''',
'                    );',
'                else',
'                    l_result := classify_error;',
'',
'                    registrar_evento_falha(',
'                        p_id_solicitacao => p_id_solicitacao,',
'                        p_id_worker      => l_id_worker,',
'                        p_id_tenant      => l_id_tenant,',
'                        p_id_correlation => l_corr,',
'                        p_tipo_evento    => case',
'                                                when l_result = c_status_falha_negocio',
'                                                then c_evt_falha_negocio',
'                                                else c_evt_falha_tecnica',
'                                            end,',
'                        p_sqlcode        => l_sqlcode,',
'                        p_sqlerrm        => l_sqlerrm,',
'                        p_etapa          => ''EXECUTAR_ARTEFATO'',',
'                        p_tentativas     => null,',
'                        p_detalhes_extra => ''entrypoint='' || l_entry || ''; falha_critica=N''',
'                    );',
'                end if;',
'',
'                l_details := substr(',
'                    ''SQLCODE='' || to_char(l_sqlcode) || ''; SQLERRM='' || l_sqlerrm,',
'                    1,',
'                    1000',
'                );',
'        end;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            null,',
'            sysdate,',
'            c_evt_artefato_executado,',
'            l_result,',
'            ''entrypoint='' || l_entry || ''; '' || l_details,',
'            l_id_tenant,',
'            l_corr',
'        );',
'',
'        p_resultado := l_result;',
'        p_detalhes  := l_details;',
'',
'        dbms_session.set_identifier(l_old_client_identifier);',
'',
'    exception',
'        when others then',
'            begin',
'                dbms_session.set_identifier(l_old_client_identifier);',
'            exception',
'                when others then',
'                    null;',
'            end;',
'',
'            declare',
'                l_err varchar2(1000) := substr(',
'                    ''Falha antes da invocacao/log: SQLCODE='' || to_char(sqlcode) ||',
'                    ''; SQLERRM='' || sqlerrm,',
'                    1,',
'                    1000',
'                );',
'            begin',
'                begin',
'                    insert into mae_registro_tecnico (',
'                        id_solicitacao,',
'                        id_worker,',
'                        dt_evento,',
'                        tipo_evento,',
'                        resultado,',
'                        detalhes,',
'                        id_tenant,',
'                        id_correlation',
'                    )',
'                    select p_id_solicitacao,',
'                           null,',
'                           sysdate,',
'                           c_evt_artefato_executado,',
'                           c_status_falha_tecnica,',
'                           l_err,',
'                           m.id_tenant,',
'                           m.id_correlation',
'                      from mae_solicitacao_execucao m',
'                     where m.id = p_id_solicitacao;',
'                exception',
'                    when others then',
'                        null;',
'                end;',
'',
'                raise;',
'            end;',
'    end executar_artefato;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-31 \2013 Normaliza\00E7\00F5es da pol\00EDtica de retry'),
'    -------------------------------------------------------------------',
'    function normalizar_max_tentativas(',
'        p_max_tentativas in number',
'    ) return number',
'    is',
'    begin',
'        if p_max_tentativas is null or p_max_tentativas < 0 then',
'            return 0;',
'        end if;',
'',
'        return p_max_tentativas;',
'    end normalizar_max_tentativas;',
'',
'    function normalizar_estrategia_retry(',
'        p_estrategia_retry in varchar2',
'    ) return varchar2',
'    is',
'        l_estrategia varchar2(20);',
'    begin',
'        l_estrategia := upper(trim(p_estrategia_retry));',
'',
'        if l_estrategia = c_retry_estrategia_fixo then',
'            return c_retry_estrategia_fixo;',
'        elsif l_estrategia = c_retry_estrategia_linear then',
'            return c_retry_estrategia_linear;',
'        elsif l_estrategia = c_retry_estrategia_exponencial then',
'            return c_retry_estrategia_exponencial;',
'        end if;',
'',
'        return c_retry_estrategia_fixo;',
'    end normalizar_estrategia_retry;',
'',
'    function normalizar_retry_base_seg(',
'        p_retry_base_seg in number',
'    ) return number',
'    is',
'    begin',
'        if p_retry_base_seg is null or p_retry_base_seg < 0 then',
'            return 0;',
'        end if;',
'',
'        return p_retry_base_seg;',
'    end normalizar_retry_base_seg;',
'',
'    function normalizar_retry_max_seg(',
'        p_retry_max_seg in number',
'    ) return number',
'    is',
'    begin',
'        if p_retry_max_seg is null or p_retry_max_seg < 0 then',
'            return 0;',
'        end if;',
'',
'        return p_retry_max_seg;',
'    end normalizar_retry_max_seg;',
'',
'    function retry_habilitado(',
'        p_max_tentativas in number',
'    ) return boolean',
'    is',
'    begin',
'        return normalizar_max_tentativas(p_max_tentativas) > 0;',
'    end retry_habilitado;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-31 \2013 Obter pol\00EDtica de retry por artefato'),
'    -------------------------------------------------------------------',
'    function obter_politica_retry(',
'        p_id_artefato in number',
'    ) return r_politica_retry',
'    is',
'        l_pol r_politica_retry;',
'    begin',
'        l_pol.id_artefato          := p_id_artefato;',
'        l_pol.max_tentativas       := 0;',
'        l_pol.estrategia_retry     := c_retry_estrategia_fixo;',
'        l_pol.retry_base_seg       := 0;',
'        l_pol.retry_max_seg        := 0;',
'        l_pol.ind_retry_habilitado := ''N'';',
'',
'        if p_id_artefato is null then',
'            return l_pol;',
'        end if;',
'',
'        begin',
'            select normalizar_max_tentativas(cfg.max_tentativas),',
'                   normalizar_estrategia_retry(cfg.estrategia_retry),',
'                   normalizar_retry_base_seg(cfg.retry_base_seg),',
'                   normalizar_retry_max_seg(cfg.retry_max_seg)',
'              into l_pol.max_tentativas,',
'                   l_pol.estrategia_retry,',
'                   l_pol.retry_base_seg,',
'                   l_pol.retry_max_seg',
'              from srv_artefato_cfg cfg',
'             where cfg.id_artefato = p_id_artefato;',
'        exception',
'            when no_data_found then',
'                null;',
'        end;',
'',
'        if retry_habilitado(l_pol.max_tentativas) then',
'            l_pol.ind_retry_habilitado := ''S'';',
'        else',
'            l_pol.ind_retry_habilitado := ''N'';',
'        end if;',
'',
'        return l_pol;',
'    end obter_politica_retry;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-32 \2013 C\00E1lculo do backoff de retry'),
'    -------------------------------------------------------------------',
'    function calcular_backoff_retry(',
'        p_estrategia_retry in varchar2,',
'        p_retry_base_seg   in number,',
'        p_tentativas_atual in number',
'    ) return number',
'    is',
'        l_estrategia       varchar2(20);',
'        l_retry_base_seg   number;',
'        l_tentativas_atual number;',
'        l_atraso           number;',
'    begin',
'        l_estrategia       := normalizar_estrategia_retry(p_estrategia_retry);',
'        l_retry_base_seg   := normalizar_retry_base_seg(p_retry_base_seg);',
'        l_tentativas_atual := nvl(p_tentativas_atual, 0);',
'',
'        if l_tentativas_atual < 0 then',
'            l_tentativas_atual := 0;',
'        end if;',
'',
'        if l_estrategia = c_retry_estrategia_linear then',
'            l_atraso := l_retry_base_seg * (l_tentativas_atual + 1);',
'        else',
'            l_atraso := l_retry_base_seg;',
'        end if;',
'',
'        if l_atraso < 0 then',
'            l_atraso := 0;',
'        end if;',
'',
'        return l_atraso;',
'    end calcular_backoff_retry;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-32 \2013 Preparar retry t\00E9cnico'),
'    -------------------------------------------------------------------',
'    procedure preparar_retry_tecnico(',
'        p_id_solicitacao in number',
'    ) is',
'        l_id_artefato        mae_solicitacao_execucao.id_artefato%type;',
'        l_status             mae_solicitacao_execucao.status%type;',
'        l_tentativas_atual   mae_solicitacao_execucao.tentativas%type;',
'        l_tenant             mae_solicitacao_execucao.id_tenant%type;',
'        l_corr               mae_solicitacao_execucao.id_correlation%type;',
'        l_pol                r_politica_retry;',
'        l_atraso_seg         number;',
'        l_nova_dt_disponivel timestamp with time zone;',
'    begin',
'        select id_artefato,',
'               status,',
'               tentativas,',
'               id_tenant,',
'               id_correlation',
'          into l_id_artefato,',
'               l_status,',
'               l_tentativas_atual,',
'               l_tenant,',
'               l_corr',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao',
'           for update;',
'',
'        if l_status <> c_status_falha_tecnica then',
'            raise_application_error(',
'                -20981,',
unistr('                ''MAE-WRK-RETRY-STATUS_INVALIDO|Solicita\00E7\00E3o n\00E3o est\00E1 em FALHA_TECNICA (id='' ||'),
'                p_id_solicitacao || '', status='' || l_status || '')''',
'            );',
'        end if;',
'',
'        l_pol := obter_politica_retry(',
'            p_id_artefato => l_id_artefato',
'        );',
'',
'        l_atraso_seg := calcular_backoff_retry(',
'            p_estrategia_retry => l_pol.estrategia_retry,',
'            p_retry_base_seg   => l_pol.retry_base_seg,',
'            p_tentativas_atual => l_tentativas_atual',
'        );',
'',
'        l_nova_dt_disponivel :=',
'            systimestamp + numtodsinterval(l_atraso_seg, ''SECOND'');',
'',
'        update mae_solicitacao_execucao',
'           set tentativas             = nvl(tentativas, 0) + 1,',
'               dt_disponivel_execucao = l_nova_dt_disponivel,',
'               status                 = c_status_pendente,',
'               dt_inicio              = null,',
'               dt_fim                 = null,',
'               id_worker              = null,',
'               dt_saude               = null',
'         where id = p_id_solicitacao',
'           and status = c_status_falha_tecnica;',
'',
'        if sql%rowcount <> 1 then',
'            raise_application_error(',
'                -20982,',
unistr('                ''MAE-WRK-RETRY-UPDATE_FALHOU|Falha ao preparar retry da solicita\00E7\00E3o id='' ||'),
'                p_id_solicitacao',
'            );',
'        end if;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            null,',
'            systimestamp,',
'            c_evt_retry_agendado,',
'            c_resultado_info,',
'            substr(',
'                ''tentativas_anterior='' || nvl(to_char(l_tentativas_atual), ''0'') ||',
'                ''; tentativas_nova='' || to_char(nvl(l_tentativas_atual, 0) + 1) ||',
'                ''; estrategia_retry='' || l_pol.estrategia_retry ||',
'                ''; retry_base_seg='' || to_char(l_pol.retry_base_seg) ||',
'                ''; atraso_calculado_seg='' || to_char(l_atraso_seg) ||',
'                ''; dt_disponivel_execucao_nova='' ||',
'                to_char(l_nova_dt_disponivel, ''YYYY-MM-DD"T"HH24:MI:SS.FF3 TZH:TZM''),',
'                1,',
'                4000',
'            ),',
'            l_tenant,',
'            l_corr',
'        );',
'    end preparar_retry_tecnico;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-33 \2013 Avalia se deve marcar ERRO_FINAL'),
'    -------------------------------------------------------------------',
'    function deve_marcar_erro_final(',
'        p_tentativas_atual in number,',
'        p_max_tentativas   in number',
'    ) return boolean',
'    is',
'        l_tentativas_atual number;',
'        l_max_tentativas   number;',
'    begin',
'        l_tentativas_atual := nvl(p_tentativas_atual, 0);',
'        l_max_tentativas   := normalizar_max_tentativas(p_max_tentativas);',
'',
'        if l_tentativas_atual < 0 then',
'            l_tentativas_atual := 0;',
'        end if;',
'',
'        if l_max_tentativas = 0 then',
'            return true;',
'        end if;',
'',
'        return l_tentativas_atual >= l_max_tentativas;',
'    end deve_marcar_erro_final;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-33 \2013 Marcar falha definitiva'),
'    -------------------------------------------------------------------',
'    procedure marcar_erro_final(',
'        p_id_solicitacao in number',
'    ) is',
'        l_id_artefato mae_solicitacao_execucao.id_artefato%type;',
'        l_status      mae_solicitacao_execucao.status%type;',
'        l_tentativas  mae_solicitacao_execucao.tentativas%type;',
'        l_tenant      mae_solicitacao_execucao.id_tenant%type;',
'        l_corr        mae_solicitacao_execucao.id_correlation%type;',
'        l_pol         r_politica_retry;',
'    begin',
'        select id_artefato,',
'               status,',
'               tentativas,',
'               id_tenant,',
'               id_correlation',
'          into l_id_artefato,',
'               l_status,',
'               l_tentativas,',
'               l_tenant,',
'               l_corr',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao',
'           for update;',
'',
'        if l_status <> c_status_falha_tecnica then',
'            raise_application_error(',
'                -20983,',
unistr('                ''MAE-WRK-ERROFINAL-STATUS_INVALIDO|Solicita\00E7\00E3o n\00E3o est\00E1 em FALHA_TECNICA (id='' ||'),
'                p_id_solicitacao || '', status='' || l_status || '')''',
'            );',
'        end if;',
'',
'        l_pol := obter_politica_retry(',
'            p_id_artefato => l_id_artefato',
'        );',
'',
'        if not deve_marcar_erro_final(',
'            p_tentativas_atual => l_tentativas,',
'            p_max_tentativas   => l_pol.max_tentativas',
'        ) then',
'            raise_application_error(',
'                -20984,',
unistr('                ''MAE-WRK-ERROFINAL-AINDA_ELEGIVEL|Solicita\00E7\00E3o ainda eleg\00EDvel a retry (id='' ||'),
'                p_id_solicitacao || '')''',
'            );',
'        end if;',
'',
'        update mae_solicitacao_execucao',
'           set status = c_status_erro_final',
'         where id = p_id_solicitacao',
'           and status = c_status_falha_tecnica;',
'',
'        if sql%rowcount <> 1 then',
'            raise_application_error(',
'                -20985,',
unistr('                ''MAE-WRK-ERROFINAL-UPDATE_FALHOU|Falha ao marcar erro final da solicita\00E7\00E3o id='' ||'),
'                p_id_solicitacao',
'            );',
'        end if;',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            null,',
'            systimestamp,',
'            c_evt_erro_final_marcado,',
'            c_resultado_info,',
'            substr(',
'                ''tentativas_atual='' || nvl(to_char(l_tentativas), ''0'') ||',
'                ''; max_tentativas='' || to_char(l_pol.max_tentativas) ||',
'                ''; retry_habilitado='' || l_pol.ind_retry_habilitado,',
'                1,',
'                4000',
'            ),',
'            l_tenant,',
'            l_corr',
'        );',
'',
'        registrar_evento_falha(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => null,',
'            p_id_tenant      => l_tenant,',
'            p_id_correlation => l_corr,',
'            p_tipo_evento    => c_evt_retry_limite_excedido,',
'            p_sqlcode        => null,',
'            p_sqlerrm        => null,',
'            p_etapa          => ''MARCAR_ERRO_FINAL'',',
'            p_tentativas     => l_tentativas,',
'            p_detalhes_extra => ''max_tentativas='' || to_char(l_pol.max_tentativas)',
'        );',
'    end marcar_erro_final;',
'',
'    -------------------------------------------------------------------',
unistr('    -- HI-CI-09 \2013 Orquestra\00E7\00E3o da falha t\00E9cnica'),
'    -------------------------------------------------------------------',
'    procedure tratar_falha_tecnica(',
'        p_id_solicitacao in number',
'    ) is',
'        l_id_artefato mae_solicitacao_execucao.id_artefato%type;',
'        l_tentativas  mae_solicitacao_execucao.tentativas%type;',
'        l_status      mae_solicitacao_execucao.status%type;',
'        l_pol         r_politica_retry;',
'    begin',
'        select id_artefato,',
'               tentativas,',
'               status',
'          into l_id_artefato,',
'               l_tentativas,',
'               l_status',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao',
'           for update;',
'',
'        if l_status <> c_status_falha_tecnica then',
'            return;',
'        end if;',
'',
'        l_pol := obter_politica_retry(',
'            p_id_artefato => l_id_artefato',
'        );',
'',
'        if deve_marcar_erro_final(',
'            p_tentativas_atual => l_tentativas,',
'            p_max_tentativas   => l_pol.max_tentativas',
'        ) then',
'            marcar_erro_final(',
'                p_id_solicitacao => p_id_solicitacao',
'            );',
'        else',
'            preparar_retry_tecnico(',
'                p_id_solicitacao => p_id_solicitacao',
'            );',
'        end if;',
'    end tratar_falha_tecnica;',
'',
'    -------------------------------------------------------------------',
unistr('    -- ST-CI-07 / ST-CI-25 / HI-CI-09 / ST-CI-65 \2013 Finalizar execu\00E7\00E3o'),
'    -------------------------------------------------------------------',
'    procedure finalizar_execucao(',
'        p_id_solicitacao in number,',
'        p_resultado      in varchar2,',
'        p_detalhes       in varchar2',
'    ) is',
'        l_status_atual mae_solicitacao_execucao.status%type;',
'        l_tenant       mae_solicitacao_execucao.id_tenant%type;',
'        l_corr         mae_solicitacao_execucao.id_correlation%type;',
'        l_worker       mae_solicitacao_execucao.id_worker%type;',
'        l_id_artefato  mae_solicitacao_execucao.id_artefato%type;',
'        l_motivo       varchar2(1000);',
'        l_result       varchar2(30);',
'        l_delay_cb_seg number;',
'        l_cb_estado    varchar2(20);',
'    begin',
'        l_result := upper(trim(p_resultado));',
'',
'        if l_result not in (',
'            c_status_sucesso,',
'            c_status_falha_negocio,',
'            c_status_falha_tecnica,',
'            c_status_erro_final,',
'            c_status_cb_bloqueado',
'        ) then',
'            raise_application_error(',
'                -20975,',
unistr('                ''MAE-WRK-FINAL-RESULT_INVALIDO|Resultado inv\00E1lido: '' || nvl(l_result, ''<null>'')'),
'            );',
'        end if;',
'',
'        if l_result = c_status_sucesso then',
'            l_motivo := null;',
'        else',
'            l_motivo := substr(nvl(p_detalhes, c_msg_erro_sem_detalhe), 1, 1000);',
'        end if;',
'',
'        -------------------------------------------------------------------',
unistr('        -- Carrega e trava a solicita  \00E3o antes de qualquer l\00F3gica de breaker'),
'        -------------------------------------------------------------------',
'        select status,',
'               id_tenant,',
'               id_correlation,',
'               id_worker,',
'               id_artefato',
'          into l_status_atual,',
'               l_tenant,',
'               l_corr,',
'               l_worker,',
'               l_id_artefato',
'          from mae_solicitacao_execucao',
'         where id = p_id_solicitacao',
'           for update;',
'',
'        if l_status_atual <> c_status_em_processamento then',
'            raise_application_error(',
'                -20973,',
unistr('                ''MAE-WRK-FINAL-STATUS_INVALIDO|Solicita\00E7\00E3o n\00E3o est\00E1 EM_PROCESSAMENTO (id=''||'),
'                p_id_solicitacao||'', status=''||l_status_atual||'')''',
'            );',
'        end if;',
'',
'        -------------------------------------------------------------------',
unistr('        -- Resultado transit\00F3rio de bloqueio por circuit breaker'),
'        -------------------------------------------------------------------',
'        if l_result = c_status_cb_bloqueado then',
'            l_delay_cb_seg := obter_delay_reagendamento_cb(',
'                p_id_artefato => l_id_artefato',
'            );',
'',
'            update mae_solicitacao_execucao',
'               set status                 = c_status_pendente,',
'                   dt_disponivel_execucao = systimestamp + numtodsinterval(l_delay_cb_seg, ''SECOND''),',
'                   dt_inicio              = null,',
'                   dt_fim                 = null,',
'                   motivo_falha           = l_motivo,',
'                   id_worker              = null,',
'                   dt_saude               = null',
'             where id = p_id_solicitacao',
'               and status = c_status_em_processamento;',
'',
'            if sql%rowcount <> 1 then',
'                raise_application_error(',
'                    -20974,',
unistr('                    ''MAE-WRK-FINAL-CB-UPDATE_FALHOU|Falha ao reagendar solicita\00E7\00E3o bloqueada por circuit breaker id='' || p_id_solicitacao'),
'                );',
'            end if;',
'',
'            insert into mae_registro_tecnico (',
'                id_solicitacao,',
'                id_worker,',
'                dt_evento,',
'                tipo_evento,',
'                resultado,',
'                detalhes,',
'                id_tenant,',
'                id_correlation',
'            ) values (',
'                p_id_solicitacao,',
'                l_worker,',
'                sysdate,',
'                c_evt_execucao_finalizada,',
'                l_result,',
'                substr(',
'                    ''resultado='' || l_result ||',
'                    ''; detalhe='' || nvl(p_detalhes, c_msg_execucao_bloqueada_cb) ||',
'                    ''; reagendado_em_seg='' || to_char(l_delay_cb_seg),',
'                    1,',
'                    1000',
'                ),',
'                l_tenant,',
'                l_corr',
'            );',
'',
'            commit;',
'            return;',
'        end if;',
'',
'        -------------------------------------------------------------------',
unistr('        -- Verifica estado do breaker antes de atualizar a solicita\00E7\00E3o,'),
unistr('        -- para identificar corretamente execu\00E7\00E3o de teste em MEIO_ABERTO'),
'        -------------------------------------------------------------------',
'        if l_result = c_status_falha_tecnica then',
'            l_cb_estado := pkg_maestro_cfg.get_cb_estado(',
'                p_id_artefato => l_id_artefato',
'            );',
'        else',
'            l_cb_estado := null;',
'        end if;',
'',
'        -------------------------------------------------------------------',
unistr('        -- Fluxo especial: execu\00E7\00E3o de teste em MEIO_ABERTO falhou'),
unistr('        -- Reabre o breaker e devolve a pr\00F3pria solicita\00E7\00E3o para PENDENTE'),
'        -------------------------------------------------------------------',
'        if l_result = c_status_falha_tecnica',
'           and l_cb_estado = pkg_maestro_cfg.c_cb_meio_aberto',
'        then',
'            pkg_maestro_cfg.registrar_falha_tecnica_cb(',
'                p_id_artefato    => l_id_artefato,',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_worker      => l_worker,',
'                p_id_tenant      => l_tenant,',
'                p_id_correlation => l_corr,',
'                p_detalhe        => to_clob(p_detalhes)',
'            );',
'',
'            reproteger_fila_por_cb_reaberto(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_artefato    => l_id_artefato,',
'                p_id_worker      => l_worker,',
'                p_id_tenant      => l_tenant,',
'                p_id_correlation => l_corr,',
'                p_detalhes       => p_detalhes',
'            );',
'',
'            insert into mae_registro_tecnico (',
'                id_solicitacao,',
'                id_worker,',
'                dt_evento,',
'                tipo_evento,',
'                resultado,',
'                detalhes,',
'                id_tenant,',
'                id_correlation',
'            ) values (',
'                p_id_solicitacao,',
'                l_worker,',
'                sysdate,',
'                c_evt_execucao_finalizada,',
'                c_status_pendente,',
'                substr(',
'                    ''resultado_original='' || l_result ||',
'                    ''; tratamento=EXECUCAO_TESTE_CB_REAGENDADA'' ||',
'                    ''; detalhe='' || nvl(p_detalhes, c_msg_erro_sem_detalhe),',
'                    1,',
'                    1000',
'                ),',
'                l_tenant,',
'                l_corr',
'            );',
'',
'            commit;',
'            return;',
'        end if;',
'',
'        -------------------------------------------------------------------',
'        -- Fluxo normal',
'        -------------------------------------------------------------------',
'        update mae_solicitacao_execucao',
'           set status       = l_result,',
'               dt_fim       = sysdate,',
'               motivo_falha = l_motivo,',
'               dt_saude     = sysdate',
'         where id = p_id_solicitacao',
'           and status = c_status_em_processamento;',
'',
'        if sql%rowcount <> 1 then',
'            raise_application_error(',
'                -20974,',
'                ''MAE-WRK-FINAL-UPDATE_FALHOU|Falha ao atualizar mensagem id='' || p_id_solicitacao',
'            );',
'        end if;',
'',
'        -------------------------------------------------------------------',
'        -- Atualiza circuit breaker no fluxo normal',
'        -------------------------------------------------------------------',
'        if l_result = c_status_sucesso then',
'            pkg_maestro_cfg.registrar_sucesso_cb(',
'                p_id_artefato    => l_id_artefato,',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_worker      => l_worker,',
'                p_id_tenant      => l_tenant,',
'                p_id_correlation => l_corr',
'            );',
'        elsif l_result in (c_status_falha_tecnica, c_status_erro_final) then',
'            pkg_maestro_cfg.registrar_falha_tecnica_cb(',
'                p_id_artefato    => l_id_artefato,',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_id_worker      => l_worker,',
'                p_id_tenant      => l_tenant,',
'                p_id_correlation => l_corr,',
'                p_detalhe        => to_clob(p_detalhes)',
'            );',
'        end if;',
'',
'        aplicar_bloqueio_falha(',
'            p_id_solicitacao_falha => p_id_solicitacao,',
'            p_resultado            => l_result',
'        );',
'',
'        insert into mae_registro_tecnico (',
'            id_solicitacao,',
'            id_worker,',
'            dt_evento,',
'            tipo_evento,',
'            resultado,',
'            detalhes,',
'            id_tenant,',
'            id_correlation',
'        ) values (',
'            p_id_solicitacao,',
'            l_worker,',
'            sysdate,',
'            c_evt_execucao_finalizada,',
'            l_result,',
'            substr(''resultado='' || l_result || ''; '' || nvl(p_detalhes, c_msg_execucao_ok), 1, 1000),',
'            l_tenant,',
'            l_corr',
'        );',
'',
'        if l_result = c_status_falha_tecnica then',
'            tratar_falha_tecnica(',
'                p_id_solicitacao => p_id_solicitacao',
'            );',
'        end if;',
'',
'        commit;',
'',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                -20974,',
unistr('                ''MAE-WRK-FINAL-UPDATE_FALHOU|Nao encontrou requisi\00E7\00E3o para id='' || p_id_solicitacao'),
'            );',
'        when others then',
'            rollback;',
'            raise;',
'    end finalizar_execucao;',
'',
'    procedure reproteger_fila_por_cb_reaberto(',
'        p_id_solicitacao in number,',
'        p_id_artefato    in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2,',
'        p_detalhes       in varchar2',
'    ) is',
'        l_cooldown_seg number;',
'        l_qtd_afetada  number := 0;',
'    begin',
'        l_cooldown_seg := obter_delay_reagendamento_cb(',
'            p_id_artefato => p_id_artefato',
'        );',
'',
'        -------------------------------------------------------------------',
unistr('        -- devolve a execu\00E7\00E3o de teste para PENDENTE'),
'        -------------------------------------------------------------------',
'        update mae_solicitacao_execucao',
'           set status                 = c_status_pendente,',
'               dt_disponivel_execucao = systimestamp + numtodsinterval(l_cooldown_seg, ''SECOND''),',
'               dt_inicio              = null,',
'               dt_fim                 = null,',
'               id_worker              = null,',
'               dt_saude               = null,',
'               motivo_falha           = substr(',
'                                            nvl(',
'                                                p_detalhes,',
unistr('                                                ''Falha t\00E9cnica persist')))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(16263274299928990)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('ente em execu\00E7\00E3o de teste do circuit breaker'''),
'                                            ),',
'                                            1,',
'                                            1000',
'                                        )',
'         where id = p_id_solicitacao;',
'',
'        -------------------------------------------------------------------',
'        -- protege as demais pendentes do mesmo artefato',
'        -------------------------------------------------------------------',
'        update mae_solicitacao_execucao',
'           set dt_disponivel_execucao = systimestamp + numtodsinterval(l_cooldown_seg, ''SECOND'')',
'         where id_artefato = p_id_artefato',
'           and status = c_status_pendente',
'           and id <> p_id_solicitacao;',
'',
'        l_qtd_afetada := sql%rowcount;',
'',
'        -------------------------------------------------------------------',
unistr('        -- evento adicional de prote\00E7\00E3o da fila'),
'        -------------------------------------------------------------------',
'        pkg_maestro_evento.registrar_evento(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => p_id_worker,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_correlation => p_id_correlation,',
'            p_tipo_evento    => c_evt_cb_fila_protegida,',
'            p_resultado      => ''INFO'',',
'            p_detalhes       => ''id_artefato='' || nvl(to_char(p_id_artefato), ''<null>'') ||',
'                                ''; cooldown_seg='' || nvl(to_char(l_cooldown_seg), ''<null>'') ||',
'                                ''; qtd_pendentes_afetadas='' || nvl(to_char(l_qtd_afetada), ''0'') ||',
'                                ''; motivo=Falha persistente em execucao de teste do circuit breaker''',
'        );',
'    end reproteger_fila_por_cb_reaberto;',
'',
'    procedure proteger_fila_cb_aberto(',
'        p_id_solicitacao in number,',
'        p_id_artefato    in number,',
'        p_id_worker      in number,',
'        p_id_tenant      in number,',
'        p_id_correlation in varchar2',
'    ) is',
'        l_cooldown_seg number;',
'        l_qtd_afetada  number := 0;',
'    begin',
'        l_cooldown_seg := obter_delay_reagendamento_cb(',
'            p_id_artefato => p_id_artefato',
'        );',
'',
'        update mae_solicitacao_execucao',
'           set dt_disponivel_execucao = systimestamp + numtodsinterval(l_cooldown_seg, ''SECOND'')',
'         where id_artefato = p_id_artefato',
'           and status = c_status_pendente',
'           and dt_disponivel_execucao <= systimestamp;',
'',
'        l_qtd_afetada := sql%rowcount;',
'',
'        pkg_maestro_evento.registrar_evento(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => p_id_worker,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_correlation => p_id_correlation,',
'            p_tipo_evento    => ''CIRCUIT_BREAKER_BLOCKED'',',
'            p_resultado      => ''BLOQUEADO'',',
'            p_detalhes       => ''id_artefato='' || nvl(to_char(p_id_artefato), ''<null>'') ||',
'                                ''; cooldown_seg='' || nvl(to_char(l_cooldown_seg), ''<null>'') ||',
'                                ''; qtd_pendentes_protegidas='' || nvl(to_char(l_qtd_afetada), ''0'')',
'        );',
'    end proteger_fila_cb_aberto;    ',
'',
'end pkg_maestro_worker;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_worker_run
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16263349492927530)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_MAESTRO_WORKER_RUN'
,p_sequence=>200
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package PKG_MAESTRO_WORKER_RUN as',
'',
'    c_job_prefix        constant varchar2(30) := ''JOB_MAE_WORKER_'';',
'    c_req_job_prefix    constant varchar2(30) := ''JOB_MAE_REQ_'';',
'    c_res_sucesso       constant varchar2(30) := ''SUCESSO'';',
'    c_res_falha_negocio constant varchar2(30) := ''FALHA_NEGOCIO'';',
'    c_res_falha_tecnica constant varchar2(30) := ''FALHA_TECNICA'';',
'',
'    -------------------------------------------------------------------',
'    -- Jobs principais das filas',
'    -------------------------------------------------------------------',
'    function gerar_nome_job_fila(',
'        p_id_sched_cfg in number',
'    ) return varchar2;',
'',
'    procedure criar_job_fila(',
'        p_id_sched_cfg in number',
'    );',
'',
'    procedure parar_job_fila(',
'        p_id_sched_cfg in number,',
'        p_force        in boolean default false',
'    );',
'',
'    procedure executar_job_fila(',
'        p_id_sched_cfg in number,',
'        p_use_current_session in boolean default false',
'    );',
'',
'    procedure dropar_job_fila(',
'        p_id_sched_cfg in number,',
'        p_force        in boolean default true',
'    );',
'',
'    -------------------------------------------------------------------',
'    -- Fluxo do worker',
'    -------------------------------------------------------------------',
'    procedure run_request(',
'        p_id_solicitacao in number',
'    );',
'',
'    procedure run_once(',
'        p_id_sched_cfg in number',
'    );',
'',
'    procedure recriar_jobs(',
'        p_id       in srv_sistema_versionado.id%type default 0,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'',
'    procedure parar_job_execucao(',
'        p_id_solicitacao in number,',
'        p_force          in boolean default true,',
'        p_dropar         in boolean default true',
'    );    ',
'',
'    procedure parar_job_execucao(',
'        p_id             in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table            ',
'    );    ',
'',
'    function detalhe_registro (',
'        p_id in mae_sched_cfg.id%type',
'    ) return varchar2;',
'',
'end PKG_MAESTRO_WORKER_RUN;',
'/',
'create or replace package body pkg_maestro_worker_run as',
'    -------------------------------------------------------------------',
'    -- Constantes internas',
'    -------------------------------------------------------------------',
'    c_evt_job_filho_erro         constant varchar2(30) := ''JOB_FILHO_ERRO'';',
'    c_evt_job_filho_criacao_erro constant varchar2(30) := ''JOB_FILHO_CRIACAO_ERRO'';',
'    c_evt_execucao_parada_manual constant varchar2(50) := ''EXECUCAO_PARADA_MANUAL'';',
unistr('    c_msg_cfg_nao_encontrada     constant varchar2(200) := ''Configura\00E7\00E3o de scheduler n\00E3o encontrada: '';'),
unistr('    c_msg_cfg_sem_artefato       constant varchar2(200) := ''Configura\00E7\00E3o sem id_artefato: '';'),
unistr('    c_msg_intervalo_invalido     constant varchar2(200) := ''intervalo_segundos inv\00E1lido na mae_sched_cfg.id='';'),
'    c_msg_falha_criar_job_fila   constant varchar2(200) := ''Erro ao criar job da fila '';',
'    c_msg_falha_parar_job_fila   constant varchar2(200) := ''Erro ao parar job da fila '';',
'    c_msg_falha_executar_job     constant varchar2(200) := ''Erro ao executar job da fila '';',
'    c_msg_falha_dropar_job_fila  constant varchar2(200) := ''Erro ao dropar job da fila '';',
'    c_msg_falha_drop_job_global  constant varchar2(200) := ''Erro ao dropar job '';',
'    c_msg_job_filho_criacao      constant varchar2(200) := ''Falha ao criar/habilitar job filho: '';',
'    c_msg_run_request_erro       constant varchar2(200) := ''Falha no RUN_REQUEST: '';',
unistr('    c_msg_req_nao_encontrada     constant varchar2(200) := ''Solicita\00E7\00E3o n\00E3o encontrada: '';'),
unistr('    c_msg_job_req_criacao_erro   constant varchar2(200) := ''Falha ao criar/habilitar job filho da solicita\00E7\00E3o '';'),
'    c_msg_ct_falha_nao_tratada   constant varchar2(200) := ''CT4|Falha nao tratada no fluxo do job filho'';',
'    -------------------------------------------------------------------',
'    -- Tipos internos',
'    -------------------------------------------------------------------',
'    type r_sched_cfg is record (',
'        id                 mae_sched_cfg.id%type,',
'        ativo              mae_sched_cfg.ativo%type,',
'        id_artefato        mae_sched_cfg.id_artefato%type,',
'        ind_paralelo       mae_sched_cfg.ind_paralelo%type,',
'        intervalo_segundos mae_sched_cfg.intervalo_segundos%type',
'    );',
'    -------------------------------------------------------------------',
unistr('    -- Utilit\00E1rios internos'),
'    -------------------------------------------------------------------',
'    function carregar_sched_cfg(',
'        p_id in number',
'    ) return r_sched_cfg',
'    is',
'        r_cfg r_sched_cfg;',
'    begin',
'        select',
'            id,',
'            ativo,',
'            id_artefato,',
'            ind_paralelo,',
'            intervalo_segundos',
'        into r_cfg',
'        from mae_sched_cfg',
'        where id = p_id;',
'        return r_cfg;',
'    exception',
'        when no_data_found then',
'            raise_application_error(',
'                -20001,',
'                c_msg_cfg_nao_encontrada || p_id',
'            );',
'    end carregar_sched_cfg;',
'    function fila_permite_paralelismo(',
'        p_ind_paralelo in char',
'    ) return boolean',
'    is',
'    begin',
'        return nvl(p_ind_paralelo, ''S'') = ''S'';',
'    end fila_permite_paralelismo;',
'    function gerar_nome_job_req(',
'        p_id_solicitacao in number',
'    ) return varchar2',
'    is',
'    begin',
'        return c_req_job_prefix || to_char(p_id_solicitacao);',
'    end gerar_nome_job_req;',
'    function existe_job(',
'        p_job_name in varchar2',
'    ) return boolean',
'    is',
'        l_dummy number;',
'    begin',
'        select 1',
'          into l_dummy',
'          from user_scheduler_jobs',
'         where job_name = upper(trim(p_job_name));',
'        return true;',
'    exception',
'        when no_data_found then',
'            return false;',
'    end existe_job;',
'    -------------------------------------------------------------------',
unistr('    -- Opera\00E7\00F5es p\00FAblicas \2013 Job principal da fila'),
'    -------------------------------------------------------------------',
'    function gerar_nome_job_fila(',
'        p_id_sched_cfg in number',
'    ) return varchar2',
'    is',
'    begin',
'        if p_id_sched_cfg is null then',
'            raise_application_error(',
'                -20010,',
unistr('                ''ID da configura\00E7\00E3o da fila n\00E3o informado'''),
'            );',
'        end if;',
'        return c_job_prefix || to_char(p_id_sched_cfg);',
'    end gerar_nome_job_fila;',
'    procedure criar_job_fila(',
'        p_id_sched_cfg in number',
'    )',
'    is',
'        r_cfg             r_sched_cfg;',
'        v_job_name        varchar2(128);',
'        v_repeat_interval varchar2(4000);',
'    begin',
'        r_cfg := carregar_sched_cfg(p_id_sched_cfg);',
'        if r_cfg.id_artefato is null then',
'            raise_application_error(',
'                -20011,',
'                c_msg_cfg_sem_artefato || p_id_sched_cfg',
'            );',
'        end if;',
'        if r_cfg.intervalo_segundos is null or r_cfg.intervalo_segundos <= 0 then',
'            raise_application_error(',
'                -20012,',
'                c_msg_intervalo_invalido || p_id_sched_cfg',
'            );',
'        end if;',
'        v_job_name := gerar_nome_job_fila(p_id_sched_cfg);',
'        begin',
'            if existe_job(v_job_name) then',
'                dbms_scheduler.drop_job(',
'                    job_name => v_job_name,',
'                    force    => true',
'                );',
'            end if;',
'        exception',
'            when others then',
'                raise_application_error(',
'                    -20013,',
'                    c_msg_falha_dropar_job_fila || p_id_sched_cfg || '': '' || substr(sqlerrm, 1, 3000)',
'                );',
'        end;',
'        v_repeat_interval := ''FREQ=SECONDLY;INTERVAL='' || r_cfg.intervalo_segundos;',
'        dbms_scheduler.create_job(',
'            job_name            => v_job_name,',
'            job_type            => ''STORED_PROCEDURE'',',
'            job_action          => ''PKG_MAESTRO_WORKER_RUN.RUN_ONCE'',',
'            number_of_arguments => 1,',
'            start_date          => systimestamp,',
'            repeat_interval     => v_repeat_interval,',
'            enabled             => false,',
'            auto_drop           => false,',
'            comments            => ''Job principal da fila cfg='' || r_cfg.id ||',
'                                   '', artefato='' || r_cfg.id_artefato',
'        );',
'        dbms_scheduler.set_job_argument_value(',
'            job_name          => v_job_name,',
'            argument_position => 1,',
'            argument_value    => to_char(r_cfg.id)',
'        );',
'        if r_cfg.ativo = ''S'' then',
'            dbms_scheduler.enable(v_job_name);',
'        end if;',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20014,',
'                c_msg_falha_criar_job_fila || p_id_sched_cfg || '': '' || substr(sqlerrm, 1, 3000)',
'            );',
'    end criar_job_fila;',
'    procedure parar_job_fila(',
'        p_id_sched_cfg in number,',
'        p_force        in boolean default false',
'    )',
'    is',
'        v_job_name varchar2(128);',
'    begin',
'        v_job_name := gerar_nome_job_fila(p_id_sched_cfg);',
'        dbms_scheduler.disable(',
'            name  => v_job_name,',
'            force => p_force',
'        );',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20015,',
'                c_msg_falha_parar_job_fila || p_id_sched_cfg || '': '' || substr(sqlerrm, 1, 3000)',
'            );',
'    end parar_job_fila;',
'    procedure executar_job_fila(',
'        p_id_sched_cfg        in number,',
'        p_use_current_session in boolean default false',
'    )',
'    is',
'        v_job_name varchar2(128);',
'    begin',
'        if p_use_current_session then',
'            run_once(',
'                p_id_sched_cfg => p_id_sched_cfg',
'            );',
'            return;',
'        end if;',
'        v_job_name := gerar_nome_job_fila(p_id_sched_cfg);',
'        dbms_scheduler.run_job(',
'            job_name            => v_job_name,',
'            use_current_session => false',
'        );',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20016,',
'                c_msg_falha_executar_job || p_id_sched_cfg || '': '' || substr(sqlerrm, 1, 3000)',
'            );',
'    end executar_job_fila;',
'    procedure dropar_job_fila(',
'        p_id_sched_cfg in number,',
'        p_force        in boolean default true',
'    )',
'    is',
'        v_job_name varchar2(128);',
'    begin',
'        v_job_name := gerar_nome_job_fila(p_id_sched_cfg);',
'        dbms_scheduler.drop_job(',
'            job_name => v_job_name,',
'            force    => p_force',
'        );',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20017,',
'                c_msg_falha_dropar_job_fila || p_id_sched_cfg || '': '' || substr(sqlerrm, 1, 3000)',
'            );',
'    end dropar_job_fila;',
'    -------------------------------------------------------------------',
unistr('    -- Job ef\00EAmero da solicita\00E7\00E3o'),
'    -------------------------------------------------------------------',
'    procedure criar_job_execucao(',
'        p_id_solicitacao in number',
'    )',
'    is',
'        v_job_name varchar2(128);',
'    begin',
'        v_job_name := gerar_nome_job_req(p_id_solicitacao);',
'        begin',
'            if existe_job(v_job_name) then',
'                dbms_scheduler.drop_job(',
'                    job_name => v_job_name,',
'                    force    => true',
'                );',
'            end if;',
'        exception',
'            when others then',
'                null;',
'        end;',
'        -- raise_application_error(-20088, c_msg_ct_falha_nao_tratada);',
'        dbms_scheduler.create_job(',
'            job_name            => v_job_name,',
'            job_type            => ''STORED_PROCEDURE'',',
'            job_action          => ''PKG_MAESTRO_WORKER_RUN.RUN_REQUEST'',',
'            number_of_arguments => 1,',
'            start_date          => systimestamp,',
'            enabled             => false,',
'            auto_drop           => true,',
'            comments            => ''Execucao efemera da solicitacao '' || p_id_solicitacao',
'        );',
'        dbms_scheduler.set_job_argument_value(',
'            job_name          => v_job_name,',
'            argument_position => 1,',
'            argument_value    => to_char(p_id_solicitacao)',
'        );',
'        dbms_scheduler.enable(v_job_name);',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20041,',
'                c_msg_job_req_criacao_erro || p_id_solicitacao || '': '' || substr(sqlerrm, 1, 3500)',
'            );',
'    end criar_job_execucao;',
'    -------------------------------------------------------------------',
unistr('    -- Execu\00E7\00E3o da solicita\00E7\00E3o'),
'    -------------------------------------------------------------------',
'    procedure run_request(',
'        p_id_solicitacao in number',
'    )',
'    is',
'        v_resultado varchar2(4000);',
'        v_detalhes  varchar2(4000);',
'        v_erro      varchar2(4000);',
'        v_tenant    number;',
'        v_corr      varchar2(64);',
'    begin',
'        begin        ',
'            pkg_maestro_worker.executar_artefato(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_resultado      => v_resultado,',
'                p_detalhes       => v_detalhes',
'            );',
'            pkg_maestro_worker.finalizar_execucao(',
'                p_id_solicitacao => p_id_solicitacao,',
'                p_resultado      => v_resultado,',
'                p_detalhes       => v_detalhes',
'            );',
'            commit;',
'        exception',
'            when others then',
'                v_erro := substr(sqlerrm, 1, 4000);',
'                begin',
'                    select id_tenant, id_correlation',
'                      into v_tenant, v_corr',
'                      from mae_solicitacao_execucao',
'                     where id = p_id_solicitacao;',
'                exception',
'                    when others then',
'                        v_tenant := null;',
'                        v_corr   := null;',
'                end;',
'                begin',
'                    insert into mae_registro_tecnico (',
'                        id_solicitacao,',
'                        id_worker,',
'                        dt_evento,',
'                        tipo_evento,',
'                        resultado,',
'                        detalhes,',
'                        id_tenant,',
'                        id_correlation',
'                    ) values (',
'                        p_id_solicitacao,',
'                        null,',
'                        sysdate,',
'                        c_evt_job_filho_erro,',
'                        c_res_falha_tecnica,',
'                        c_msg_run_request_erro || v_erro,',
'                        v_tenant,',
'                        v_corr',
'                    );',
'                exception',
'                    when others then',
'                        null;',
'                end;',
'                begin',
'                    pkg_maestro_worker.finalizar_execucao(',
'                        p_id_solicitacao => p_id_solicitacao,',
'                        p_resultado      => nvl(v_resultado, c_res_falha_tecnica),',
'                        p_detalhes       => v_erro',
'                    );',
'                    commit;',
'                exception',
'                    when others then',
'                        rollback;',
'                        raise;',
'                end;',
'        end;',
'    end run_request;',
'    -------------------------------------------------------------------',
unistr('    -- Execu\00E7\00E3o principal da fila'),
'    -------------------------------------------------------------------',
'    procedure run_once(',
'        p_id_sched_cfg in number',
'    )',
'    is',
'        r_cfg            r_sched_cfg;',
'        v_id_worker      number;',
'        v_id_mensagem    number;',
'        v_erro           varchar2(4000);',
'        v_tenant         number;',
'        v_corr           varchar2(64);',
'        v_qtd_processada number;',
'    begin',
'        r_cfg := carregar_sched_cfg(p_id_sched_cfg);',
'        if r_cfg.ativo = ''N'' then',
'            return;',
'        end if;',
'        if r_cfg.id_artefato is null then',
'            raise_application_error(',
'                -20002,',
'                c_msg_cfg_sem_artefato || p_id_sched_cfg',
'            );',
'        end if;',
'        v_id_worker := p_id_sched_cfg;',
'        pkg_maestro_worker.recuperar_travadas(r_cfg.id_artefato,v_qtd_processada);',
'        pkg_maestro_worker.reservar_pendente(',
'            p_id_worker   => v_id_worker,',
'            p_id_artefato => r_cfg.id_artefato,',
'            p_id_mensagem => v_id_mensagem',
'        );',
'        if v_id_mensagem is null then',
'            return;',
'        end if;',
'        if fila_permite_paralelismo(r_cfg.ind_paralelo) then',
'            begin',
'                criar_job_execucao(',
'                    p_id_solicitacao => v_id_mensagem',
'                );',
'            exception',
'                when others then',
'                    v_erro := substr(sqlerrm, 1, 4000);',
'                    begin',
'                        select id_tenant, id_correlation',
'                          into v_tenant, v_corr',
'                          from mae_solicitacao_execucao',
'                         where id = v_id_mensagem;',
'                    exception',
'                        when others then',
'                            v_tenant := null;',
'                            v_corr   := null;',
'                    end;',
'                    begin',
'                        insert into mae_registro_tecnico (',
'                            id_solicitacao,',
'                            id_worker,',
'                            dt_evento,',
'                            tipo_evento,',
'                            resultado,',
'                            detalhes,',
'                            id_tenant,',
'                            id_correlation',
'                        ) values (',
'                            v_id_mensagem,',
'                            v_id_worker,',
'                            sysdate,',
'                            c_evt_job_filho_criacao_erro,',
'                            c_res_falha_tecnica,',
'                            c_msg_job_filho_criacao || v_erro,',
'                            v_tenant,',
'                            v_corr',
'                        );',
'                    exception',
'                        when others then',
'                            null;',
'                    end;',
'                    begin',
'                        pkg_maestro_worker.finalizar_execucao(',
'                            p_id_solicitacao => v_id_mensagem,',
'                            p_resultado      => c_res_falha_tecnica,',
'                            p_detalhes       => c_msg_job_filho_criacao || v_erro',
'                        );',
'                        commit;',
'                    exception',
'                        when others then',
'                            rollback;',
'                            raise;',
'                    end;',
'                    return;',
'            end;',
'        else',
'            run_request(',
'                p_id_solicitacao => v_id_mensagem',
'            );',
'        end if;',
'    exception',
'        when others then',
'            raise;',
'    end run_once;',
'    -------------------------------------------------------------------',
unistr('    -- Recria\00E7\00E3o global dos jobs principais das filas'),
'    -------------------------------------------------------------------',
'    procedure recriar_jobs(',
'        p_id       in srv_sistema_versionado.id%type default 0,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        p_sucesso := null;',
'        -----------------------------------------------------------------',
'        -- 1) Dropa apenas jobs principais das filas',
'        -----------------------------------------------------------------',
'        for r_job in (',
'            select job_name',
'              from user_scheduler_jobs',
'             where job_name like c_job_prefix || ''%''',
'        ) loop',
'            begin',
'                dbms_scheduler.drop_job(',
'                    job_name => r_job.job_name,',
'                    force    => true',
'                );',
'            exception',
'                when others then',
'                    raise_application_error(',
'                        -20031,',
'                        c_msg_falha_drop_job_global || r_job.job_name || '': '' || sqlerrm',
'                    );',
'            end;',
'        end loop;',
'        -----------------------------------------------------------------',
'        -- 2) Recria um job principal por linha da MAE_SCHED_CFG',
'        -----------------------------------------------------------------',
'        for r_cfg in (',
'            select id',
'              from mae_sched_cfg',
'             where id_artefato is not null',
'        ) loop',
'            criar_job_fila(',
'                p_id_sched_cfg => r_cfg.id',
'            );',
'        end loop;',
'        p_sucesso := ''S'';',
'    end recriar_jobs;',
'    function detalhe_registro (',
'        p_id in mae_sched_cfg.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(',
'            ''select',
'                id                as mae_sched_cfg$id',
'             from mae_sched_cfg',
'             where id = '' || p_id',
'        );',
'    end detalhe_registro;    ',
'',
'    procedure parar_job_execucao(',
'        p_id_solicitacao in number,',
'        p_force          in boolean default true,',
'        p_dropar         in boolean default true',
'    )',
'    is',
'        v_job_name      varchar2(128);',
'        v_status        mae_solicitacao_execucao.status%type;',
'        v_tenant        mae_solicitacao_execucao.id_tenant%type;',
'        v_corr          mae_solicitacao_execucao.id_correlation%type;',
'        v_id_worker     mae_solicitacao_execucao.id_worker%type;',
'        v_detalhes      varchar2(4000);',
'        v_existe_job    number;',
'    begin',
'        -- if p_id_solicitacao is null then',
'        --     return;',
'        -- end if;',
'',
'        v_job_name := gerar_nome_job_req(p_id_solicitacao);',
'        if not existe_job(v_job_name) then',
'            return;',
'        end if;',
'',
'        -- begin',
'        --     dbms_scheduler.stop_job(',
'        --         job_name => v_job_name,',
'        --         force    => p_force',
'        --     );',
'        -- exception',
'        --     when others then',
'        --         null;',
'        -- end;',
'',
'        if p_dropar then',
'            select count(1) into v_existe_job from user_scheduler_jobs where upper(job_name) = upper(v_job_name);',
'            if v_existe_job > 0 then',
'                dbms_scheduler.drop_job(',
'                    job_name => v_job_name,',
'                    force    => true',
'                );',
'            end if;',
'        end if;',
'',
'        begin',
'            select status,',
'                   id_tenant,',
'                   id_correlation,',
'                   id_worker',
'              into v_status,',
'                   v_tenant,',
'                   v_corr,',
'                   v_id_worker',
'              from mae_solicitacao_execucao',
'             where id = p_id_solicitacao',
'               for update;',
'        exception',
'            when no_data_found then',
'                return;',
'        end;',
'',
'        if v_status <> ''EM_PROCESSAMENTO'' then',
'            return;',
'        end if;',
'',
'        update mae_solicitacao_execucao',
'           set status       = ''ERRO_FINAL'',',
'               dt_fim       = sysdate,',
'               motivo_falha = ''Execucao interrompida manualmente'',',
'               id_worker    = null,',
'               dt_saude     = null',
'         where id = p_id_solicitacao',
'           and status = ''EM_PROCESSAMENTO'';',
'',
'        if sql%rowcount <> 1 then',
'            return;',
'        end if;',
'',
'        v_detalhes := substr(',
'            ''job_name='' || v_job_name ||',
'            ''; force='' || case when p_force then ''S'' else ''N'' end ||',
'            ''; dropar='' || case when p_dropar then ''S'' else ''N'' end ||',
'            ''; status_anterior='' || v_status ||',
'            ''; status_novo=ERRO_FINAL'' ||',
'            ''; id_worker_anterior='' || nvl(to_char(v_id_worker), ''<null>'') ||',
'            ''; motivo=Execucao interrompida manualmente'',',
'            1,',
'            4000',
'        );',
'',
'        pkg_maestro_evento.registrar_evento(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_worker      => v_id_worker,',
'            p_id_tenant      => v_tenant,',
'            p_id_correlation => v_corr,',
'            p_tipo_evento    => c_evt_execucao_parada_manual,',
'            p_resultado      => ''INFO'',',
'            p_detalhes       => v_detalhes',
'        );',
'        commit;',
'    end parar_job_execucao;    ',
'',
'    procedure parar_job_execucao(',
'        p_id             in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table       ',
'    )is ',
'    begin',
'        parar_job_execucao(',
'            p_id_solicitacao => p_id,',
'            p_force          => true,',
'            p_dropar         => true',
'        );',
'    end;',
'',
'end pkg_maestro_worker_run;',
'/'))
);
end;
/
