'        p_cb_falhas_consecutivas out srv_artefato_cfg.cb_falhas_consecutivas%type,',
'        p_cb_dt_ultima_falha out srv_artefato_cfg.cb_dt_ultima_falha%type,',
'        p_cb_dt_abertura out srv_artefato_cfg.cb_dt_abertura%type,',
'        p_cb_ind_teste_em_andamento out srv_artefato_cfg.cb_ind_teste_em_andamento%type,',
'        p_estrategia_retry out srv_artefato_cfg.estrategia_retry%type,',
'        p_ttl_pendente_seg out srv_artefato_cfg.ttl_pendente_seg%type,',
'        p_ttl_processando_seg out srv_artefato_cfg.ttl_processando_seg%type,',
'        p_sla_fila_seg out srv_artefato_cfg.sla_fila_seg%type,',
'        p_ind_coalescencia out srv_artefato_cfg.ind_coalescencia%type,',
'        p_modo_bloqueio_falha out srv_artefato_cfg.modo_bloqueio_falha%type,',
'        p_plsql_entrypoint out srv_artefato_cfg.plsql_entrypoint%type,',
'        p_max_payload_bytes out srv_artefato_cfg.max_payload_bytes%type, ',
'        p_id in out srv_artefato_cfg.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_srv_artefato_cfg'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_artefato_cfg.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_artefato,',
'            ind_execucao_assincrona,',
'            prioridade_padrao,',
'            delay_execucao_seg,',
'            max_tentativas,',
'            retry_base_seg,',
'            retry_max_seg,',
'            ind_circuit_breaker,',
'            cb_qtd_falhas_abertura,',
'            cb_cooldown_seg,',
'            cb_estado,',
'            cb_falhas_consecutivas,',
'            cb_dt_ultima_falha,',
'            cb_dt_abertura,',
'            cb_ind_teste_em_andamento,',
'            estrategia_retry,',
'            ttl_pendente_seg,',
'            ttl_processando_seg,',
'            sla_fila_seg,',
'            ind_coalescencia,',
'            modo_bloqueio_falha,',
'            plsql_entrypoint,',
'            max_payload_bytes, ',
'            id ',
'            into ',
'            p_id_artefato,',
'            p_ind_execucao_assincrona,',
'            p_prioridade_padrao,',
'            p_delay_execucao_seg,',
'            p_max_tentativas,',
'            p_retry_base_seg,',
'            p_retry_max_seg,',
'            p_ind_circuit_breaker,',
'            p_cb_qtd_falhas_abertura,',
'            p_cb_cooldown_seg,',
'            p_cb_estado,',
'            p_cb_falhas_consecutivas,',
'            p_cb_dt_ultima_falha,',
'            p_cb_dt_abertura,',
'            p_cb_ind_teste_em_andamento,',
'            p_estrategia_retry,',
'            p_ttl_pendente_seg,',
'            p_ttl_processando_seg,',
'            p_sla_fila_seg,',
'            p_ind_coalescencia,',
'            p_modo_bloqueio_falha,',
'            p_plsql_entrypoint,',
'            p_max_payload_bytes, ',
'            p_id ',
'        from srv_artefato_cfg ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_srv_artefato_cfg'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_srv_artefato_cfg'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in srv_artefato_cfg.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_srv_artefato_cfg'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_artefato_cfg.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from srv_artefato_cfg where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from srv_artefato_cfg where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_srv_artefato_cfg'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_srv_artefato_cfg'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_srv_artefato_cfg'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in srv_artefato_cfg.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from srv_artefato_cfg where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in srv_artefato_cfg.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from srv_artefato_cfg where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in srv_artefato_cfg.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''srv_artefato_cfg'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''srv_artefato_cfg'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in srv_artefato_cfg.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_artefato */ '),
'        valida_id_artefato(v_new.id_artefato);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_execucao_assincrona */ '),
'        valida_ind_execucao_assincrona(v_new.ind_execucao_assincrona);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo prioridade_padrao */ '),
'        valida_prioridade_padrao(v_new.prioridade_padrao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo delay_execucao_seg */ '),
'        valida_delay_execucao_seg(v_new.delay_execucao_seg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo max_tentativas */ '),
'        valida_max_tentativas(v_new.max_tentativas);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo retry_base_seg */ '),
'        valida_retry_base_seg(v_new.retry_base_seg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo retry_max_seg */ '),
'        valida_retry_max_seg(v_new.retry_max_seg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_circuit_breaker */ '),
'        valida_ind_circuit_breaker(v_new.ind_circuit_breaker);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cb_qtd_falhas_abertura */ '),
'        valida_cb_qtd_falhas_abertura(v_new.cb_qtd_falhas_abertura);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cb_cooldown_seg */ '),
'        valida_cb_cooldown_seg(v_new.cb_cooldown_seg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cb_estado */ '),
'        valida_cb_estado(v_new.cb_estado);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cb_falhas_consecutivas */ '),
'        valida_cb_falhas_consecutivas(v_new.cb_falhas_consecutivas);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cb_dt_ultima_falha */ '),
'        valida_cb_dt_ultima_falha(v_new.cb_dt_ultima_falha);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cb_dt_abertura */ '),
'        valida_cb_dt_abertura(v_new.cb_dt_abertura);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cb_ind_teste_em_andamento */ '),
'        valida_cb_ind_teste_em_andamento(v_new.cb_ind_teste_em_andamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo estrategia_retry */ '),
'        valida_estrategia_retry(v_new.estrategia_retry);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ttl_pendente_seg */ '),
'        valida_ttl_pendente_seg(v_new.ttl_pendente_seg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ttl_processando_seg */ '),
'        valida_ttl_processando_seg(v_new.ttl_processando_seg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo sla_fila_seg */ '),
'        valida_sla_fila_seg(v_new.sla_fila_seg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_coalescencia */ '),
'        valida_ind_coalescencia(v_new.ind_coalescencia);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo modo_bloqueio_falha */ '),
'        valida_modo_bloqueio_falha(v_new.modo_bloqueio_falha);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo plsql_entrypoint */ '),
'        valida_plsql_entrypoint(v_new.plsql_entrypoint);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo max_payload_bytes */ '),
'        valida_max_payload_bytes(v_new.max_payload_bytes);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_artefato(p_id_artefato in srv_artefato_cfg.id_artefato%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_artefato is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_artefato_cfg.id_artefato''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_artefato'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from srv_artefato_cfg where lower(trim(id_artefato)) = lower(trim(p_id_artefato)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from srv_artefato_cfg where lower(trim(id_artefato)) = lower(trim(p_id_artefato)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_artefato_cfg.id_artefato'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''id_artefato'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_id_artefato(p_id_artefato);',
'    end valida_id_artefato;     ',
'',
'    procedure valida_ind_execucao_assincrona(p_ind_execucao_assincrona in srv_artefato_cfg.ind_execucao_assincrona%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_ind_execucao_assincrona is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_artefato_cfg.ind_execucao_assincrona''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''ind_execucao_assincrona'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_ind_execucao_assincrona(p_ind_execucao_assincrona);',
'    end valida_ind_execucao_assincrona;     ',
'',
'    procedure valida_prioridade_padrao(p_prioridade_padrao in srv_artefato_cfg.prioridade_padrao%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_prioridade_padrao is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_artefato_cfg.prioridade_padrao''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''prioridade_padrao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_prioridade_padrao(p_prioridade_padrao);',
'    end valida_prioridade_padrao;     ',
'',
'    procedure valida_delay_execucao_seg(p_delay_execucao_seg in srv_artefato_cfg.delay_execucao_seg%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_delay_execucao_seg is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_artefato_cfg.delay_execucao_seg''); ',
