unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_artefato_cfg'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_artefato_cfg'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_artefato_cfg'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_artefato_cfg'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_artefato_cfg'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_artefato_cfg'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in srv_artefato_cfg%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_artefato'', p_rec.id_artefato, true);',
'        apex_json.write(''ind_execucao_assincrona'', p_rec.ind_execucao_assincrona, true);',
'        apex_json.write(''prioridade_padrao'', p_rec.prioridade_padrao, true);',
'        apex_json.write(''delay_execucao_seg'', p_rec.delay_execucao_seg, true);',
'        apex_json.write(''max_tentativas'', p_rec.max_tentativas, true);',
'        apex_json.write(''retry_base_seg'', p_rec.retry_base_seg, true);',
'        apex_json.write(''retry_max_seg'', p_rec.retry_max_seg, true);',
'        apex_json.write(''ind_circuit_breaker'', p_rec.ind_circuit_breaker, true);',
'        apex_json.write(''cb_qtd_falhas_abertura'', p_rec.cb_qtd_falhas_abertura, true);',
'        apex_json.write(''cb_cooldown_seg'', p_rec.cb_cooldown_seg, true);',
'        apex_json.write(''cb_estado'', p_rec.cb_estado, true);',
'        apex_json.write(''cb_falhas_consecutivas'', p_rec.cb_falhas_consecutivas, true);',
'        apex_json.write(''cb_dt_ultima_falha'', p_rec.cb_dt_ultima_falha, true);',
'        apex_json.write(''cb_dt_abertura'', p_rec.cb_dt_abertura, true);',
'        apex_json.write(''cb_ind_teste_em_andamento'', p_rec.cb_ind_teste_em_andamento, true);',
'        apex_json.write(''estrategia_retry'', p_rec.estrategia_retry, true);',
'        apex_json.write(''ttl_pendente_seg'', p_rec.ttl_pendente_seg, true);',
'        apex_json.write(''ttl_processando_seg'', p_rec.ttl_processando_seg, true);',
'        apex_json.write(''sla_fila_seg'', p_rec.sla_fila_seg, true);',
'        apex_json.write(''ind_coalescencia'', p_rec.ind_coalescencia, true);',
'        apex_json.write(''modo_bloqueio_falha'', p_rec.modo_bloqueio_falha, true);',
'        apex_json.write(''plsql_entrypoint'', p_rec.plsql_entrypoint, true);',
'        apex_json.write(''max_payload_bytes'', p_rec.max_payload_bytes, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
