'        p_ativo out mae_admin_operador.ativo%type,',
'        p_id_usuario out mae_admin_operador.id_usuario%type,',
'        p_perfil out mae_admin_operador.perfil%type,',
'        p_observacao out mae_admin_operador.observacao%type, ',
'        p_id in out mae_admin_operador.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
