'    procedure hook_valida_id_usuario(p_id_usuario in mae_admin_operador.id_usuario%type); ',
'    procedure hook_valida_perfil(p_perfil in mae_admin_operador.perfil%type); ',
'    procedure hook_valida_observacao(p_observacao in mae_admin_operador.observacao%type); ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
