 p_id=>wwv_flow_imp.id(16264184713874547)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'ct count(1) into l_verifica_valor_unico from mae_admin_operador where lower(trim(id_usuario)) = lower(trim(p_id_usuario)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from mae_admin_operador where lower(trim(id_usuario)) = lower(trim(p_id_usuario)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_admin_operador.id_usuario'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''id_usuario'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
