'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_id_usuario(p_id_usuario);',
'    end valida_id_usuario;     ',
'',
'    procedure valida_perfil(p_perfil in mae_admin_operador.perfil%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_perfil is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_admin_operador.perfil''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''perfil'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_perfil(p_perfil);',
'    end valida_perfil;     ',
'',
'    procedure valida_observacao(p_observacao in mae_admin_operador.observacao%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_observacao is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_admin_operador.observacao''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_observacao(p_observacao);',
'    end valida_observacao;    ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
'    procedure hook_valida_ativo(p_ativo in mae_admin_operador.ativo%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ativo;     ',
'',
'    procedure hook_valida_id_usuario(p_id_usuario in mae_admin_operador.id_usuario%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_usuario;     ',
'',
'    procedure hook_valida_perfil(p_perfil in mae_admin_operador.perfil%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_perfil;     ',
'',
'    procedure hook_valida_observacao(p_observacao in mae_admin_operador.observacao%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_observacao;     ',
'',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''mae_admin_operador'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mae_admin_operador'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''mae_admin_operador'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mae_admin_operador'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''mae_admin_operador'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mae_admin_operador'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in mae_admin_operador%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''ativo'', p_rec.ativo, true);',
'        apex_json.write(''id_usuario'', p_rec.id_usuario, true);',
'        apex_json.write(''perfil'', p_rec.perfil, true);',
'        apex_json.write(''observacao'', p_rec.observacao, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    function detalhe_registro (',
'        p_id in mae_admin_operador.id%type    ',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select ',
'                b.nome as mae_admin_operador$id_usuario',
'            from mae_admin_operador a',
'            join mpd_usuario b on b.id = a.id_usuario',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_mae_admin_operador;',
'/'))
);
end;
