unistr('            p_ds_mensagem => ''In\00EDcio da inclus\00E3o de registro'''),
'        );',
'        v_parametro(0) := ''bo_mae_sched_cfg.inclui_registro'';   ',
'        v_pagina := p_pagina; ',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.intervalo_segundos := p_intervalo_segundos;',
'        v_new.ind_paralelo := p_ind_paralelo;',
'        v_new.ativo := p_ativo;',
