'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_intervalo_segundos(p_intervalo_segundos);',
'    end valida_intervalo_segundos;     ',
'',
'    procedure valida_ind_paralelo(p_ind_paralelo in mae_sched_cfg.ind_paralelo%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_ind_paralelo is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_sched_cfg.ind_paralelo''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''ind_paralelo'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_ind_paralelo(p_ind_paralelo);',
'    end valida_ind_paralelo;     ',
'',
'    procedure valida_ativo(p_ativo in mae_sched_cfg.ativo%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_ativo is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_sched_cfg.ativo''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''ativo'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_ativo(p_ativo);',
'    end valida_ativo;     ',
'',
'    procedure valida_id_artefato(p_id_artefato in mae_sched_cfg.id_artefato%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_artefato is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_sched_cfg.id_artefato''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_artefato'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from mae_sched_cfg where lower(trim(id_artefato)) = lower(trim(p_id_artefato)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from mae_sched_cfg where lower(trim(id_artefato)) = lower(trim(p_id_artefato)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_sched_cfg.id_artefato'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''id_artefato'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_id_artefato(p_id_artefato);',
'    end valida_id_artefato;     ',
'',
'    procedure valida_ind_sincronizar(p_ind_sincronizar in mae_sched_cfg.ind_sincronizar%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_ind_sincronizar is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mae_sched_cfg.ind_sincronizar''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''ind_sincronizar'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_ind_sincronizar(p_ind_sincronizar);',
'    end valida_ind_sincronizar;     ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
'    procedure hook_valida_intervalo_segundos(p_intervalo_segundos in mae_sched_cfg.intervalo_segundos%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_intervalo_segundos;     ',
'',
'    procedure hook_valida_ind_paralelo(p_ind_paralelo in mae_sched_cfg.ind_paralelo%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ind_paralelo;     ',
'',
'    procedure hook_valida_ativo(p_ativo in mae_sched_cfg.ativo%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ativo;     ',
'',
'    procedure hook_valida_id_artefato(p_id_artefato in mae_sched_cfg.id_artefato%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_artefato;     ',
'',
'    procedure hook_valida_ind_sincronizar(p_ind_sincronizar in mae_sched_cfg.ind_sincronizar%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ind_sincronizar;     ',
'',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''mae_sched_cfg'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mae_sched_cfg'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''mae_sched_cfg'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mae_sched_cfg'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''mae_sched_cfg'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mae_sched_cfg'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in mae_sched_cfg%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''intervalo_segundos'', p_rec.intervalo_segundos, true);',
'        apex_json.write(''ind_paralelo'', p_rec.ind_paralelo, true);',
'        apex_json.write(''ativo'', p_rec.ativo, true);',
'        apex_json.write(''id_artefato'', p_rec.id_artefato, true);',
'        apex_json.write(''ind_sincronizar'', p_rec.ind_sincronizar, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    procedure inclui_registro_sincronizacao(  ',
'        p_intervalo_segundos in mae_sched_cfg.intervalo_segundos%type,',
'        p_ind_paralelo in mae_sched_cfg.ind_paralelo%type,',
'        p_ativo in mae_sched_cfg.ativo%type,',
'        p_id_artefato in mae_sched_cfg.id_artefato%type, ',
'        p_ind_sincronizar in mae_sched_cfg.ind_sincronizar%type, ',
'        p_id out mae_sched_cfg.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        v_operacao := ''SINCRONIZACAO'';',
'        inclui_registro(',
'            p_intervalo_segundos => p_intervalo_segundos,',
'            p_ind_paralelo => p_ind_paralelo,',
'            p_ativo => p_ativo,',
'            p_id_artefato => p_id_artefato,',
'            p_ind_sincronizar => p_ind_sincronizar, ',
'            p_id => p_id,',
'            p_pagina => p_pagina,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    procedure altera_registro_sincronizacao(  ',
'        p_intervalo_segundos in mae_sched_cfg.intervalo_segundos%type,',
'        p_ind_paralelo in mae_sched_cfg.ind_paralelo%type,',
'        p_ativo in mae_sched_cfg.ativo%type,',
'        p_id_artefato in mae_sched_cfg.id_artefato%type, ',
'        p_ind_sincronizar in mae_sched_cfg.ind_sincronizar%type, ',
'        p_id in mae_sched_cfg.id%type, ',
'        p_data_alteracao in mae_sched_cfg.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        v_operacao := ''SINCRONIZACAO'';',
'        altera_registro(',
'            p_intervalo_segundos => p_intervalo_segundos,',
'            p_ind_paralelo => p_ind_paralelo,',
'            p_ativo => p_ativo,',
'            p_id_artefato => p_id_artefato,',
'            p_ind_sincronizar => p_ind_sincronizar, ',
'            p_id => p_id,',
'            p_data_alteracao => p_data_alteracao,',
'            p_pagina => p_pagina,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'    --',
'    function verifica_registro_artefato( ',
'        p_id_artefato in mae_sched_cfg.id_artefato%type ',
'    ) return number is ',
'        l_existe_registro number; ',
'        l_id number; ',
'    begin ',
'        select count(1) into l_existe_registro from mae_sched_cfg where id_artefato = p_id_artefato; ',
'        if l_existe_registro > 0 then',
'            select id into l_id from mae_sched_cfg where id_artefato = p_id_artefato; ',
'            return l_id;     ',
'        else',
'            return null;     ',
'        end if;',
'    end;',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        if v_operacao is null then',
'            pkg_maestro_admin.assert_permissao(',
'                p_operacao  => pkg_maestro_admin.c_oper_reprocessar_mensagem,',
'                p_id_tenant => null',
'            );',
'        end if;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_maestro_worker_run.criar_job_fila(v_new.id);',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        if v_operacao is null then',
'            pkg_maestro_admin.assert_permissao(',
'                p_operacao  => pkg_maestro_admin.c_oper_reprocessar_mensagem,',
'                p_id_tenant => null',
'            );',
'        end if;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_maestro_admin.assert_permissao(',
'            p_operacao  => pkg_maestro_admin.c_oper_reprocessar_mensagem,',
'            p_id_tenant => null',
'        );',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        commit;',
'        pkg_maestro_worker_run.dropar_job_fila(v_old.id);',
'    end; ',
'    --',
'    function detalhe_registro (',
'        p_id in mae_sched_cfg.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select',
'                b.nome_artefato as srv_artefato$nome_artefato',
'            from mae_sched_cfg a',
'            join srv_artefato b on b.id = a.id_artefato',
'            where a.id = ~''||p_id);',
'    end detalhe_registro; ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_mae_sched_cfg;',
'/'))
);
end;
/
