'        p_status in mae_solicitacao_execucao.status%type,',
'        p_chave_bloqueio in mae_solicitacao_execucao.chave_bloqueio%type,',
'        p_parametros in mae_solicitacao_execucao.parametros%type,',
'        p_conteudo in mae_solicitacao_execucao.conteudo%type,',
'        p_dt_inicio in mae_solicitacao_execucao.dt_inicio%type,',
'        p_dt_proxima_tentativa in mae_solicitacao_execucao.dt_proxima_tentativa%type,',
