'/',
'create or replace package body                      bo_mae_solicitacao_execucao ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out mae_solicitacao_execucao.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into mae_solicitacao_execucao (  ',
'            id_artefato,',
'            tipo_acao,',
'            chave_coalescencia,',
'            dt_fim,',
'            dt_expiracao,',
'            tentativas,',
'            id_correlation,',
'            dt_criacao,',
'            id_tenant,',
'            id_usuario,',
'            prioridade,',
'            motivo_falha,',
'            dt_disponibilidade,',
'            id_worker,',
'            status,',
'            chave_bloqueio,',
'            parametros,',
'            conteudo,',
'            dt_inicio,',
'            dt_proxima_tentativa,',
'            dt_saude,',
'            id_negocio,',
'            dt_disponivel_execucao, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_artefato,',
'            v_new.tipo_acao,',
'            v_new.chave_coalescencia,',
'            v_new.dt_fim,',
'            v_new.dt_expiracao,',
'            v_new.tentativas,',
'            v_new.id_correlation,',
'            v_new.dt_criacao,',
'            v_new.id_tenant,',
'            v_new.id_usuario,',
'            v_new.prioridade,',
'            v_new.motivo_falha,',
'            v_new.dt_disponibilidade,',
'            v_new.id_worker,',
'            v_new.status,',
'            v_new.chave_bloqueio,',
'            v_new.parametros,',
'            v_new.conteudo,',
'            v_new.dt_inicio,',
'            v_new.dt_proxima_tentativa,',
'            v_new.dt_saude,',
'            v_new.id_negocio,',
'            v_new.dt_disponivel_execucao, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in mae_solicitacao_execucao.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''In\00EDcio da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de alterar */ ',
'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'        --     ',
'        /* Executa update */ ',
'        update mae_solicitacao_execucao set  ',
'            id_artefato = v_new.id_artefato,',
'            tipo_acao = v_new.tipo_acao,',
'            chave_coalescencia = v_new.chave_coalescencia,',
'            dt_fim = v_new.dt_fim,',
'            dt_expiracao = v_new.dt_expiracao,',
'            tentativas = v_new.tentativas,',
'            id_correlation = v_new.id_correlation,',
'            dt_criacao = v_new.dt_criacao,',
'            id_tenant = v_new.id_tenant,',
'            id_usuario = v_new.id_usuario,',
'            prioridade = v_new.prioridade,',
'            motivo_falha = v_new.motivo_falha,',
'            dt_disponibilidade = v_new.dt_disponibilidade,',
'            id_worker = v_new.id_worker,',
'            status = v_new.status,',
'            chave_bloqueio = v_new.chave_bloqueio,',
'            parametros = v_new.parametros,',
'            conteudo = v_new.conteudo,',
'            dt_inicio = v_new.dt_inicio,',
'            dt_proxima_tentativa = v_new.dt_proxima_tentativa,',
'            dt_saude = v_new.dt_saude,',
'            id_negocio = v_new.id_negocio,',
'            dt_disponivel_execucao = v_new.dt_disponivel_execucao, ',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'        --',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''Fim da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_mae_solicitacao_execucao'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end grava;',
