'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_usuario'', p_rec.id_usuario, true);',
'        apex_json.write(''prioridade'', p_rec.prioridade, true);',
'        apex_json.write(''motivo_falha'', p_rec.motivo_falha, true);',
'        apex_json.write(''dt_disponibilidade'', p_rec.dt_disponibilidade, true);',
'        apex_json.write(''id_worker'', p_rec.id_worker, true);',
'        apex_json.write(''status'', p_rec.status, true);',
'        apex_json.write(''chave_bloqueio'', p_rec.chave_bloqueio, true);',
'        apex_json.write(''parametros'', p_rec.parametros, true);',
'        apex_json.write(''conteudo'', p_rec.conteudo, true);',
'        apex_json.write(''dt_inicio'', p_rec.dt_inicio, true);',
'        apex_json.write(''dt_proxima_tentativa'', p_rec.dt_proxima_tentativa, true);',
'        apex_json.write(''dt_saude'', p_rec.dt_saude, true);',
'        apex_json.write(''id_negocio'', p_rec.id_negocio, true);',
'        apex_json.write(''dt_disponivel_execucao'', p_rec.dt_disponivel_execucao, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
