unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_moeda_cotacao'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_moeda_cotacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_moeda_cotacao'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_moeda_cotacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_moeda_cotacao'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_moeda_cotacao'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in ng_moeda_cotacao%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_moeda_origem'', p_rec.id_moeda_origem, true);',
'        apex_json.write(''id_moeda_destino'', p_rec.id_moeda_destino, true);',
'        apex_json.write(''data_cotacao'', p_rec.data_cotacao, true);',
'        apex_json.write(''valor_taxa_compra'', p_rec.valor_taxa_compra, true);',
'        apex_json.write(''valor_taxa_venda'', p_rec.valor_taxa_venda, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        bo_ng_traducaotexto.exclui_registros(',
'            p_nome_entidade => ''ng_moeda'',',
'            p_id_origem => v_old.id,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end; ',
'    --',
unistr('    -- Fun\00E7\00F5es complementares'),
'    --',
'    function detalhe_registro (',
'        p_id in ng_moeda_cotacao.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(',
'            q''~select',
'                d.nome_fantasia as ng_moeda_cotacao$id_tenant, ',
'                b.codigo_moeda || '' - '' || pkg_traducao.get_traducao(b.descricao_moeda) as ng_moeda_cotacao$id_moeda_origem,',
'                c.codigo_moeda || '' - '' || pkg_traducao.get_traducao(c.descricao_moeda) as ng_moeda_cotacao$id_moeda_destino, ',
'                to_char(a.data_cotacao, ''dd/mm/yyyy'') as ng_moeda_cotacao$data_cotacao,',
'                replace(to_char(a.valor_taxa_compra, ''FML999G999G999G999G990D000000''), ''R$'', '''') as ng_moeda_cotacao$valor_taxa_compra,',
'                replace(to_char(a.valor_taxa_venda, ''FML999G999G999G999G990D000000''), ''R$'', '''') as ng_moeda_cotacao$valor_taxa_venda ',
'            from ng_moeda_cotacao a ',
'            left join ng_moeda b on b.id = a.id_moeda_origem ',
'            left join mpd_tenant d on d.id = a.id_tenant',
'            left join ng_moeda c on c.id = a.id_moeda_destino ',
'            where a.id = ~''||p_id);',
'',
'    end detalhe_registro;',
'    --',
'    function retorna_cotacao_data(',
'        p_id_moeda_origem in ng_moeda_cotacao.id_moeda_origem%type,',
'        p_id_moeda_destino in ng_moeda_cotacao.id_moeda_destino%type default c_moeda_dolar,',
'        p_data_cotacao in ng_moeda_cotacao.data_cotacao%type default current_date',
'    ) return ng_moeda_cotacao.valor_taxa_compra%type is',
'        l_resultado ng_moeda_cotacao.valor_taxa_compra%type;',
'    begin ',
'        if p_id_moeda_origem = p_id_moeda_destino then',
'            l_resultado := 1;',
'        else',
'            select ',
'                valor_taxa_compra ',
'            into',
'                l_resultado',
'            from ng_moeda_cotacao ',
'            where id_moeda_origem = p_id_moeda_origem',
'            and id_moeda_destino = p_id_moeda_destino',
'            and (to_date(to_char(data_cotacao, ''dd/mm/yyyy''), ''dd/mm/yyyy'') = to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'            or data_cotacao in (',
'                select max(data_cotacao) from ng_moeda_cotacao where id_moeda_origem = p_id_moeda_origem and id_moeda_destino = p_id_moeda_destino',
'            ))',
'            order by data_alteracao desc',
'            fetch first 1 row only;',
'        end if;',
'        return l_resultado;',
'        exception',
'            when no_data_found then',
'                return null;',
'            when others then',
'                raise_application_error(-20001, sqlerrm);',
'                --return null;',
'    end;',
'    --',
'    function retorna_cotacao_compra(',
'        p_id_tenant in ng_moeda_cotacao.id_tenant%type,',
'        p_id_moeda_origem in ng_moeda_cotacao.id_moeda_origem%type,',
'        p_id_moeda_destino in ng_moeda_cotacao.id_moeda_destino%type',
'    ) return number is',
'        l_cotacao t_cotacao;',
'    begin',
'        select get_cotacao(p_id_tenant, p_id_moeda_origem, p_id_moeda_destino) into l_cotacao from dual;',
'',
'        return l_cotacao.valor_taxa_compra;',
'    end retorna_cotacao_compra;',
'    --',
'    function retorna_cotacao_venda(',
'        p_id_tenant in ng_moeda_cotacao.id_tenant%type,',
'        p_id_moeda_origem in ng_moeda_cotacao.id_moeda_origem%type,',
'        p_id_moeda_destino in ng_moeda_cotacao.id_moeda_destino%type',
'    ) return number is',
'        l_cotacao t_cotacao;',
'    begin',
'        select get_cotacao(p_id_tenant, p_id_moeda_origem, p_id_moeda_destino) into l_cotacao from dual;',
'',
'        return l_cotacao.valor_taxa_venda;',
'    end retorna_cotacao_venda;',
'    --',
'    function retorna_cotacao_data_cotacao(',
'        p_id_tenant in ng_moeda_cotacao.id_tenant%type,',
'        p_id_moeda_origem in ng_moeda_cotacao.id_moeda_origem%type,',
'        p_id_moeda_destino in ng_moeda_cotacao.id_moeda_destino%type',
'    ) return date is',
'        l_cotacao t_cotacao;',
'    begin',
'        select get_cotacao(p_id_tenant, p_id_moeda_origem, p_id_moeda_destino) into l_cotacao from dual;',
'',
'        return l_cotacao.data_cotacao;',
'    end retorna_cotacao_data_cotacao;',
'    --',
'procedure importar_cotacao_dia(',
'    p_id_usuario   in number,',
'    p_data_cotacao in date default trunc(sysdate)',
')',
'is',
'    l_compra number;',
'    l_venda  number;',
'    l_moeda_nao_existe boolean default false;',
'',
'    c_dias_retroativos constant number := 5;',
'',
'    procedure importar_data(',
'        p_data              in date,',
'        p_obrigatoria_retry in varchar2 default ''N''',
'    )',
'    is',
'    begin',
'        pkg_context.set_role(''SYSTEM_JOB'');',
'        for r_iso in (',
'            select distinct upper(simbolo_iso) simbolo_iso',
'              from ng_moeda',
'             where simbolo_iso is not null',
'               and upper(simbolo_iso) <> ''BRL''',
'               and (',
'                    data_fim_vigencia is null',
'                    or data_fim_vigencia >= trunc(p_data)',
'               )',
'             order by upper(simbolo_iso)',
'        )',
'        loop',
'            l_compra := null;',
'            l_venda  := null;',
'',
'            pkg_api_externa.buscar_ptax_moeda(',
'                p_simbolo_iso   => r_iso.simbolo_iso,',
'                p_data_cotacao  => trunc(p_data),',
'                p_valor_compra  => l_compra,',
'                p_valor_venda   => l_venda,',
'                p_moeda_nao_existe => l_moeda_nao_existe',
'            );',
'',
'            if not l_moeda_nao_existe then',
'                if l_compra is null then',
'                    if p_obrigatoria_retry = ''S'' then',
'                        raise_application_error(',
'                            pkg_maestro_worker.c_erro_falha_tecnica,',
'                            ''Nenhuma PTAX de fechamento encontrada para '' ||',
'                            r_iso.simbolo_iso ||',
'                            '' em '' || to_char(trunc(p_data), ''dd/mm/yyyy'')',
'                        );',
'                    else',
'                        grava_log2(',
unistr('                            ''PTAX n\00E3o encontrada para data retroativa. Moeda='' ||'),
'                            r_iso.simbolo_iso ||',
'                            '' Data='' || to_char(trunc(p_data), ''dd/mm/yyyy'')',
'                        );',
'',
'                        continue;',
'                    end if;',
'                end if;',
'                ',
'',
'                merge into ng_moeda_cotacao dst',
'                using (',
'                    select t.id                  as id_tenant,',
'                           moeda_origem.id       as id_moeda_origem,',
'                           moeda_brl.id          as id_moeda_destino,',
'                           trunc(p_data)         as data_cotacao,',
'                           l_compra              as valor_taxa_compra,',
'                           l_venda               as valor_taxa_venda',
'                      from mpd_tenant t',
'                      join ng_moeda moeda_origem',
'                        on moeda_origem.id_tenant = t.id',
'                       and upper(moeda_origem.simbolo_iso) = r_iso.simbolo_iso',
'                       and upper(moeda_origem.simbolo_iso) <> ''BRL''',
'                       and (',
'                            moeda_origem.data_fim_vigencia is null',
'                            or moeda_origem.data_fim_vigencia >= trunc(p_data)',
'                       )',
'                      join ng_moeda moeda_brl',
'                        on moeda_brl.id_tenant = t.id',
'                       and upper(moeda_brl.simbolo_iso) = ''BRL''',
'                ) src',
'                on (',
'                    dst.id_tenant            = src.id_tenant',
'                    and dst.id_moeda_origem  = src.id_moeda_origem',
'                    and dst.id_moeda_destino = src.id_moeda_destino',
'                    and dst.data_cotacao     = src.data_cotacao',
'                )',
'                when matched then',
'                    update set',
'                        dst.valor_taxa_compra = src.valor_taxa_compra,',
'                        dst.valor_taxa_venda  = src.valor_taxa_venda,',
'                        dst.data_alteracao    = systimestamp',
'                when not matched then',
'                    insert (',
'                        id_tenant,',
'                        id_moeda_origem,',
'                        id_moeda_destino,',
'                        data_cotacao,',
'                        valor_taxa_compra,',
'                        valor_taxa_venda,',
'                        id_usuario_incluiu,',
'                        data_inclusao',
'                    )',
'                    values (',
'                        src.id_tenant,',
'                        src.id_moeda_origem,',
'                        src.id_moeda_destino,',
'                        src.data_cotacao,',
'                        src.valor_taxa_compra,',
'                        src.valor_taxa_venda,',
'                        p_id_usuario,',
'                        systimestamp',
'                    );',
'                commit;',
'            end if;',
'        end loop;',
'        pkg_context.set_role(NULL);',
'    end importar_data;',
'',
'begin',
'    for i in 1 .. c_dias_retroativos loop',
'        importar_data(',
'            p_data              => trunc(p_data_cotacao) - i,',
'            p_obrigatoria_retry => ''N''',
'        );',
'    end loop;',
'',
'    importar_data(',
'        p_data              => trunc(p_data_cotacao),',
'        p_obrigatoria_retry => ''S''',
'    );',
'end importar_cotacao_dia;',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_moeda_cotacao;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_api_externa
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16272980663782594)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_API_EXTERNA'
,p_sequence=>270
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_api_externa as',
'',
'    function moeda_disponivel_ptax(',
'        p_simbolo_iso in varchar2',
'    ) return boolean;',
'',
'    procedure buscar_ptax_moeda(',
'        p_simbolo_iso   in varchar2,',
'        p_data_cotacao  in date,',
'        p_valor_compra  out number,',
'        p_valor_venda   out number,',
'        p_moeda_nao_existe out boolean ',
'    );',
'',
'end pkg_api_externa;',
'/',
'create or replace package body pkg_api_externa as',
'',
'    function moeda_disponivel_ptax(',
'        p_simbolo_iso in varchar2',
'    ) return boolean',
'    is',
'        l_url      varchar2(4000);',
'        l_response clob;',
'        l_qtd      number;',
'    begin',
'        l_url :=',
'            ''https://olinda.bcb.gov.br/olinda/servico/PTAX/versao/v1/odata/'' ||',
'            ''Moedas?$top=100&$format=json'';',
'',
'        l_response := apex_web_service.make_rest_request(',
'            p_url         => l_url,',
'            p_http_method => ''GET''',
'        );',
'',
'        if apex_web_service.g_status_code <> 200 then',
'            raise_application_error(',
'                -20000,',
unistr('                ''FALHA_TECNICA | Erro ao consultar moedas dispon\00EDveis na PTAX. HTTP: '' ||'),
'                apex_web_service.g_status_code',
'            );',
'        end if;',
'',
'        select count(*)',
'          into l_qtd',
'          from json_table(',
'                 l_response,',
'                 ''$.value[*]''',
'                 columns (',
'                     simbolo varchar2(10) path ''$.simbolo''',
'                 )',
'               )',
'         where upper(simbolo) = upper(p_simbolo_iso);',
'',
'        return l_qtd > 0;',
'    end moeda_disponivel_ptax;',
'',
'    procedure buscar_ptax_moeda(',
'        p_simbolo_iso   in varchar2,',
'        p_data_cotacao  in date,',
'        p_valor_compra  out number,',
'        p_valor_venda   out number,',
'        p_moeda_nao_existe out boolean ',
'    )',
'    is',
'        l_url      varchar2(4000);',
'        l_response clob;',
'    begin',
'        p_moeda_nao_existe := false;',
'        p_valor_compra := null;',
'        p_valor_venda  := null;',
'',
'        if not moeda_disponivel_ptax(p_simbolo_iso) then',
'            p_moeda_nao_existe := true;',
'            return;',
'        end if;',
'',
'        l_url :=',
'            ''https://olinda.bcb.gov.br/olinda/servico/PTAX/versao/v1/odata/'' ||',
'            ''CotacaoMoedaDia(moeda=@moeda,dataCotacao=@dataCotacao)'' ||',
'            ''?@moeda='' || apex_util.url_encode('''''''' || upper(p_simbolo_iso) || '''''''') ||',
'            ''&@dataCotacao='' || apex_util.url_encode('''''''' || to_char(p_data_cotacao, ''mm-dd-yyyy'') || '''''''') ||',
'            ''&$format=json'';',
'',
'        l_response := apex_web_service.make_rest_request(',
'            p_url         => l_url,',
'            p_http_method => ''GET''',
'        );',
'',
'        if apex_web_service.g_status_code <> 200 then',
'            raise_application_error(',
'                -20000,',
'                ''FALHA_TECNICA | Erro ao consultar PTAX. Moeda: '' || p_simbolo_iso ||',
'                '' HTTP: '' || apex_web_service.g_status_code',
'            );',
'        end if;',
'',
'        select cotacao_compra,',
'               cotacao_venda',
'          into p_valor_compra,',
'               p_valor_venda',
'          from (',
'                select cotacao_compra,',
'                       cotacao_venda,',
'                       data_hora_cotacao,',
'                       tipo_boletim',
'                  from json_table(',
'                         l_response,',
'                         ''$.value[*]''',
'                         columns (',
'                             cotacao_compra    number        path ''$.cotacaoCompra'',',
'                             cotacao_venda     number        path ''$.cotacaoVenda'',',
'                             data_hora_cotacao varchar2(50)  path ''$.dataHoraCotacao'',',
'                             tipo_boletim      varchar2(50)  path ''$.tipoBoletim''',
'                         )',
'                       )',
'                 where upper(tipo_boletim) = ''FECHAMENTO PTAX''',
'                 order by data_hora_cotacao desc',
'               )',
'         fetch first 1 row only;',
'',
'        exception',
'            when no_data_found then',
'                null;',
'            when others then',
'                raise_application_error(',
'                    pkg_maestro_worker.c_erro_falha_tecnica,',
'                    ''Erro inesperado ao buscar PTAX de fechamento encontrada para '' ||',
'                    upper(p_simbolo_iso) ||',
'                    '' em '' || to_char(p_data_cotacao, ''dd/mm/yyyy'')',
'                );',
'',
'    end buscar_ptax_moeda;',
'',
'end pkg_api_externa;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_formulario_dinamico
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16281397121601260)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_FORMULARIO_DINAMICO'
,p_sequence=>290
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "PKG_FORMULARIO_DINAMICO" as',
'',
'',
'    c_template_attributes CONSTANT VARCHAR2(4000) := ',
'        ''coluna="#COLUNA#" '' ||',
'        ''#ID# '' ||',
'        ''class="#CLASSE#" '' ||',
'        ''placeholder="#PLACEHOLDER#" '' ||',
'        ''onchange="#ONCHANGE#" '' ||',
'        -- ''onload="#ONLOAD#" '' ||',
'        '' #ONLOAD# '' ||',
'        ''style="#STYLE#" '' ||',
'        ''#EXTRAPOP# '' ||',
'        ''#EXTRA#'';',
'',
'    c_textarea_linhas constant number := 5;',
'',
'    c_textarea_colunas constant number := 100;',
'',
'    c_formato_campo_decimal constant varchar2(2000) := ',
'    q''~  ',
'        $("##COLUNA#").inputmask({',
'          alias: "decimal",',
'          digits: #DECIMAL#,',
'          prefix: "#PREFIXO#",',
'          digitsOptional: false,',
'          groupSeparator: "#SEPARADOR_NUMERICO#",',
'          radixPoint: "#SEPARADOR_DECIMAL#",',
'          autoGroup: false,',
'          allowMinus: #NEGATIVO#,',
'          rightAlign: false,',
'          max: "#MASCARA#",',
'          onBeforeMask:function(maskedValue, unmaskedValue) {',
'            // Preserva o valor exato como string, ajustando separadores            ',
'            console.log(''onBeforeMask maskedValue:''+maskedValue);',
'            const valorTruncado = truncarDecimal(maskedValue, #DECIMAL#);',
'            console.log(''onBeforeMask valorTruncado:''+valorTruncado);',
'            return valorTruncado;         ',
'          }',
'        });',
'    ~''; ',
'',
'    c_registro_nao_encontrado constant varchar2(2000) := ',
'    q''~  ',
unistr('      <h1>Registro n\00E3o encontrado!</h1>'),
unistr('      <p>O registro que voc\00EA estava visualizando n\00E3o est\00E1 mais dispon\00EDvel. Ele pode ter sido exclu\00EDdo.</p>'),
'    ~''; ',
'    --   <i class="fa-solid fa-file-search" aria-hidden="true"></i>',
'',
'',
'    c_formato_campo_decimal3 constant varchar2(2000) := ',
'    q''~  ',
'        applyAutoNumericMask("##COLUNA#", #DECIMAL#, "#PREFIXO#", "#SEPARADOR_NUMERICO#", "#SEPARADOR_DECIMAL#", #NEGATIVO#, #INTEIROS#); ',
'    ~'';',
'',
'    c_formato_campo_texto constant varchar2(2000) := ',
'    q''~  ',
'         $("##COLUNA#").inputmask({',
'          mask: "#MASCARA#",',
unistr('          placeholder: "_",         // caractere exibido nos espa\00E7os vazios'),
'          showMaskOnHover: true,',
'          showMaskOnFocus: true,',
unistr('          clearIncomplete: false     // limpa se n\00E3o preencher tudo'),
'        });  ',
'    ~''; ',
'',
'    c_formato_campo_email constant varchar2(2000) := ',
'    q''~  ',
'        $("##COLUNA#").inputmask({ alias: "email"});',
'    ~''; ',
'',
'    c_formato_campo_data constant varchar2(2000) := ',
'    q''~  ',
'        setTimeout(function() {$("##COLUNA#_data_input").inputmask({alias: "datetime", placeholder: "_", inputFormat: "dd/MM/yyyy"});}, 300);',
'    ~''; ',
'',
'    c_formato_campo_data_hora constant varchar2(2000) := ',
'    q''~  ',
'        setTimeout(function() {$("##COLUNA#_datahora_input").inputmask({alias: "datetime",placeholder: "_",inputFormat: "dd/mm/yyyy HH:MM"});}, 300);',
'    ~''; ',
'',
'    c_formato_campo_texto_upper constant varchar2(2000) := ',
'    q''~  ',
'         $("##COLUNA#").inputmask({',
'          casing: "upper"     ',
'        });  ',
'    ~''; ',
'',
'    c_formato_campo_texto_lower constant varchar2(2000) := ',
'    q''~  ',
'         $("##COLUNA#").inputmask({',
'          casing: "lower"     ',
'        });  ',
'    ~''; ',
'',
'    c_html_item_icone constant clob := ',
'    q''~ ',
'        <span class="text_field apex-item-text fa #ICONE#"></span><br/>',
'    ~'';     ',
'',
'    c_tipo_campo constant varchar2(256) := ''t-Form-fieldContainer--floatingLabel''; ',
