'    procedure gerar_formulario(',
'        p_codigo_artefato in varchar2,',
'        p_id in number default null,',
'        p_visualizar in number default null, ',
'        p_html out clob,',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null',
'    );',
'',
'    function retorna_html_before(',
'        p_tipo in varchar2,',
'        p_nome_coluna in varchar2,',
'        p_label_coluna in varchar2,',
'        p_instrucao_coluna in varchar2 default '''',',
'        p_help_coluna in varchar2 default '''',',
'        p_oculto in varchar2 default '''',',
'        p_value in varchar2 default '''',',
'        p_ordem in varchar2 default '''',',
'        p_obrigatorio in varchar2 default ''''',
'    ) return varchar2;    ',
'',
'    function retorna_html_after_item(',
'        p_nome_coluna in varchar2,',
'        p_label_coluna in varchar2,',
'        p_help_coluna in varchar2',
'    ) return varchar2; ',
'',
'    function gerar_opcao_lov (',
'        p_tipo in varchar,',
'        p_coluna in varchar,',
'        p_lov_name in varchar2,  -- nome da lov',
'        p_contador in number,     -- contador para o apex_item.radiogroup',
'        p_valor_atual in varchar2 default null,',
'        funcao_dependencia varchar2 default null,',
'        funcao_dependenciaLoad varchar2 default null',
'        -- p_condicao in varchar2 default null, --TD3-68',
'        -- p_coluna_alvo in varchar2 default null, --TD3-68',
'        -- p_esconde_ou_desabilita in varchar2 default null --TD3-68         ',
'    ) return varchar2;',
'',
'    function list_opcao_lov (',
'        p_array in apex_application_global.vc_arr2',
'    ) return varchar2;',
'',
'    function campos_detalhes(',
'        p_sql in clob,',
'        p_label_fixo in varchar2 default ''n''',
'    ) return clob;    ',
'',
'    function retorna_mascara (',
'        p_edicao in varchar2',
'    ) return varchar2;',
'',
'    function monta_chamada_atribuiValor (',
'        p_json in clob,',
'        p_coluna varchar2 default '''' --no caso do load',
'    ) return CLOB;',
'',
'    function executa_sql_parametrizado (',
'        p_param1 in varchar2,',
'        p_sql    in clob',
'    ) return clob;',
'',
'    function gerar_p_attributes (',
'        p_tipo                        in varchar2,',
'        p_nome_coluna                 in varchar2,',
'        p_instrucao                   in varchar2 default null,',
'        p_funcao_onchange             in varchar2 default null,',
'        p_funcao_onload               in varchar2 default null,',
'        p_html_visualizar             in varchar2 default null',
'    ) return varchar2; ',
'',
