'        p_tipo                          in varchar2,',
'        p_nome_coluna                   in varchar2,',
'        p_formato_campo                 in varchar2 default '''',',
'        p_texto_funcao_dependeciaLoad   in varchar2 default '''',',
'        p_texto_funcao_executa_js       in varchar2 default '''',',
'        p_texto_funcao_atribuir_valor   in varchar2 default '''',',
'        p_texto_funcao_transformaElem   in varchar2 default ''''',
'    ) return clob;',
'',
'end "PKG_FORMULARIO_DINAMICO";',
'/',
'create or replace package body "PKG_FORMULARIO_DINAMICO" as',
'',
unistr('--Historico de altera\00E7\00E3o de fonte--'),
unistr('--Data: 14/07/2025 - Chamado: TD3-161 - Responsavel: Northonn Oliveira - Assunto: Alterar tipo de intera\00E7\00E3o( V\00EDsivel e Inv\00EDsivel) dinamicamente com condi\00E7\00E3o de outra entidade'),
'--Data: 21/07/2025 - Chamado: TD3-165 - Responsavel: Northonn Oliveira - Assunto: Permitir informar tag de coluna de outras tabelas nas UI do artefatos',
'',
'    procedure gerar_formulario(',
'        p_codigo_artefato in varchar2,',
'        p_id in number default null,        ',
'        p_visualizar in number default null, ',
'        p_html out clob,',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null        ',
'    ) is',
unistr('        -- defina as vari\00E1veis que correspondem ao select    '),
'        l_nome_coluna varchar2(256); l_indice number; l_tipo_interacao varchar2(10); l_nome_consulta_espec varchar2(4000);',
'        l_nome_consulta varchar2(4000); l_somente_leitura varchar2(1); l_coluna_tabela varchar(1); l_valor_param1 varchar2(32000);',
'        l_url_new varchar2(4000); l_url_zoom varchar2(4000); l_eh_coluna_obrigatoria varchar2(1) := ''N''; l_dependencia varchar2(2000); l_atribuir_valor clob;',
'        l_executa_js clob; l_calcular_valor clob; l_html_regiao clob; l_tag_campo varchar2(128);',
'',
unistr('        -- Vari\00E1veis relacionadas ao HTML e visualiza\00E7\00E3o:'),
'        c_cursor sys_refcursor; l_html clob := ''''; l_html_aux clob := ''''; l_html_visualizar varchar2(4000) := null; l_html_visualizar1 varchar2(4000) := null; ',
'',
unistr('        -- Vari\00E1veis relacionadas a valores de dados:'),
'        l_value varchar2(32000); l_arquivo blob; l_sql clob; l_item varchar2(4000); ',
'        l_tenant_idioma number;',
'',
unistr('        -- Vari\00E1veis de controle e intera\00E7\00E3o:'),
'        l_tipo_interacao_tabela varchar2(10);  ',
'        l_somente_leitura_l varchar2(10);',
'',
unistr('        -- Vari\00E1veis relacionadas a consultas:'),
'         l_nome_consulta_tabela varchar2(4000); ',
'        l_formato_campo varchar2(4000);',
'',
unistr('        -- Vari\00E1veis de identifica\00E7\00E3o e entidade:'),
'        l_id number; l_nome_entidade varchar2(256); l_tipo_funcionalidade varchar2(256);  ',
'        l_tipo_dado varchar2(16); l_label varchar2(256); l_instrucao varchar2(512); l_help varchar2(4000);',
'        l_edicao varchar2(16); l_id_artefato_versionado_novo number; l_id_artefato_versionado_zoom number; l_ind_negativo varchar2(1); l_ind_formato_texto varchar2(1);',
'',
unistr('        -- Vari\00E1veis auxiliares e contadores:'),
'        l_existe_formulario_especico number; ',
'',
'        --Dependencia entre colunas TD3-68',
'        l_id_coluna number;',
'        l_texto_funcao_executa_js clob;',
'        l_texto_funcao_atribuir_valor clob;',
'        l_texto_funcao_atribuir_valor_Load clob;',
'        l_texto_funcao_calcular_valor clob;',
'        l_texto_funcao_dependecia clob; ',
'        l_texto_funcao_dependeciaLoad clob;',
'        l_texto_funcao_dependeciaLoadOpc clob;',
'        l_texto_funcao_dependeciaSETNULL clob;',
'',
'        --TD3-149 Inicio',
'        l_condicao varchar2(256); l_coluna_alvo varchar2(256); l_comportamento varchar2(256);                 ',
'        l_campos_alvo varchar2(2000);',
'        l_attributes_completo clob;',
'        l_formula clob;',
'        l_texto_funcao_transformaElemento clob;',
'',
'        -- Tamanho: Quantidade de caracteres que podem ser informados no campo',
'        l_tamanho number;',
'        l_qtd_casas_descimais number;',
'        l_linha number;',
'        id_nao_existe exception;',
'',
'        procedure adicionar_dependencia (',
'            p_condicao      in varchar2,',
'            p_coluna_alvo   in varchar2,',
'            p_comportamento in varchar2',
'        ) is',
'        begin',
'            if lower(p_comportamento) = ''lim'' then',
'                l_texto_funcao_dependeciaSETNULL := ''setNull(this,'' || aspas(p_coluna_alvo) || '');'';',
'            else',
'                l_texto_funcao_dependecia := l_texto_funcao_dependecia ||',
