 p_id=>wwv_flow_imp.id(16281397121601260)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'm ||'' - Nome da coluna: '' || l_nome_consulta ||'' - Linha: '' || l_linha;',
'',
'    end gerar_formulario; ',
'',
'    function retorna_html_before(',
'        p_tipo in varchar2,',
'        p_nome_coluna in varchar2,',
'        p_label_coluna in varchar2,',
'        p_instrucao_coluna in varchar2 default '''',',
'        p_help_coluna in varchar2 default '''',',
'        p_oculto in varchar2 default '''',',
'        p_value in varchar2 default '''',',
'        p_ordem in varchar2 default '''',',
'        p_obrigatorio in varchar2',
'    ) return varchar2 is',
'        l_html clob;',
'    begin',
'        case p_tipo',
'            when ''TEX'' then l_html := c_html_before_item_areatext;',
'            when ''SEL'' then l_html := c_html_before_item_text;',
'            when ''POP'' then l_html := c_html_before_item_popup_pop;',
'            when ''POP1'' then l_html := c_html_before_item_popup_pop;',
'            when ''POPTEX'' then l_html := c_html_before_item_popup_pop;',
'            when ''POPTEX1'' then l_html := c_html_before_item_popup_pop;',
'            when ''RAD'' then l_html := c_html_before_item_radiogroup;   ',
'            when ''CHK'' then l_html := c_html_before_item_checkbox;               ',
'            when ''DAT'' then l_html := c_html_before_item_data;               ',
'            when ''DAH'' then l_html := c_html_before_item_datahora;               ',
'            when ''FIL'' then l_html := c_html_before_item_file;       ',
'            when ''LOV'' then l_html := ''Desativado'';                           ',
'            when ''HID'' then l_html := c_html_before_item_text;     ',
'            when ''SWI'' then l_html := c_html_before_item_text;     ',
'            when ''JSO'' then l_html := c_html_before_item_grid;     ',
'            when ''GRI'' then l_html := c_html_before_label;     ',
'            else l_html := c_html_before_item_text;                           ',
'        end case;',
'        l_html := replace(l_html,''#NOME_COLUNA#'',p_nome_coluna);',
'        l_html := replace(l_html,''#LABEL_COLUNA#'',p_label_coluna);',
'        l_html := replace(l_html,''#INSTRUCAO_COLUNA#'',p_instrucao_coluna);  ',
'        l_html := replace(l_html,''#HELP_COLUNA#'',p_help_coluna);     ',
'        l_html := replace(l_html,''#CLASSE_OCULTO#'',p_oculto);     ',
'        l_html := replace(l_html,''#VALUE#'',p_value);             ',
'        l_html := replace(l_html,''#ORDEM#'',trim(TO_CHAR(p_ordem,''00'')));         ',
'        if upper(p_obrigatorio) = ''S'' then',
'            l_html := replace(l_html,''#OBRIGATORIO1#'',''is-required'');',
'            l_html := replace(l_html,''#OBRIGATORIO2#'',c_html_obrigatorio);',
'        else',
'            l_html := replace(l_html,''#OBRIGATORIO1#'','''');',
'            l_html := replace(l_html,''#OBRIGATORIO2#'','''');',
'        end if;        ',
'             ',
'        return l_html;',
'    end;    ',
'',
'    function retorna_html_after_item(',
'        p_nome_coluna in varchar2,',
'        p_label_coluna in varchar2,',
'        p_help_coluna in varchar2',
'    ) return varchar2 is',
'        l_html clob;',
'    begin',
'        l_html := replace(c_html_after_item,''#NOME_COLUNA#'',p_nome_coluna);',
'        l_html := replace(l_html,''#LABEL_COLUNA#'',p_label_coluna);',
'        l_html := replace(l_html,''#HELP_COLUNA#'',p_help_coluna);',
'        return l_html;',
'    end;',
'',
'    function gerar_opcao_lov (',
'        p_tipo in varchar,',
'        p_coluna in varchar,',
'        p_lov_name   in varchar2,  -- nome da lov',
'        p_contador   in number,     -- contador para o apex_item.radiogroup',
'        p_valor_atual in varchar2 default null,',
'        funcao_dependencia varchar2 default null,',
'        funcao_dependenciaLoad varchar2 default null        ',
'        -- p_condicao in varchar2 default null, --TD3-68',
'        -- p_coluna_alvo in varchar2 default null, --TD3-68',
'        -- p_esconde_ou_desabilita in varchar2 default null --TD3-68         ',
'    ) ',
'    return varchar2',
'    is',
'        l_sql_query       varchar2(32767);',
'        l_tabela          varchar2(32767);',
'        l_return_column   varchar2(4000);',
'        l_display_column  varchar2(4000);',
'        l_html            varchar2(32767) := '''';',
'        l_value           varchar2(4000);',
'        l_display         varchar2(4000);',
'        l_sql_cursor      sys_refcursor;',
'        l_sql_exec        varchar2(32767);',
'        l_contador        number := p_contador;',
'        l_rownum          number;',
'        l_valor_atual     varchar2(256) := p_valor_atual;',
'        p_attributes      varchar2(4000); --TD3-68',
'        l_texto_funcao_dependeciaLoadOpc clob := funcao_dependenciaLoad;',
'    begin',
'',
'        -- apex_debug.error(''gerar_opcao_lov p_lov_name:%s'',p_lov_name); ',
'        -- apex_debug.error(''gerar_opcao_lov v(''''APP_ID''''):%s'',v(''APP_ID'')); ',
'',
unistr('        -- captura o sql da lov din\00E2mica, e as colunas de retorno e display'),
'        select list_of_values_query, return_column_name, display_column_name, table_name, rownum',
'        into l_sql_query, l_return_column, l_display_column, l_tabela, l_rownum',
'        from apex_application_lovs',
'        where upper(list_of_values_name) = upper(p_lov_name)',
'        --and application_id = v(''APP_ID'')',
'        and rownum = 1;',
'',
'        l_sql_query := nvl(l_tabela,l_sql_query);',
'',
'        -- monta o sql a partir da query da lov com as colunas de retorno e display',
'        l_sql_exec := ''select '' || l_display_column || '', '' || l_return_column || '' from ('' || l_sql_query || '')'';',
'',
unistr('        -- abre o cursor din\00E2mico para o sql montado'),
'        open l_sql_cursor for l_sql_exec;',
'',
'        -- loop para cada linha do resultado da consulta',
'        loop',
'            fetch l_sql_cursor into l_display, l_value;',
'            exit when l_sql_cursor%notfound;',
'',
'            ----TD3-68 Inicio              ',
'            --if p_esconde_ou_desabilita in (''vis'',''hab'') then',
'            p_attributes := '' coluna="''||p_coluna||''" onchange="enviarParametros(this,''||aspas(p_coluna)||''); ''||funcao_dependencia||'' " id="''||p_coluna||''_''||l_value||''" data-display="''||l_display||''" aria-label="''||l_display||''"'';',
'            --else',
'            --    p_attributes := '' onchange="enviarParametros(this,''||aspas(p_coluna)||'');" id="''||p_coluna||''_''||l_value||''" data-display="''||l_display||''" aria-label="''||l_display||''"'';',
'            --end if;',
'            ----TD3-68 Fim',
'',
'            -- concatena o apex_item.radiogroup com o html gerado',
'            l_html := l_html || ''<div class="apex-item-option">'';',
'            if p_tipo = ''RAD'' then',
'                if l_rownum = 1 and l_valor_atual is null then',
'                    l_valor_atual := l_value;',
'                end if;',
'                l_html := l_html || apex_item.radiogroup(',
'                    p_idx    => l_contador,',
'                    p_value  => l_value,',
'                    p_selected_value => l_valor_atual,',
'                    --TD3-68 p_attributes => '' onchange="enviarParametros(this,''||aspas(p_coluna)||'');" id="''||p_coluna||''_''||l_value||''" data-display="''||l_display||''" aria-label="''||l_display||''"''',
'                    p_attributes => p_attributes --TD3-68',
'                );',
'                l_html := l_html || ''<label class="u-radio" for="''||p_coluna||''_''||l_value||''" aria-hidden="true">''||l_display||''</label></div>'';',
'            elsif p_tipo = ''CHK'' then',
'                l_html := l_html || apex_item.checkbox2(',
'                        p_idx => l_contador,  ',
'                        p_value => l_value,',
'                        p_checked_values => l_valor_atual,',
'                        p_checked_values_delimiter => '':'',',
'                        --D3-68  p_attributes => '' onchange="enviarParametros(this,''||aspas(p_coluna)||'');" id="''||p_coluna||''_''||l_value||''" data-display="''||l_display||''" aria-label="''||l_display||''"''',
'                        p_attributes => p_attributes --D3-68 ',
'                    );',
'                l_html := l_html || ''<label class="u-checkbox" for="''||p_coluna||''_''||l_value||''" aria-hidden="true">''||l_display||''</label></div>'';',
'            end if;',
'        end loop;',
'        l_texto_funcao_dependeciaLoadOpc := replace(l_texto_funcao_dependeciaLoadOpc,''#VALOR#'',l_valor_atual);',
'        l_html := l_html || ''<script> document.addEventListener("DOMContentLoaded", function(){enviarParametrosLoad("''||p_coluna||''");''|| l_texto_funcao_dependeciaLoadOpc ||''});</script>'';',
'        -- fecha o cursor',
'        close l_sql_cursor;',
'',
'        return l_html;',
'    exception',
'        when no_data_found then',
unistr('            return ''lov n\00E3o encontrada ou sem sql definido.'';'),
'        when others then',
'            return ''erro: '' || sqlerrm;',
'    end gerar_opcao_lov;    ',
'',
'    function list_opcao_lov (',
'        p_array in apex_application_global.vc_arr2',
'    ) return varchar2 is',
'        v_texto varchar2(4000);',
'    begin',
'        for i in 1..p_array.count loop',
'            if p_array(i) is not null then',
'                v_texto := v_texto || p_array(i) || '':'';',
'            end if;',
'        end loop;',
'',
unistr('        -- remove o \00FAltimo '':'' se v_texto n\00E3o estiver vazio'),
'        if v_texto is not null then',
'            v_texto := rtrim(v_texto, '':'');',
'        end if;        ',
'        return v_texto;',
'    end;',
'',
'    function campos_detalhes( ',
'        p_sql clob, ',
'        p_label_fixo in varchar2 default ''n''',
'    ) return clob ',
'    as ',
'        v_detalhes         pk_types.t_detalhes := pk_types.t_detalhes(); ',
'        c          number; ',
'        cntCols    number; ',
'        cols       dbms_sql.desc_tab2;  ',
'        colValue   varchar2(4000); ',
'        tag        varchar2(4000); ',
'        l_label    varchar2(4000);',
'        l_help     varchar2(4000);',
'        l_html     clob; ',
'    begin ',
'        c := dbms_sql.open_cursor; ',
'        dbms_sql.parse(c, p_sql, dbms_sql.native); ',
'        dbms_sql.describe_columns2(c, cntCols, cols); ',
' ',
'        for i in 1 .. cntCols loop ',
'            dbms_sql.define_column(c, i, colValue, 4000); ',
'        end loop;         ',
' ',
'        --v_detalhes.extend(cntCols); ',
'        if dbms_sql.execute(c) = 0 then ',
'            while dbms_sql.fetch_rows(c) > 0 loop         ',
'                for i in 1 .. cntCols loop ',
'                    dbms_sql.column_value(c, i, colValue); ',
'                    tag := replace(cols(i).col_name,''$'',''.'');',
'',
'                    if p_label_fixo = ''n'' then ',
'                        l_label := pkg_ui.retorna_coluna(tag);',
'                        l_help := pkg_ui.retorna_coluna(tag,''h'');',
'                    else',
'                        l_label := tag;                        ',
'                    end if;',
'                    l_html := l_html || retorna_html_before(''TXT'', tag,l_label,'''','''',''apex-item-wrapper--display-only'','''');',
'                    if length(colValue) > 75 then',
'                        l_html := l_html || apex_item.textarea(',
'                            p_idx => 1, ',
'                            p_value => colValue, ',
'                            p_rows => c_textarea_linhas,',
'                            p_attributes => '' readonly class="text_field apex-item-text" style="pointer-events: auto;"''',
'                        ) || ''<br/>'';',
'                    else',
'                        l_html := l_html || apex_item.text(',
'                            p_idx => 1, ',
'                            p_value => colValue, ',
'                            p_attributes => ''id="''||tag||''" readonly class="text_field apex-item-text"''',
'                        ) || ''<br/>'';',
'                    end if;',
'                    l_html := l_html || retorna_html_after_item ('''',l_label,l_help);',
'                    l_html := replace(l_html,''#AFTER_LINK#'','''');',
'                end loop; ',
'            end loop; ',
'        end if; ',
'        l_html := replace(l_html,''#TIPO_CAMPO#'',c_tipo_campo);   ',
'        --raise_application_error(-20010, ''l_html:''||l_html);',
'        return l_html;         ',
'        -- return detalhes_confirmacao( ',
'        --     p_detalhes => v_detalhes ',
'        -- ); ',
'    end campos_detalhes; ',
'',
'    function retorna_mascara (',
'        p_edicao in varchar2',
'    ) return varchar2 is',
'        l_mascara varchar2(256);',
'    begin',
'        CASE p_edicao',
'          WHEN ''1'' THEN l_mascara := ''99999-999''; -- CEP',
'          WHEN ''2'' THEN l_mascara := ''**.***.***/****-99''; -- CNPJ',
'          WHEN ''3'' THEN l_mascara := ''999.999.999-99''; -- CPF',
'          WHEN ''4'' THEN l_mascara := ''dd/mm/yyyy''; -- Data',
'          WHEN ''5'' THEN l_mascara := ''dd/mm/yyyy HH''; -- Data e hora',
unistr('          WHEN ''6'' THEN l_mascara := ''dd/mm/yyyy HH:MI''; -- Data e hora e minutos (erro de sintaxe com MM, que \00E9 para m\00EAs)'),
'          WHEN ''7'' THEN l_mascara := ''dd/mm/yyyy HH:MI:ss''; -- Data e Hora com Minutos e Segundos',
'          WHEN ''8'' THEN l_mascara := ''email''; -- Email',
'          WHEN ''9'' THEN l_mascara := ''HH''; -- Hora',
'          WHEN ''10'' THEN l_mascara := ''HH:MI''; -- Hora com Minutos',
'          WHEN ''11'' THEN l_mascara := ''HH:MI:ss''; -- Hora com Minutos e segundos',
unistr('          WHEN ''12'' THEN l_mascara := ''999999999999999''; -- Inscri\00E7\00E3o estadual'),
'          WHEN ''13'' THEN l_mascara := ''(99) 9999-9999''; -- Telefone',
unistr('          WHEN ''14'' THEN l_mascara := ''9999 9999 9999 9999''; -- Cart\00E3o de cr\00E9dito'),
unistr('          WHEN ''16'' THEN l_mascara := ''AAA9A99''; -- Placa de ve\00EDculo'),
'          WHEN ''17'' THEN l_mascara := ''99999999999999''; -- GTIN          ',
'          WHEN ''19'' THEN l_mascara := ''99999999999''; -- CNH          ',
'          WHEN ''20'' THEN l_mascara := ''A99999999''; -- Passaporte          ',
'          ELSE',
unistr('            l_mascara := ''''; -- Caso contr\00E1rio'),
'        END CASE;',
'        return l_mascara;',
'    end;    ',
'',
'    FUNCTION monta_chamada_atribuiValor (',
'        p_json CLOB,',
'        p_coluna VARCHAR2 DEFAULT '''' -- no caso do load',
'    ) RETURN CLOB',
'    IS',
'        v_final_js      CLOB;',
'        v_trimmed_json  CLOB;',
'        v_is_array      BOOLEAN := FALSE;',
'',
'        --================================================================================',
unistr('        -- **NOVO**: Fun\00E7\00E3o local para processar UM \00DANICO objeto JSON.'),
unistr('        -- Isso evita a duplica\00E7\00E3o de c\00F3digo.'),
'        --================================================================================',
'        FUNCTION processa_objeto_json (',
'            p_obj_json CLOB,',
'            p_col_local VARCHAR2',
'        ) RETURN CLOB',
'        IS',
'            v_sql      VARCHAR2(4000);',
'            v_result   CLOB;',
'            v_array    CLOB;',
'            v_virgula  BOOLEAN := FALSE;',
'        BEGIN',
'            -- 1. Extrai o valor de SQL do objeto',
'            v_sql := JSON_VALUE(p_obj_json, ''$.SQL'');',
'',
'            -- 2. Monta o array de campos ["campo1","campo2"]',
'            FOR r IN (',
'                SELECT jt.campo_alvo',
'                FROM JSON_TABLE(',
'                    p_obj_json,',
'                    ''$.CAMPO_ALVO[*]'' COLUMNS (',
'                        campo_alvo VARCHAR2(4000) PATH ''$''',
'                    )',
'                ) jt',
'            ) LOOP',
'                IF v_virgula THEN',
'                    v_array := v_array || '','';',
'                END IF;',
'                v_array := v_array || ''"'' || REPLACE(r.campo_alvo, ''"'', ''\"'') || ''"'';',
'                v_virgula := TRUE;',
'            END LOOP;',
'',
'            v_array := ''['' || v_array || '']'';',
'',
'            -- 3. Monta a chamada JS pura',
'            IF p_col_local IS NOT NULL THEN',
'                v_result := ''atribuiValorLoad('''''' || p_col_local || '''''', '''''' || REPLACE(v_sql, '''''''', '''''''''''') || '''''', '' || v_array || '')'';',
'            ELSE',
'                v_result := ''atribuiValor(this, '''''' || REPLACE(v_sql, '''''''', '''''''''''') || '''''', '' || v_array || '')'';',
'            END IF;',
'',
'            -- 4. Escapa aspas duplas para usar em atributo HTML',
'            IF p_col_local IS NULL THEN',
'                v_result := REPLACE(v_result, ''"'', ''&quot;'');',
'            END IF;',
'',
'            RETURN v_result;',
'        END processa_objeto_json;',
'',
'    --================================================================================',
unistr('    -- In\00EDcio da L\00F3gica Principal da Fun\00E7\00E3o'),
'    --================================================================================',
'    BEGIN',
'        -- Retorna nulo se a entrada for vazia',
'        IF p_json IS NULL OR DBMS_LOB.getlength(p_json) = 0 THEN',
'            RETURN NULL;',
'        END IF;',
'',
unistr('        -- **NOVO**: Verifica se o JSON de entrada \00E9 um array ou um objeto'),
unistr('        -- A maneira mais simples \00E9 verificar o primeiro caractere n\00E3o-espa\00E7o.'),
'        v_trimmed_json := TRIM(p_json);',
'        IF SUBSTR(v_trimmed_json, 1, 1) = ''['' THEN',
'            v_is_array := TRUE;',
'        END IF;',
'',
unistr('        -- **NOVO**: L\00F3gica para tratar array ou objeto \00FAnico'),
'        IF v_is_array THEN',
unistr('            -- Se for um array, itera sobre cada objeto e chama a fun\00E7\00E3o local'),
'            FOR item IN (',
'                SELECT value',
'                FROM JSON_TABLE(p_json, ''$[*]'' COLUMNS (value CLOB FORMAT JSON PATH ''$''))',
'            ) LOOP',
unistr('                -- Concatena cada chamada de fun\00E7\00E3o JavaScript com um ponto e v\00EDrgula'),
'                v_final_js := v_final_js || processa_objeto_json(item.value, p_coluna) || '';'';',
'            END LOOP;',
'        ELSE',
unistr('            -- Se for um objeto \00FAnico, apenas chama a fun\00E7\00E3o local uma vez'),
'            v_final_js := processa_objeto_json(p_json, p_coluna) || '';'';',
'        END IF;',
'',
'        -- Se nada foi gerado, retorna nulo',
'        IF v_final_js IS NULL THEN',
'            RETURN NULL;',
'        END IF;',
'        ',
unistr('        -- Envolve todo o c\00F3digo JavaScript gerado em um \00FAnico setTimeout'),
'        RETURN ''setTimeout(() => { '' || v_final_js || '' }, 200);'';',
'',
'    END monta_chamada_atribuiValor;',
'',
'    -- FUNCTION monta_chamada_atribuiValor (',
'    --     p_json CLOB,',
'    --     p_coluna varchar2 default '''' --no caso do load',
'    -- ) RETURN CLOB',
