'    --     v_virgula       BOOLEAN := FALSE;',
'    -- BEGIN',
'    --     -- Extrai o valor de SQL',
'    --     v_sql := JSON_VALUE(p_json, ''$.SQL'');',
'',
'    --     -- Monta o array ["campo1","campo2"]',
'    --     FOR r IN (',
'    --         SELECT jt.campo_alvo',
'    --         FROM JSON_TABLE(',
