'',
'    function executa_sql_parametrizado (',
'        p_param1 in varchar2,',
'        p_sql    in clob',
'    ) return clob is',
'        v_cursor     integer;',
'        v_cols       dbms_sql.desc_tab2;',
'        v_col_count  integer;',
'        v_value      varchar2(4000);',
'        l_sql_exec   clob;',
'        l_result     clob;',
'    begin',
unistr('        -- monta a instru\00E7\00E3o com par\00E2metro'),
'        execute immediate ''begin :sql := '' || p_sql || ''(:param1); end;''',
'            using out l_sql_exec, in p_param1;',
'',
unistr('        -- abre e prepara o cursor din\00E2mico'),
'        v_cursor := dbms_sql.open_cursor;',
'        dbms_sql.parse(v_cursor, l_sql_exec, dbms_sql.native);',
'',
'        -- descreve as colunas de retorno',
'        dbms_sql.describe_columns2(v_cursor, v_col_count, v_cols);',
'',
'        -- define as colunas para leitura',
'        for i in 1 .. v_col_count loop',
'            dbms_sql.define_column(v_cursor, i, v_value, 4000);',
'        end loop;',
'',
'        -- executa e busca os dados',
'        if dbms_sql.execute(v_cursor) = 0 then',
'            if dbms_sql.fetch_rows(v_cursor) > 0 then',
'                apex_json.initialize_clob_output;',
'                apex_json.open_object;',
'',
'                for i in 1 .. v_col_count loop',
'                    dbms_sql.column_value(v_cursor, i, v_value);',
'                    apex_json.write(v_cols(i).col_name, v_value);',
'                end loop;',
'',
'                apex_json.close_object;',
'                l_result := apex_json.get_clob_output;',
'            else',
'                apex_json.initialize_clob_output;',
'                apex_json.open_object;',
'                apex_json.write(''erro'', ''Nenhum registro encontrado''); -- retorna a mensagem do erro',
'                apex_json.close_object;',
'                RETURN apex_json.get_clob_output;',
'            end if;',
'        end if;',
'',
'        dbms_sql.close_cursor(v_cursor);',
'        return l_result;',
'',
'    exception',
'        when others then',
'            if dbms_sql.is_open(v_cursor) then',
'                dbms_sql.close_cursor(v_cursor);',
'            end if;',
'            apex_json.initialize_clob_output;',
'            apex_json.open_object;',
'            apex_json.write(''erro'', SQLERRM); -- retorna a mensagem do erro',
'            apex_json.close_object;',
'            RETURN apex_json.get_clob_output;',
'',
'            ',
'',
'    end executa_sql_parametrizado;    ',
'',
'FUNCTION gerar_p_attributes (',
'        p_tipo                    IN VARCHAR2,',
'        p_nome_coluna             IN VARCHAR2,',
'        p_instrucao               IN VARCHAR2 DEFAULT NULL,',
'        p_funcao_onchange         IN VARCHAR2 DEFAULT NULL,',
'        p_funcao_onload           IN VARCHAR2 DEFAULT NULL, ',
'        p_html_visualizar         IN VARCHAR2 DEFAULT NULL',
'    ) RETURN VARCHAR2 IS',
'        l_result     VARCHAR2(4000) := c_template_attributes;',
'        l_classe     VARCHAR2(500);',
'        l_onchange   VARCHAR2(1000);',
'        l_onload     VARCHAR2(1000);',
'        l_style      VARCHAR2(1000);',
'        l_extra      VARCHAR2(1000);',
'        l_extrapop   VARCHAR2(1000);',
'        l_id         VARCHAR2(1000);',
'    BEGIN',
'        l_onload := p_funcao_onload;',
'        if p_tipo in (''DAT'',''DAH'') THEN ',
'            l_id := ''id="''|| p_nome_coluna || ''_hidden"'';',
'        elsif p_tipo in (''POP'',''POP1'',''POPTEX'',''POPTEX1'') THEN ',
'            l_id := '''';',
'        else',
'            l_id := ''id="''|| p_nome_coluna || ''"'';',
'        end if;',
'        -- Define classe por tipo',
'        CASE p_tipo',
'            WHEN ''TXT'' THEN l_classe := ''item-round text_field apex-item-text'';',
'            WHEN ''PAS'' THEN l_classe := ''item-round password text_field apex-item-text'';',
'            WHEN ''SEL'' THEN l_classe := ''item-round selectlist apex-item-select'';',
'            WHEN ''POP'' THEN l_classe := ''item-round-topleft-botleft popup_lov apex-item-text apex-item-popup-lov'';',
'            WHEN ''POP1'' THEN l_classe := ''item-round-topleft-botleft popup_lov apex-item-text apex-item-popup-lov'';',
'            WHEN ''POPTEX'' THEN l_classe := ''item-round-topleft-botleft popup_lov apex-item-text apex-item-popup-lov'';',
'            WHEN ''POPTEX1'' THEN l_classe := ''item-round-topleft-botleft popup_lov apex-item-text apex-item-popup-lov'';',
'            WHEN ''TEX'' THEN l_classe := ''item-round text_field apex-item-text ''; --padding-top-37',
'            WHEN ''HID'' THEN l_classe := ''item-round text_field apex-item-text'';',
'            ELSE l_classe := '''';',
'        END CASE;     ',
'',
'        -- Define onchange',
'        l_onchange := ''enviarParametros(this); '' || p_funcao_onchange;',
'',
'        IF p_tipo in (''POP'',''POP1'',''POPTEX'',''POPTEX1'') THEN',
'            l_onchange := l_onchange || '' toggleClearButton(''''#COLUNA#''''); '';',
'            --TESTE',
'            l_extra := ''readonly'';',
'            l_extrapop := ''role="combobox" aria-autocomplete="list" aria-expanded="false" aria-haspopup="dialog"'';',
'            l_style := ''width: 100%;'';',
'        END IF;',
'',
'        -- Define estilo',
'        IF p_tipo IN (''TEX'', ''HID'') THEN',
'            l_style := ''pointer-events: auto; resize: vertical;'';',
'        elsif p_tipo IN (''SEL'') THEN',
'            l_style := ''width: 100%;'';',
'        END IF;',
'',
unistr('        -- Substitui\00E7\00F5es'),
'        l_result := REPLACE(l_result, ''#ID#'', l_id);',
'        l_result := REPLACE(l_result, ''#CLASSE#'', l_classe);',
'        l_result := REPLACE(l_result, ''#PLACEHOLDER#'', NVL(p_instrucao, ''''));',
'        l_result := REPLACE(l_result, ''#ONCHANGE#'', NVL(l_onchange, ''''));',
'        l_result := REPLACE(l_result, ''#ONLOAD#'', NVL(l_onload,''''));',
'        l_result := REPLACE(l_result, ''#STYLE#'', NVL(l_style, ''''));',
'        l_result := REPLACE(l_result, ''#EXTRAPOP#'', NVL(l_extrapop, ''''));',
'        l_result := REPLACE(l_result, ''#EXTRA#'', l_extra);',
'        l_result := REPLACE(l_result, ''#COLUNA#'', p_nome_coluna);',
'',
'        RETURN NVL(p_html_visualizar, '''') || l_result;',
'    END;',
'',
'    function gerar_script_tipo(',
'        p_tipo                          in varchar2,',
'        p_nome_coluna                   in varchar2,',
'        p_formato_campo                 in varchar2 default '''',',
'        p_texto_funcao_dependeciaLoad   in varchar2 default '''',',
'        p_texto_funcao_executa_js       in varchar2 default '''',',
'        p_texto_funcao_atribuir_valor   in varchar2 default '''',',
'        p_texto_funcao_transformaElem   in varchar2 default ''''',
'    ) return clob is',
'        l_html     clob;',
'        l_conteudo clob;',
'    begin',
' ',
unistr('        -- Conte\00FAdo inicial sempre presente'),
'        l_conteudo := '''';',
'',
'        -- Alguns tipos usam formato de campo antes do enviarParametrosLoad',
'        if p_tipo in (''TXT'', ''DAT'', ''DAH'', ''HID'') then',
'            l_conteudo := l_conteudo || p_formato_campo;',
'        end if;',
'',
unistr('        -- Enviar par\00E2metros sempre presente'),
'        l_conteudo := l_conteudo || '' enviarParametrosLoad("''||p_nome_coluna||''");'';',
'',
unistr('        -- Depend\00EAncia'),
'        l_conteudo := l_conteudo || p_texto_funcao_dependeciaLoad;',
'',
'        -- Tipos que usam transformaElemento',
'        if p_tipo in (''POP'',''POP1'',''POPTEX'',''POPTEX1'') then',
'            l_conteudo := l_conteudo || p_texto_funcao_transformaElem;',
'        end if;',
'',
'        -- Tipos que usam executa_js',
'        if p_tipo not in (''SWI'') then',
'            l_conteudo := l_conteudo || p_texto_funcao_executa_js;',
'        end if;',
'',
'        -- Tipos que usam atribuir valor',
'        if p_tipo not in (''SWI'') then',
'            l_conteudo := l_conteudo || p_texto_funcao_atribuir_valor;',
'        end if;',
'',
'        -- Monta o script final',
'        l_html := ''<script>document.addEventListener("DOMContentLoaded", function(){'' ||',
'                        l_conteudo || ',
'                        ''$("#FORM").on("apexafterrefresh", function () {''|| ',
'                            l_conteudo || ',
'                        ''});''|| ',
'                  ''});</script>'';',
'',
'',
'        return l_html;',
'    end gerar_script_tipo;',
'',
'end "PKG_FORMULARIO_DINAMICO";',
'/'))
);
end;
