'create or replace package body "PKG_UTIL" as ',
' ',
'    function retorna_id_usuario_logado return number is ',
'        l_id_usuario mpd_usuario.id%type; ',
'        l_existe number;',
'    begin ',
'        select count(1) into l_existe from mpd_usuario where upper(login) = upper(apex_custom_auth.get_username); ',
'        if l_existe > 0 then',
'            select id into l_id_usuario from mpd_usuario where upper(login) = upper(apex_custom_auth.get_username);         ',
'            return l_id_usuario; ',
'        else',
'            return valor_client_identifier(''USUARIO'');  ',
'        end if;',
'        ',
'        exception  ',
'            when no_data_found then ',
'                return 1;  ',
'    end retorna_id_usuario_logado; ',
' ',
'    function esconder_email (p_email in varchar2)  ',
'    return varchar2 is  ',
'        v_partes varchar2(32767);  ',
'        v_usuario varchar2(32767);  ',
'        v_dominio varchar2(32767);  ',
'        v_tamanho_usuario number;  ',
'        v_parte_visivel number;  ',
'        v_parte_oculta number;  ',
'        v_usuario_visivel varchar2(32767);  ',
'        v_usuario_oculto varchar2(32767);  ',
'        v_email_final varchar2(32767);  ',
'    begin  ',
'        v_partes := regexp_replace(p_email, ''(.*)@(.*)'', ''\1|\2'');  ',
'        v_usuario := substr(v_partes, 1, instr(v_partes, ''|'')-1);  ',
'        v_dominio := substr(v_partes, instr(v_partes, ''|'')+1);  ',
'        v_tamanho_usuario := length(v_usuario);  ',
'        v_parte_visivel := trunc(v_tamanho_usuario / 2);  ',
'        v_parte_oculta := v_tamanho_usuario - v_parte_visivel;  ',
'        v_usuario_visivel := substr(v_usuario, 1, v_parte_visivel);  ',
'        v_usuario_oculto := rpad(''*'', v_parte_oculta, ''*'');  ',
'        v_email_final := v_usuario_visivel || v_usuario_oculto || ''@'' || v_dominio;  ',
'        return v_email_final;  ',
'    end esconder_email;  ',
'  ',
'    function hide_email (p_email in varchar2)  ',
'    return varchar2 is  ',
'        v_partes varchar2(32767);  ',
'        v_usuario varchar2(32767);  ',
'        v_dominio varchar2(32767);  ',
'        v_tamanho_usuario number;  ',
'        v_parte_visivel number;  ',
'        v_parte_oculta number;  ',
'        v_usuario_visivel varchar2(32767);  ',
'        v_usuario_oculto varchar2(32767);  ',
'        v_email_final varchar2(32767);  ',
'    begin  ',
'        v_partes := regexp_replace(p_email, ''(.*)@(.*)'', ''\1|\2'');  ',
'        v_usuario := substr(v_partes, 1, instr(v_partes, ''|'')-1);  ',
'        v_dominio := substr(v_partes, instr(v_partes, ''|'')+1);  ',
'        v_tamanho_usuario := length(v_usuario);  ',
'        v_parte_visivel := trunc(v_tamanho_usuario / 2);  ',
'        v_parte_oculta := v_tamanho_usuario - v_parte_visivel;  ',
'        v_usuario_visivel := substr(v_usuario, 1, v_parte_visivel);  ',
'        v_usuario_oculto := rpad(''*'', v_parte_oculta, ''*'');  ',
'        v_email_final := v_usuario_visivel || v_usuario_oculto || ''@'' || v_dominio;  ',
'        return v_email_final;  ',
'    end hide_email;     ',
'  ',
'    function hide_fone (p_fone in varchar2)  ',
'    return varchar2 is  ',
'        l_area  varchar(20);  ',
'        l_part1 varchar(20);  ',
'        l_part2 varchar(20);  ',
'    begin  ',
'        l_area := substr(p_fone, 1, instr(p_fone, '')''));  ',
'        l_part1 := substr(p_fone, 1, instr(p_fone, ''-'')-1);  ',
'        l_area := substr(l_part1, 1, instr(l_part1, '')''));    ',
'        l_part1 := substr(l_part1, instr(l_part1, '' ''), 6);  ',
'        l_part2 := substr(p_fone, instr(p_fone, ''-'')+1, 5);  ',
'        return l_area ||'' *****-'' || l_part2;  ',
'    end hide_fone;      ',
' ',
'    function retorna_descricao_artefato (p_artefato_codigo in number)  ',
'    return varchar2 is  ',
'        l_descricao varchar(2000); ',
'    begin  ',
'        select ajuda into l_descricao from SRV_ARTEFATO where CODIGO_ARTEFATO = p_artefato_codigo; ',
'        return l_descricao; ',
' ',
'        exception  ',
'        when others then        ',
'            return ''Sem ajuda'';  ',
'             ',
'    end retorna_descricao_artefato;          ',
' ',
'    function html_info ',
'    return varchar2 is  ',
'        l_html varchar(255); ',
'    begin  ',
'        return ''<id id="icon_info" class="fa fa-info-circle-o" style="font-size: 1rem; margin-top:0.5rem;"></id>'';             ',
'    end html_info; ',
' ',
'    function retorna_campos_tabela(p_tabela in varchar2, p_alias in boolean default false, p_separador in varchar2 default '';'') ',
'    return varchar2 is ',
'        l_colunas varchar2(2000); ',
'    begin ',
'        if p_alias then ',
'            select ''col'' || to_char(rownum,''000'')|| '' '' || listagg( column_name,'','') into l_colunas from all_tab_columns where table_name = p_tabela and column_name not in (''id''); ',
'        else ',
'            select listagg( column_name,p_separador) into l_colunas from all_tab_columns where table_name = p_tabela and column_name not in (''id''); ',
'        end if; ',
'        return l_colunas; ',
'    end;           ',
' ',
'    function sql_carrega_csv(p_tabela in varchar2, p_id_arquivo in varchar) ',
'    return varchar2 is ',
'        l_sql varchar2(4000); ',
'        l_campos varchar2(2000); ',
'    begin ',
'        if p_id_arquivo is not null then ',
'            l_campos := retorna_campos_tabela(p_tabela, true); ',
'        end if; ',
'        l_sql := q''~ ',
'            select line_number, #campos# ',
'            from apex_application_temp_files f,  ',
'               table( apex_data_parser.parse( ',
'                          p_content                     => f.blob_content, ',
'                          p_add_headers_row             => ''y'', ',
'                          p_row_selector                => ''/document/rowset/row'', ',
'                          p_store_profile_to_collection => ''file_parser_collection'', ',
'                          p_file_name                   => f.filename ) ) p ',
'            where f.name = ''#arquivo#'' ~''; ',
'         ',
'            l_sql := replace(l_sql,''#campos#'',nvl(l_campos,1)); ',
'            l_sql := replace(l_sql,''#arquivo#'',nvl(p_id_arquivo,1));   ',
'         ',
'        return l_sql; ',
'    end;                   ',
' ',
'    procedure gerar_csv(o_clobdata out clob, p_tabela in varchar2) is  ',
'        l_blob blob;l_clob clob;l_campos varchar2(2000); ',
'    begin ',
'        l_campos := pkg_util.retorna_campos_tabela(p_tabela,false,'';''); ',
'        dbms_lob.createtemporary(lob_loc => l_clob, cache => true, dur => dbms_lob.call); ',
'        select clob_val ',
'        into   l_clob ',
'        from   ( ',
'                    select xmlcast(xmlagg(xmlelement(e, col_value ',
'                                  || chr(13) ',
'                                  || chr(10))) as clob) as clob_val, ',
'                           count(*) as                     number_of_rows ',
'                    from   ( ',
'                                  select l_campos as col_value ',
'                                  from   dual )); ',
' ',
'        o_clobdata := l_clob; ',
'        exception ',
'        when others then ',
'            null; ',
'             ',
'    end;     ',
' ',
'    function obter_nomes_chaves(p_chaves in varchar2, p_tabela in varchar) ',
'    return varchar2 ',
'    is ',
'        v_nomes varchar2(4000); ',
'        l_sql varchar2(4000); ',
'    begin ',
'        l_sql := q''~ ',
'        select listagg(tr.nome, '', '') within group (order by tr.id) ',
'        from #tabela# tr ',
'        where tr.id in (select to_number(regexp_substr(''#chaves#'', ''\d+'', 1, level)) ',
'                    from dual ',
'                    connect by regexp_substr(''#chaves#'', ''\d+'', 1, level) is not null)  ',
'        ~'';       ',
'        l_sql := replace(l_sql,''#chaves#'',nvl(p_chaves,1)); ',
'        l_sql := replace(l_sql,''#tabela#'',nvl(p_tabela,1));   ',
' ',
'        execute immediate l_sql into v_nomes; ',
'        return v_nomes; ',
'    exception ',
'        when no_data_found then ',
'            return null; ',
'    end; ',
'  ',
'    function obter_descricao_opcao(p_valor in varchar2, p_nome_lista in varchar) ',
'    return varchar2 is ',
'        l_descricao varchar2(2000); ',
'        l_sql varchar2(2000); ',
'    begin ',
'       ',
'        l_sql := q''~ ',
'        select listagg(tr.display_value, '', '') within group (order by tr.return_value) ',
'        from apex_application_lov_entries tr ',
'        where list_of_values_name = ''#p_nome_lista#'' and tr.return_value in (select regexp_substr(''#p_valor#'', ''\d+'', 1, level) ',
'                    from dual ',
'                    connect by regexp_substr(''#p_valor#'', ''\d+'', 1, level) is not null)  ',
'        ~'';       ',
'        l_sql := replace(l_sql,''#p_valor#'',nvl(p_valor,1)); ',
'        l_sql := replace(l_sql,''#p_nome_lista#'',nvl(p_nome_lista,1));   ',
' ',
'        execute immediate l_sql into l_descricao; ',
'        return l_descricao; ',
' ',
'        exception ',
'            when no_data_found then ',
'                return null; ',
' ',
'    end;                   ',
' ',
' ',
'    function remover_acentos(p_texto in varchar2) ',
'    return varchar2 is ',
'        l_texto_limpo varchar2(2000); ',
'    begin ',
'        select  ',
unistr('        translate (p_texto,''\0161\017E\0161\017E\00FF\00E1\00E7\00E9\00ED\00F3\00FA\00E0\00E8\00EC\00F2\00F9\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00EB\00FC\00EF\00F6\00F1\00FD\00E5\00E1\00E7\00E9\00ED\00F3\00FA\00E0\00E8\00EC\00F2\00F9\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00EB\00FC\00EF\00F6\00F1\00FD\00FF'',''szszyaceiouaeiouaeiouaoeuionyaaceiouaeiouaeiouaoeuionyy'') into l_texto_limpo '),
'        from dual; ',
'        return replace(l_texto_limpo,'' '',''_'') ; ',
'    end;  ',
'',
'    function remover_acentos2(p_texto in varchar2) ',
'    return varchar2 is ',
'        l_texto_limpo varchar2(2000); ',
'    begin ',
'        select  ',
unistr('        translate (lower(p_texto),''\0161\017E\0161\017E\00FF\00E1\00E7\00E9\00ED\00F3\00FA\00E0\00E8\00EC\00F2\00F9\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00EB\00FC\00EF\00F6\00F1\00FD\00E5\00E1\00E7\00E9\00ED\00F3\00FA\00E0\00E8\00EC\00F2\00F9\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00EB\00FC\00EF\00F6\00F1\00FD\00FF'',''szszyaceiouaeiouaeiouaoeuionyaaceiouaeiouaeiouaoeuionyy'') into l_texto_limpo '),
'        from dual; ',
