'',
'    function remover_espacos(p_texto in varchar2) ',
'    return varchar2 is ',
'        l_texto_limpo varchar2(2000); ',
'    begin  ',
'        return replace(p_texto,'' '',''_''); ',
'    end;    ',
'',
'    function retorna_icone_idioma(p_codigo in srv_idioma.codigo%type)',
'    return varchar2 is',
'        l_icon varchar2(256);',
'    begin',
'        select ',
'        case p_codigo',
'            when ''pt-br'' then ''ico-flag-brazil-sm'' ',
'            when ''es'' then ''ico-flag-spain-sm'' ',
'            when ''en'' then ''ico-flag-usa-sm'' ',
'            when ''zh'' then ''ico-flag-china-sm''',
'            else ''ico-flag-brazil-sm'' ',
'        end into l_icon from dual;',
'        return l_icon;',
'    end retorna_icone_idioma;',
