'    function dominio_retorna_lista(p_tabela varchar2, p_coluna varchar2)   ',
'    return t_dominio pipelined as ',
'        cursor c_query is ',
'            select c.valor r, pkg_ui.retorna_dominio(c.id_dominio,c.valor) d from mpd_entidade a',
'            join mpd_entidade_coluna b on b.id_entidade = a.id',
'            join mpd_dominio_valor c on c.id_dominio = b.id_dominio',
'            where lower(nome_entidade) = lower(p_tabela) ',
'            and lower(nome_coluna) = lower(p_coluna);',
' ',
'        v_reg_row           c_query%rowtype; ',
'        v_reg_type          r_dominio;         ',
'        v_registros         t_dominio := t_dominio(); ',
'    begin ',
'        open c_query; ',
'        loop ',
'            fetch c_query into v_reg_row; ',
'            exit when c_query%notfound; ',
'             ',
'            v_reg_type := r_dominio( ',
'                trim(v_reg_row.d), ',
'                trim(v_reg_row.r)); ',
'                 ',
'            v_registros.extend; ',
'            v_registros(v_registros.last) := v_reg_type; ',
' ',
'        end loop; ',
'        close c_query; ',
'         ',
'        if v_registros.count > 0 then ',
'            for i in v_registros.first .. v_registros.last loop ',
'                pipe row(v_registros(i)); ',
' ',
'            end loop; ',
' ',
'        end if;          ',
'    end dominio_retorna_lista;       ',
'',
'    function dominio_retorna_lista(p_id_dominio number)   ',
'    return t_dominio pipelined as ',
'        cursor c_query is ',
'            select c.valor r, pkg_ui.retorna_dominio(c.id_dominio,c.valor) d from mpd_dominio_valor c ',
'            where lower(c.id_dominio) = lower(p_id_dominio);',
'            ',
' ',
'        v_reg_row           c_query%rowtype; ',
'        v_reg_type          r_dominio;         ',
'        v_registros         t_dominio := t_dominio(); ',
'    begin ',
'        open c_query; ',
'        loop ',
'            fetch c_query into v_reg_row; ',
'            exit when c_query%notfound; ',
'             ',
'            v_reg_type := r_dominio( ',
'                trim(v_reg_row.d), ',
'                trim(v_reg_row.r)); ',
'                 ',
'            v_registros.extend; ',
'            v_registros(v_registros.last) := v_reg_type; ',
' ',
'        end loop; ',
'        close c_query; ',
'         ',
