'    function dominio_retorna_valor(p_tabela varchar2, p_coluna varchar2 ,p_tag varchar2)  ',
'    return varchar2 is ',
'        l_valor varchar2(128); ',
'    begin ',
'        select valor into l_valor from mpd_entidade a',
'        join mpd_entidade_coluna b on b.id_entidade = a.id',
'        join mpd_dominio_valor c on c.id_dominio = b.id_dominio',
'        where lower(nome_entidade) = lower(p_tabela) ',
'        and lower(nome_coluna) = lower(p_coluna)',
'        and lower(tag) = lower(p_tag);',
'        ',
'        return trim(l_valor); ',
'        exception  ',
'            when no_data_found then ',
'                return '''';  ',
'    end dominio_retorna_valor; ',
'',
'    function dominio_retorna_valor_titulo(p_tabela varchar2, p_coluna varchar2 ,p_titulo varchar2)  ',
'    return varchar2 is ',
'        l_valor varchar2(128); ',
'    begin ',
'        select valor into l_valor from srv_entidade a',
'        join srv_entidade_coluna b on b.id_entidade = a.id',
'        join srv_dominio_valor c on c.id_dominio = b.id_dominio',
'        where lower(nome_entidade) = lower(p_tabela) ',
'        and lower(nome_coluna) = lower(p_coluna)',
'        and lower(titulo) = lower(p_titulo);',
'        ',
'        return trim(l_valor); ',
'        exception  ',
'            when no_data_found then ',
'                return '''';  ',
'    end dominio_retorna_valor_titulo; ',
'',
'',
'    function dominio_retorna_tag(p_tabela varchar2, p_coluna varchar2 ,p_valor varchar2)  ',
'    return varchar2 is ',
'        l_tag varchar2(128); ',
'    begin ',
'        select pkg_ui.retorna_dominio(c.id_dominio,c.valor) into l_tag from mpd_entidade a',
'        join mpd_entidade_coluna b on b.id_entidade = a.id',
'        join mpd_dominio_valor c on c.id_dominio = b.id_dominio',
'        where lower(nome_entidade) = lower(p_tabela) ',
'        and lower(nome_coluna) = lower(p_coluna)',
'        and lower(valor) = lower(p_valor);',
'        ',
'        return trim(l_tag); ',
'        exception  ',
'            when no_data_found then ',
'                return '''';  ',
'    end dominio_retorna_tag; ',
'',
'    function dominio_retorna_tags(p_tabela varchar2, p_coluna varchar2)  ',
'    return varchar2 is ',
'        l_tag varchar2(128); ',
'    begin ',
'        for c_dominio in (',
'            select pkg_ui.retorna_dominio(c.id_dominio,c.valor) as titulo from mpd_entidade a',
'            join mpd_entidade_coluna b on b.id_entidade = a.id',
'            join mpd_dominio_valor c on c.id_dominio = b.id_dominio',
'            where lower(nome_entidade) = lower(p_tabela) ',
'            and lower(nome_coluna) = lower(p_coluna)',
'        ) loop  ',
'            l_tag := l_tag || c_dominio.titulo || chr(10);',
'        end loop;',
'        ',
'        return trim(l_tag); ',
'        exception  ',
'            when no_data_found then ',
'                return '''';  ',
'    end dominio_retorna_tags;     ',
'',
'',
'    function dominio_retorna_titulo(p_dominio number, p_valor varchar2)  ',
'    return varchar2 is ',
'        l_titulo varchar2(128); ',
'    begin ',
'        select pkg_ui.retorna_dominio(id_dominio,valor) into l_titulo',
'        from mpd_dominio_valor ',
'        where id_dominio = p_dominio ',
'        and lower(valor) = lower(p_valor);',
'      --   for c_dominio in (',
'',
'      --   ) loop  ',
'      --       l_titulo := l_titulo || c_dominio.titulo || chr(10);',
'      --   end loop;',
'        ',
'        return trim(l_titulo); ',
'        exception  ',
'            when no_data_found then ',
'                return '''';  ',
'    end dominio_retorna_titulo;     ',
'',
'    function verifica_dominio(p_tabela varchar2, p_coluna varchar2 ,p_valor VARCHAR2)  ',
'    return boolean is ',
'        l_verifica_valor_existente varchar2(128);',
'    begin ',
'        select pkg_util.dominio_retorna_tag(p_tabela,p_coluna, p_valor) into l_verifica_valor_existente from dual;',
'        return l_verifica_valor_existente is not null;',
'        exception  ',
'            when no_data_found then ',
'                return false;',
'            when others then ',
'                return false;',
