'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record             ',
'    ) is',
'        l_cpf       varchar2(50);',
'        l_parametro pkg_mensagem.paramentros;        ',
'        l_total     number := 0;',
'        l_digito    number := 0;        ',
'    begin ',
'        l_cpf := trim(regexp_replace(p_cpf, ''[^[:digit:]]'', ''''));',
'',
'        if l_cpf is null or length(l_cpf) <> 11 or regexp_like(p_cpf, ''[[:alpha:]]'') then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''41'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;',
'    for i in 1..9 loop',
'             l_total := l_total + substr(l_cpf, i, 1) * (11 - i);',
'        end loop;',
'',
'        l_digito := 11 - mod(l_total, 11);',
'',
'        if l_digito > 9 then',
'            l_digito := 0;',
'        end if;',
'',
'        if l_digito != substr(l_cpf, 10, 1) then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''41'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );            ',
'        end if;',
'',
'        l_digito := 0;',
'        l_total  := 0;',
'',
'        for i in 1..10 loop',
'            l_total := l_total + substr(l_cpf, i, 1) * (12 - i);',
'        end loop;',
'',
'        l_digito := 11 - mod(l_total, 11);',
'',
'        if l_digito > 9 then',
'            l_digito := 0;',
'        end if;',
'',
'        if l_digito != substr(l_cpf, 11, 1) then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''41'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;         ',
'    exception ',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''41'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_cpf;    ',
'    ',
'    procedure valida_formato_cnpj (',
'        p_cnpj            in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is',
'        l_cnpj      varchar2(50);',
'        l_parametro pkg_mensagem.paramentros;',
'        l_total     number := 0;',
'        l_digito    number := 0;',
'',
'        function valor_caractere (',
'            p_char in varchar2',
'        ) return number is',
'        begin',
'            /*',
unistr('                Regra do CNPJ alfanum\00E9rico:'),
unistr('                - n\00FAmeros continuam valendo 0 a 9'),
'                - letras usam ASCII - 48',
'                  Ex: A = 65 - 48 = 17',
'            */',
'            return ascii(p_char) - 48;',
'        end valor_caractere;',
'',
'        procedure registrar_erro is',
'        begin',
'            l_parametro(1) := sqlerrm;',
'            l_parametro(2) := p_cnpj;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end registrar_erro;',
'',
'    begin',
'        /*',
unistr('            Remove m\00E1scara e qualquer caractere que n\00E3o seja letra ou n\00FAmero.'),
'            Ex:',
'            12.ABC.345/01DE-35 -> 12ABC34501DE35',
'        */',
'        l_cnpj := upper(trim(regexp_replace(p_cnpj, ''[^[:alnum:]]'', '''')));',
'',
'        /*',
unistr('            Valida\00E7\00F5es b\00E1sicas:'),
'            - precisa ter 14 caracteres',
unistr('            - precisa conter apenas letras mai\00FAsculas e n\00FAmeros'),
unistr('            - os 2 \00FAltimos caracteres precisam ser num\00E9ricos'),
'        */',
'',
'        if l_cnpj is null',
'           or length(l_cnpj) <> 14',
'           or regexp_like(l_cnpj, ''[^A-Z0-9]'')',
'           or not regexp_like(substr(l_cnpj, 13, 2), ''^[0-9]{2}$'')',
'        then',
'            registrar_erro;',
'            return;',
'        end if;',
'',
'        /*',
unistr('            Primeiro d\00EDgito verificador.'),
'            Pesos:',
unistr('            posi\00E7\00F5es 1 a 4  -> 5, 4, 3, 2'),
unistr('            posi\00E7\00F5es 5 a 12 -> 9, 8, 7, 6, 5, 4, 3, 2'),
'        */',
'        l_total := 0;',
'',
'        for i in 1..4 loop',
'            l_total := l_total + valor_caractere(substr(l_cnpj, i, 1)) * (6 - i);',
'        end loop;',
'',
'        for i in 5..12 loop',
'            l_total := l_total + valor_caractere(substr(l_cnpj, i, 1)) * (14 - i);',
'        end loop;',
'',
'        l_digito := 11 - mod(l_total, 11);',
'',
'        if l_digito > 9 then',
'            l_digito := 0;',
'        end if;',
'',
'        if l_digito != to_number(substr(l_cnpj, 13, 1)) then',
'            registrar_erro;',
'            return;',
'        end if;',
'',
'        /*',
unistr('            Segundo d\00EDgito verificador.'),
'            Pesos:',
unistr('            posi\00E7\00F5es 1 a 5  -> 6, 5, 4, 3, 2'),
unistr('            posi\00E7\00F5es 6 a 13 -> 9, 8, 7, 6, 5, 4, 3, 2'),
'        */',
'        l_total := 0;',
'',
'        for i in 1..5 loop',
'            l_total := l_total + valor_caractere(substr(l_cnpj, i, 1)) * (7 - i);',
'        end loop;',
'',
'        for i in 6..13 loop',
'            l_total := l_total + valor_caractere(substr(l_cnpj, i, 1)) * (15 - i);',
'        end loop;',
'',
'        l_digito := 11 - mod(l_total, 11);',
'',
'        if l_digito > 9 then',
'            l_digito := 0;',
'        end if;',
'',
'        -- if l_digito != to_number(substr(l_cnpj, 14, 1)) then',
'        --     registrar_erro;',
'        --     return;',
'        -- end if;',
'',
'    exception',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            l_parametro(2) := p_cnpj;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_cnpj;',
'',
'    procedure valida_formato_cep (        ',
'        p_cep             in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record       ',
'    ) is  ',
'        l_cep       varchar2(20);',
'        l_parametro pkg_mensagem.paramentros;',
'        l_json_api  clob;                         ',
'    begin       ',
'        l_cep := trim(regexp_replace(p_cep, ''[^[:digit:]]'', ''''));',
'        ',
'        if l_cep is null or length(l_cep) <> 8 or regexp_like(p_cep, ''[[:alpha:]]'') then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if; ',
'            ',
'            apex_web_service.g_request_headers.delete();            ',
'            ',
'            l_json_api := apex_web_service.make_rest_request(',
'                p_url => ''https://viacep.com.br/ws/''||l_cep||''/json/'',',
'                p_http_method => ''GET''',
'            );',
'',
'            for cur in (',
'                select             ',
'                cep',
'                --logradouro,',
'                --complemento,',
'                --bairro,',
'                --localidade,',
'                --uf',
'                --ibge,',
'                --gia,',
'                --ddd,',
'                --siafi',
'                from json_table (',
'                    l_json_api format json, ''$''columns(                    ',
'                        cep         varchar2(255) path ''$.cep''',
'                        --logradouro  varchar2(255) path ''$.logradouro'',',
'                        --complemento varchar2(255) path ''$.complemento'',',
'                        --bairro      varchar2(255) path ''$.bairro'',',
'                        --localidade  varchar2(255) path ''$.localidade'',',
'                        --uf          varchar2(255) path ''$.uf''',
'                        --ibge        varchar2(255) path ''$.ibge'',',
'                        --gia         varchar2(255) path ''$.gia'',',
'                        --ddd         varchar2(255) path ''$.ddd'',',
'                        --siafi       varchar2(255) path ''$.siafi''',
'                    )',
'                )',
'            ) loop',
'                l_cep           := cur.cep;',
'                --v_logradouro    := cur.logradouro;',
'                --v_complemento   := cur.complemento;',
'                --v_bairro        := cur.bairro;',
'                --v_localidade    := cur.localidade;',
'                --v_uf            := cur.uf;',
'                --v_ibge          := cur.ibge;',
'                --v_gia           := cur.gia;',
'                --v_ddd           := cur.ddd;',
'                --v_siafi         := cur.siafi;                                ',
'              end loop;             ',
'    exception ',
'        when others then ',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );   ',
'    end valida_formato_cep;          ',
'',
