'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;',
'    exception',
'        when others then ',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
