'',
'    procedure valida_formato_data (',
'        p_data            in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is',
'        l_data      varchar2(20);',
'        l_parametro pkg_mensagem.paramentros;',
'    begin',
'        l_data := trim(regexp_replace(p_data, ''[^[:digit:]]'', ''''));',
'        ',
'        if l_data is null or length(l_data) <> 8 or regexp_like(p_data, ''[[:alpha:]]'') or substr(l_data, 0, 2) < 01 or substr(l_data, 0, 2) > 31 or substr(l_data, 3, 2) < 01 or substr(l_data, 3, 2) > 12 or substr(l_data, 5, 4) < 1900 or substr(l_data'
||', 5, 4) > 2100 then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );        ',
'        end if;',
'    exception',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_data;',
'',
'    procedure valida_formato_data_hora (',
'        p_data_hora       in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is ',
'        l_data_hora       varchar2(20);',
'        l_data            varchar2(8);',
'        l_hora            varchar2(2);',
'        l_parametro       pkg_mensagem.paramentros;',
'        l_objeto_mensagem pkg_mensagem.message_record;        ',
'    begin',
'        l_data_hora := trim(regexp_replace(p_data_hora, ''[^[:digit:]]'', ''''));        ',
'',
'        if length(l_data_hora) <> 10 or regexp_like(p_data_hora, ''[[:alpha:]]'') then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        else',
'            l_data := substr(l_data_hora, 0, 8);',
'            l_hora := substr(l_data_hora, 9, 2);',
'        end if;',
'',
'        pkg_util.valida_formato_data(',
'            p_data            => l_data,',
'            p_campo           => p_campo,',
'            p_parametro       => p_parametro,',
'            p_pagina          => p_pagina,',
'            p_objeto_mensagem => l_objeto_mensagem',
'        );',
'',
'        if l_objeto_mensagem.mensagem is null then',
'            if l_hora is null or length(l_hora) <> 2 or l_hora < 00 or l_hora > 23 then     ',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''19'',',
'                    p_nome_campo      => p_campo,',
'                    p_parametro       => p_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => p_objeto_mensagem',
'                );',
'            end if;',
'        else',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;',
'    exception',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_data_hora;',
'',
'    procedure valida_formato_data_hora_minuto (',
'        p_data_hora_minuto in varchar2,',
'        p_campo            in varchar2,',
'        p_parametro        in pkg_mensagem.paramentros,',
'        p_pagina           in number,',
'        p_objeto_mensagem  out pkg_mensagem.message_record',
'    ) is',
'        l_data_hora_minuto varchar2(50);',
'        l_data_hora        varchar2(10);',
'        l_minutos          varchar2(2);',
'        l_parametro        pkg_mensagem.paramentros;',
'        l_objeto_mensagem  pkg_mensagem.message_record;        ',
'    begin',
'        l_data_hora_minuto := trim(regexp_replace(p_data_hora_minuto, ''[^[:digit:]]'', ''''));',
'',
'        if length(l_data_hora_minuto) <> 12 or regexp_like(p_data_hora_minuto, ''[[:alpha:]]'') then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        else',
'            l_data_hora := substr(l_data_hora_minuto, 0, 10);',
'            l_minutos := substr(l_data_hora_minuto, 11, 2);',
'        end if;',
'',
'        pkg_util.valida_formato_data_hora(',
'            p_data_hora        => l_data_hora,',
'            p_campo            => p_campo,',
'            p_parametro        => p_parametro,',
'            p_pagina           => p_pagina,',
'            p_objeto_mensagem  => l_objeto_mensagem            ',
'        );',
'',
'        if l_objeto_mensagem.mensagem is null then',
'            if l_minutos is null or length(l_minutos) <> 2 or l_minutos < 00 or l_minutos > 59 then     ',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''19'',',
'                    p_nome_campo      => p_campo,',
'                    p_parametro       => p_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => p_objeto_mensagem',
'                );',
'            end if;',
'        else',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;        ',
'    exception',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_data_hora_minuto;',
'',
'    procedure valida_formato_data_hora_minuto_segundo (',
'        p_data_hora_minuto_segundo  in varchar2,',
'        p_campo                     in varchar2,',
'        p_parametro                 in pkg_mensagem.paramentros,',
'        p_pagina                    in number,',
'        p_objeto_mensagem           out pkg_mensagem.message_record',
'    ) is',
'        l_data_hora_minuto_segundo varchar2(50);',
'        l_data_hora_minuto         varchar2(12);',
'        l_segundos                 varchar2(2);',
'        l_parametro                pkg_mensagem.paramentros;',
'        l_objeto_mensagem          pkg_mensagem.message_record;',
'    begin',
'        l_data_hora_minuto_segundo := trim(regexp_replace(p_data_hora_minuto_segundo, ''[^[:digit:]]'', ''''));',
'',
'        if length(l_data_hora_minuto_segundo) <> 14 or regexp_like(p_data_hora_minuto_segundo, ''[[:alpha:]]'') then',
