'        );',
'',
'        if l_objeto_mensagem.mensagem is null then',
'            if l_segundos is null or length(l_segundos) <> 2 or l_segundos < 00 or l_segundos > 59 then',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''19'',',
'                    p_nome_campo      => p_campo,',
'                    p_parametro       => p_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => p_objeto_mensagem',
'                );',
'            end if;',
'        else',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;',
'    exception ',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_hora_minuto_segundo;',
'',
'    procedure valida_formato_numero_cartao (',
'        p_numero_cartao   in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    )is ',
'        l_numero_cartao varchar2(50) := p_numero_cartao;',
'        l_soma          number := 0;',
'        l_dobro         number;',
'        l_tamanho       number := length(l_numero_cartao);',
'        l_digito        number;',
'        l_parametro     pkg_mensagem.paramentros;        ',
'    begin',
'        l_numero_cartao := trim(regexp_replace(l_numero_cartao, ''[^[:digit:]]'', ''''));',
'',
'        if l_numero_cartao is null or length(l_numero_cartao) <> 16 then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        else',
'            for i in 0 .. l_tamanho - 1 loop',
'            l_digito := to_number(substr(l_numero_cartao, l_tamanho - i, 1));',
'                if mod(i, 2) = 1 then',
'                    l_dobro := l_digito * 2;',
'                    if l_dobro > 9 then',
'                        l_soma := l_soma + (l_dobro - 9);',
'                    else',
'                        l_soma := l_soma + l_dobro;',
'                    end if;',
'                else',
'                    l_soma := l_soma + l_digito;',
'                end if;',
'            end loop;',
'            ',
'            if not mod(l_soma, 10) = 0 then',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''19'',',
'                    p_nome_campo      => p_campo,',
'                    p_parametro       => p_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => p_objeto_mensagem',
'                );   ',
'            end if;',
'        end if;',
'    exception',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_numero_cartao;',
'',
'    procedure valida_formato_placa_veiculo(',
'        p_placa           in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is',
'        l_placa     varchar2(20);',
'        l_parametro pkg_mensagem.paramentros;',
'    begin',
'        l_placa := upper(trim(regexp_replace(p_placa, ''[^A-Za-z0-9]'', '''')));        ',
'',
'        if l_placa is null or length(l_placa) <> 7 then ',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if; ',
'        if regexp_like(l_placa, ''^[A-Z]{3}[0-9]{4}$'') or regexp_like(l_placa, ''^[A-Z]{3}[0-9][A-Z][0-9]{2}$'') then',
'            null;',
'        else',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;',
'    exception',
'        when others then ',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_placa_veiculo;',
'',
'    procedure valida_formato_url (',
'        p_url             in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is ',
'        l_parametro pkg_mensagem.paramentros;',
'    begin        ',
'        if p_url is null then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;    ',
'        if regexp_like(p_url, ''.*[a-zA-Z0-9]+\.[a-zA-Z0-9]+.*'') then                              ',
'            null;',
'        else',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;        ',
'    exception',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_url;',
'',
'    procedure valida_formato_gtin (',
'        p_gtin            in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is',
'        l_gtin      varchar2(20);',
'        l_sum       number := 0;',
'        l_digit     number;',
'        l_parametro pkg_mensagem.paramentros;',
'    begin',
'        l_gtin := trim(regexp_replace(p_gtin, ''[^0-9]'', ''''));',
'',
'        if p_gtin is null or length(p_gtin) <> 13 or not regexp_like(p_gtin, ''^[0-9]+$'')then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );    ',
'        else',
'            for i in 1..12 loop',
'                l_digit := to_number(substr(l_gtin, i, 1));',
'                if i mod 2 = 0 then',
'                    l_sum := l_sum + (l_digit * 3);',
'                else',
'                    l_sum := l_sum + l_digit;',
'                end if;',
'            end loop;',
'            ',
'            l_digit := 10 - mod(l_sum, 10);',
'            if l_digit = 10 then',
'                l_digit := 0;',
'            end if;',
'',
'            if not l_digit = to_number(substr(l_gtin, 13, 1)) then',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''19'',',
'                    p_nome_campo      => p_campo,',
'                    p_parametro       => p_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => p_objeto_mensagem',
'                );',
'            end if;           ',
'        end if;',
'    exception',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_gtin;',
'',
'    procedure valida_formato_senha (',
'        p_senha           in varchar2,',
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is',
'        l_parametro pkg_mensagem.paramentros;',
'    begin    ',
'        l_parametro := p_parametro;',
'        l_parametro(2) :=    q''~  ',
unistr('                \2705 Formato final exigido para a senha:'),
unistr('                \2265 8 caracteres'),
unistr('                \2265 1 letra mai\00FAscula'),
unistr('                \2265 1 letra min\00FAscula'),
unistr('                \2265 1 n\00FAmero'),
unistr('                \2265 2 caracteres especiais'),
'        ~''; ',
'        if p_senha is null or length(p_senha) < 8 then ',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;',
'        if not regexp_like(p_senha, ''(.*[A-Z])'') or not regexp_like(p_senha, ''(.*[a-z])'') or not regexp_like(p_senha, ''(.*[0-9])'') or regexp_count(p_senha, ''[^a-zA-Z0-9]'') < 2 then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        end if;',
'    exception ',
'        when others then',
'            l_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''19'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => l_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'    end valida_formato_senha; ',
'',
'    procedure valida_formato_caracteres(',
'        p_caracteres      in varchar2,',
unistr('        p_tipo            in varchar2, -- 1=letras, 2=n\00FAmeros'),
'        p_campo           in varchar2,',
'        p_parametro       in pkg_mensagem.paramentros,',
'        p_pagina          in number,',
'        p_objeto_mensagem out pkg_mensagem.message_record',
'    ) is',
'    begin',
'        if p_tipo = 1 then',
'            if not regexp_like(p_caracteres, ''^[A-Za-z]+$'') then',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''19'',',
'                    p_nome_campo      => p_campo,',
'                    p_parametro       => p_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => p_objeto_mensagem',
'                ); ',
'            end if;',
'        elsif p_tipo = 2 then',
'            if not regexp_like(p_caracteres, ''^[0-9]+$'') then',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''19'',',
'                    p_nome_campo      => p_campo,',
'                    p_parametro       => p_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => p_objeto_mensagem',
'                ); ',
'            end if;',
'        end if;',
'    end valida_formato_caracteres;',
'    ',
'    procedure valida_largura_obrigatoria(',
'        p_largura_obrigatoria in varchar2,',
'        p_valor               in varchar2,',
'        p_campo               in varchar2,',
'        p_parametro           in pkg_mensagem.paramentros,',
'        p_pagina              in number,',
'        p_objeto_mensagem     out pkg_mensagem.message_record',
'    ) is',
'        l_parametro pkg_mensagem.paramentros;',
'    begin',
'        if length(p_valor) <> p_largura_obrigatoria then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''24'',',
'                p_nome_campo      => p_campo,',
'                p_parametro       => p_parametro,',
'                p_pagina          => p_pagina,',
'                p_objeto_mensagem => p_objeto_mensagem',
'            );',
'        else',
'            null;',
'        end if;',
'    end;',
