'    function retorna_nome_procedure(',
'        p_edicao in srv_entidade_coluna.edicao%type ',
'    ) return varchar2 is',
'        l_resultado clob;        ',
'    begin                    ',
'        case p_edicao ',
'            when ''1'' then l_resultado := ''cep'';',
'            when ''2'' then l_resultado := ''cnpj'';',
'            when ''3'' then l_resultado := ''cpf'';',
'            when ''4'' then l_resultado := ''data'';',
'            when ''5'' then l_resultado := ''data_hora'';',
'            when ''6'' then l_resultado := ''data_hora_minuto'';',
'            when ''7'' then l_resultado := ''data_hora_minuto_segundo'';',
'            when ''8'' then l_resultado := ''email'';',
'            when ''9'' then l_resultado := ''hora'';',
'            when ''10'' then l_resultado := ''hora_minuto'';',
'            when ''11'' then l_resultado := ''hora_minuto_segundo'';',
'            when ''12'' then l_resultado := ''inscricao_estadual'';',
'            when ''13'' then l_resultado := ''telefone'';',
'            when ''14'' then l_resultado := ''numero_cartao'';',
'            when ''15'' then l_resultado := ''senha'';',
'            when ''16'' then l_resultado := ''placa_veiculo'';',
'            when ''17'' then l_resultado := ''gtin'';',
'            when ''18'' then l_resultado := ''url'';',
'        else',
'            l_resultado := '''';',
'        end case;',
'        return l_resultado;                ',
'    end retorna_nome_procedure;',
'',
'    procedure executa_comando (',
'        p_sql             in clob,',
'        p_esquema         in varchar2 default null',
'    )is',
'        c_pkg constant varchar2(100) := ''pkg_util.executa_comando'';',
'        l_clob           clob;',
'        l_sql            clob;',
'        l_json_sql       clob;',
'        error_details    varchar2(4000);    ',
'        error_code       varchar2(4000);',
'        l_etapa          varchar2(200);',
'        l_token          varchar2(4000);',
'    begin',
'        l_etapa := ''INICIO'';',
'        log_debug(c_pkg, ''INICIO p_esquema=''||nvl(p_esquema,''<null>''));',
'',
'        l_etapa := ''MONTAR_SQL'';',
'        if p_esquema is not null then',
'            l_sql := replace(p_sql, ''#ESQUEMA#'', p_esquema);',
'            log_debug(c_pkg, ''SQL montado com esquema'');',
'        else',
'            l_sql := replace(p_sql, ''#ESQUEMA#'', '''');',
'            log_debug(c_pkg, ''SQL montado sem esquema'');',
'        end if;',
'',
'        log_debug(c_pkg, ''Tamanho SQL=''||dbms_lob.getlength(l_sql));',
'        log_debug(c_pkg, ''Trecho SQL=''||dbms_lob.substr(l_sql, 1500, 1));',
'',
'        l_etapa := ''OBTER_TOKEN'';',
'        l_token := retorna_token_ouath2(9999);',
'        log_debug(c_pkg, ''Token obtido com sucesso'');',
'',
'        l_etapa := ''CONFIGURAR_HEADERS'';',
'        apex_web_service.g_request_headers.delete();',
'        log_debug(c_pkg, ''Headers limpos'');',
'',
'        apex_web_service.g_request_headers(1).name := ''Authorization'';',
'        apex_web_service.g_request_headers(1).value := l_token;',
'        log_debug(c_pkg, ''Header Authorization definido'');',
'',
'        apex_web_service.g_request_headers(2).name := ''Content-Type'';',
'        apex_web_service.g_request_headers(2).value := ''application/json'';',
'        log_debug(c_pkg, ''Header Content-Type definido'');',
'',
'        l_etapa := ''MONTAR_JSON'';',
'        log_debug(c_pkg, ''Iniciando montagem do JSON via APEX_JSON'');',
'',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''statementText'', l_sql);',
'        apex_json.close_object;',
'',
'        l_json_sql := apex_json.get_clob_output;',
'',
'        log_debug(c_pkg, ''JSON montado com sucesso'');',
'        log_debug(c_pkg, ''Tamanho JSON=''||dbms_lob.getlength(l_json_sql));',
'        log_debug(c_pkg, ''Trecho JSON=''||dbms_lob.substr(l_json_sql, 1500, 1));',
'        log_debug(c_pkg, l_json_sql);',
'',
'        apex_json.free_output;',
'        log_debug(c_pkg, ''Buffer do APEX_JSON liberado'');',
'',
'        l_etapa := ''CHAMADA_REST'';',
'        log_debug(c_pkg, ''Iniciando chamada REST'');',
'',
'        l_clob := apex_web_service.make_rest_request(',
'            p_url         => ''https://geae26552a5af32-dbng.adb.sa-vinhedo-1.oraclecloudapps.com/ords/admin/_/sql'',',
'            p_body        => l_json_sql,',
'            p_http_method => ''POST''',
'        );',
'',
'        log_debug(c_pkg, ''Chamada REST finalizada'');',
'        log_debug(c_pkg, ''Tamanho retorno=''||dbms_lob.getlength(l_clob));',
'        log_debug(c_pkg, ''Retorno=''||dbms_lob.substr(l_clob, 1500, 1));',
'',
'        l_etapa := ''VALIDAR_BADREQUEST'';',
'        if instr(l_clob, ''"code": "BadRequest"'') > 0',
'           or instr(l_clob, ''"o:errorCode": "ORDS-24000"'') > 0 then',
'            log_debug(c_pkg, ''API retornou BadRequest/ORDS-24000'');',
'            raise_application_error(-20113, ''Erro ao interpretar JSON enviado para a API: ''||dbms_lob.substr(l_clob, 1500, 1));',
'        end if;',
'',
'        l_etapa := ''ANALISAR_RETORNO'';',
'        begin',
'            select json_value(l_clob, ''$.items[0].result''),',
'                   json_value(l_clob, ''$.items[0].response'')',
'              into error_code,',
'                   error_details',
'              from dual;',
'',
'            log_debug(c_pkg, ''error_code=''||nvl(error_code,''<null>''));',
'            log_debug(c_pkg, ''error_details=''||substr(nvl(error_details,''<null>''),1,2000));',
'',
'            if error_code is not null and error_code <> ''0'' then',
'                log_debug(c_pkg, ''Retorno da API indica erro'');',
'                raise_application_error(-20111, nvl(error_details, ''Erro ao executar comando remoto.''));',
'            end if;',
'        exception',
'            when others then',
'                log_debug(c_pkg, ''Falha ao interpretar JSON de retorno: sqlcode=''||sqlcode||'' sqlerrm=''||sqlerrm);',
'        end;',
'',
'        log_debug(c_pkg, ''FINALIZADO COM SUCESSO'');',
'',
'    exception ',
'        when others then',
'            begin',
'                apex_json.free_output;',
'            exception',
'                when others then',
'                    null;',
'            end;',
'',
'            grava_log2(',
'                ''[executa_comando] ERRO etapa=''||l_etapa||',
'                '' sqlcode=''||sqlcode||',
'                '' sqlerrm=''||sqlerrm',
'            );',
'',
'            if l_sql is not null then',
'                log_debug(c_pkg, ''SQL no erro=''||dbms_lob.substr(l_sql, 1500, 1));',
'            end if;',
'',
'            if l_json_sql is not null then',
'                log_debug(c_pkg, ''JSON no erro=''||dbms_lob.substr(l_json_sql, 1500, 1));',
'            end if;',
'',
'            if l_clob is not null then',
'                log_debug(c_pkg, ''RETORNO no erro=''||dbms_lob.substr(l_clob, 1500, 1));',
'            end if;',
'',
'            raise_application_error(',
'                -20112,',
'                ''Erro em executa_comando. Etapa: ''||l_etapa||'' - ''||sqlerrm',
'            );',
'    end executa_comando;',
'',
'    procedure executa_comando (',
'        p_sql             in clob,',
'        p_retorno         out clob',
'    )is',
'        l_json_sql CLOB;',
'        error_details varchar(4000);    ',
'    begin',
'        apex_web_service.g_request_headers.delete();',
'        apex_web_service.g_request_headers(1).name := ''Authorization'';',
'        apex_web_service.g_request_headers(1).value := RETORNA_TOKEN_OUATH2(9999); ',
'',
'        apex_web_service.g_request_headers(2).name := ''Content-Type'';',
'        apex_web_service.g_request_headers(2).value := ''application/json''; ',
'',
'        l_json_sql := TO_CLOB(''{ "statementText":"''||p_sql||'';"}'');',
'        --apex_debug.error(''executa_comando l_json_sql:%s'',l_json_sql); ',
'        --apex_debug.error(''executa_comando RETORNA_TOKEN_'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(16282830324567158)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'OUATH2(9999):%s'',RETORNA_TOKEN_OUATH2(9999)); ',
'',
'        p_retorno := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url               => ''https://geae26552a5af32-dbng.adb.sa-vinhedo-1.oraclecloudapps.com/ords/admin/_/sql'',',
'            p_body              => l_json_sql,',
'            p_http_method       => ''POST''',
'        );',
'         ',
'        select json_value(p_retorno, ''$.items[0].errorDetails'') into error_details from dual;    ',
'',
'        if error_details is not null then',
'           raise_application_error(-20111,error_details);',
'        end if;    ',
'    end executa_comando;    ',
'',
'    procedure executa_comando (',
'        p_sql             in clob,',
'        p_erro           out clob',
'    )is',
'        l_json_sql clob;',
'        error_details clob;    ',
'        p_retorno clob;    ',
'    begin',
'        apex_web_service.g_request_headers.delete();',
'        apex_web_service.g_request_headers(1).name := ''Authorization'';',
'        apex_web_service.g_request_headers(1).value := RETORNA_TOKEN_OUATH2(9999); ',
'',
'        apex_web_service.g_request_headers(2).name := ''Content-Type'';',
'        apex_web_service.g_request_headers(2).value := ''application/json''; ',
'',
'        l_json_sql := TO_CLOB(''{ "statementText":"''||p_sql||'';"}'');',
'        --apex_debug.error(''executa_comando l_json_sql:%s'',l_json_sql); ',
'        --apex_debug.error(''executa_comando RETORNA_TOKEN_OUATH2(9999):%s'',RETORNA_TOKEN_OUATH2(9999)); ',
'',
'        p_retorno := APEX_WEB_SERVICE.MAKE_REST_REQUEST(',
'            p_url               => ''https://geae26552a5af32-dbng.adb.sa-vinhedo-1.oraclecloudapps.com/ords/admin/_/sql'',',
'            p_body              => l_json_sql,',
'            p_http_method       => ''POST''',
'        );',
'        --apex_debug.error(''executa_comando p_retorno%s'',p_retorno); ',
'',
'        select json_value(p_retorno, ''$.items[0].errorDetails'') into error_details from dual;    ',
'        if error_details is not null then',
'           p_erro := error_details;',
'        else ',
'            select json_value(p_retorno, ''$.items[0].response'') into error_details from dual;    ',
'            if error_details like ''%error%'' or error_details like ''%ora-%'' then',
'                p_erro := error_details;',
'            end if;',
'        end if;    ',
'    end executa_comando;    ',
'',
'    function retorna_id_tag_origem (',
'        p_tag        varchar2,',
'        p_tipo_texto number',
'    ) return number is',
'        l_valor_1 varchar2(4000);',
'        l_valor_2 varchar2(4000);        ',
'        l_sql     varchar2(4000);        ',
'        l_retorno number;',
'    begin',
'        l_valor_1 := lower(regexp_substr(p_tag, ''[^.]+'', 1, 2));',
'        l_valor_2 := lower(regexp_substr(p_tag, ''[^.]+'', 1, 3));',
'',
'        if p_tipo_texto = 1 then',
'            l_sql := ''select id from srv_aplicacao_texto where lower(tag) = :1'';',
'            execute immediate l_sql into l_retorno using l_valor_1;            ',
'        elsif p_tipo_texto = 2 then',
'            l_sql := ''select a.id from srv_entidade_coluna a '' ||',
'                     ''join srv_entidade b on b.id = a.id_entidade '' ||',
'                     ''where lower(nome_entidade) = :1 and lower(nome_coluna) = :2'';',
'            execute immediate l_sql into l_retorno using l_valor_1, l_valor_2;            ',
'        elsif p_tipo_texto = 3 then',
'            l_sql := ''select id from srv_aplicacao_texto where lower(tag) = :1'';',
'            execute immediate l_sql into l_retorno using l_valor_1||''.''||l_valor_2;            ',
'        elsif p_tipo_texto = 4 then',
'            l_sql := ''select id from srv_artefato where codigo_artefato = :1'';',
'            execute immediate l_sql into l_retorno using l_valor_1;            ',
'        elsif p_tipo_texto = 5 then            ',
'            l_sql := ''select id from srv_aplicacao_mensagem where (codigo_mensagem) = :1'';',
'            execute immediate l_sql into l_retorno using l_valor_1;',
'        elsif p_tipo_texto = 6 then',
'            l_retorno := l_valor_1;',
'        elsif p_tipo_texto = 7 then',
'            l_retorno := l_valor_1;',
'        elsif p_tipo_texto = 8 then',
'            l_retorno := l_valor_1;',
'        end if;',
'',
'        return l_retorno;',
'        ',
'    end retorna_id_tag_origem;   ',
'',
'    procedure merge_tabelas(',
'        p_esquema clob,',
'        p_tabela_origem clob,',
'        p_tabela_destino clob,',
'        p_condicao clob,',
'        p_update clob,',
'        p_campos clob,',
'        p_valores clob',
'    ) is',
'        l_sql clob;',
'        l_tabela_destino clob;',
'    begin',
'        l_sql := replace(pk_constants.c_merge ,''#ESQUEMA#'',p_esquema);             ',
'        l_tabela_destino := replace(p_tabela_destino ,''#ESQUEMA#'',apex_application_install.get_schema);     ',
'        l_sql := replace(l_sql ,''#TABELA_DESTINO#'',l_tabela_destino);                     ',
'        l_sql := replace(l_sql ,''#TABELA_ORIGEM#'',p_tabela_origem);             ',
'        l_sql := replace(l_sql ,''#CONDICAO#'',p_condicao);             ',
'        l_sql := replace(l_sql ,''#UPDATE#'',p_update);             ',
'        l_sql := replace(l_sql ,''#CAMPOS#'',p_campos);             ',
'        l_sql := replace(l_sql ,''#VALORES#'',p_valores);             ',
'        l_sql := replace(l_sql ,''#ESQUEMA#'',p_esquema);             ',
'        grava_log2(l_sql);',
'        pkg_util.executa_comando(l_sql);',
'    end merge_tabelas;',
'',
'    function retorna_id_tenant_origem(',
'        p_id number,',
'        p_id_tabela number,',
'        p_consulta_fixa varchar2 default null',
'    ) return varchar2',
'    is',
'        l_nome_tabela varchar2(255);',
'        l_sql varchar2(255);',
'        l_id_tenant number;',
'        l_id_tenant_usuario_logado number;',
'        l_verifica_coluna_tenant number;        ',
'    begin                ',
'        if p_consulta_fixa is not null then',
'            execute immediate p_consulta_fixa into l_id_tenant;',
'            --l_id_tenant := p_consulta_fixa;',
'        else',
'            select nome_entidade into l_nome_tabela from srv_entidade where id = p_id_tabela;',
'            select count(1) into l_verifica_coluna_tenant from srv_entidade a join srv_entidade_coluna b on b.id_entidade = a.id where lower(a.nome_entidade) = lower(l_nome_tabela) and lower(b.nome_coluna) = ''id_tenant'';        ',
'            if l_verifica_coluna_tenant > 0 then',
'                l_sql := ''select id_tenant from ''||l_nome_tabela||'' where id = ''||p_id;',
'                execute immediate l_sql into l_id_tenant;                ',
'            end if;                    ',
'        end if;',
'        return l_id_tenant;   ',
'        exception',
'            when others then',
'                select id_tenant into l_id_tenant_usuario_logado from mpd_usuario_tenant where id_usuario = retorna_id_usuario_logado and rownum = 1;',
'                --return null;',
'                return l_id_tenant_usuario_logado;          ',
'    end;',
'',
'    function retorna_id_tenant_coluna(',
'        p_id number,',
'        p_id_coluna number        ',
'    ) return varchar2',
'    is',
'        l_entidade number;',
'        l_nome_tabela varchar2(255);',
'        l_sql varchar2(255);',
'        l_id_tenant number;',
'        l_id_tenant_usuario_logado number;',
'    begin        ',
'        select id_entidade into l_entidade from srv_entidade_coluna where id = p_id_coluna;',
'        select nome_entidade into l_nome_tabela from srv_entidade where id = l_entidade;',
'        l_sql := ''select id_tenant from ''||l_nome_tabela||'' where id = ''||p_id;',
'        execute immediate l_sql into l_id_tenant;        ',
'        return l_id_tenant;   ',
'        exception',
'            when others then',
'                select id_tenant into l_id_tenant_usuario_logado from mpd_usuario_tenant where id_usuario = retorna_id_usuario_logado and rownum = 1;',
'                --return null;',
'                return l_id_tenant_usuario_logado;          ',
'    end;',
'',
'    function retorna_descricao_idioma_logado(',
'        p_id number',
'    ) return varchar2 is',
'        l_return varchar2(256);',
'    begin',
'        select descricao into l_return from mpd_descricao where id_tabela in (select id from srv_entidade where lower(nome_entidade) = ''srv_idioma'') ',
'        and id_idioma = apex_util.get_session_state(''IDIOMA_LOGADO'') and id_chave_tabela = p_id;',
'        return l_return;',
'    end;',
'',
'    function retorna_codigo_idioma_logado ',
'    return varchar2 is',
'        l_return varchar2(256);',
'    begin',
'        select codigo ',
'          into l_return ',
'          from srv_idioma ',
'         where id = apex_util.get_session_state(''IDIOMA_LOGADO'');',
'',
'        return l_return;',
'',
'    exception',
'        when no_data_found then',
'            return ''pt-br'';',
'',
'        when others then',
'            return ''pt-br'';',
'    end;',
'',
'    function retorna_descricao_codigo_idioma(',
'        p_codigo varchar2',
'    ) return varchar2 is',
'        l_return varchar2(256);',
'    begin',
'        select descricao into l_return from mpd_descricao a join srv_idioma b on b.id = a.id_chave_tabela ',
'        where id_tabela in (select id from srv_entidade where lower(nome_entidade) = ''srv_idioma'') ',
'        and id_idioma = apex_util.get_session_state(''IDIOMA_LOGADO'') ',
'        and lower(b.codigo) = lower(p_codigo);',
'        return l_return;',
'    end;',
'',
'    function retorna_descricao(',
'        p_id number,',
'        nome_entidadeo varchar2',
'    ) return varchar2 is',
'        l_return varchar2(256);',
'    begin',
'        select descricao into l_return from mpd_descricao where id_tabela in (select id from srv_entidade where lower(nome_entidade) = lower(nome_entidadeo)) ',
'        and id_idioma = apex_util.get_session_state(''IDIOMA_LOGADO'') and id_chave_tabela = p_id;',
'        return l_return;',
'    end;',
'',
unistr('    -- Fun\00E7\00E3o utilizada para retornar o link de acesso as op\00E7\00F5es (atalhos) das colunas - (L\00E9o em 27/03/2025)'),
'    function retorna_link_cadastro(',
'        p_pagina in number,',
'        p_itens in varchar2 default null,',
'        p_valores in varchar2 default null',
'    ) return varchar2 is',
'        l_return varchar2(4000);',
'    begin',
'        if p_itens is null or p_valores is null then',
'            select apex_page.get_url(p_page => p_pagina, p_clear_cache => p_pagina) into l_return from dual;',
'        else',
'            select apex_page.get_url(p_page => p_pagina, p_items => p_itens, p_values => p_valores, p_clear_cache => p_pagina) into l_return from dual;',
'        end if;',
'        return l_return;',
'    exception',
'        when others then',
'            return null;',
'    end;',
'',
'   function ObterValoresDasColunas (p_consulta_sql in varchar2, p_formato in varchar2, p_tabela in textarray default null, p_icones in textarray default null, p_label_fixo in textarray default null, p_abrir_regiao in textarray default null, p_color_i'
||'nicial number default 1, p_tipo_label varchar2 default ''coluna'', p_classe varchar2 default '''')',
'   return varchar2 is',
'',
unistr('       -- Defini\00E7\00E3o de tipos e vari\00E1veis'),
'       TYPE ref_cursor IS REF CURSOR;',
unistr('       cursor_referencia   ref_cursor;     -- Cursor de refer\00EAncia'),
unistr('       numero_cursor       NUMBER;         -- N\00FAmero do cursor'),
'       quantidade_colunas  NUMBER;         -- Contador de colunas',
unistr('       descricao_colunas   DBMS_SQL.DESC_TAB;  -- Descri\00E7\00E3o das colunas'),
unistr('       valor_coluna        VARCHAR2(4000);   -- Vari\00E1vel para armazenar o valor de cada coluna'),
unistr('       resultado           VARCHAR2(4000);   -- Vari\00E1vel para armazenar o resultado final'),
'       v_html              clob;',
'       v_label             varchar2(4000);',
'       v_abrir_regiao      varchar2(4000);',
'       v_color             varchar2(4000);',
'       v_icone             varchar2(4000);',
'    BEGIN',
unistr('       -- Abrindo o cursor para a consulta din\00E2mica fornecida'),
'       OPEN cursor_referencia FOR p_consulta_sql;',
'       numero_cursor := DBMS_SQL.to_cursor_number(cursor_referencia);',
'',
'       -- Descrevendo as colunas do cursor',
'       DBMS_SQL.DESCRIBE_COLUMNS(numero_cursor, quantidade_colunas, descricao_colunas);',
'',
unistr('       -- Definindo as vari\00E1veis para cada coluna'),
'       FOR indice_coluna IN 1..quantidade_colunas LOOP',
'          DBMS_SQL.DEFINE_COLUMN(numero_cursor, indice_coluna, valor_coluna, 4000);',
'       END LOOP;',
'',
'       -- Inicializando a string de resultado',
'       resultado := ''Resultados das Colunas:'' || CHR(10);',
'',
'       -- Buscar e processar as linhas do cursor',
'       if lower(p_formato) = lower(''pequeno'') then',
'           v_html := ''<ul class="a-CardView-items a-CardView-items--grid t-CardsRegion u-colors lto95758567024685940_0 js-apex-region t-CardsRegion--styleC" style="display: ruby;">'';',
'       elsif lower(p_formato) = lower(''grande'') then',
'           v_html := ''<ul class="a-CardView-items a-CardView-items--grid t-CardsRegion u-colors lto95758567024685940_0 js-apex-region t-CardsRegion--styleB">'';',
'       end if;',
'       LOOP',
'          -- Fetch de uma linha do cursor',
'          IF DBMS_SQL.FETCH_ROWS(numero_cursor) > 0 THEN',
unistr('             -- Loop para percorrer as colunas e adicionar seus valores \00E0 string de resultado'),
'             FOR indice_coluna IN 1..quantidade_colunas LOOP',
'',
'                if p_tabela is not null then',
'                    v_label := p_tabela(indice_coluna)||''.''||descricao_colunas(indice_coluna).col_name;',
'                elsif p_label_fixo is not null then',
'                    v_label := p_label_fixo(indice_coluna);',
'                end if;',
'',
'                if p_abrir_regiao is not null then',
'                    v_abrir_regiao := p_abrir_regiao(indice_coluna);',
'                else',
'                    v_abrir_regiao := '''';',
'                end if;',
'                if p_icones is not null then',
'                    v_icone := p_icones(indice_coluna);',
'                else',
'                    v_icone := '''';',
'                end if;',
'',
'                v_color := p_color_inicial + indice_coluna;',
'                ',
'                dbms_sql.column_value(numero_cursor, indice_coluna, valor_coluna);',
'                v_html := v_html || pkg_componentes.html_card_cabecalho(v_label, v_icone,valor_coluna,p_color=>v_color, p_tipo_label => p_tipo_label, p_abrir_regiao => v_abrir_regiao, p_classe => p_classe);',
'                --v_html := v_html || pkg_componentes.html_campo(v_label, v_icone,valor_coluna,p_tipo_label => p_tipo_label,p_color=>v_color);',
'           ',
'             END LOOP;',
'',
'          ELSE',
unistr('             EXIT;  -- Sai do loop quando n\00E3o houver mais linhas'),
'          END IF;',
'       END LOOP;',
'       v_html := v_html || ''</ul>'';',
'',
'       -- Fecha o cursor',
'       DBMS_SQL.CLOSE_CURSOR(numero_cursor);',
'',
'       -- Retorna o resultado como uma string',
'       return v_html;        ',
'       ',
'    end ObterValoresDasColunas;',
'',
'    function retorna_descricao_ou_traducao(',
'        p_nome_entidade     varchar2,',
'        p_nome_coluna       varchar2,',
'        p_id_idioma_tenant  number,',
'        p_id_chave_entidade number    ',
'    ) return varchar2 is        ',
'        l_id_idioma_logado number := apex_util.get_session_state(''IDIOMA_LOGADO'');',
'        l_id_coluna        number;',
'        l_verificador      number;',
'        l_traducao_existe  number;',
'        l_texto_original   varchar2(255);',
'        l_result           varchar2(255);        ',
'    begin  ',
'        -- Primeiro verifica se p_nome_entidade e p_nome_coluna existem e combinam:            ',
'        select count(1) into l_verificador from mpd_entidade_coluna a join mpd_entidade b on b.id = a.id_entidade where trim(lower(a.nome_coluna)) = trim(lower(p_nome_coluna)) and trim(lower(b.nome_entidade)) = trim(lower(p_nome_entidade));        ',
'            ',
'            if l_verificador > 0 then -- Se existem e combinam:            ',
'            ',
unistr('                if p_id_idioma_tenant = nvl(l_id_idioma_logado, p_id_idioma_tenant) then -- Se o idioma logado \00E9 o mesmo do idioma da empresa:'),
'                    execute immediate ''select ''|| trim(lower(p_nome_coluna)) ||'' from '' || trim(lower(p_nome_entidade)) || '' where id = '' || p_id_chave_entidade',
'                    into l_result;                    ',
unistr('                else -- Se o idioma logado \00E9 diferente do idioma da empresa:'),
'                    select a.id into l_id_coluna from mpd_entidade_coluna a join mpd_entidade b on b.id = a.id_entidade where trim(lower(a.nome_coluna)) = trim(lower(p_nome_coluna)) and trim(lower(b.nome_entidade)) = trim(lower(p_nome_entidade));',
'                    ',
unistr('                    -- Verifica se existe tradu\00E7\00E3o:'),
'                    select count(1) into l_traducao_existe from ng_traducaotexto where id_chave_entidade = p_id_chave_entidade and id_campo = l_id_coluna and id_idioma = l_id_idioma_logado;',
'',
unistr('                    if l_traducao_existe > 0 then -- Se a tradu\00E7\00E3o existe:    '),
unistr('                        -- Busca a tradu\00E7\00E3o existente:'),
'                        select texto_traduzido into l_result from ng_traducaotexto where id_chave_entidade = p_id_chave_entidade and id_campo = l_id_coluna and id_idioma = l_id_idioma_logado;',
'                    ',
unistr('                    else -- Se a tradu\00E7\00E3o n\00E3o existe:                                                '),
'                        ',
'                        /* Reculpera o texto original para enviar para a API contratada */',
'                        execute immediate ''select ''|| trim(lower(p_nome_coluna)) ||'' from '' || trim(lower(p_nome_entidade)) || '' where id = '' || p_id_chave_entidade',
'                        into l_texto_original;',
'',
'                        /**********************************************',
'                            ',
unistr('                            CHAMAR A API DE TRADU\00C7\00C3O CONTRATADA AQUI '),
'',
'                        **********************************************/',
'                        ',
unistr('                        --l_result := pkg_ui.retorna_label_tela(''sem_traducao''); -- Retornando um texto gen\00E9rico no momento. '),
'                        ',
unistr('                        l_result := l_texto_original; -- Se n\00E3o existe tradu\00E7\00E3o cadastrada, mostra descri\00E7\00E3o original.'),
'                    end if;',
'                end if;',
unistr('            else  -- Se p_nome_entidade e p_nome_coluna n\00E3o existem ou n\00E3o combinam:'),
'                l_result := pkg_ui.retorna_label_tela(''entidade_coluna_inexistente''); -- Ajustar para exibir uma mensagem adequada...                    ',
'        end if;  ',
'        return l_result;',
'        exception',
'            when others then',
'                return null;',
'    end;',
'',
'    function tem_dependencia_chave_fk (',
'        p_nome_entidade   in varchar2,',
'        p_id_registro     in number,',
'        p_entidade        out varchar2',
'    ) return boolean is',
'        v_sql             varchar2(4000);',
'        v_count           number;',
'        v_registro        number;',
'        v_entidade_atual  varchar2(256);',
'    begin',
'        for fk_rec in (',
'            select a.id,',
'                   b.nome_entidade           as tabela_origem,',
'                   c.nome_entidade           as tabela_destino,',
'                   d.nome_coluna             as coluna_origem,',
'                   e.nome_coluna             as coluna_destino',
'            from srv_entidade_foreign_key a',
'            join srv_entidade b on b.id = a.id_entidade',
'            join srv_entidade c on c.id = a.id_entidade_estrangeira',
'            join srv_entidade_coluna d on d.id = a.id_coluna_origem',
'            join srv_entidade_coluna e on e.id = a.id_coluna_destino',
'            where c.id = (select id from srv_entidade where upper(nome_entidade) = upper(p_nome_entidade))',
'              and upper(a.acao_ao_deletar_estrangeira) = upper(''R'')',
'        ) loop',
'            v_entidade_atual := fk_rec.tabela_origem;',
'',
'            begin',
unistr('                -- monta sql din\00E2mico para verificar se h\00E1 depend\00EAncia'),
'                v_sql := ''select count(*) from '' || fk_rec.tabela_origem ||',
'                         '' where '' || fk_rec.coluna_origem || '' = :1'';',
'',
'                execute immediate v_sql into v_count using p_id_registro;',
'',
'                if v_count > 0 then',
'                    p_entidade := fk_rec.tabela_origem;',
unistr('                    return true; -- existe depend\00EAncia (n\00E3o pode deletar)'),
'                end if;',
'            exception',
'                when others then',
'                    -- registra o erro e continua verificando as demais tabelas',
'                    apex_debug.enable(apex_debug.c_log_level_info);',
unistr('                    apex_debug.info(''Aviso: falha ao verificar depend\00EAncia em ''||v_entidade_atual||'' - Erro: ''||sqlerrm);    '),
'                    -- dbms_output.put_line(',
unistr('                    --     ''Aviso: falha ao verificar depend\00EAncia em ''||v_entidade_atual||'),
'                    --     '' - Erro: ''||sqlerrm',
'                    -- );',
'                    -- continua o loop',
'            end;',
'        end loop;',
'',
unistr('        return false; -- nenhuma depend\00EAncia encontrada'),
'    end;',
'',
unistr('    /* Overload \2013 sem OUT */'),
'    function tem_dependencia_chave_fk (',
'        p_nome_entidade in varchar2,',
'        p_id_registro   in number',
'    ) return boolean is',
'        v_dummy varchar2(4000);',
'    begin',
'        return tem_dependencia_chave_fk(p_nome_entidade, p_id_registro, v_dummy);',
'    end;',
'',
'    function retorna_number (',
'        p_numero                  in varchar2',
'    ) return number is',
'    begin',
'        return replace(p_numero,separador_numerico,'''');',
'    end;',
'',
'    procedure download_packages(',
'        p_id in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is        ',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(1) := ''Download packages ZIP realizado'';   ',
'        v_parametro(0) := ''pkg_util.download_packages'';',
'',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_acao, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        ',
'        apex_util.redirect_url(''javascript:apex.navigation.dialog.close(true);window.open(''''f?p='' || v(''APP_ID'') || '':0:'' || v(''APP_SESSION'') || '':APPLICATION_PROCESS=DOWNLOAD_PACKAGES_ZIP'''', ''''_blank'''')'');                ',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'            when others then',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_acao, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'    end;  ',
'',
'    function valor_referencia(',
'        p_id in number,',
'        p_nome_entidade in varchar2',
'    ) return varchar2 is',
'        l_resultado varchar2(4000);',
'        l_colunas_ref varchar2(4000);',
'        v_sql varchar2(4000);',
'    begin',
'        for reccoluna in (',
'            select listagg(nome_coluna, ''#'') within group (order by referencia) as colunas_ref',
'            from srv_entidade_coluna',
'            where id_entidade = (select id from srv_entidade where upper(nome_entidade) = upper(p_nome_entidade)) and upper(referencia) is not null and upper(nome_coluna) not like ''id_%''',
'        ) loop',
'            l_colunas_ref := replace(reccoluna.colunas_ref, ''#'', '' || '''' - '''' || '');',
'            if p_id is not null then',
'                v_sql := ''select '' || l_colunas_ref || '' from '' || p_nome_entidade|| '' where id = '' || p_id;',
'                execute immediate v_sql into l_resultado;',
'            end if;',
'        end loop;',
'',
'        return l_resultado;',
'    end;',
'',
'end "PKG_UTIL";',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_componentes
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16285990940391596)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_COMPONENTES'
,p_sequence=>320
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace PACKAGE "PKG_COMPONENTES" IS  ',
'/*',
'        <div class="mb-4">',
'            <!-- Container da barra -->',
'            <div class="w-full bg-gray-200 rounded-full h-6 overflow-hidden">',
'                <!-- Barra de progresso interna (a que se move) -->',
'                <div id="progressBar_#ID#" class="bg-blue-600 h-6 rounded-full flex items-center justify-center" style="width: #PERCENTUAL#%;">',
'                    <!-- Texto com valores e percentagem -->',
'                    <span id="progressText_#ID#" class="text-white text-xs font-medium px-2">#PERCENTUAL#%</span>',
'                </div>                ',
'            </div>',
'        </div>',
'*/',
'    c_html_progress_bar constant varchar2(4000) :=',
'    q''~  ',
'        <div style="margin-bottom: 1rem;">',
'          <!-- Container da barra -->',
'          <div style="width: 100%; background-color: #e5e7eb; border-radius: 9999px; height: 1.5rem; overflow: hidden;">',
'            <!-- Barra de progresso interna (a que se move) -->',
'            <div id="progressBar_#ID#" ',
'                 style="background-color: #2563eb; height: 1.5rem; border-radius: 9999px; display: flex; align-items: center; justify-content: center; width: #PERCENTUAL#%;">',
'              <!-- Texto com valores e percentagem -->',
'              <span id="progressText_#ID#" ',
'                    style="color: white; font-size: 0.75rem; font-weight: 500; padding-left: 0.5rem; padding-right: 0.5rem;">',
'                #PERCENTUAL#%',
'              </span>',
'            </div>',
'          </div>',
'        </div>        ',
'    ~''; ',
'',
'    c_html_label_destaque_danger constant varchar2(256) :=',
'    q''~  ',
unistr('        <span class="destaque destaque--danger">Cr\00EDtico</span>'),
'    ~''; ',
'',
'    c_html_label_destaque_warning constant varchar2(256) :=',
'    q''~  ',
'        <span class="destaque destaque--warning">Moderado</span>',
'    ~''; ',
'',
'    c_html_label_destaque_success constant varchar2(256) :=',
'    q''~  ',
unistr('        <span class="destaque destaque--success">Satisfat\00F3rio</span>'),
'    ~''; ',
'',
'',
'    c_html_log_bloco_geral constant clob := ',
'    q''~  ',
'        <script src="https://cdn.tailwindcss.com"></script>',
'        <link rel="preconnect" href="https://fonts.googleapis.com">',
'        <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>',
'        <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">',
'        <style>',
'            body {',
'                   font-family: ''Inter'', sans-serif;',
'                   color: #f8fafc; /* gray-50 */',
'                   background-color: #f8fafc; /* gray-50 */',
'            }',
'            /* Estilo para a linha da timeline */',
'            .cor-fundo{',
'                background-color: var(--cor-fundo-cabecalho-card);',
'            }',
'            -- .fundo-item{',
'            --     padding: 1rem;',
'            --     background-color: var(--cor-fundo-cabecalho-card);',
'            --     border-radius: 1rem;            ',
'            -- }',
'            .timeline-line {',
'                position: absolute;',
unistr('                left: 1.25rem; /* Posi\00E7\00E3o do \00EDcone */'),
'                top: 1.25rem;',
'                bottom: -1.25rem;',
'                width: 2px;',
'                background-color: #e2e8f0; /* slate-200 */',
'                transform: translateX(-50%);',
'            }',
unistr('            /* Garante que a \00FAltima linha n\00E3o apare\00E7a */'),
'            .timeline-item:last-child .timeline-line {',
'                display: none;',
'            }',
'        </style>    ',
'        <div class="max-w-4xl mx-auto bg-white rounded-xl shadow-sm border border-slate-200">',
'          <div class="p-6 border-b cor-fundo border-slate-200" style="border-top-right-radius: 0.75rem;border-top-left-radius: 0.75rem;">',
