'/',
'create or replace PACKAGE body "PKG_COMPONENTES" IS  ',
'',
'    function html_icone_lista(p_classe varchar2 default ''fa-square-o'', p_cor varchar2 default ''u-color'', p_titulo varchar2 default null) return varchar2',
'    is',
'        l_icone_lista varchar2(4000);',
'    begin',
'        l_icone_lista := replace(c_icone_lista,''#CLASSE#'',p_classe);',
'        l_icone_lista := replace(l_icone_lista,''#COR#'',p_cor);',
'        l_icone_lista := replace(l_icone_lista,''#TITULO#'',p_titulo);',
'        return l_icone_lista; ',
'    end html_icone_lista;',
'',
'    function html_card_title (  ',
'        p_descricao  in varchar2',
'    ) return varchar2 is',
'    begin',
'        return ''<div class="st-card-title">''||p_descricao||''</div>'';',
'    end html_card_title;',
'',
'    function html_cor_texto(',
'        p_coluna in varchar2',
'    ) return varchar2 is',
'    begin',
'        return ''<span style="color:red;">'' || p_coluna || ''</span>'';',
'    end;',
'',
'    function html_icone_situacao return varchar2 is',
'        l_hover_ind_situacao varchar2(4000);',
'    begin',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual; ',
'        return ''<i title="''||l_hover_ind_situacao||''" class="fa fa-exclamation-triangle" style="color:orange; font-size:small" aria-hidden="true"></i>'';',
'    end;',
'',
'    function html_icone_pendente(',
'        p_tipo number default 0',
'    ) return varchar2 is',
'        l_hover varchar2(4000);',
'    begin',
'        if p_tipo = 0 then        ',
'            select pkg_ui.retorna_label_tela(''fk_pendente'') into l_hover from dual;',
'            return ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon fa fa-warning" style="color: red; background-color: #E9E9E9;" aria-hidden="true" title="''||l_hover||''"></span></div>'';        ',
'        elsif p_tipo = 1 then',
'            select pkg_ui.retorna_label_tela(''fk_efetiva'') into l_hover from dual;',
'            return ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon fa fa-check-circle" style="color: green; background-color: #E9E9E9;" aria-hidden="true" title="''||l_hover||''"></span></div>'';        ',
'        end if;',
'    end;',
'',
'    function html_card_detail (  ',
'        p_descricao  in varchar2,  ',
'        p_icone      in varchar2,  ',
'        p_valor      in varchar2, ',
'        p_class      in varchar2 default '''', ',
'        p_ultimo     in varchar2 default ''n'', ',
'        p_label_fixo in varchar2 default ''n'', ',
'        p_color      in varchar2 default ''1'', ',
'        p_link_foto  in varchar2 default ''n''',
'    ) return varchar2 is  ',
'        l_html varchar2(2000); ',
'        l_label varchar(2000);  ',
'        l_style_1 varchar(2000);  ',
'        l_style_2 varchar(2000);  ',
'    begin  ',
'        if lower(p_label_fixo) = ''s'' then ',
'            l_label := p_descricao; ',
'        else ',
'            l_label := pkg_ui.retorna_label_coluna(p_descricao); ',
'        end if; ',
'        if lower(p_link_foto) = ''n'' then',
'            l_style_1 := ''display: none;'';',
'            l_style_2 := '''';',
'        else',
'            l_style_1 := '''';',
'            l_style_2 := ''display: none;'';',
'        end if;',
'        l_html :=   ',
'        ''<div class="a-CardView-header ''|| case when lower(p_ultimo) = ''s'' then ''padding-bottom-md'' else ''padding-bottom-none'' END ||'' ">''||  ',
'        ''    <div class="a-CardView-iconWrap a-CardView-iconWrap--start">''||  ',
'        ''        <img src="''||p_link_foto||''" class="a-CardView-iconImg" style="''||l_style_1||''">''||',
'        ''        <span class="a-CardView-icon u-color-''||p_color||'' fa ''||P_ICONE||''" style="''||l_style_2||'' " aria-hidden="true" title=""></span>''||  ',
'        ''    </div>''||  ',
'        ''    <div class="a-CardView-headerBody">''||  ',
'        ''        <div class="u-font-size-sm u-italics">''||l_label||''</div>''||  ',
'        ''        <div class="row">''||  ',
'        ''            <div class="col col-12 apex-col-auto col-start">''||  ',
'        ''                <div class="u-font-size-sm u-bold overflow_line''|| P_CLASS ||''">''||P_VALOR||''</div>''||  ',
'        ''            </div>''||  ',
'        ''        </div>''||  ',
'        ''    </div>''||  ',
'        ''</div>'';  ',
'        return l_html;  ',
'    end html_card_detail;  ',
'',
'    function html_campo (  ',
'        p_descricao  in varchar2,  ',
'        p_icone      in varchar2,  ',
'        p_valor      in varchar2, ',
'        p_tipo_label in varchar2 default ''coluna'', ',
'        p_color      in varchar2 default ''1''',
'    ) return varchar2 is  ',
'        l_html varchar2(2000); ',
'        l_label varchar(2000);  ',
'    begin  ',
'        if lower(p_tipo_label) = lower(''tela'') then ',
'            l_label := pkg_ui.retorna_label_tela(p_descricao);',
'        elsif lower(p_tipo_label) = lower(''coluna'') then',
'            l_label := pkg_ui.retorna_label_coluna(p_descricao); ',
'        elsif lower(p_tipo_label) = lower(''fixo'') then',
'            l_label := p_descricao; ',
'        end if; ',
'',
'        l_html := ',
'            ''<div class="a-CardView-header">''||',
