'                       '' </div>'';',
'            l_html := replace(l_html,''#ICONE#'',l_icone);',
'        else',
'            l_html := replace(l_html,''#ICONE#'','''');',
'        end if;',
'',
'        if p_abrir_regiao is not null then',
'            l_vermais := ''<div class="">''||',
'            ''               <div class="a-CardView-actionsPrimary">''||',
'            ''                 <span class="a-CardView-button t-Button--link" onClick="openRegion(''||aspas(p_abrir_regiao)||'')">Ver mais</span>''||',
'            ''               </div>''||',
'            ''             </div>'';',
'            l_html := replace(l_html,''#VER_MAIS#'',l_vermais);',
'        else',
'            l_html := replace(l_html,''#VER_MAIS#'','''');',
'        end if;',
'',
'        return l_html;  ',
'    end html_card_campo;',
