'    function html_botao_ordenar (',
'        p_id_botao in varchar2,',
'        p_id_regiao in varchar2',
'    ) return clob is',
'        l_html clob;',
'        l_label_botao varchar2(256);',
'    begin',
'        l_label_botao := pkg_ui.retorna_label_tela(''ordenar'');',
'        l_html :=',
'            ''<div class="a-Button t-Button--link" style="padding:12px;white-space: normal; text-align: left;" label="''||l_label_botao||''" id="''||p_id_botao||''">''||l_label_botao||''</div>''||',
'            ''<script>''||',
