'            ''        apex.theme.openRegion("''||p_id_regiao||''");''||',
'            ''    });''||',
'            ''</script>'';',
'        return l_html;',
'    end;',
'',
'    function json_to_html_grid(p_json clob) return clob is',
'        j          apex_json.t_values;',
'        l_html     clob := '''';',
'        l_html_aux clob := '''';',
'        l_html_cabecalho clob := '''';',
'        l_html_valor clob := '''';',
'        i          pls_integer;',
'        l_count    pls_integer;',
'        l_json clob := '''';',
'    begin',
unistr('        -- usa json padr\00E3o se p_json for nulo ou vazio'),
'        l_json := nvl(p_json,''{"id_tenant":43,"nome_cidade":"lages","id_estado":30,"id_pais":1,"data_fim_vigencia":"2025-07-11t00:00:00z","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","n'
||'ome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cidade":"lages","nome_cida'
||'de":"lages"}'');',
'            ',
'        if p_json is not null then',
'            -- parseia o json',
'            apex_json.parse(j, p_json);',
'',
unistr('            -- obt\00E9m o n\00FAmero de membros no objeto json raiz'),
'            l_count := apex_json.get_count(p_path => ''.'', p_values => j);',
'',
unistr('            -- monta o cabe\00E7alho da tabela'),
'            l_html := c_classic_report;',
'            for i in 1 .. l_count loop',
'                l_html_aux := replace(c_classic_report_cabecalho,''#LABEL#'',apex_json.get_members(p_path=>''.'',p_values=>j)(i)); ',
'                l_html_aux := replace(l_html_aux,''#NOME_COLUNA#'',apex_json.get_members(p_path=>''.'',p_values=>j)(i)); ',
'                l_html_cabecalho := l_html_cabecalho || l_html_aux;',
'            end loop;',
'',
'            -- monta os valores correspondentes',
'            for i in 1 .. l_count loop',
'                l_html_aux := replace(c_classic_report_valores,''#VALOR#'',apex_json.get_varchar2(',
'                                    p_path    => apex_json.get_members(p_path=>''.'',p_values=>j)(i),',
'                                    p_values  => j',
'                                ));',
'                l_html_aux := replace(l_html_aux,''#NOME_COLUNA#'',apex_json.get_members(p_path=>''.'',p_values=>j)(i));',
'                l_html_valor := l_html_valor || l_html_aux;',
'            end loop;',
'',
'            l_html := replace(l_html,''#CABECALHO#'',l_html_cabecalho);',
'            l_html := replace(l_html,''#VALORES#'',l_html_valor);',
'',
'            return l_html;',
'        else',
'            l_html := c_classic_report;',
'            l_html := replace(l_html,''#CABECALHO#'',pkg_ui.retorna_label_botao(''nenhum-registro''));',
'            l_html := replace(l_html,''#VALORES#'','''');',
'            return l_html;',
'        end if;',
'    end json_to_html_grid;    ',
'',
'    function select_to_html_grid(p_sql clob, p_label_fixo varchar default ''n'') return clob is',
'        -- Definir um tipo para uma linha de dados',
'        TYPE t_uma_linha IS TABLE OF pk_types.t_detalhe INDEX BY PLS_INTEGER;',
'        -- Definir um tipo para todas as linhas (um array de t_uma_linha)',
'        TYPE t_todas_linhas IS TABLE OF t_uma_linha INDEX BY PLS_INTEGER;',
'',
unistr('        v_todas_linhas   t_todas_linhas; -- Nova vari\00E1vel para armazenar todas as linhas'),
'        c                number;',
'        cntCols          number;',
'        cols             dbms_sql.desc_tab2;',
'        colValue         varchar2(4000);',
'        tag              varchar2(4000);',
'        l_html           clob := '''';',
'        l_html_cabecalho clob := '''';',
'        l_html_valores_geral clob := ''''; -- Para concatenar o HTML de todas as linhas de valores',
'        i                pls_integer;',
'        linha_idx        pls_integer := 0; -- Contador para as linhas',
'        l_label          varchar2(4000);',
'    begin',
'        c := dbms_sql.open_cursor;',
'        dbms_sql.parse(c, p_sql, dbms_sql.native);',
'        dbms_sql.describe_columns2(c, cntCols, cols);',
'',
'        -- Definir as colunas para o fetch',
'        for i in 1 .. cntCols loop',
'            dbms_sql.define_column(c, i, colValue, 4000);',
'        end loop;',
'',
unistr('        -- Constru\00E7\00E3o do cabe\00E7alho uma \00FAnica vez'),
unistr('        l_html := c_classic_report; -- Supondo que c_classic_report \00E9 a estrutura base do grid'),
'        if cntCols > 0 then',
'            for i in 1 .. cntCols loop',
'                tag := replace(cols(i).col_name,''$'',''.'');',
'                if p_label_fixo = ''n'' then',
'                    l_label := pkg_ui.retorna_coluna(tag);',
unistr('                    if instr(l_label, ''Texto indispon\00EDvel'') > 0  then'),
'                        l_label := pkg_ui.retorna_label_botao(tag);',
'                    end if;',
'                    l_html_cabecalho := l_html_cabecalho || replace(c_classic_report_cabecalho,''#LABEL#'',l_label);                                        ',
'                else',
'                    l_html_cabecalho := l_html_cabecalho || replace(c_classic_report_cabecalho,''#LABEL#'',tag);',
'                end if;',
'            end loop;',
'        end if;',
'',
'        -- Executa a consulta e itera sobre todas as linhas',
'        if dbms_sql.execute(c) = 0 then',
'            while dbms_sql.fetch_rows(c) > 0 loop',
'                linha_idx := linha_idx + 1; -- Incrementa o contador de linha',
'                v_todas_linhas(linha_idx) := t_uma_linha(); -- Inicializa a linha atual',
'',
'                -- Extrai os valores para a linha atual',
'                for i in 1 .. cntCols loop',
'                    dbms_sql.column_value(c, i, colValue);',
'                    tag := replace(cols(i).col_name,''$'',''.'');',
'',
'                    -- Armazena o detalhe (label e valor) para a coluna atual da linha atual',
'                    if p_label_fixo = ''n'' then',
'                        v_todas_linhas(linha_idx)(i) := pk_types.t_detalhe(pkg_ui.retorna_coluna(tag), colValue);',
'                    else',
'                        v_todas_linhas(linha_idx)(i) := pk_types.t_detalhe(tag, colValue);',
'                    end if;',
'                end loop;',
'            end loop;',
'        end if;',
unistr('        dbms_sql.close_cursor(c); -- Fechar o cursor ap\00F3s o fetch'),
'',
'        -- Montagem do HTML dos valores',
'        if v_todas_linhas.count > 0 then',
'            -- Percorre cada linha que foi coletada',
'            for l_idx in 1 .. v_todas_linhas.count loop',
'                l_html_valores_geral := l_html_valores_geral || ''<tr>''; -- Abre a tag de linha para cada registro',
'                -- Percorre cada coluna da linha atual',
'                for c_idx in 1 .. v_todas_linhas(l_idx).count loop',
'                    -- Adiciona o valor da coluna atual da linha atual',
'                    l_html_valores_geral := l_html_valores_geral || replace(c_classic_report_valores,''#VALOR#'',v_todas_linhas(l_idx)(c_idx).value);',
'                end loop;',
'                l_html_valores_geral := l_html_valores_geral || ''</tr>''; -- Fecha a tag de linha',
'            end loop;',
'        end if;',
'',
unistr('        -- Substitui\00E7\00F5es finais no HTML'),
'        l_html := replace(l_html,''#CABECALHO#'',l_html_cabecalho);',
'        l_html := replace(l_html,''#VALORES#'',l_html_valores_geral);',
'',
'        return l_html;',
'',
'    exception',
'        when others then',
'            if dbms_sql.is_open(c) then',
'                dbms_sql.close_cursor(c);',
'            end if;',
unistr('            raise; -- Re-lan\00E7a a exce\00E7\00E3o ap\00F3s fechar o cursor'),
'    end select_to_html_grid;',
'',
'    -- function select_to_html_grid(p_sql clob, p_label_fixo varchar default ''n'') return clob is',
'    --     v_detalhes         pk_types.t_detalhes := pk_types.t_detalhes(); ',
'    --     c          number; ',
'    --     cntCols    number; ',
'    --     cols       dbms_sql.desc_tab2;  ',
'    --     colValue   varchar2(4000); ',
'    --     tag        varchar2(4000); ',
'    --     l_html     clob := '''';',
'    --     l_html_aux clob := '''';',
'    --     l_html_cabecalho clob := '''';',
'    --     l_html_valor clob := '''';',
'    --     i          pls_integer;',
'    -- begin',
'    --     c := dbms_sql.open_cursor; ',
'    --     dbms_sql.parse(c, p_sql, dbms_sql.native); ',
'    --     dbms_sql.describe_columns2(c, cntCols, cols); ',
' ',
'    --     for i in 1 .. cntCols loop ',
'    --         dbms_sql.define_column(c, i, colValue, 4000); ',
'    --     end loop;         ',
' ',
'    --     v_detalhes.extend(cntCols); ',
'    --     if dbms_sql.execute(c) = 0 then ',
'    --         while dbms_sql.fetch_rows(c) > 0 loop         ',
'    --             for i in 1 .. cntCols loop ',
'    --                 dbms_sql.column_value(c, i, colValue); ',
'    --                 tag := replace(cols(i).col_name,''$'',''.'');',
'',
'    --                 if p_label_fixo = ''n'' then                        ',
'    --                     v_detalhes(i) := pk_types.t_detalhe(pkg_ui.retorna_coluna(tag), colValue); ',
'    --                 else',
'    --                     v_detalhes(i) := pk_types.t_detalhe(tag, colValue); ',
'    --                 end if;',
'    --             end loop; ',
'    --         end loop; ',
'    --     end if; ',
'',
'    --     if v_detalhes.count > 0 then',
'    --         l_html := c_classic_report;',
'    --         for i in 1..v_detalhes.count loop ',
'    --             l_html_aux := replace(c_classic_report_cabecalho,''#LABEL#'',v_detalhes(i).label); ',
'    --             --l_html_aux := replace(l_html_aux,''#NOME_COLUNA#'',apex_json.get_members(p_path=>''.'',p_values=>j)(i)); ',
'    --             l_html_cabecalho := l_html_cabecalho || l_html_aux;',
'    --         end loop; ',
'',
'    --         for i in 1..v_detalhes.count loop ',
'    --             l_html_aux := replace(c_classic_report_valores,''#VALOR#'',v_detalhes(i).value);',
'    --             l_html_valor := l_html_valor || l_html_aux;',
'    --         end loop; ',
'',
'    --         l_html := replace(l_html,''#CABECALHO#'',l_html_cabecalho);',
'    --         l_html := replace(l_html,''#VALORES#'',l_html_valor);',
'',
'    --         return l_html;',
'    --     else',
'    --         l_html := c_classic_report;',
'    --         l_html := replace(l_html,''#CABECALHO#'',pkg_ui.retorna_label_botao(''nenhum-registro''));',
'    --         l_html := replace(l_html,''#VALORES#'','''');',
'    --         return l_html;',
'    --     end if;',
'    -- end select_to_html_grid;    ',
'',
'',
'    function html_coluna_checkbox(id in number) return varchar2 is ',
'        l_html varchar2(256);',
'    begin',
'        l_html := ',
'        q''~  ',
'            apex_item.checkbox(1,#ID#,''onclick="seleciona(this);"'')',
'        ~''; ',
'        return replace(l_html,''#ID#'',id);',
'    end;',
'',
'    function html_label_destaque(opcao in number) return varchar2 is',
'        l_html varchar2(1024);',
'    begin',
'        case opcao ',
'            when 1 then l_html := c_html_label_destaque_success;',
'            when 2 then l_html := c_html_label_destaque_warning;',
'            when 3 then l_html := c_html_label_destaque_danger;',
'        end case;',
'        return l_html;',
'    end;    ',
'',
'    function html_progress_bar(p_id in number,p_atual in number,p_total in number) return varchar2 is',
'        l_html_progress_bar varchar2(4000);',
'    begin',
'        l_html_progress_bar := replace(c_html_progress_bar,''#ID#'',p_id);',
'        l_html_progress_bar := replace(l_html_progress_bar,''#ATUAL#'',p_atual);',
'        l_html_progress_bar := replace(l_html_progress_bar,''#TOTAL#'',p_total);',
'        l_html_progress_bar := replace(l_html_progress_bar,''#PERCENTUAL#'',ROUND((p_atual / p_total) * 100));',
'        ',
'        return l_html_progress_bar;',
'    end;',
'',
'    function retorna_icone_viatransporte_card(',
'        p_icon_class varchar2,',
'        p_title varchar2',
'    ) return varchar2 is',
'    begin',
'        return ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start">'' ||',
'               ''<span class="a-CardView-icon u-color fa '' || p_icon_class ||',
'               ''" aria-hidden="true" title="'' || p_title || ''"></span>'' ||',
'               ''</div>'';',
'    end;',
'',
'END "PKG_COMPONENTES";',
'/'))
);
end;
