,p_name=>'WHERE_TENANT_ID'
,p_sequence=>340
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace function where_tenant_id',
'  (object_schema in varchar2',
'  ,object_name in varchar2) ',
'return varchar2',
'is',
'    l_sql varchar2(2000);',
'    l_sql_where varchar2(2000);',
'    l_tenant_list varchar2(2000);',
'    l_existetenant number;',
'    l_existecadastrocompartilhado number;',
'    l_client_identifier varchar2(2000);',
'',
'    type collect_tenant is record (',
'      id_tenant                number,',
'      id_tenant_cedente number',
'    );',
'',
'    type collect_tenant_row is table of collect_tenant',
'      index by pls_integer;',
'',
'    l_tenant_sub   collect_tenant_row;',
'',
'begin',
'    IF sys_context(''APP_CTX'',''ROLE'') = ''SYSTEM_JOB''  THEN',
'       RETURN ''1=1'';',
'    END IF;',
'',
'    l_tenant_list := valor_client_identifier(''TENANT'');',
'    if l_tenant_list is null then',
'        l_tenant_list := lista_tenant_usuario(null);',
'    end if;',
'',
'    l_sql_where := ''id in ('' || l_tenant_list || '')'';',
'',
'    l_sql := ',
'    '' select count(1) ''||',
'    '' from mpd_tenant_cadastro_compartilhado a ''||',
'    '' join mpd_cadastro_compartilhavel b on b.id = a.id_cadastro_compartilhavel ''||',
'    '' join mpd_cadastro_compartilhavel_entidade c on c.id_cadastro_compartilhavel = b.id ''||',
'    '' where lower(trim(c.nome_entidade)) = lower(''''''||object_name||'''''') ''||',
'    ''  and to_char(a.id_tenant) in ( ''||l_tenant_list||'' )'';',
'',
'    execute immediate l_sql into l_existecadastrocompartilhado;',
'',
'    if l_existecadastrocompartilhado > 0 then',
'        l_sql := ',
'        '' select id_tenant, id_tenant_cedente ''||',
'        '' from mpd_tenant_cadastro_compartilhado a ''||',
'        '' join mpd_cadastro_compartilhavel b on b.id = a.id_cadastro_compartilhavel ''||',
'        '' join mpd_cadastro_compartilhavel_entidade c on c.id_cadastro_compartilhavel = b.id ''||',
'        '' where lower(trim(c.nome_entidade)) = lower(''''''||object_name||'''''') ''||',
'        ''  and to_char(a.id_tenant) in ( ''||l_tenant_list||'' )'';',
'',
'        execute immediate l_sql bulk collect into l_tenant_sub;',
'        for indx in 1 .. l_tenant_sub.count',
'        loop',
'            if l_tenant_sub(indx).id_tenant_cedente is not null then',
'                l_tenant_list := replace(l_tenant_list, l_tenant_sub(indx).id_tenant, l_tenant_sub(indx).id_tenant_cedente);',
'            end if;',
'        end loop;',
'',
'        l_sql_where := '' id in ('' || l_tenant_list || '')'';',
'    end if;',
'',
'    --apex_debug.error(''where_tenant l_sql_where %s'', l_sql_where);',
'',
'    return l_sql_where;',
'    exception',
'        when others then',
'            apex_debug.error(''critical error %s'', sqlerrm);',
'',
'end where_tenant_id;',
'/'))
);
end;
/
