prompt --application/deployment/install/install_pkg_data
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(16287421270265955)
,p_install_id=>wwv_flow_imp.id(216780107998249685)
,p_name=>'PKG_DATA'
,p_sequence=>370
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package pkg_data as',
'  -- Estilos suportados:',
unistr('  -- ''DATA''           -> s\00F3 data'),
'  -- ''DATA_HORA''      -> data + hora',
'  -- ''DATA_MINUTO''    -> data + hora:minuto',
'  -- ''DATA_SEGUNDO''   -> data + hora:minuto:segundo',
'  function fmt(',
'    p_value in timestamp with time zone,',
'    p_style in varchar2 default ''DATA_SEGUNDO''',
'  ) return varchar2;',
'',
'  -- Overloads (opcionais) para facilitar uso com outros tipos',
'  function fmt(',
'    p_value in timestamp,',
'    p_style in varchar2 default ''DATA_SEGUNDO'',',
'    p_source_tz in varchar2 default null -- se null, assume SESSIONTIMEZONE',
'  ) return varchar2;',
'',
'  function fmtd(',
'    p_value in date,',
'    p_style in varchar2 default ''DATA_SEGUNDO'',',
'    p_source_tz in varchar2 default null -- se null, assume SESSIONTIMEZONE',
'  ) return varchar2;',
'',
'end pkg_data;',
'/',
'create or replace package body pkg_data as',
'',
unistr('  -- Define a m\00E1scara conforme territ\00F3rio e estilo'),
'  function mask_for(p_territory varchar2, p_style varchar2) return varchar2 is',
'    l_style varchar2(20) := upper(trim(p_style));',
'    l_us    boolean := (upper(trim(p_territory)) = ''AMERICA''); -- EUA',
'  begin',
'    if l_style = ''DATA'' then',
'      return case when l_us then ''MM/DD/YYYY'' else ''DD/MM/YYYY'' end;',
'    elsif l_style = ''DATA_HORA'' then',
'      return case when l_us then ''MM/DD/YYYY HH AM'' else ''DD/MM/YYYY HH24'' end;',
'    elsif l_style = ''DATA_MINUTO'' then',
'      return case when l_us then ''MM/DD/YYYY HH:MI AM'' else ''DD/MM/YYYY HH24:MI'' end;',
'    elsif l_style = ''DATA_SEGUNDO'' then',
'      return case when l_us then ''MM/DD/YYYY HH:MI:SS AM'' else ''DD/MM/YYYY HH24:MI:SS'' end;',
'    elsif l_style = ''DATA_MILESIMO'' then',
'      return case when l_us then ''MM/DD/YYYY HH:MI:SS AM'' else ''DD/MM/YYYY HH24:MI:SS.FF3'' end;',
'    elsif l_style = ''DATA_DIA_MES'' then',
'      return case when l_us then ''MM/DD'' else ''DD/MM'' end;',
'    else',
'      -- fallback seguro',
'      return case when l_us then ''MM/DD/YYYY HH:MI:SS AM'' else ''DD/MM/YYYY HH24:MI:SS'' end;',
'    end if;',
'  end;',
'',
'  -- =====================================================================',
'  -- 1) TIMESTAMP WITH TIME ZONE (origem pode estar em UTC ou qualquer TZ)',
unistr('  --    -> converte para o TZ da sess\00E3o (SESSIONTIMEZONE) e formata'),
'  -- =====================================================================',
'  function fmt(',
'    p_value in timestamp with time zone,',
'    p_style in varchar2 default ''DATA_SEGUNDO''',
'  ) return varchar2',
'  is',
'    l_territory varchar2(50);',
'    l_mask      varchar2(40);',
'    l_result    varchar2(60);',
'  begin',
'    select sys_context(''USERENV'',''NLS_TERRITORY'')',
'      into l_territory',
'      from dual;',
'',
'    l_mask := mask_for(l_territory, p_style);',
'',
unistr('    -- Converte para o fuso da sess\00E3o (APEX) e aplica m\00E1scara.'),
'    -- Uso de AT TIME ZONE SESSIONTIMEZONE evita problemas de parser com AT LOCAL TIME ZONE em PL/SQL.',
'    select to_char(',
'             cast(p_value as timestamp with time zone) at time zone sessiontimezone,',
'             l_mask',
'           )',
'      into l_result',
'      from dual;',
'',
'    return l_result;',
'  end;',
'',
'  -- =====================================================================',
'  -- 2) TIMESTAMP (SEM TZ) -> ASSUMIR UTC (conforme combinado)',
unistr('  --    -> carimba UTC e converte para TZ da sess\00E3o'),
'  -- =====================================================================',
'  function fmt(',
'    p_value in timestamp,',
'    p_style in varchar2 default ''DATA_SEGUNDO'',',
'    p_source_tz in varchar2 default null',
'  ) return varchar2',
'  is',
unistr('    l_src_tz varchar2(64) := nvl(p_source_tz, ''UTC''); -- padr\00E3o: UTC'),
'  begin',
'    return fmt(from_tz(p_value, l_src_tz), p_style);',
'  end;',
'',
'  -- =====================================================================',
'  -- 3) DATE (SEM TZ) -> ASSUMIR UTC (conforme combinado)',
unistr('  --    -> carimba UTC e converte para TZ da sess\00E3o'),
'  -- =====================================================================',
'    function fmtd(',
'        p_value in date,',
'        p_style in varchar2 default ''DATA_SEGUNDO'',',
'        p_source_tz in varchar2 default null',
'      ) return varchar2',
'      is',
'        l_src_tz    varchar2(64) := nvl(p_source_tz, ''UTC'');',
'        l_territory varchar2(50);',
'        l_mask      varchar2(40);',
'      begin',
unistr('        -- Se for "apenas data", N\00C3O aplica fuso.'),
'        if upper(trim(p_style)) = ''DATA'' then',
'          select sys_context(''USERENV'',''NLS_TERRITORY'')',
'            into l_territory',
'            from dual;',
'',
'          l_mask := mask_for(l_territory, ''DATA'');',
'',
'          return to_char(trunc(p_value), l_mask);',
'        end if;',
'',
unistr('        -- Para estilos com hora/min/seg, mant\00E9m a l\00F3gica de TZ.'),
'        return fmt(from_tz(cast(p_value as timestamp), l_src_tz), p_style);',
'      end;',
'',
'',
'end pkg_data;',
'/'))
);
end;
/
